#include "check.h"

uint32_t crc32_table[8][256];
uint64_t crc64_table[4][256];
static bool tables_ready = false;

void crc_tables_init(void)
{
	if (tables_ready)
		return;
	for (uint32_t s = 0; s < 8; ++s) {
		for (uint32_t b = 0; b < 256; ++b) {
			uint32_t r = s == 0 ? b : crc32_table[s - 1][b];
			if (s == 0) {
				for (int i = 0; i < 8; ++i)
					r = (r >> 1) ^ (UINT32_C(0xEDB88320) & (0 - (r & 1)));
			} else {
				r = crc32_table[0][r & 0xFF] ^ (r >> 8);
			}
			crc32_table[s][b] = r;
		}
	}
	for (uint32_t s = 0; s < 4; ++s) {
		for (uint32_t b = 0; b < 256; ++b) {
			uint64_t r = s == 0 ? b : crc64_table[s - 1][b];
			if (s == 0) {
				for (int i = 0; i < 8; ++i)
					r = (r >> 1) ^ (UINT64_C(0xC96C5795D7870F42) & (0 - (r & 1)));
			} else {
				r = crc64_table[0][r & 0xFF] ^ (r >> 8);
			}
			crc64_table[s][b] = r;
		}
	}
	tables_ready = true;
}

uint32_t crc32_update(const uint8_t *buf, size_t size, uint32_t crc)
{
	crc_tables_init();
	crc = ~crc;
	while (size >= 8) {
		uint32_t a = read32le(buf) ^ crc;
		uint32_t b = read32le(buf + 4);
		crc = crc32_table[7][a & 0xFF] ^ crc32_table[6][(a >> 8) & 0xFF]
			^ crc32_table[5][(a >> 16) & 0xFF] ^ crc32_table[4][a >> 24]
			^ crc32_table[3][b & 0xFF] ^ crc32_table[2][(b >> 8) & 0xFF]
			^ crc32_table[1][(b >> 16) & 0xFF] ^ crc32_table[0][b >> 24];
		buf += 8;
		size -= 8;
	}
	while (size-- > 0)
		crc = crc32_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

uint64_t crc64_update(const uint8_t *buf, size_t size, uint64_t crc)
{
	crc_tables_init();
	crc = ~crc;
	while (size >= 4) {
		uint32_t a = read32le(buf) ^ (uint32_t)crc;
		crc >>= 32;
		crc ^= crc64_table[3][a & 0xFF] ^ crc64_table[2][(a >> 8) & 0xFF]
			^ crc64_table[1][(a >> 16) & 0xFF] ^ crc64_table[0][a >> 24];
		buf += 4;
		size -= 4;
	}
	while (size-- > 0)
		crc = crc64_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

/* SHA-256 */
static const uint32_t K[64] = {
	0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5, 0x3956C25B, 0x59F111F1, 0x923F82A4, 0xAB1C5ED5,
	0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3, 0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174,
	0xE49B69C1, 0xEFBE4786, 0x0FC19DC6, 0x240CA1CC, 0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
	0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7, 0xC6E00BF3, 0xD5A79147, 0x06CA6351, 0x14292967,
	0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13, 0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85,
	0xA2BFE8A1, 0xA81A664B, 0xC24B8B70, 0xC76C51A3, 0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
	0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5, 0x391C0CB3, 0x4ED8AA4A, 0x5B9CCA4F, 0x682E6FF3,
	0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208, 0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2,
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }

static void sha256_block(uint32_t st[8], const uint8_t *p)
{
	uint32_t w[64];
	for (int i = 0; i < 16; ++i)
		w[i] = read32be(p + 4 * i);
	for (int i = 16; i < 64; ++i) {
		uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
		uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
		w[i] = w[i-16] + s0 + w[i-7] + s1;
	}
	uint32_t a = st[0], b = st[1], c = st[2], d = st[3], e = st[4], f = st[5], g = st[6], h = st[7];
	for (int i = 0; i < 64; ++i) {
		uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
		uint32_t ch = (e & f) ^ (~e & g);
		uint32_t t1 = h + S1 + ch + K[i] + w[i];
		uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
		uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
		uint32_t t2 = S0 + maj;
		h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
	}
	st[0] += a; st[1] += b; st[2] += c; st[3] += d; st[4] += e; st[5] += f; st[6] += g; st[7] += h;
}

void sha256_init(sha256_state *s)
{
	static const uint32_t iv[8] = {
		0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
		0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
	};
	memcpy(s->state, iv, sizeof(iv));
	s->size = 0;
	s->buf_used = 0;
}

void sha256_update(sha256_state *s, const uint8_t *buf, size_t size)
{
	s->size += size;
	if (s->buf_used > 0) {
		size_t n = 64 - s->buf_used;
		if (n > size) n = size;
		memcpy(s->buf + s->buf_used, buf, n);
		s->buf_used += n;
		buf += n;
		size -= n;
		if (s->buf_used == 64) {
			sha256_block(s->state, s->buf);
			s->buf_used = 0;
		}
	}
	while (size >= 64) {
		sha256_block(s->state, buf);
		buf += 64;
		size -= 64;
	}
	if (size > 0) {
