/* ---------- Encoder ---------- */

typedef struct {
	uint64_t low;
	uint64_t cache_size;
	uint32_t range;
	uint8_t cache;
	/* Output buffer owned by the user of the encoder. */
	uint8_t *out;
	size_t out_pos;
	size_t out_size;
} rc_enc;

static inline void rc_enc_reset(rc_enc *rc)
{
	rc->low = 0;
	rc->cache_size = 1;
	rc->range = UINT32_MAX;
	rc->cache = 0;
}

static inline void rc_shift_low(rc_enc *rc)
{
	if ((uint32_t)(rc->low) < UINT32_C(0xFF000000) || (uint32_t)(rc->low >> 32) != 0) {
		do {
			/* Output buffer is always large enough; callers ensure this. */
			rc->out[rc->out_pos++] = rc->cache + (uint8_t)(rc->low >> 32);
			rc->cache = 0xFF;
		} while (--rc->cache_size != 0);
		rc->cache = (rc->low >> 24) & 0xFF;
	}
	++rc->cache_size;
	rc->low = (rc->low & UINT32_C(0x00FFFFFF)) << RC_SHIFT_BITS;
}

static inline void rc_bit(rc_enc *rc, prob_t *prob, uint32_t bit)
{
	uint32_t p = *prob;
	uint32_t bound = (rc->range >> RC_BIT_MODEL_TOTAL_BITS) * p;
	if (bit == 0) {
		rc->range = bound;
		*prob = (prob_t)(p + ((RC_BIT_MODEL_TOTAL - p) >> RC_MOVE_BITS));
	} else {
		rc->low += bound;
		rc->range -= bound;
		*prob = (prob_t)(p - (p >> RC_MOVE_BITS));
	}
	if (rc->range < RC_TOP_VALUE) {
		rc->range <<= RC_SHIFT_BITS;
		rc_shift_low(rc);
	}
}

static inline void rc_bittree(rc_enc *rc, prob_t *probs, uint32_t bit_count, uint32_t symbol)
{
	uint32_t model_index = 1;
	do {
		const uint32_t bit = (symbol >> --bit_count) & 1;
		rc_bit(rc, &probs[model_index], bit);
		model_index = (model_index << 1) + bit;
	} while (bit_count != 0);
}

static inline void rc_bittree_reverse(rc_enc *rc, prob_t *probs, uint32_t bit_count, uint32_t symbol)
{
	uint32_t model_index = 1;
	do {
		const uint32_t bit = symbol & 1;
		symbol >>= 1;
		rc_bit(rc, &probs[model_index], bit);
		model_index = (model_index << 1) + bit;
