	STATE_LIT_MATCH,
	STATE_LIT_LONGREP,
	STATE_LIT_SHORTREP,
	STATE_NONLIT_MATCH,
	STATE_NONLIT_REP,
} lzma_state;

#define STATES 12
#define LIT_STATES 7

static inline lzma_state state_after_literal(lzma_state s)
{
	if (s <= STATE_SHORTREP_LIT_LIT) return STATE_LIT_LIT;
	if (s <= STATE_LIT_SHORTREP) return (lzma_state)(s - 3);
	return (lzma_state)(s - 6);
}
static inline lzma_state state_after_match(lzma_state s) { return s < LIT_STATES ? STATE_LIT_MATCH : STATE_NONLIT_MATCH; }
static inline lzma_state state_after_long_rep(lzma_state s) { return s < LIT_STATES ? STATE_LIT_LONGREP : STATE_NONLIT_REP; }
static inline lzma_state state_after_short_rep(lzma_state s) { return s < LIT_STATES ? STATE_LIT_SHORTREP : STATE_NONLIT_REP; }
static inline bool is_literal_state(lzma_state s) { return s < LIT_STATES; }

