{
	return probs + ((((pos) & lp_mask) << lc) + (prev_byte >> (8U - lc))) * LITERAL_CODER_SIZE;
}

/* Encode/decode the lc/lp/pb properties byte. */
static inline bool lzma_lclppb_decode(lzma_options *o, uint8_t byte)
{
	if (byte > (4 * 5 + 4) * 9 + 8)
		return true;
	o->pb = byte / (9 * 5);
	byte -= o->pb * 9 * 5;
	o->lp = byte / 9;
	o->lc = byte - o->lp * 9;
