static lz_match *hc_find_func(const uint32_t len_limit, const uint32_t pos,
		const uint8_t *const cur, uint32_t cur_match, uint32_t depth,
		uint32_t *const son, const uint32_t cyclic_pos, const uint32_t cyclic_size,
		lz_match *matches, uint32_t len_best)
{
	son[cyclic_pos] = cur_match;
	while (true) {
		const uint32_t delta = pos - cur_match;
		if (depth-- == 0 || delta >= cyclic_size)
