			if (limit > mf->match_len_max)
				limit = mf->match_len_max;
			const uint8_t *p1 = mf_ptr(mf) - 1;
			const uint8_t *p2 = p1 - matches[count - 1].dist - 1;
			len_best = memcmplen(p1, p2, len_best, limit);
		}
	}
	*count_ptr = count;
	++mf->read_ahead;
	return len_best;
}

bool lz_mf_prepare(lz_mf *mf, const lz_options *opt)
{
	if (opt->dict_size < LZ_DICT_SIZE_MIN || opt->dict_size > LZ_DICT_SIZE_MAX
			|| opt->nice_len > opt->match_len_max)
		return true;

	mf->keep_size_before = (uint32_t)(opt->before_size + opt->dict_size);
	mf->keep_size_after = (uint32_t)(opt->after_size + opt->match_len_max);

	uint32_t reserve = (uint32_t)(opt->dict_size / 2);
	if (reserve > (UINT32_C(1) << 30))
		reserve /= 2;
	reserve += (uint32_t)((opt->before_size + opt->match_len_max + opt->after_size) / 2 + (UINT32_C(1) << 19));

	mf->size = mf->keep_size_before + reserve + mf->keep_size_after;
	mf->match_len_max = (uint32_t)opt->match_len_max;
	mf->nice_len = (uint32_t)opt->nice_len;
	mf->cyclic_size = (uint32_t)opt->dict_size + 1;

	switch (opt->match_finder) {
	case MF_HC3: mf->find = hc3_find; mf->skip = hc3_skip; break;
	case MF_HC4: mf->find = hc4_find; mf->skip = hc4_skip; break;
	case MF_BT2: mf->find = bt2_find; mf->skip = bt2_skip; break;
	case MF_BT3: mf->find = bt3_find; mf->skip = bt3_skip; break;
	case MF_BT4: mf->find = bt4_find; mf->skip = bt4_skip; break;
	default: return true;
	}

	const uint32_t hash_bytes = mf_get_hash_bytes(opt->match_finder);
	if (hash_bytes > mf->nice_len)
		return true;

	const bool is_bt = (opt->match_finder & 0x10) != 0;
	uint32_t hs;
	if (hash_bytes == 2) {
		hs = 0xFFFF;
	} else {
		hs = (uint32_t)opt->dict_size - 1;
		hs |= hs >> 1;
		hs |= hs >> 2;
		hs |= hs >> 4;
		hs |= hs >> 8;
		hs >>= 1;
		hs |= 0xFFFF;
		if (hs > (UINT32_C(1) << 24)) {
			if (hash_bytes == 3)
				hs = (UINT32_C(1) << 24) - 1;
			else
				hs >>= 1;
		}
	}
	mf->hash_mask = hs;
	++hs;
	if (hash_bytes > 2)
		hs += HASH_2_SIZE;
	if (hash_bytes > 3)
		hs += HASH_3_SIZE;
	mf->hash_count = hs;
	mf->sons_count = mf->cyclic_size;
	if (is_bt)
		mf->sons_count *= 2;

	mf->depth = opt->depth;
	if (mf->depth == 0) {
		if (is_bt)
			mf->depth = 16 + mf->nice_len / 2;
		else
			mf->depth = 4 + mf->nice_len / 4;
	}
	return false;
}

uint64_t lz_mf_memusage(const lz_options *opt)
{
	lz_mf mf;
	memset(&mf, 0, sizeof(mf));
	if (lz_mf_prepare(&mf, opt))
		return UINT64_MAX;
	return ((uint64_t)mf.hash_count + mf.sons_count) * sizeof(uint32_t) + mf.size;
}

bool lz_mf_init(lz_mf *mf, const lz_options *opt)
{
	crc_tables_init();
	if (mf->buffer == NULL) {
		mf->buffer = malloc((size_t)mf->size + MEMCMPLEN_EXTRA);
		if (mf->buffer == NULL)
			return true;
		memset(mf->buffer + mf->size, 0, MEMCMPLEN_EXTRA);
	}
	mf->offset = mf->cyclic_size;
	mf->read_pos = 0;
	mf->read_ahead = 0;
	mf->read_limit = 0;
	mf->write_pos = 0;
	mf->pending = 0;

	if (mf->hash == NULL) {
		mf->hash = calloc(mf->hash_count, sizeof(uint32_t));
		mf->son = malloc((size_t)mf->sons_count * sizeof(uint32_t));
		if (mf->hash == NULL || mf->son == NULL)
			return true;
	} else {
		memset(mf->hash, 0, (size_t)mf->hash_count * sizeof(uint32_t));
	}
	mf->cyclic_pos = 0;

	if (opt->preset_dict != NULL && opt->preset_dict_size > 0) {
		mf->write_pos = xmin32(opt->preset_dict_size, mf->size);
		memcpy(mf->buffer, opt->preset_dict + opt->preset_dict_size - mf->write_pos, mf->write_pos);
		mf->action = A_SYNC_FLUSH;
		mf->skip(mf, mf->write_pos);
	}
	mf->action = A_RUN;
	return false;
}

void lz_mf_free(lz_mf *mf)
{
	free(mf->buffer);
	free(mf->hash);
	free(mf->son);
	mf->buffer = NULL;
	mf->hash = NULL;
	mf->son = NULL;
}

static void move_window(lz_mf *mf)
{
	const uint32_t move_offset = (mf->read_pos - mf->keep_size_before) & ~UINT32_C(15);
	const size_t move_size = mf->write_pos - move_offset;
	memmove(mf->buffer, mf->buffer + move_offset, move_size);
	mf->offset += move_offset;
	mf->read_pos -= move_offset;
	mf->read_limit -= move_offset;
	mf->write_pos -= move_offset;
}

void lz_mf_fill_window(lz_mf *mf, const uint8_t *in, size_t *in_pos, size_t in_size, xaction action)
{
	if (mf->read_pos >= mf->size - mf->keep_size_after)
		move_window(mf);

	size_t write_pos = mf->write_pos;
	bufcpy(in, in_pos, in_size, mf->buffer, &write_pos, mf->size);
	bool end = action != A_RUN && *in_pos == in_size;
	mf->write_pos = (uint32_t)write_pos;
	memset(mf->buffer + write_pos, 0, MEMCMPLEN_EXTRA);

	if (end) {
		mf->action = action;
		mf->read_limit = mf->write_pos;
	} else if (mf->write_pos > mf->keep_size_after) {
		mf->read_limit = mf->write_pos - mf->keep_size_after;
	}

	if (mf->pending > 0 && mf->read_pos < mf->read_limit) {
		const uint32_t pending = mf->pending;
		mf->pending = 0;
		mf->read_pos -= pending;
		mf->skip(mf, pending);
	}
}
