#include "mf.h"
#include "check.h"

#define EMPTY_HASH_VALUE 0
#define MUST_NORMALIZE_POS UINT32_MAX

#define HASH_2_SIZE (UINT32_C(1) << 10)
#define HASH_3_SIZE (UINT32_C(1) << 16)
#define HASH_4_SIZE (UINT32_C(1) << 20)
#define HASH_2_MASK (HASH_2_SIZE - 1)
#define HASH_3_MASK (HASH_3_SIZE - 1)
#define FIX_3_HASH_SIZE (HASH_2_SIZE)
#define FIX_4_HASH_SIZE (HASH_2_SIZE + HASH_3_SIZE)

#define hash_table crc32_table[0]

#define hash_2_calc() \
	const uint32_t hash_value = read16le(cur)

#define hash_3_calc() \
	const uint32_t temp = hash_table[cur[0]] ^ cur[1]; \
	const uint32_t hash_2_value = temp & HASH_2_MASK; \
	const uint32_t hash_value = (temp ^ ((uint32_t)(cur[2]) << 8)) & mf->hash_mask

#define hash_4_calc() \
	const uint32_t temp = hash_table[cur[0]] ^ cur[1]; \
	const uint32_t hash_2_value = temp & HASH_2_MASK; \
	const uint32_t hash_3_value = (temp ^ ((uint32_t)(cur[2]) << 8)) & HASH_3_MASK; \
	const uint32_t hash_value = (temp ^ ((uint32_t)(cur[2]) << 8) \
			^ (hash_table[cur[3]] << 5)) & mf->hash_mask

static uint32_t mf_get_hash_bytes(lzma_mf_t m) { return (uint32_t)m & 0x0F; }

bool lz_mf_is_supported(lzma_mf_t m)
{
	return m == MF_HC3 || m == MF_HC4 || m == MF_BT2 || m == MF_BT3 || m == MF_BT4;
}

static void normalize(lz_mf *mf)
{
	const uint32_t subvalue = MUST_NORMALIZE_POS - mf->cyclic_size;
	for (uint32_t i = 0; i < mf->hash_count; ++i) {
		if (mf->hash[i] <= subvalue)
			mf->hash[i] = EMPTY_HASH_VALUE;
		else
			mf->hash[i] -= subvalue;
	}
	for (uint32_t i = 0; i < mf->sons_count; ++i) {
		if (mf->son[i] <= subvalue)
			mf->son[i] = EMPTY_HASH_VALUE;
		else
			mf->son[i] -= subvalue;
	}
	mf->offset -= subvalue;
}

static inline void move_pos(lz_mf *mf)
{
	if (++mf->cyclic_pos == mf->cyclic_size)
		mf->cyclic_pos = 0;
	++mf->read_pos;
	if (mf->read_pos + mf->offset == MUST_NORMALIZE_POS)
		normalize(mf);
}

static inline void move_pending(lz_mf *mf)
{
	++mf->read_pos;
	++mf->pending;
}

#define header(is_bt, len_min, ret_op) \
	uint32_t len_limit = mf_avail(mf); \
	if (mf->nice_len <= len_limit) { \
		len_limit = mf->nice_len; \
	} else if (len_limit < (len_min)) { \
		move_pending(mf); \
		ret_op; \
	} \
	const uint8_t *cur = mf_ptr(mf); \
	const uint32_t pos = mf->read_pos + mf->offset

#define header_find(is_bt, len_min) \
	header(is_bt, len_min, return 0); \
	uint32_t matches_count = 0

#define header_skip(is_bt, len_min) \
	header(is_bt, len_min, continue)

#define call_find(func, len_best) \
do { \
	matches_count = (uint32_t)(func(len_limit, pos, cur, cur_match, mf->depth, \
			mf->son, mf->cyclic_pos, mf->cyclic_size, \
			matches + matches_count, len_best) - matches); \
	move_pos(mf); \
	return matches_count; \
} while (0)

/* ---------- Hash chain ---------- */

static lz_match *hc_find_func(const uint32_t len_limit, const uint32_t pos,
		const uint8_t *const cur, uint32_t cur_match, uint32_t depth,
		uint32_t *const son, const uint32_t cyclic_pos, const uint32_t cyclic_size,
		lz_match *matches, uint32_t len_best)
{
	son[cyclic_pos] = cur_match;
	while (true) {
		const uint32_t delta = pos - cur_match;
		if (depth-- == 0 || delta >= cyclic_size)
			return matches;
		const uint8_t *const pb = cur - delta;
		cur_match = son[cyclic_pos - delta + (delta > cyclic_pos ? cyclic_size : 0)];
		if (pb[len_best] == cur[len_best] && pb[0] == cur[0]) {
			uint32_t len = memcmplen(pb, cur, 1, len_limit);
			if (len_best < len) {
				len_best = len;
				matches->len = len;
				matches->dist = delta - 1;
				++matches;
				if (len == len_limit)
					return matches;
			}
		}
	}
}

#define hc_skip() \
do { \
	mf->son[mf->cyclic_pos] = cur_match; \
	move_pos(mf); \
} while (0)

static uint32_t hc3_find(lz_mf *mf, lz_match *matches)
{
	header_find(false, 3);
	hash_3_calc();
	const uint32_t delta2 = pos - mf->hash[hash_2_value];
	const uint32_t cur_match = mf->hash[FIX_3_HASH_SIZE + hash_value];
	mf->hash[hash_2_value] = pos;
	mf->hash[FIX_3_HASH_SIZE + hash_value] = pos;
	uint32_t len_best = 2;
	if (delta2 < mf->cyclic_size && *(cur - delta2) == *cur) {
		len_best = memcmplen(cur - delta2, cur, len_best, len_limit);
		matches[0].len = len_best;
		matches[0].dist = delta2 - 1;
		matches_count = 1;
		if (len_best == len_limit) {
			hc_skip();
			return 1;
		}
	}
	call_find(hc_find_func, len_best);
}

static void hc3_skip(lz_mf *mf, uint32_t amount)
{
	do {
		if (mf_avail(mf) < 3) {
			move_pending(mf);
			continue;
		}
		const uint8_t *cur = mf_ptr(mf);
		const uint32_t pos = mf->read_pos + mf->offset;
		hash_3_calc();
		const uint32_t cur_match = mf->hash[FIX_3_HASH_SIZE + hash_value];
		mf->hash[hash_2_value] = pos;
		mf->hash[FIX_3_HASH_SIZE + hash_value] = pos;
		hc_skip();
	} while (--amount != 0);
}

static uint32_t hc4_find(lz_mf *mf, lz_match *matches)
{
	header_find(false, 4);
	hash_4_calc();
	uint32_t delta2 = pos - mf->hash[hash_2_value];
	const uint32_t delta3 = pos - mf->hash[FIX_3_HASH_SIZE + hash_3_value];
	const uint32_t cur_match = mf->hash[FIX_4_HASH_SIZE + hash_value];
	mf->hash[hash_2_value] = pos;
	mf->hash[FIX_3_HASH_SIZE + hash_3_value] = pos;
	mf->hash[FIX_4_HASH_SIZE + hash_value] = pos;
	uint32_t len_best = 1;
	if (delta2 < mf->cyclic_size && *(cur - delta2) == *cur) {
		len_best = 2;
		matches[0].len = 2;
		matches[0].dist = delta2 - 1;
		matches_count = 1;
	}
	if (delta2 != delta3 && delta3 < mf->cyclic_size && *(cur - delta3) == *cur) {
		len_best = 3;
		matches[matches_count++].dist = delta3 - 1;
		delta2 = delta3;
	}
	if (matches_count != 0) {
		len_best = memcmplen(cur - delta2, cur, len_best, len_limit);
		matches[matches_count - 1].len = len_best;
		if (len_best == len_limit) {
			hc_skip();
			return matches_count;
		}
	}
	if (len_best < 3)
		len_best = 3;
	call_find(hc_find_func, len_best);
}

static void hc4_skip(lz_mf *mf, uint32_t amount)
{
	do {
		if (mf_avail(mf) < 4) {
			move_pending(mf);
			continue;
		}
		const uint8_t *cur = mf_ptr(mf);
		const uint32_t pos = mf->read_pos + mf->offset;
		hash_4_calc();
		const uint32_t cur_match = mf->hash[FIX_4_HASH_SIZE + hash_value];
		mf->hash[hash_2_value] = pos;
		mf->hash[FIX_3_HASH_SIZE + hash_3_value] = pos;
		mf->hash[FIX_4_HASH_SIZE + hash_value] = pos;
		hc_skip();
	} while (--amount != 0);
}

/* ---------- Binary tree ---------- */

static lz_match *bt_find_func(const uint32_t len_limit, const uint32_t pos,
		const uint8_t *const cur, uint32_t cur_match, uint32_t depth,
		uint32_t *const son, const uint32_t cyclic_pos, const uint32_t cyclic_size,
		lz_match *matches, uint32_t len_best)
{
	uint32_t *ptr0 = son + (cyclic_pos << 1) + 1;
	uint32_t *ptr1 = son + (cyclic_pos << 1);
	uint32_t len0 = 0;
	uint32_t len1 = 0;

	while (true) {
		const uint32_t delta = pos - cur_match;
		if (depth-- == 0 || delta >= cyclic_size) {
			*ptr0 = EMPTY_HASH_VALUE;
			*ptr1 = EMPTY_HASH_VALUE;
			return matches;
		}
		uint32_t *const pair = son + ((cyclic_pos - delta + (delta > cyclic_pos ? cyclic_size : 0)) << 1);
		const uint8_t *const pb = cur - delta;
		uint32_t len = xmin32(len0, len1);
		if (pb[len] == cur[len]) {
			while (++len != len_limit)
				if (pb[len] != cur[len])
					break;
			if (len_best < len) {
				len_best = len;
				matches->len = len;
				matches->dist = delta - 1;
				++matches;
				if (len == len_limit) {
					*ptr1 = pair[0];
					*ptr0 = pair[1];
					return matches;
				}
			}
		}
		if (pb[len] < cur[len]) {
			*ptr1 = cur_match;
			ptr1 = pair + 1;
			cur_match = *ptr1;
			len1 = len;
		} else {
			*ptr0 = cur_match;
			ptr0 = pair;
			cur_match = *ptr0;
			len0 = len;
		}
	}
}

static void bt_skip_func(const uint32_t len_limit, const uint32_t pos,
		const uint8_t *const cur, uint32_t cur_match, uint32_t depth,
		uint32_t *const son, const uint32_t cyclic_pos, const uint32_t cyclic_size)
{
	uint32_t *ptr0 = son + (cyclic_pos << 1) + 1;
	uint32_t *ptr1 = son + (cyclic_pos << 1);
	uint32_t len0 = 0;
	uint32_t len1 = 0;

	while (true) {
		const uint32_t delta = pos - cur_match;
		if (depth-- == 0 || delta >= cyclic_size) {
			*ptr0 = EMPTY_HASH_VALUE;
			*ptr1 = EMPTY_HASH_VALUE;
			return;
		}
		uint32_t *pair = son + ((cyclic_pos - delta + (delta > cyclic_pos ? cyclic_size : 0)) << 1);
		const uint8_t *pb = cur - delta;
		uint32_t len = xmin32(len0, len1);
		if (pb[len] == cur[len]) {
			while (++len != len_limit)
				if (pb[len] != cur[len])
					break;
			if (len == len_limit) {
				*ptr1 = pair[0];
				*ptr0 = pair[1];
				return;
			}
		}
		if (pb[len] < cur[len]) {
			*ptr1 = cur_match;
			ptr1 = pair + 1;
			cur_match = *ptr1;
			len1 = len;
		} else {
			*ptr0 = cur_match;
			ptr0 = pair;
			cur_match = *ptr0;
			len0 = len;
		}
	}
}

#define bt_skip() \
do { \
	bt_skip_func(len_limit, pos, cur, cur_match, mf->depth, \
			mf->son, mf->cyclic_pos, mf->cyclic_size); \
	move_pos(mf); \
} while (0)

static uint32_t bt2_find(lz_mf *mf, lz_match *matches)
{
	header_find(true, 2);
	hash_2_calc();
	const uint32_t cur_match = mf->hash[hash_value];
	mf->hash[hash_value] = pos;
	call_find(bt_find_func, 1);
}

static void bt2_skip(lz_mf *mf, uint32_t amount)
{
	do {
		header_skip(true, 2);
		hash_2_calc();
		const uint32_t cur_match = mf->hash[hash_value];
		mf->hash[hash_value] = pos;
		bt_skip();
	} while (--amount != 0);
}

static uint32_t bt3_find(lz_mf *mf, lz_match *matches)
{
	header_find(true, 3);
	hash_3_calc();
	const uint32_t delta2 = pos - mf->hash[hash_2_value];
	const uint32_t cur_match = mf->hash[FIX_3_HASH_SIZE + hash_value];
	mf->hash[hash_2_value] = pos;
	mf->hash[FIX_3_HASH_SIZE + hash_value] = pos;
	uint32_t len_best = 2;
	if (delta2 < mf->cyclic_size && *(cur - delta2) == *cur) {
		len_best = memcmplen(cur, cur - delta2, len_best, len_limit);
		matches[0].len = len_best;
		matches[0].dist = delta2 - 1;
		matches_count = 1;
		if (len_best == len_limit) {
			bt_skip();
			return 1;
		}
	}
	call_find(bt_find_func, len_best);
}

static void bt3_skip(lz_mf *mf, uint32_t amount)
{
	do {
		header_skip(true, 3);
		hash_3_calc();
		const uint32_t cur_match = mf->hash[FIX_3_HASH_SIZE + hash_value];
		mf->hash[hash_2_value] = pos;
		mf->hash[FIX_3_HASH_SIZE + hash_value] = pos;
		bt_skip();
	} while (--amount != 0);
}

static uint32_t bt4_find(lz_mf *mf, lz_match *matches)
{
	header_find(true, 4);
	hash_4_calc();
	uint32_t delta2 = pos - mf->hash[hash_2_value];
	const uint32_t delta3 = pos - mf->hash[FIX_3_HASH_SIZE + hash_3_value];
	const uint32_t cur_match = mf->hash[FIX_4_HASH_SIZE + hash_value];
	mf->hash[hash_2_value] = pos;
	mf->hash[FIX_3_HASH_SIZE + hash_3_value] = pos;
	mf->hash[FIX_4_HASH_SIZE + hash_value] = pos;
	uint32_t len_best = 1;
	if (delta2 < mf->cyclic_size && *(cur - delta2) == *cur) {
		len_best = 2;
		matches[0].len = 2;
		matches[0].dist = delta2 - 1;
		matches_count = 1;
	}
	if (delta2 != delta3 && delta3 < mf->cyclic_size && *(cur - delta3) == *cur) {
		len_best = 3;
		matches[matches_count++].dist = delta3 - 1;
		delta2 = delta3;
	}
	if (matches_count != 0) {
		len_best = memcmplen(cur, cur - delta2, len_best, len_limit);
		matches[matches_count - 1].len = len_best;
		if (len_best == len_limit) {
			bt_skip();
			return matches_count;
		}
	}
	if (len_best < 3)
		len_best = 3;
	call_find(bt_find_func, len_best);
}

static void bt4_skip(lz_mf *mf, uint32_t amount)
{
	do {
		header_skip(true, 4);
		hash_4_calc();
		const uint32_t cur_match = mf->hash[FIX_4_HASH_SIZE + hash_value];
		mf->hash[hash_2_value] = pos;
		mf->hash[FIX_3_HASH_SIZE + hash_3_value] = pos;
		mf->hash[FIX_4_HASH_SIZE + hash_value] = pos;
		bt_skip();
	} while (--amount != 0);
}

/* ---------- Generic ---------- */

uint32_t mf_find(lz_mf *mf, uint32_t *count_ptr, lz_match *matches)
{
	const uint32_t count = mf->find(mf, matches);
	uint32_t len_best = 0;
	if (count > 0) {
		len_best = matches[count - 1].len;
		if (len_best == mf->nice_len) {
			uint32_t limit = mf_avail(mf) + 1;
			if (limit > mf->match_len_max)
				limit = mf->match_len_max;
			const uint8_t *p1 = mf_ptr(mf) - 1;
			const uint8_t *p2 = p1 - matches[count - 1].dist - 1;
			len_best = memcmplen(p1, p2, len_best, limit);
		}
	}
	*count_ptr = count;
	++mf->read_ahead;
	return len_best;
}

bool lz_mf_prepare(lz_mf *mf, const lz_options *opt)
{
	if (opt->dict_size < LZ_DICT_SIZE_MIN || opt->dict_size > LZ_DICT_SIZE_MAX
			|| opt->nice_len > opt->match_len_max)
		return true;

	mf->keep_size_before = (uint32_t)(opt->before_size + opt->dict_size);
	mf->keep_size_after = (uint32_t)(opt->after_size + opt->match_len_max);

	uint32_t reserve = (uint32_t)(opt->dict_size / 2);
	if (reserve > (UINT32_C(1) << 30))
		reserve /= 2;
	reserve += (uint32_t)((opt->before_size + opt->match_len_max + opt->after_size) / 2 + (UINT32_C(1) << 19));

	mf->size = mf->keep_size_before + reserve + mf->keep_size_after;
	mf->match_len_max = (uint32_t)opt->match_len_max;
	mf->nice_len = (uint32_t)opt->nice_len;
	mf->cyclic_size = (uint32_t)opt->dict_size + 1;

	switch (opt->match_finder) {
	case MF_HC3: mf->find = hc3_find; mf->skip = hc3_skip; break;
	case MF_HC4: mf->find = hc4_find; mf->skip = hc4_skip; break;
	case MF_BT2: mf->find = bt2_find; mf->skip = bt2_skip; break;
	case MF_BT3: mf->find = bt3_find; mf->skip = bt3_skip; break;
	case MF_BT4: mf->find = bt4_find; mf->skip = bt4_skip; break;
	default: return true;
	}

	const uint32_t hash_bytes = mf_get_hash_bytes(opt->match_finder);
	if (hash_bytes > mf->nice_len)
		return true;

	const bool is_bt = (opt->match_finder & 0x10) != 0;
	uint32_t hs;
	if (hash_bytes == 2) {
		hs = 0xFFFF;
	} else {
		hs = (uint32_t)opt->dict_size - 1;
		hs |= hs >> 1;
		hs |= hs >> 2;
		hs |= hs >> 4;
		hs |= hs >> 8;
		hs >>= 1;
		hs |= 0xFFFF;
		if (hs > (UINT32_C(1) << 24)) {
			if (hash_bytes == 3)
				hs = (UINT32_C(1) << 24) - 1;
			else
				hs >>= 1;
		}
	}
	mf->hash_mask = hs;
	++hs;
	if (hash_bytes > 2)
		hs += HASH_2_SIZE;
	if (hash_bytes > 3)
		hs += HASH_3_SIZE;
	mf->hash_count = hs;
	mf->sons_count = mf->cyclic_size;
	if (is_bt)
		mf->sons_count *= 2;

	mf->depth = opt->depth;
	if (mf->depth == 0) {
		if (is_bt)
			mf->depth = 16 + mf->nice_len / 2;
		else
			mf->depth = 4 + mf->nice_len / 4;
	}
	return false;
}

uint64_t lz_mf_memusage(const lz_options *opt)
{
	lz_mf mf;
	memset(&mf, 0, sizeof(mf));
	if (lz_mf_prepare(&mf, opt))
		return UINT64_MAX;
	return ((uint64_t)mf.hash_count + mf.sons_count) * sizeof(uint32_t) + mf.size;
}

bool lz_mf_init(lz_mf *mf, const lz_options *opt)
{
	crc_tables_init();
	if (mf->buffer == NULL) {
		mf->buffer = malloc((size_t)mf->size + MEMCMPLEN_EXTRA);
		if (mf->buffer == NULL)
			return true;
		memset(mf->buffer + mf->size, 0, MEMCMPLEN_EXTRA);
	}
	mf->offset = mf->cyclic_size;
	mf->read_pos = 0;
	mf->read_ahead = 0;
	mf->read_limit = 0;
	mf->write_pos = 0;
	mf->pending = 0;

	if (mf->hash == NULL) {
		mf->hash = calloc(mf->hash_count, sizeof(uint32_t));
		mf->son = malloc((size_t)mf->sons_count * sizeof(uint32_t));
		if (mf->hash == NULL || mf->son == NULL)
			return true;
	} else {
		memset(mf->hash, 0, (size_t)mf->hash_count * sizeof(uint32_t));
	}
	mf->cyclic_pos = 0;

	if (opt->preset_dict != NULL && opt->preset_dict_size > 0) {
		mf->write_pos = xmin32(opt->preset_dict_size, mf->size);
		memcpy(mf->buffer, opt->preset_dict + opt->preset_dict_size - mf->write_pos, mf->write_pos);
		mf->action = A_SYNC_FLUSH;
		mf->skip(mf, mf->write_pos);
	}
	mf->action = A_RUN;
	return false;
}

void lz_mf_free(lz_mf *mf)
{
	free(mf->buffer);
	free(mf->hash);
	free(mf->son);
	mf->buffer = NULL;
	mf->hash = NULL;
	mf->son = NULL;
}

static void move_window(lz_mf *mf)
{
	const uint32_t move_offset = (mf->read_pos - mf->keep_size_before) & ~UINT32_C(15);
	const size_t move_size = mf->write_pos - move_offset;
	memmove(mf->buffer, mf->buffer + move_offset, move_size);
	mf->offset += move_offset;
	mf->read_pos -= move_offset;
	mf->read_limit -= move_offset;
	mf->write_pos -= move_offset;
}

void lz_mf_fill_window(lz_mf *mf, const uint8_t *in, size_t *in_pos, size_t in_size, xaction action)
{
	if (mf->read_pos >= mf->size - mf->keep_size_after)
		move_window(mf);

	size_t write_pos = mf->write_pos;
	bufcpy(in, in_pos, in_size, mf->buffer, &write_pos, mf->size);
	bool end = action != A_RUN && *in_pos == in_size;
	mf->write_pos = (uint32_t)write_pos;
	memset(mf->buffer + write_pos, 0, MEMCMPLEN_EXTRA);

	if (end) {
		mf->action = action;
		mf->read_limit = mf->write_pos;
	} else if (mf->write_pos > mf->keep_size_after) {
		mf->read_limit = mf->write_pos - mf->keep_size_after;
	}

	if (mf->pending > 0 && mf->read_pos < mf->read_limit) {
		const uint32_t pending = mf->pending;
		mf->pending = 0;
		mf->read_pos -= pending;
		mf->skip(mf, pending);
	}
}
EOF
