#include "lzma_enc.h"

/* ---------- distance slots ---------- */

static inline uint32_t get_dist_slot(uint32_t dist)
{
	if (dist < DIST_MODEL_START)
		return dist;
	const uint32_t i = bsr32(dist);
	return (i + i) + ((dist >> (i - 1)) & 1);
}

static inline bool not_equal_16(const uint8_t *a, const uint8_t *b)
{
	return a[0] != b[0] || a[1] != b[1];
}

/* ---------- prices ---------- */

static inline uint32_t get_literal_price(const lzma1_enc *coder, uint32_t pos, uint32_t prev_byte,
		bool match_mode, uint32_t match_byte, uint32_t symbol)
{
	const prob_t *subcoder = literal_subcoder((prob_t *)coder->literal, coder->literal_context_bits,
			coder->literal_pos_mask, pos, prev_byte);
	uint32_t price = 0;
	if (!match_mode) {
		price = rc_bittree_price(subcoder, 8, symbol);
	} else {
		uint32_t offset = 0x100;
		symbol += UINT32_C(1) << 8;
		do {
			match_byte <<= 1;
			const uint32_t match_bit = match_byte & offset;
			const uint32_t subcoder_index = offset + match_bit + (symbol >> 8);
			const uint32_t bit = (symbol >> 7) & 1;
			price += rc_bit_price(subcoder[subcoder_index], bit);
			symbol <<= 1;
			offset &= ~(match_byte ^ symbol);
		} while (symbol < (UINT32_C(1) << 16));
	}
	return price;
}

static inline uint32_t get_len_price(const len_encoder *lc, uint32_t len, uint32_t pos_state)
{
	return lc->prices[pos_state][len - MATCH_LEN_MIN];
}

static inline uint32_t get_short_rep_price(const lzma1_enc *coder, lzma_state state, uint32_t pos_state)
{
	return rc_bit_0_price(coder->is_rep0[state]) + rc_bit_0_price(coder->is_rep0_long[state][pos_state]);
}

static inline uint32_t get_pure_rep_price(const lzma1_enc *coder, uint32_t rep_index, lzma_state state, uint32_t pos_state)
{
	uint32_t price;
	if (rep_index == 0) {
		price = rc_bit_0_price(coder->is_rep0[state]);
		price += rc_bit_1_price(coder->is_rep0_long[state][pos_state]);
	} else {
		price = rc_bit_1_price(coder->is_rep0[state]);
		if (rep_index == 1) {
			price += rc_bit_0_price(coder->is_rep1[state]);
		} else {
			price += rc_bit_1_price(coder->is_rep1[state]);
			price += rc_bit_price(coder->is_rep2[state], rep_index - 2);
		}
	}
	return price;
}

static inline uint32_t get_rep_price(const lzma1_enc *coder, uint32_t rep_index, uint32_t len, lzma_state state, uint32_t pos_state)
{
	return get_len_price(&coder->rep_len_encoder, len, pos_state) + get_pure_rep_price(coder, rep_index, state, pos_state);
}

static inline uint32_t get_dist_len_price(const lzma1_enc *coder, uint32_t dist, uint32_t len, uint32_t pos_state)
{
	const uint32_t dist_state = get_dist_state(len);
	uint32_t price;
	if (dist < FULL_DISTANCES) {
		price = coder->dist_prices[dist_state][dist];
	} else {
		const uint32_t dist_slot = get_dist_slot(dist);
		price = coder->dist_slot_prices[dist_state][dist_slot] + coder->align_prices[dist & ALIGN_MASK];
	}
	price += get_len_price(&coder->match_len_encoder, len, pos_state);
	return price;
}

static void fill_dist_prices(lzma1_enc *coder)
{
	for (uint32_t dist_state = 0; dist_state < DIST_STATES; ++dist_state) {
		uint32_t *const dist_slot_prices = coder->dist_slot_prices[dist_state];
		for (uint32_t dist_slot = 0; dist_slot < coder->dist_table_size; ++dist_slot)
			dist_slot_prices[dist_slot] = rc_bittree_price(coder->dist_slot[dist_state], DIST_SLOT_BITS, dist_slot);
		for (uint32_t dist_slot = DIST_MODEL_END; dist_slot < coder->dist_table_size; ++dist_slot)
			dist_slot_prices[dist_slot] += rc_direct_price(((dist_slot >> 1) - 1) - ALIGN_BITS);
		for (uint32_t i = 0; i < DIST_MODEL_START; ++i)
			coder->dist_prices[dist_state][i] = dist_slot_prices[i];
	}
	for (uint32_t i = DIST_MODEL_START; i < FULL_DISTANCES; ++i) {
		const uint32_t dist_slot = get_dist_slot(i);
		const uint32_t footer_bits = ((dist_slot >> 1) - 1);
		const uint32_t base = (2 | (dist_slot & 1)) << footer_bits;
		const uint32_t price = rc_bittree_reverse_price(coder->dist_special + base - dist_slot - 1, footer_bits, i - base);
		for (uint32_t dist_state = 0; dist_state < DIST_STATES; ++dist_state)
			coder->dist_prices[dist_state][i] = price + coder->dist_slot_prices[dist_state][dist_slot];
	}
	coder->match_price_count = 0;
}

static void fill_align_prices(lzma1_enc *coder)
{
	for (uint32_t i = 0; i < ALIGN_SIZE; ++i)
		coder->align_prices[i] = rc_bittree_reverse_price(coder->dist_align, ALIGN_BITS, i);
	coder->align_price_count = 0;
}

/* ---------- optimum: normal mode ---------- */

#define make_literal(opt) do { (opt).back_prev = UINT32_MAX; (opt).prev_1_is_literal = false; } while (0)
#define make_short_rep(opt) do { (opt).back_prev = 0; (opt).prev_1_is_literal = false; } while (0)
#define is_short_rep(opt) ((opt).back_prev == 0)

static void backward(lzma1_enc *coder, uint32_t *len_res, uint32_t *back_res, uint32_t cur)
{
	coder->opts_end_index = cur;
	uint32_t pos_mem = coder->opts[cur].pos_prev;
	uint32_t back_mem = coder->opts[cur].back_prev;
	do {
		if (coder->opts[cur].prev_1_is_literal) {
			make_literal(coder->opts[pos_mem]);
			coder->opts[pos_mem].pos_prev = pos_mem - 1;
			if (coder->opts[cur].prev_2) {
				coder->opts[pos_mem - 1].prev_1_is_literal = false;
				coder->opts[pos_mem - 1].pos_prev = coder->opts[cur].pos_prev_2;
				coder->opts[pos_mem - 1].back_prev = coder->opts[cur].back_prev_2;
			}
		}
		const uint32_t pos_prev = pos_mem;
		const uint32_t back_cur = back_mem;
		back_mem = coder->opts[pos_prev].back_prev;
		pos_mem = coder->opts[pos_prev].pos_prev;
		coder->opts[pos_prev].back_prev = back_cur;
		coder->opts[pos_prev].pos_prev = cur;
		cur = pos_prev;
	} while (cur != 0);
	coder->opts_current_index = coder->opts[0].pos_prev;
	*len_res = coder->opts[0].pos_prev;
	*back_res = coder->opts[0].back_prev;
}

static inline uint32_t helper1(lzma1_enc *coder, lz_mf *mf, uint32_t *back_res, uint32_t *len_res, uint32_t position)
{
	const uint32_t nice_len = mf->nice_len;
	uint32_t len_main;
	uint32_t matches_count;

	if (mf->read_ahead == 0) {
		len_main = mf_find(mf, &matches_count, coder->matches);
	} else {
		len_main = coder->longest_match_length;
		matches_count = coder->matches_count;
	}

	const uint32_t buf_avail = xmin32(mf_avail(mf) + 1, MATCH_LEN_MAX);
	if (buf_avail < 2) {
		*back_res = UINT32_MAX;
		*len_res = 1;
		return UINT32_MAX;
	}

	const uint8_t *const buf = mf_ptr(mf) - 1;
	uint32_t rep_lens[REPS];
	uint32_t rep_max_index = 0;

	for (uint32_t i = 0; i < REPS; ++i) {
		const uint8_t *const buf_back = buf - coder->reps[i] - 1;
		if (not_equal_16(buf, buf_back)) {
			rep_lens[i] = 0;
			continue;
		}
		rep_lens[i] = memcmplen(buf, buf_back, 2, buf_avail);
		if (rep_lens[i] > rep_lens[rep_max_index])
			rep_max_index = i;
	}

	if (rep_lens[rep_max_index] >= nice_len) {
		*back_res = rep_max_index;
		*len_res = rep_lens[rep_max_index];
		mf_skip(mf, *len_res - 1);
		return UINT32_MAX;
	}

	if (len_main >= nice_len) {
		*back_res = coder->matches[matches_count - 1].dist + REPS;
		*len_res = len_main;
		mf_skip(mf, len_main - 1);
		return UINT32_MAX;
	}

	const uint8_t current_byte = *buf;
	const uint8_t match_byte = *(buf - coder->reps[0] - 1);

	if (len_main < 2 && current_byte != match_byte && rep_lens[rep_max_index] < 2) {
		*back_res = UINT32_MAX;
		*len_res = 1;
		return UINT32_MAX;
	}

	coder->opts[0].state = coder->state;
	const uint32_t pos_state = position & coder->pos_mask;

	coder->opts[1].price = rc_bit_0_price(coder->is_match[coder->state][pos_state])
			+ get_literal_price(coder, position, buf[-1], !is_literal_state(coder->state), match_byte, current_byte);
	make_literal(coder->opts[1]);

	const uint32_t match_price = rc_bit_1_price(coder->is_match[coder->state][pos_state]);
	const uint32_t rep_match_price = match_price + rc_bit_1_price(coder->is_rep[coder->state]);

	if (match_byte == current_byte) {
		const uint32_t short_rep_price = rep_match_price + get_short_rep_price(coder, coder->state, pos_state);
		if (short_rep_price < coder->opts[1].price) {
			coder->opts[1].price = short_rep_price;
			make_short_rep(coder->opts[1]);
		}
	}

	const uint32_t len_end = xmax32(len_main, rep_lens[rep_max_index]);
	if (len_end < 2) {
		*back_res = coder->opts[1].back_prev;
		*len_res = 1;
		return UINT32_MAX;
	}

	coder->opts[1].pos_prev = 0;
	for (uint32_t i = 0; i < REPS; ++i)
		coder->opts[0].backs[i] = coder->reps[i];

	uint32_t len = len_end;
	do {
		coder->opts[len].price = RC_INFINITY_PRICE;
	} while (--len >= 2);

	for (uint32_t i = 0; i < REPS; ++i) {
		uint32_t rep_len = rep_lens[i];
		if (rep_len < 2)
			continue;
		const uint32_t price = rep_match_price + get_pure_rep_price(coder, i, coder->state, pos_state);
		do {
			const uint32_t cur_and_len_price = price + get_len_price(&coder->rep_len_encoder, rep_len, pos_state);
			if (cur_and_len_price < coder->opts[rep_len].price) {
				coder->opts[rep_len].price = cur_and_len_price;
				coder->opts[rep_len].pos_prev = 0;
				coder->opts[rep_len].back_prev = i;
				coder->opts[rep_len].prev_1_is_literal = false;
			}
		} while (--rep_len >= 2);
	}

	const uint32_t normal_match_price = match_price + rc_bit_0_price(coder->is_rep[coder->state]);

	len = rep_lens[0] >= 2 ? rep_lens[0] + 1 : 2;
	if (len <= len_main) {
		uint32_t i = 0;
		while (len > coder->matches[i].len)
			++i;
		for (;; ++len) {
			const uint32_t dist = coder->matches[i].dist;
			const uint32_t cur_and_len_price = normal_match_price + get_dist_len_price(coder, dist, len, pos_state);
			if (cur_and_len_price < coder->opts[len].price) {
				coder->opts[len].price = cur_and_len_price;
				coder->opts[len].pos_prev = 0;
				coder->opts[len].back_prev = dist + REPS;
				coder->opts[len].prev_1_is_literal = false;
			}
			if (len == coder->matches[i].len)
				if (++i == matches_count)
					break;
		}
	}
	return len_end;
}

static inline uint32_t helper2(lzma1_enc *coder, uint32_t *reps, const uint8_t *buf,
		uint32_t len_end, uint32_t position, const uint32_t cur,
		const uint32_t nice_len, const uint32_t buf_avail_full)
{
	uint32_t matches_count = coder->matches_count;
	uint32_t new_len = coder->longest_match_length;
	uint32_t pos_prev = coder->opts[cur].pos_prev;
	lzma_state state;

	if (coder->opts[cur].prev_1_is_literal) {
		--pos_prev;
		if (coder->opts[cur].prev_2) {
			state = coder->opts[coder->opts[cur].pos_prev_2].state;
			if (coder->opts[cur].back_prev_2 < REPS)
				state = state_after_long_rep(state);
			else
				state = state_after_match(state);
		} else {
			state = coder->opts[pos_prev].state;
		}
		state = state_after_literal(state);
	} else {
		state = coder->opts[pos_prev].state;
	}

	if (pos_prev == cur - 1) {
		if (is_short_rep(coder->opts[cur]))
			state = state_after_short_rep(state);
		else
			state = state_after_literal(state);
	} else {
		uint32_t pos;
		if (coder->opts[cur].prev_1_is_literal && coder->opts[cur].prev_2) {
			pos_prev = coder->opts[cur].pos_prev_2;
			pos = coder->opts[cur].back_prev_2;
			state = state_after_long_rep(state);
		} else {
			pos = coder->opts[cur].back_prev;
			if (pos < REPS)
				state = state_after_long_rep(state);
			else
				state = state_after_match(state);
		}

		if (pos < REPS) {
			reps[0] = coder->opts[pos_prev].backs[pos];
			uint32_t i;
			for (i = 1; i <= pos; ++i)
				reps[i] = coder->opts[pos_prev].backs[i - 1];
			for (; i < REPS; ++i)
				reps[i] = coder->opts[pos_prev].backs[i];
		} else {
			reps[0] = pos - REPS;
			for (uint32_t i = 1; i < REPS; ++i)
				reps[i] = coder->opts[pos_prev].backs[i - 1];
		}
	}

	coder->opts[cur].state = state;
	for (uint32_t i = 0; i < REPS; ++i)
		coder->opts[cur].backs[i] = reps[i];

	const uint32_t cur_price = coder->opts[cur].price;
	const uint8_t current_byte = *buf;
	const uint8_t match_byte = *(buf - reps[0] - 1);
	const uint32_t pos_state = position & coder->pos_mask;

	const uint32_t cur_and_1_price = cur_price
			+ rc_bit_0_price(coder->is_match[state][pos_state])
			+ get_literal_price(coder, position, buf[-1], !is_literal_state(state), match_byte, current_byte);

	bool next_is_literal = false;
	if (cur_and_1_price < coder->opts[cur + 1].price) {
		coder->opts[cur + 1].price = cur_and_1_price;
		coder->opts[cur + 1].pos_prev = cur;
		make_literal(coder->opts[cur + 1]);
		next_is_literal = true;
	}

	const uint32_t match_price = cur_price + rc_bit_1_price(coder->is_match[state][pos_state]);
	const uint32_t rep_match_price = match_price + rc_bit_1_price(coder->is_rep[state]);

	if (match_byte == current_byte
			&& !(coder->opts[cur + 1].pos_prev < cur && coder->opts[cur + 1].back_prev == 0)) {
		const uint32_t short_rep_price = rep_match_price + get_short_rep_price(coder, state, pos_state);
		if (short_rep_price <= coder->opts[cur + 1].price) {
			coder->opts[cur + 1].price = short_rep_price;
			coder->opts[cur + 1].pos_prev = cur;
			make_short_rep(coder->opts[cur + 1]);
			next_is_literal = true;
		}
	}

	if (buf_avail_full < 2)
		return len_end;

	const uint32_t buf_avail = xmin32(buf_avail_full, nice_len);

	if (!next_is_literal && match_byte != current_byte) {
		const uint8_t *const buf_back = buf - reps[0] - 1;
		const uint32_t limit = xmin32(buf_avail_full, nice_len + 1);
		const uint32_t len_test = memcmplen(buf, buf_back, 1, limit) - 1;

		if (len_test >= 2) {
			lzma_state state_2 = state_after_literal(state);
			const uint32_t pos_state_next = (position + 1) & coder->pos_mask;
			const uint32_t next_rep_match_price = cur_and_1_price
					+ rc_bit_1_price(coder->is_match[state_2][pos_state_next])
					+ rc_bit_1_price(coder->is_rep[state_2]);
			const uint32_t offset = cur + 1 + len_test;
			while (len_end < offset)
				coder->opts[++len_end].price = RC_INFINITY_PRICE;
			const uint32_t cur_and_len_price = next_rep_match_price
					+ get_rep_price(coder, 0, len_test, state_2, pos_state_next);
			if (cur_and_len_price < coder->opts[offset].price) {
				coder->opts[offset].price = cur_and_len_price;
				coder->opts[offset].pos_prev = cur + 1;
				coder->opts[offset].back_prev = 0;
				coder->opts[offset].prev_1_is_literal = true;
				coder->opts[offset].prev_2 = false;
			}
		}
	}

	uint32_t start_len = 2;

	for (uint32_t rep_index = 0; rep_index < REPS; ++rep_index) {
		const uint8_t *const buf_back = buf - reps[rep_index] - 1;
		if (not_equal_16(buf, buf_back))
			continue;

		uint32_t len_test = memcmplen(buf, buf_back, 2, buf_avail);

		while (len_end < cur + len_test)
			coder->opts[++len_end].price = RC_INFINITY_PRICE;

		const uint32_t len_test_temp = len_test;
		const uint32_t price = rep_match_price + get_pure_rep_price(coder, rep_index, state, pos_state);

		do {
			const uint32_t cur_and_len_price = price + get_len_price(&coder->rep_len_encoder, len_test, pos_state);
			if (cur_and_len_price < coder->opts[cur + len_test].price) {
				coder->opts[cur + len_test].price = cur_and_len_price;
				coder->opts[cur + len_test].pos_prev = cur;
				coder->opts[cur + len_test].back_prev = rep_index;
				coder->opts[cur + len_test].prev_1_is_literal = false;
			}
		} while (--len_test >= 2);

		len_test = len_test_temp;

		if (rep_index == 0)
			start_len = len_test + 1;

		uint32_t len_test_2 = len_test + 1;
		const uint32_t limit = xmin32(buf_avail_full, len_test_2 + nice_len);
		if (len_test_2 < limit)
			len_test_2 = memcmplen(buf, buf_back, len_test_2, limit);
		len_test_2 -= len_test + 1;

		if (len_test_2 >= 2) {
			lzma_state state_2 = state_after_long_rep(state);
			state_2 = state_after_literal(state_2);

			uint32_t pos_state_next = (position + len_test) & coder->pos_mask;

			const uint32_t cur_and_len_literal_price = price
					+ get_len_price(&coder->rep_len_encoder, len_test, pos_state)
					+ rc_bit_0_price(coder->is_match[state_2][pos_state_next])
					+ get_literal_price(coder, position + len_test, buf[len_test - 1], true,
						buf_back[len_test], buf[len_test]);

			state_2 = state_after_literal(state_2);
			pos_state_next = (position + len_test + 1) & coder->pos_mask;

			const uint32_t next_rep_match_price = cur_and_len_literal_price
					+ rc_bit_1_price(coder->is_match[state_2][pos_state_next])
					+ rc_bit_1_price(coder->is_rep[state_2]);

			const uint32_t offset = cur + len_test + 1 + len_test_2;
			while (len_end < offset)
				coder->opts[++len_end].price = RC_INFINITY_PRICE;

			const uint32_t cur_and_len_price = next_rep_match_price
					+ get_rep_price(coder, 0, len_test_2, state_2, pos_state_next);

			if (cur_and_len_price < coder->opts[offset].price) {
				coder->opts[offset].price = cur_and_len_price;
				coder->opts[offset].pos_prev = cur + len_test + 1;
				coder->opts[offset].back_prev = 0;
				coder->opts[offset].prev_1_is_literal = true;
				coder->opts[offset].prev_2 = true;
				coder->opts[offset].pos_prev_2 = cur;
				coder->opts[offset].back_prev_2 = rep_index;
			}
		}
	}

	if (new_len > buf_avail) {
		new_len = buf_avail;
		matches_count = 0;
		while (new_len > coder->matches[matches_count].len)
			++matches_count;
		coder->matches[matches_count++].len = new_len;
	}

	if (new_len >= start_len) {
		const uint32_t normal_match_price = match_price + rc_bit_0_price(coder->is_rep[state]);
		while (len_end < cur + new_len)
			coder->opts[++len_end].price = RC_INFINITY_PRICE;

		uint32_t i = 0;
		while (start_len > coder->matches[i].len)
			++i;

		for (uint32_t len_test = start_len;; ++len_test) {
			const uint32_t cur_back = coder->matches[i].dist;
			uint32_t cur_and_len_price = normal_match_price + get_dist_len_price(coder, cur_back, len_test, pos_state);

			if (cur_and_len_price < coder->opts[cur + len_test].price) {
				coder->opts[cur + len_test].price = cur_and_len_price;
				coder->opts[cur + len_test].pos_prev = cur;
				coder->opts[cur + len_test].back_prev = cur_back + REPS;
				coder->opts[cur + len_test].prev_1_is_literal = false;
			}

			if (len_test == coder->matches[i].len) {
				const uint8_t *const buf_back = buf - cur_back - 1;
				uint32_t len_test_2 = len_test + 1;
				const uint32_t limit = xmin32(buf_avail_full, len_test_2 + nice_len);
				if (len_test_2 < limit)
					len_test_2 = memcmplen(buf, buf_back, len_test_2, limit);
				len_test_2 -= len_test + 1;

				if (len_test_2 >= 2) {
					lzma_state state_2 = state_after_match(state);
					uint32_t pos_state_next = (position + len_test) & coder->pos_mask;

					const uint32_t cur_and_len_literal_price = cur_and_len_price
							+ rc_bit_0_price(coder->is_match[state_2][pos_state_next])
							+ get_literal_price(coder, position + len_test, buf[len_test - 1], true,
								buf_back[len_test], buf[len_test]);

					state_2 = state_after_literal(state_2);
					pos_state_next = (pos_state_next + 1) & coder->pos_mask;

					const uint32_t next_rep_match_price = cur_and_len_literal_price
							+ rc_bit_1_price(coder->is_match[state_2][pos_state_next])
							+ rc_bit_1_price(coder->is_rep[state_2]);

					const uint32_t offset = cur + len_test + 1 + len_test_2;
					while (len_end < offset)
						coder->opts[++len_end].price = RC_INFINITY_PRICE;

					cur_and_len_price = next_rep_match_price
							+ get_rep_price(coder, 0, len_test_2, state_2, pos_state_next);

					if (cur_and_len_price < coder->opts[offset].price) {
						coder->opts[offset].price = cur_and_len_price;
						coder->opts[offset].pos_prev = cur + len_test + 1;
						coder->opts[offset].back_prev = 0;
						coder->opts[offset].prev_1_is_literal = true;
						coder->opts[offset].prev_2 = true;
						coder->opts[offset].pos_prev_2 = cur;
						coder->opts[offset].back_prev_2 = cur_back + REPS;
					}
				}

				if (++i == matches_count)
					break;
			}
		}
	}

	return len_end;
}

static void optimum_normal(lzma1_enc *coder, lz_mf *mf, uint32_t *back_res, uint32_t *len_res, uint32_t position)
{
	if (coder->opts_end_index != coder->opts_current_index) {
		*len_res = coder->opts[coder->opts_current_index].pos_prev - coder->opts_current_index;
		*back_res = coder->opts[coder->opts_current_index].back_prev;
		coder->opts_current_index = coder->opts[coder->opts_current_index].pos_prev;
		return;
	}

	if (mf->read_ahead == 0) {
		if (coder->match_price_count >= (1 << 7))
			fill_dist_prices(coder);
		if (coder->align_price_count >= ALIGN_SIZE)
			fill_align_prices(coder);
	}

	uint32_t len_end = helper1(coder, mf, back_res, len_res, position);
	if (len_end == UINT32_MAX)
		return;

	uint32_t reps[REPS];
	memcpy(reps, coder->reps, sizeof(reps));

	uint32_t cur;
	for (cur = 1; cur < len_end; ++cur) {
		coder->longest_match_length = mf_find(mf, &coder->matches_count, coder->matches);
		if (coder->longest_match_length >= mf->nice_len)
			break;
		len_end = helper2(coder, reps, mf_ptr(mf) - 1, len_end, position + cur, cur, mf->nice_len,
				xmin32(mf_avail(mf) + 1, OPTS - 1 - cur));
	}

	backward(coder, len_res, back_res, cur);
}

/* ---------- optimum: fast mode ---------- */

static inline bool change_pair(uint32_t small_dist, uint32_t big_dist)
{
	return (big_dist >> 7) > small_dist;
}

static void optimum_fast(lzma1_enc *coder, lz_mf *mf, uint32_t *back_res, uint32_t *len_res)
{
	const uint32_t nice_len = mf->nice_len;
	uint32_t len_main;
	uint32_t matches_count;

	if (mf->read_ahead == 0) {
		len_main = mf_find(mf, &matches_count, coder->matches);
	} else {
		len_main = coder->longest_match_length;
		matches_count = coder->matches_count;
	}

	const uint8_t *buf = mf_ptr(mf) - 1;
	const uint32_t buf_avail = xmin32(mf_avail(mf) + 1, MATCH_LEN_MAX);

	if (buf_avail < 2) {
		*back_res = UINT32_MAX;
		*len_res = 1;
		return;
	}

	uint32_t rep_len = 0;
	uint32_t rep_index = 0;

	for (uint32_t i = 0; i < REPS; ++i) {
		const uint8_t *const buf_back = buf - coder->reps[i] - 1;
		if (not_equal_16(buf, buf_back))
			continue;
		const uint32_t len = memcmplen(buf, buf_back, 2, buf_avail);
		if (len >= nice_len) {
			*back_res = i;
			*len_res = len;
			mf_skip(mf, len - 1);
			return;
		}
		if (len > rep_len) {
			rep_index = i;
			rep_len = len;
		}
	}

	if (len_main >= nice_len) {
		*back_res = coder->matches[matches_count - 1].dist + REPS;
		*len_res = len_main;
		mf_skip(mf, len_main - 1);
		return;
	}

	uint32_t back_main = 0;
	if (len_main >= 2) {
		back_main = coder->matches[matches_count - 1].dist;
		while (matches_count > 1 && len_main == coder->matches[matches_count - 2].len + 1) {
			if (!change_pair(coder->matches[matches_count - 2].dist, back_main))
				break;
			--matches_count;
			len_main = coder->matches[matches_count - 1].len;
			back_main = coder->matches[matches_count - 1].dist;
		}
		if (len_main == 2 && back_main >= 0x80)
			len_main = 1;
	}

	if (rep_len >= 2) {
		if (rep_len + 1 >= len_main
				|| (rep_len + 2 >= len_main && back_main > (UINT32_C(1) << 9))
				|| (rep_len + 3 >= len_main && back_main > (UINT32_C(1) << 15))) {
			*back_res = rep_index;
			*len_res = rep_len;
			mf_skip(mf, rep_len - 1);
			return;
		}
	}

	if (len_main < 2 || buf_avail <= 2) {
		*back_res = UINT32_MAX;
		*len_res = 1;
		return;
	}

	coder->longest_match_length = mf_find(mf, &coder->matches_count, coder->matches);

	if (coder->longest_match_length >= 2) {
		const uint32_t new_dist = coder->matches[coder->matches_count - 1].dist;
		if ((coder->longest_match_length >= len_main && new_dist < back_main)
				|| (coder->longest_match_length == len_main + 1 && !change_pair(back_main, new_dist))
				|| (coder->longest_match_length > len_main + 1)
				|| (coder->longest_match_length + 1 >= len_main && len_main >= 3
					&& change_pair(new_dist, back_main))) {
			*back_res = UINT32_MAX;
			*len_res = 1;
			return;
		}
	}

	++buf;
	const uint32_t limit = xmax32(2, len_main - 1);
	for (uint32_t i = 0; i < REPS; ++i) {
		if (memcmp(buf, buf - coder->reps[i] - 1, limit) == 0) {
			*back_res = UINT32_MAX;
			*len_res = 1;
			return;
		}
	}

	*back_res = back_main + REPS;
	*len_res = len_main;
	mf_skip(mf, len_main - 2);
}

/* ---------- symbol encoding ---------- */

static inline void literal_matched(rc_enc *rc, prob_t *subcoder, uint32_t match_byte, uint32_t symbol)
{
	uint32_t offset = 0x100;
	symbol += UINT32_C(1) << 8;
	do {
		match_byte <<= 1;
		const uint32_t match_bit = match_byte & offset;
		const uint32_t subcoder_index = offset + match_bit + (symbol >> 8);
		const uint32_t bit = (symbol >> 7) & 1;
		rc_bit(rc, &subcoder[subcoder_index], bit);
		symbol <<= 1;
		offset &= ~(match_byte ^ symbol);
	} while (symbol < (UINT32_C(1) << 16));
}

static inline void encode_literal(lzma1_enc *coder, lz_mf *mf, uint32_t position)
{
	const uint8_t cur_byte = mf->buffer[mf->read_pos - mf->read_ahead];
	prob_t *subcoder = literal_subcoder(coder->literal, coder->literal_context_bits, coder->literal_pos_mask,
			position, mf->buffer[mf->read_pos - mf->read_ahead - 1]);
	if (is_literal_state(coder->state)) {
		rc_bittree(&coder->rc, subcoder, 8, cur_byte);
	} else {
		const uint8_t match_byte = mf->buffer[mf->read_pos - coder->reps[0] - 1 - mf->read_ahead];
		literal_matched(&coder->rc, subcoder, match_byte, cur_byte);
	}
	coder->state = state_after_literal(coder->state);
}

static void length_update_prices(len_encoder *lc, uint32_t pos_state)
{
	const uint32_t table_size = lc->table_size;
	lc->counters[pos_state] = table_size;
	const uint32_t a0 = rc_bit_0_price(lc->choice);
	const uint32_t a1 = rc_bit_1_price(lc->choice);
	const uint32_t b0 = a1 + rc_bit_0_price(lc->choice2);
	const uint32_t b1 = a1 + rc_bit_1_price(lc->choice2);
	uint32_t *const prices = lc->prices[pos_state];
	uint32_t i;
	for (i = 0; i < table_size && i < LEN_LOW_SYMBOLS; ++i)
		prices[i] = a0 + rc_bittree_price(lc->low[pos_state], LEN_LOW_BITS, i);
	for (; i < table_size && i < LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS; ++i)
		prices[i] = b0 + rc_bittree_price(lc->mid[pos_state], LEN_MID_BITS, i - LEN_LOW_SYMBOLS);
	for (; i < table_size; ++i)
		prices[i] = b1 + rc_bittree_price(lc->high, LEN_HIGH_BITS, i - LEN_LOW_SYMBOLS - LEN_MID_SYMBOLS);
}

static inline void encode_length(rc_enc *rc, len_encoder *lc, uint32_t pos_state, uint32_t len, bool fast_mode)
{
	len -= MATCH_LEN_MIN;
	if (len < LEN_LOW_SYMBOLS) {
		rc_bit(rc, &lc->choice, 0);
		rc_bittree(rc, lc->low[pos_state], LEN_LOW_BITS, len);
	} else {
		rc_bit(rc, &lc->choice, 1);
		len -= LEN_LOW_SYMBOLS;
		if (len < LEN_MID_SYMBOLS) {
			rc_bit(rc, &lc->choice2, 0);
			rc_bittree(rc, lc->mid[pos_state], LEN_MID_BITS, len);
		} else {
			rc_bit(rc, &lc->choice2, 1);
			len -= LEN_MID_SYMBOLS;
			rc_bittree(rc, lc->high, LEN_HIGH_BITS, len);
		}
	}
	if (!fast_mode)
		if (--lc->counters[pos_state] == 0)
			length_update_prices(lc, pos_state);
}

static inline void encode_match(lzma1_enc *coder, uint32_t pos_state, uint32_t distance, uint32_t len)
{
	coder->state = state_after_match(coder->state);
	encode_length(&coder->rc, &coder->match_len_encoder, pos_state, len, coder->fast_mode);

	const uint32_t dist_slot = get_dist_slot(distance);
	const uint32_t dist_state = get_dist_state(len);
	rc_bittree(&coder->rc, coder->dist_slot[dist_state], DIST_SLOT_BITS, dist_slot);

	if (dist_slot >= DIST_MODEL_START) {
		const uint32_t footer_bits = (dist_slot >> 1) - 1;
		const uint32_t base = (2 | (dist_slot & 1)) << footer_bits;
		const uint32_t dist_reduced = distance - base;
		if (dist_slot < DIST_MODEL_END) {
			rc_bittree_reverse(&coder->rc, coder->dist_special + base - dist_slot - 1, footer_bits, dist_reduced);
		} else {
			rc_direct(&coder->rc, dist_reduced >> ALIGN_BITS, footer_bits - ALIGN_BITS);
			rc_bittree_reverse(&coder->rc, coder->dist_align, ALIGN_BITS, dist_reduced & ALIGN_MASK);
			++coder->align_price_count;
		}
	}

	coder->reps[3] = coder->reps[2];
	coder->reps[2] = coder->reps[1];
	coder->reps[1] = coder->reps[0];
	coder->reps[0] = distance;
	++coder->match_price_count;
}

static inline void encode_rep_match(lzma1_enc *coder, uint32_t pos_state, uint32_t rep, uint32_t len)
{
	if (rep == 0) {
		rc_bit(&coder->rc, &coder->is_rep0[coder->state], 0);
		rc_bit(&coder->rc, &coder->is_rep0_long[coder->state][pos_state], len != 1);
	} else {
		const uint32_t distance = coder->reps[rep];
		rc_bit(&coder->rc, &coder->is_rep0[coder->state], 1);
		if (rep == 1) {
			rc_bit(&coder->rc, &coder->is_rep1[coder->state], 0);
		} else {
			rc_bit(&coder->rc, &coder->is_rep1[coder->state], 1);
			rc_bit(&coder->rc, &coder->is_rep2[coder->state], rep - 2);
			if (rep == 3)
				coder->reps[3] = coder->reps[2];
			coder->reps[2] = coder->reps[1];
		}
		coder->reps[1] = coder->reps[0];
		coder->reps[0] = distance;
	}

	if (len == 1) {
		coder->state = state_after_short_rep(coder->state);
	} else {
		encode_length(&coder->rc, &coder->rep_len_encoder, pos_state, len, coder->fast_mode);
		coder->state = state_after_long_rep(coder->state);
	}
}

static void encode_symbol(lzma1_enc *coder, lz_mf *mf, uint32_t back, uint32_t len, uint32_t position)
{
	const uint32_t pos_state = position & coder->pos_mask;
	if (back == UINT32_MAX) {
		rc_bit(&coder->rc, &coder->is_match[coder->state][pos_state], 0);
		encode_literal(coder, mf, position);
	} else {
		rc_bit(&coder->rc, &coder->is_match[coder->state][pos_state], 1);
		if (back < REPS) {
			rc_bit(&coder->rc, &coder->is_rep[coder->state], 1);
			encode_rep_match(coder, pos_state, back, len);
		} else {
			rc_bit(&coder->rc, &coder->is_rep[coder->state], 0);
			encode_match(coder, pos_state, back - REPS, len);
		}
	}
	mf->read_ahead -= len;
}

static bool encode_init(lzma1_enc *coder, lz_mf *mf)
{
	if (mf->read_pos == mf->read_limit) {
		if (mf->action == A_RUN)
			return false;
	} else {
		mf_skip(mf, 1);
		mf->read_ahead = 0;
		rc_bit(&coder->rc, &coder->is_match[0][0], 0);
		rc_bittree(&coder->rc, coder->literal, 8, mf->buffer[0]);
	}
	coder->is_initialized = true;
	return true;
}

static void encode_eopm(lzma1_enc *coder, uint32_t position)
{
	const uint32_t pos_state = position & coder->pos_mask;
	rc_bit(&coder->rc, &coder->is_match[coder->state][pos_state], 1);
	rc_bit(&coder->rc, &coder->is_rep[coder->state], 0);
	encode_match(coder, pos_state, UINT32_MAX, MATCH_LEN_MIN);
}

/* Minimum amount of free space in the output buffer before we refuse to
 * encode another symbol in LZMA1 mode. A single symbol plus the range
 * coder's pending bytes can never exceed this. */
#define LZMA1_OUT_SLACK 1024

xret lzma1_encode(lzma1_enc *coder, lz_mf *mf, uint8_t *out, size_t *out_pos, size_t out_size, uint32_t limit)
{
	coder->rc.out = out;
	coder->rc.out_pos = *out_pos;
	coder->rc.out_size = out_size;

	if (!coder->is_initialized && !encode_init(coder, mf)) {
		*out_pos = coder->rc.out_pos;
		return R_OK;
	}

	uint32_t position = mf_position(mf);

	while (true) {
		if (limit != UINT32_MAX
				&& (mf->read_pos - mf->read_ahead >= limit
					|| coder->rc.out_pos + rc_pending(&coder->rc) >= LZMA2_CHUNK_MAX - LOOP_INPUT_MAX))
			break;

		if (limit == UINT32_MAX && coder->rc.out_pos + LZMA1_OUT_SLACK >= out_size) {
			*out_pos = coder->rc.out_pos;
			return R_OK;
		}

		if (mf->read_pos >= mf->read_limit) {
			if (mf->action == A_RUN) {
				*out_pos = coder->rc.out_pos;
				return R_OK;
			}
			if (mf->read_ahead == 0)
				break;
		}

		uint32_t len;
		uint32_t back;
		if (coder->fast_mode)
			optimum_fast(coder, mf, &back, &len);
		else
			optimum_normal(coder, mf, &back, &len, position);

		encode_symbol(coder, mf, back, len, position);
		position += len;
	}

	if (!coder->is_flushed) {
		coder->is_flushed = true;
		if (limit == UINT32_MAX)
			encode_eopm(coder, position);
		rc_flush(&coder->rc);
	}

	coder->is_flushed = false;
	*out_pos = coder->rc.out_pos;
	return R_STREAM_END;
}

/* ---------- init / reset ---------- */

bool lzma_options_valid(const lzma_options *o)
{
	return o->lc <= LZMA_LCLP_MAX && o->lp <= LZMA_LCLP_MAX && o->lc + o->lp <= LZMA_LCLP_MAX
			&& o->pb <= LZMA_PB_MAX
			&& o->nice_len >= MATCH_LEN_MIN && o->nice_len <= MATCH_LEN_MAX
			&& (o->mode == MODE_FAST || o->mode == MODE_NORMAL);
}

static uint32_t mf_hash_bytes(lzma_mf_t m) { return (uint32_t)m & 0x0F; }

void lzma_set_lz_options(lz_options *lz, const lzma_options *o)
{
	lz->before_size = OPTS;
	lz->dict_size = o->dict_size;
	lz->after_size = LOOP_INPUT_MAX;
	lz->match_len_max = MATCH_LEN_MAX;
	lz->nice_len = xmax32(mf_hash_bytes(o->mf), o->nice_len);
	lz->match_finder = o->mf;
	lz->depth = o->depth;
	lz->preset_dict = o->preset_dict;
	lz->preset_dict_size = o->preset_dict_size;
}

static void length_encoder_reset(len_encoder *lc, uint32_t num_pos_states, bool fast_mode)
{
	lc->choice = PROB_INIT;
	lc->choice2 = PROB_INIT;
	for (size_t ps = 0; ps < num_pos_states; ++ps) {
		probs_reset(lc->low[ps], LEN_LOW_SYMBOLS);
		probs_reset(lc->mid[ps], LEN_MID_SYMBOLS);
	}
	probs_reset(lc->high, LEN_HIGH_SYMBOLS);
	if (!fast_mode)
		for (uint32_t ps = 0; ps < num_pos_states; ++ps)
			length_update_prices(lc, ps);
}

xret lzma1_enc_reset(lzma1_enc *coder, const lzma_options *o)
{
	if (!lzma_options_valid(o))
		return R_OPTIONS_ERROR;

	coder->pos_mask = (1U << o->pb) - 1;
	coder->literal_context_bits = o->lc;
	coder->literal_pos_mask = (1U << o->lp) - 1;

	rc_enc_reset(&coder->rc);
	coder->state = STATE_LIT_LIT;
	for (size_t i = 0; i < REPS; ++i)
		coder->reps[i] = 0;

	probs_reset(coder->literal, (size_t)LITERAL_CODER_SIZE << (o->lc + o->lp));

	for (size_t i = 0; i < STATES; ++i) {
		for (size_t j = 0; j <= coder->pos_mask; ++j) {
			coder->is_match[i][j] = PROB_INIT;
			coder->is_rep0_long[i][j] = PROB_INIT;
		}
		coder->is_rep[i] = PROB_INIT;
		coder->is_rep0[i] = PROB_INIT;
		coder->is_rep1[i] = PROB_INIT;
		coder->is_rep2[i] = PROB_INIT;
	}
	probs_reset(coder->dist_special, FULL_DISTANCES - DIST_MODEL_END);
	for (size_t i = 0; i < DIST_STATES; ++i)
		probs_reset(coder->dist_slot[i], DIST_SLOTS);
	probs_reset(coder->dist_align, ALIGN_SIZE);

	length_encoder_reset(&coder->match_len_encoder, 1U << o->pb, coder->fast_mode);
	length_encoder_reset(&coder->rep_len_encoder, 1U << o->pb, coder->fast_mode);

	coder->match_price_count = UINT32_MAX / 2;
	coder->align_price_count = UINT32_MAX / 2;
	coder->opts_end_index = 0;
	coder->opts_current_index = 0;
	return R_OK;
}

xret lzma1_enc_create(lzma1_enc **coder_ptr, const lzma_options *o, lz_options *lz)
{
	rc_prices_init();
	if (*coder_ptr == NULL) {
		*coder_ptr = malloc(sizeof(lzma1_enc));
		if (*coder_ptr == NULL)
			return R_MEM_ERROR;
	}
	lzma1_enc *coder = *coder_ptr;

	switch (o->mode) {
	case MODE_FAST:
		coder->fast_mode = true;
		break;
	case MODE_NORMAL: {
		coder->fast_mode = false;
		if (o->dict_size > LZ_DICT_SIZE_MAX)
			return R_OPTIONS_ERROR;
		uint32_t log_size = 0;
		while ((UINT32_C(1) << log_size) < o->dict_size)
			++log_size;
		coder->dist_table_size = log_size * 2;
		const uint32_t nice_len = xmax32(mf_hash_bytes(o->mf), o->nice_len);
		coder->match_len_encoder.table_size = nice_len + 1 - MATCH_LEN_MIN;
		coder->rep_len_encoder.table_size = nice_len + 1 - MATCH_LEN_MIN;
		break;
	}
	default:
		return R_OPTIONS_ERROR;
	}

	if (!lz_mf_is_supported(o->mf))
		return R_OPTIONS_ERROR;

	coder->is_initialized = false;
	coder->is_flushed = false;
	lzma_set_lz_options(lz, o);
	return lzma1_enc_reset(coder, o);
}

uint64_t lzma1_enc_memusage(const lzma_options *o)
{
	if (!lzma_options_valid(o))
		return UINT64_MAX;
	lz_options lz;
	lzma_set_lz_options(&lz, o);
	const uint64_t lz_memusage = lz_mf_memusage(&lz);
	if (lz_memusage == UINT64_MAX)
		return UINT64_MAX;
	return lz_memusage;
}
