	lz_encoder *coder = ctx;
	while (*out_pos < out_size && (*in_pos < in_size || action != A_RUN)) {
		if (coder->mf.action == A_RUN && coder->mf.read_pos >= coder->mf.read_limit)
			lz_mf_fill_window(&coder->mf, in, in_pos, in_size, action);

