		}
	}
	if (lz_mf_prepare(&coder->mf, &coder->lz_opt) || lz_mf_init(&coder->mf, &coder->lz_opt)) {
		lz_encoder_end(coder);
		return R_OPTIONS_ERROR;
	}
	c->ctx = coder;
	c->code = lz_encode;
	c->end = lz_encoder_end;
	return R_OK;
}

xret lzma2_encoder_init(xcoder *c, const lzma_options *o)
{
	if (o == NULL)
		return R_PROG_ERROR;
	return lz_encoder_init(c, o, true);
}

xret lzma1_encoder_init(xcoder *c, const lzma_options *o)
{
	if (o == NULL)
		return R_PROG_ERROR;
	return lz_encoder_init(c, o, false);
}

uint64_t lzma2_encoder_memusage(const lzma_options *o)
{
	if (!lzma_options_valid(o))
		return UINT64_MAX;
	lz_options lz;
	lzma_set_lz_options(&lz, o);
	if (lz.before_size + lz.dict_size < LZMA2_CHUNK_MAX)
		lz.before_size = LZMA2_CHUNK_MAX - lz.dict_size;
	const uint64_t m = lz_mf_memusage(&lz);
	if (m == UINT64_MAX)
		return UINT64_MAX;
	return m + LZMA2_ENC_STRUCT_MEMUSAGE;
}

uint64_t lzma1_encoder_memusage(const lzma_options *o)
{
	const uint64_t m = lzma1_enc_memusage(o);
	if (m == UINT64_MAX)
		return UINT64_MAX;
	return m + LZMA1_ENC_STRUCT_MEMUSAGE;
}

uint64_t lzma2_block_size(const lzma_options *o)
{
	const uint64_t a = (uint64_t)o->dict_size * 3;
	return a > (UINT64_C(1) << 20) ? a : (UINT64_C(1) << 20);
}

static inline uint32_t dist_slot_of(uint32_t dist)
{
	if (dist < 4)
		return dist;
	const uint32_t i = bsr32(dist);
	return (i + i) + ((dist >> (i - 1)) & 1);
}

bool lzma2_props_encode(const lzma_options *o, uint8_t *out)
{
	uint32_t d = xmax32(o->dict_size, LZMA_DICT_SIZE_MIN);
	--d;
	d |= d >> 2;
	d |= d >> 3;
	d |= d >> 4;
	d |= d >> 8;
	d |= d >> 16;
	if (d == UINT32_MAX)
		out[0] = 40;
	else
		out[0] = (uint8_t)(dist_slot_of(d + 1) - 24);
	return false;
}

bool lzma1_props_encode(const lzma_options *o, uint8_t *out)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return true;
	out[0] = lzma_lclppb_encode(o);
	write32le(out + 1, o->dict_size);
	return false;
}
