#include "lzma_dec.h"

void (*lzma_dec_trace)(uint32_t back, uint32_t len, uint64_t pos) = NULL;

/* Memory usage constants chosen to match the reference implementation's
 * reported numbers. */
#define LZMA2_DEC_STRUCT_MEMUSAGE 33432
#define LZMA1_DEC_STRUCT_MEMUSAGE 33432

/* ---------- dictionary ---------- */

static inline void dict_reset(lz_dict *d)
{
	d->need_reset = true;
}

static inline bool dict_is_distance_valid(const lz_dict *d, size_t dist)
{
	return d->full > dist;
}

static inline uint8_t dict_get(const lz_dict *d, uint32_t dist)
{
	return d->buf[d->pos - dist - 1 + (dist < d->pos ? 0 : d->size)];
}

static inline bool dict_is_empty(const lz_dict *d) { return d->full == 0; }

static inline void dict_put(lz_dict *d, uint8_t b)
{
	d->buf[d->pos++] = b;
	if (d->full < d->pos)
		d->full = d->pos;
}

/* Repeat `len` bytes from distance. Returns true if more remains (limit hit). */
static inline bool dict_repeat(lz_dict *d, uint32_t dist, uint32_t *len)
{
	const size_t dict_avail = d->limit - d->pos;
	uint32_t left = xmin32(*len, (uint32_t)dict_avail);
	*len -= left;
	size_t back = d->pos - dist - 1;
	if (dist >= d->pos)
		back += d->size;
	do {
		d->buf[d->pos++] = d->buf[back++];
		if (back == d->size)
			back = 0;
	} while (--left > 0);
	if (d->full < d->pos)
		d->full = d->pos;
	return *len != 0;
}

static inline void dict_write(lz_dict *d, const uint8_t *in, size_t *in_pos, size_t in_size, size_t *left)
{
	if (in_size - *in_pos > *left)
		in_size = *in_pos + *left;
	*left -= bufcpy(in, in_pos, in_size, d->buf, &d->pos, d->limit);
	if (d->pos > d->full)
		d->full = d->pos;
}

/* ---------- LZMA1 decoder ---------- */

typedef struct {
	prob_t choice;
	prob_t choice2;
	prob_t low[POS_STATES_MAX][LEN_LOW_SYMBOLS];
	prob_t mid[POS_STATES_MAX][LEN_MID_SYMBOLS];
	prob_t high[LEN_HIGH_SYMBOLS];
} len_decoder;

typedef struct {
	rc_dec rc;
	lzma_state state;
	uint32_t rep0, rep1, rep2, rep3;
	uint32_t pos_mask;
	uint32_t literal_context_bits;
	uint32_t literal_pos_mask;

	prob_t literal[LITERAL_CODERS_MAX * LITERAL_CODER_SIZE];
	prob_t is_match[STATES][POS_STATES_MAX];
	prob_t is_rep[STATES];
	prob_t is_rep0[STATES];
	prob_t is_rep1[STATES];
	prob_t is_rep2[STATES];
	prob_t is_rep0_long[STATES][POS_STATES_MAX];
	prob_t dist_slot[DIST_STATES][DIST_SLOTS];
	prob_t dist_special[FULL_DISTANCES - DIST_MODEL_END];
	prob_t dist_align[ALIGN_SIZE];
	len_decoder match_len_decoder;
	len_decoder rep_len_decoder;

	uint64_t uncompressed_size;
	bool allow_eopm;

	/* Pending match copy. */
	uint32_t pending_len;
	uint64_t total_pos; /* for trace */

	/* Input staging so that a whole symbol can always be decoded from
	 * contiguous memory. */
	uint8_t temp[256];
	size_t temp_size;
} lzma1_dec;

#define SYMBOL_IN_MAX 64

static void lzma1_dec_reset(lzma1_dec *d, const lzma_options *o)
{
	d->pos_mask = (1U << o->pb) - 1;
	d->literal_context_bits = o->lc;
	d->literal_pos_mask = (1U << o->lp) - 1;
	probs_reset(d->literal, (size_t)LITERAL_CODER_SIZE << (o->lc + o->lp));
	PROBS_RESET(d->is_match);
	PROBS_RESET(d->is_rep);
	PROBS_RESET(d->is_rep0);
	PROBS_RESET(d->is_rep1);
	PROBS_RESET(d->is_rep2);
	PROBS_RESET(d->is_rep0_long);
	PROBS_RESET(d->dist_slot);
	PROBS_RESET(d->dist_special);
	PROBS_RESET(d->dist_align);
	PROBS_RESET(d->match_len_decoder);
	PROBS_RESET(d->rep_len_decoder);
	d->state = STATE_LIT_LIT;
	d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
	d->pending_len = 0;
	rc_dec_reset(&d->rc);
	d->temp_size = 0;
}

/* Range decoder primitives operating on a local copy. */
typedef struct {
	uint32_t range;
	uint32_t code;
	const uint8_t *in;
	size_t in_pos;
} rcl;

static inline void rcl_normalize(rcl *r)
{
	if (r->range < RC_TOP_VALUE) {
		r->range <<= RC_SHIFT_BITS;
		r->code = (r->code << RC_SHIFT_BITS) | r->in[r->in_pos++];
	}
}

static inline uint32_t rcl_bit(rcl *r, prob_t *prob)
{
	rcl_normalize(r);
	const uint32_t bound = (r->range >> RC_BIT_MODEL_TOTAL_BITS) * *prob;
	if (r->code < bound) {
		r->range = bound;
		*prob += (RC_BIT_MODEL_TOTAL - *prob) >> RC_MOVE_BITS;
		return 0;
	}
	r->range -= bound;
	r->code -= bound;
	*prob -= *prob >> RC_MOVE_BITS;
	return 1;
}

static inline uint32_t rcl_bittree(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	do {
		symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
	} while (--bits != 0);
	return symbol - (1U << (symbol ? 0 : 0)) ; /* placeholder, fixed below */
}

static inline uint32_t rcl_bittree_n(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
	return symbol - (1U << bits);
}

static inline uint32_t rcl_bittree_reverse(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	uint32_t result = 0;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rcl_bit(r, &probs[symbol]);
		symbol = (symbol << 1) | bit;
		result |= bit << i;
	}
	return result;
}

static inline uint32_t rcl_direct(rcl *r, uint32_t bits)
{
	uint32_t result = 0;
	do {
		rcl_normalize(r);
		r->range >>= 1;
		r->code -= r->range;
		const uint32_t t = 0 - (r->code >> 31);
		r->code += r->range & t;
		result = (result << 1) + (t + 1);
	} while (--bits != 0);
	return result;
}

static inline uint32_t decode_len(rcl *r, len_decoder *ld, uint32_t pos_state)
{
	if (rcl_bit(r, &ld->choice) == 0)
		return MATCH_LEN_MIN + rcl_bittree_n(r, ld->low[pos_state], LEN_LOW_BITS);
	if (rcl_bit(r, &ld->choice2) == 0)
		return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + rcl_bittree_n(r, ld->mid[pos_state], LEN_MID_BITS);
	return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + rcl_bittree_n(r, ld->high, LEN_HIGH_BITS);
}

/* Decode one symbol from contiguous input `in` (at least SYMBOL_IN_MAX bytes
 * available or the stream is known to end). Writes into dict. Returns:
 *  0 = symbol decoded (dict updated, possibly pending_len set)
 *  1 = end of payload marker
 *  2 = data error
 * Updates rc and in_pos through r. */
static int decode_symbol(lzma1_dec *d, rcl *r, lz_dict *dict)
{
	const uint32_t pos_state = (uint32_t)dict->pos & d->pos_mask;
	lzma_state state = d->state;

	if (rcl_bit(r, &d->is_match[state][pos_state]) == 0) {
		/* literal */
		const uint8_t prev = dict_is_empty(dict) ? 0 : dict_get(dict, 0);
		prob_t *probs = literal_subcoder(d->literal, d->literal_context_bits, d->literal_pos_mask,
				(uint32_t)dict->pos, prev);
		uint32_t symbol = 1;
		if (is_literal_state(state)) {
			for (int i = 0; i < 8; ++i)
				symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
		} else {
			uint32_t match_byte = dict_get(dict, d->rep0);
			uint32_t offset = 0x100;
			do {
				match_byte <<= 1;
				const uint32_t match_bit = match_byte & offset;
				const uint32_t idx = offset + match_bit + symbol;
				const uint32_t bit = rcl_bit(r, &probs[idx]);
				symbol = (symbol << 1) | bit;
				if (bit)
					offset &= match_bit;
				else
					offset &= ~match_bit;
			} while (symbol < 0x100);
		}
		dict_put(dict, (uint8_t)symbol);
		d->state = state_after_literal(state);
		if (lzma_dec_trace)
			lzma_dec_trace(UINT32_MAX, 1, d->total_pos);
		d->total_pos += 1;
		return 0;
	}

	uint32_t len;
	uint32_t back;
	if (rcl_bit(r, &d->is_rep[state]) == 0) {
		/* match */
		len = decode_len(r, &d->match_len_decoder, pos_state);
		const uint32_t dist_slot = rcl_bittree_n(r, d->dist_slot[get_dist_state(len)], DIST_SLOT_BITS);
		uint32_t rep0;
		if (dist_slot < DIST_MODEL_START) {
			rep0 = dist_slot;
		} else {
			const uint32_t limit = (dist_slot >> 1) - 1;
			rep0 = 2 + (dist_slot & 1);
			if (dist_slot < DIST_MODEL_END) {
				rep0 <<= limit;
				rep0 += rcl_bittree_reverse(r, d->dist_special + rep0 - dist_slot - 1, limit);
			} else {
				rep0 <<= limit;
				rep0 += rcl_direct(r, limit - ALIGN_BITS) << ALIGN_BITS;
				rep0 += rcl_bittree_reverse(r, d->dist_align, ALIGN_BITS);
				if (rep0 == UINT32_MAX) {
					/* end of payload marker */
					if (!d->allow_eopm)
						return 2;
					d->state = state_after_match(state);
					return 1;
				}
			}
		}
		d->rep3 = d->rep2;
		d->rep2 = d->rep1;
		d->rep1 = d->rep0;
		d->rep0 = rep0;
		d->state = state_after_match(state);
		back = rep0 + REPS;
	} else {
		if (rcl_bit(r, &d->is_rep0[state]) == 0) {
			if (rcl_bit(r, &d->is_rep0_long[state][pos_state]) == 0) {
				/* short rep */
				if (dict_is_empty(dict))
					return 2;
				d->state = state_after_short_rep(state);
				len = 1;
				if (!dict_is_distance_valid(dict, d->rep0))
					return 2;
				dict_put(dict, dict_get(dict, d->rep0));
				if (lzma_dec_trace)
					lzma_dec_trace(0, 1, d->total_pos);
				d->total_pos += 1;
				return 0;
			}
			back = 0;
		} else {
			uint32_t dist;
			if (rcl_bit(r, &d->is_rep1[state]) == 0) {
				dist = d->rep1;
				back = 1;
			} else {
				if (rcl_bit(r, &d->is_rep2[state]) == 0) {
					dist = d->rep2;
					back = 2;
				} else {
					dist = d->rep3;
					d->rep3 = d->rep2;
					back = 3;
				}
				d->rep2 = d->rep1;
			}
			d->rep1 = d->rep0;
			d->rep0 = dist;
		}
		len = decode_len(r, &d->rep_len_decoder, pos_state);
		d->state = state_after_long_rep(state);
	}

	if (!dict_is_distance_valid(dict, d->rep0))
		return 2;
	if (lzma_dec_trace)
		lzma_dec_trace(back, len, d->total_pos);
	d->total_pos += len;
	d->pending_len = len;
	return 0;
}

/* Decode as much as possible. dict->limit must be set by the caller.
 * Returns R_OK (need more input or output full), R_STREAM_END (eopm or
 * uncompressed_size reached), R_DATA_ERROR. */
static xret lzma1_decode(lzma1_dec *d, lz_dict *dict, const uint8_t *in, size_t *in_pos, size_t in_size, bool finishing)
{
	/* Range decoder init. */
	if (d->rc.init_bytes_left > 0) {
		bool err = false;
		if (!rc_dec_read_init(&d->rc, in, in_pos, in_size, &err))
			return R_OK;
		if (err)
			return R_DATA_ERROR;
	}

	/* Limit the dictionary by uncompressed_size. */
	if (d->uncompressed_size != VLI_UNKNOWN && dict->limit - dict->pos > d->uncompressed_size)
		dict->limit = dict->pos + (size_t)d->uncompressed_size;

	while (true) {
		/* Finish pending match copy. */
		if (d->pending_len > 0) {
			if (dict->pos >= dict->limit)
				break;
			if (dict_repeat(dict, d->rep0, &d->pending_len))
				break; /* limit hit */
			continue;
		}

		if (dict->pos >= dict->limit)
			break;

		/* Check for end by uncompressed size. */
		if (d->uncompressed_size != VLI_UNKNOWN) {
			/* uncompressed_size is tracked via dict progress below. */
		}

		/* Make sure we have enough contiguous input. */
		rcl r;
		r.range = d->rc.range;
		r.code = d->rc.code;
		bool from_temp = false;
		size_t avail = in_size - *in_pos;
		if (d->temp_size > 0 || (avail < SYMBOL_IN_MAX && !finishing)) {
			/* Fill temp. */
			size_t want = SYMBOL_IN_MAX - d->temp_size;
			if (want > avail)
				want = avail;
			memcpy(d->temp + d->temp_size, in + *in_pos, want);
			d->temp_size += want;
			*in_pos += want;
			if (d->temp_size < SYMBOL_IN_MAX && !finishing)
				return R_OK; /* need more input */
			/* Pad for safety when finishing. */
			memset(d->temp + d->temp_size, 0, sizeof(d->temp) - d->temp_size);
			r.in = d->temp;
			r.in_pos = 0;
			from_temp = true;
		} else {
			r.in = in;
			r.in_pos = *in_pos;
		}

		const int res = decode_symbol(d, &r, dict);

		/* Commit input position. */
		if (from_temp) {
			if (r.in_pos > d->temp_size) {
				/* Read past the available data: truncated input. */
				return R_DATA_ERROR;
			}
			/* Remove consumed bytes from temp. */
			memmove(d->temp, d->temp + r.in_pos, d->temp_size - r.in_pos);
			d->temp_size -= r.in_pos;
		} else {
			if (r.in_pos > in_size)
				return R_DATA_ERROR;
			*in_pos = r.in_pos;
		}
		d->rc.range = r.range;
		d->rc.code = r.code;

		if (res == 2)
			return R_DATA_ERROR;
		if (res == 1) {
			/* EOPM */
			if (d->uncompressed_size != VLI_UNKNOWN && d->uncompressed_size != 0)
				return R_DATA_ERROR;
			d->uncompressed_size = 0;
			goto finished;
		}
	}

	/* Track uncompressed size. */
	if (d->uncompressed_size != VLI_UNKNOWN) {
		/* Computed by caller via dict progress; handled below. */
	}
	return R_OK;

finished:
	/* The range decoder must have code == 0 at the end. */
	if (d->rc.code != 0)
		return R_DATA_ERROR;
	return R_STREAM_END;
}

/* ---------- LZ decoder wrapper (LZMA1) ---------- */

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	uint64_t uncompressed_left; /* VLI_UNKNOWN if unknown */
	bool eopm_seen;
	bool finished;
	/* temp for data not yet copied out */
} lz1_coder;

static xret lz1_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lz1_coder *c = ctx;
	lz_dict *dict = &c->dict;
	(void)action;

	if (dict->need_reset) {
		dict->pos = 0;
		dict->full = 0;
		dict->buf[dict->size - 1] = 0;
		dict->need_reset = false;
	}

	while (true) {
		/* Copy out what is already decoded but not yet output. */
		const size_t dict_start = dict->pos;
		/* Set the limit. */
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;

		if (c->finished) {
			return R_STREAM_END;
		}

		if (dict->limit == dict->pos) {
			/* Output full or dictionary wrapped. */
			if (dict->pos == dict->size)
				dict->pos = 0;
			if (*out_pos == out_size)
				return R_OK;
			continue;
		}

		/* Apply uncompressed size limit. */
		if (c->lzma->uncompressed_size != VLI_UNKNOWN) {
			if (c->lzma->uncompressed_size == 0 && !c->lzma->allow_eopm) {
				c->finished = true;
				return R_STREAM_END;
			}
			if (dict->limit - dict->pos > c->lzma->uncompressed_size)
				dict->limit = dict->pos + (size_t)c->lzma->uncompressed_size;
		}

		const xret ret = lzma1_decode(c->lzma, dict, in, in_pos, in_size, action == A_FINISH);
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;
		if (c->lzma->uncompressed_size != VLI_UNKNOWN && ret != R_STREAM_END)
			c->lzma->uncompressed_size -= produced;

		if (ret == R_STREAM_END) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (ret != R_OK)
			return ret;

		if (c->lzma->uncompressed_size == 0) {
			if (c->lzma->allow_eopm) {
				/* An EOPM may still follow; try to decode it. */
				/* Decoding with a zero-size limit: handled by decoding a symbol
				 * that must be EOPM. */
				rcl r;
				/* Need input. */
				if (c->lzma->rc.init_bytes_left > 0) {
					bool err = false;
					if (!rc_dec_read_init(&c->lzma->rc, in, in_pos, in_size, &err))
						return R_OK;
					if (err)
						return R_DATA_ERROR;
				}
				size_t avail = in_size - *in_pos;
				if (c->lzma->temp_size > 0 || (avail < SYMBOL_IN_MAX && action != A_FINISH)) {
					size_t want = SYMBOL_IN_MAX - c->lzma->temp_size;
					if (want > avail) want = avail;
					memcpy(c->lzma->temp + c->lzma->temp_size, in + *in_pos, want);
					c->lzma->temp_size += want;
					*in_pos += want;
					if (c->lzma->temp_size < SYMBOL_IN_MAX && action != A_FINISH)
						return R_OK;
					memset(c->lzma->temp + c->lzma->temp_size, 0, sizeof(c->lzma->temp) - c->lzma->temp_size);
					r.in = c->lzma->temp; r.in_pos = 0;
				} else {
					r.in = in; r.in_pos = *in_pos;
				}
				r.range = c->lzma->rc.range;
				r.code = c->lzma->rc.code;
				/* Peek: the next symbol must be is_match=1, is_rep=0, len=2, EOPM dist. */
				const uint32_t pos_state = (uint32_t)dict->pos & c->lzma->pos_mask;
				lzma_state st = c->lzma->state;
				if (rcl_bit(&r, &c->lzma->is_match[st][pos_state]) == 0)
					; /* literal would exceed size: treat as finished without eopm */
				else {
					if (rcl_bit(&r, &c->lzma->is_rep[st]) != 0)
						return R_DATA_ERROR;
					uint32_t len = decode_len(&r, &c->lzma->match_len_decoder, pos_state);
					const uint32_t dist_slot = rcl_bittree_n(&r, c->lzma->dist_slot[get_dist_state(len)], DIST_SLOT_BITS);
					if (dist_slot < DIST_MODEL_END)
						return R_DATA_ERROR;
					const uint32_t limit = (dist_slot >> 1) - 1;
					uint32_t rep0 = (2 + (dist_slot & 1)) << limit;
					rep0 += rcl_direct(&r, limit - ALIGN_BITS) << ALIGN_BITS;
					rep0 += rcl_bittree_reverse(&r, c->lzma->dist_align, ALIGN_BITS);
					if (rep0 != UINT32_MAX)
						return R_DATA_ERROR;
					rcl_normalize(&r);
					if (r.code != 0)
						return R_DATA_ERROR;
					if (r.in == c->lzma->temp) {
						if (r.in_pos > c->lzma->temp_size) return R_DATA_ERROR;
						memmove(c->lzma->temp, c->lzma->temp + r.in_pos, c->lzma->temp_size - r.in_pos);
						c->lzma->temp_size -= r.in_pos;
					} else {
						if (r.in_pos > in_size) return R_DATA_ERROR;
						*in_pos = r.in_pos;
					}
					c->lzma->rc.range = r.range; c->lzma->rc.code = r.code;
				}
			}
			c->finished = true;
			return R_STREAM_END;
		}

		if (*out_pos == out_size || *in_pos == in_size)
			return R_OK;
		if (dict->pos == dict->size)
			dict->pos = 0;
	}
}

static void lz1_end(void *ctx)
{
	lz1_coder *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c);
}

static lzma1_dec *lzma1_dec_new(const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	lzma1_dec *d = calloc(1, sizeof(lzma1_dec));
	if (d == NULL)
		return NULL;
	lzma1_dec_reset(d, o);
	d->uncompressed_size = uncompressed_size;
	d->allow_eopm = allow_eopm;
	d->total_pos = 0;
	return d;
}

static bool dict_alloc(lz_dict *dict, uint32_t dict_size)
{
	size_t size = dict_size;
	if (size < 4096)
		size = 4096;
	size = (size + 15) & ~(size_t)15;
	dict->size = size;
	dict->buf = malloc(size);
	dict->need_reset = true;
	dict->pos = 0;
	dict->full = 0;
	dict->limit = 0;
	return dict->buf == NULL;
}

xret lzma1_decoder_init(xcoder *c, const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return R_OPTIONS_ERROR;
	lz1_coder *lz = calloc(1, sizeof(lz1_coder));
	if (lz == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&lz->dict, o->dict_size)) {
		free(lz);
		return R_MEM_ERROR;
	}
	lz->lzma = lzma1_dec_new(o, uncompressed_size, allow_eopm);
	if (lz->lzma == NULL) {
		free(lz->dict.buf);
		free(lz);
		return R_MEM_ERROR;
	}
	c->ctx = lz;
	c->code = lz1_code;
	c->end = lz1_end;
	return R_OK;
}

/* ---------- LZMA2 decoder ---------- */

typedef enum {
	L2_SEQ_CONTROL,
	L2_SEQ_UNCOMPRESSED_1,
	L2_SEQ_UNCOMPRESSED_2,
	L2_SEQ_COMPRESSED_0,
	L2_SEQ_COMPRESSED_1,
	L2_SEQ_PROPERTIES,
	L2_SEQ_LZMA,
	L2_SEQ_COPY,
} lzma2_seq;

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	lzma2_seq sequence;
	lzma2_seq next_sequence;
	size_t uncompressed_size;
	size_t compressed_size;
	bool need_properties;
	bool need_dictionary_reset;
	lzma_options options;
	/* Buffer for the compressed chunk so the LZMA decoder always sees the
	 * whole chunk contiguously. */
	uint8_t *chunk;
	size_t chunk_pos;    /* bytes of chunk already consumed by decoder */
	size_t chunk_filled; /* bytes received so far */
	bool finished;
} lzma2_dec;

static xret lzma2_decode_internal(lzma2_dec *c, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size)
{
	lz_dict *dict = &c->dict;

	while (*out_pos < out_size || c->sequence != L2_SEQ_LZMA) {
	switch (c->sequence) {
	case L2_SEQ_CONTROL: {
		if (*in_pos >= in_size)
			return R_OK;
		const uint32_t control = in[(*in_pos)++];
		if (control == 0x00) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (control >= 0xE0 || control == 1) {
			c->need_properties = true;
			c->need_dictionary_reset = true;
		} else if (c->need_dictionary_reset) {
			return R_DATA_ERROR;
		}
		if (control >= 0x80) {
			c->uncompressed_size = (control & 0x1F) << 16;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			if (control >= 0xC0) {
				c->need_properties = false;
				c->next_sequence = L2_SEQ_PROPERTIES;
			} else if (c->need_properties) {
				return R_DATA_ERROR;
			} else {
				c->next_sequence = L2_SEQ_LZMA;
				if (control >= 0xA0)
					lzma1_dec_reset(c->lzma, &c->options);
			}
		} else {
			if (control > 2)
				return R_DATA_ERROR;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			c->next_sequence = L2_SEQ_COPY;
		}
		if (c->need_dictionary_reset) {
			c->need_dictionary_reset = false;
			dict_reset(dict);
			if (dict->need_reset) {
				dict->pos = 0;
				dict->full = 0;
				dict->buf[dict->size - 1] = 0;
				dict->need_reset = false;
			}
		}
		break;
	}
	case L2_SEQ_UNCOMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_UNCOMPRESSED_2;
		break;
	case L2_SEQ_UNCOMPRESSED_2:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence == L2_SEQ_COPY ? L2_SEQ_COPY : L2_SEQ_COMPRESSED_0;
		if (c->sequence == L2_SEQ_COPY) {
			/* nothing */
		}
		break;
	case L2_SEQ_COMPRESSED_0:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_COMPRESSED_1;
		break;
	case L2_SEQ_COMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence;
		c->chunk_pos = 0;
		c->chunk_filled = 0;
		break;
	case L2_SEQ_PROPERTIES:
		if (*in_pos >= in_size)
			return R_OK;
		if (lzma_lclppb_decode(&c->options, in[(*in_pos)++]))
			return R_DATA_ERROR;
		lzma1_dec_reset(c->lzma, &c->options);
		c->sequence = L2_SEQ_LZMA;
		break;
	case L2_SEQ_LZMA: {
		/* Gather the whole compressed chunk first. */
		if (c->chunk_filled < c->compressed_size) {
			const size_t want = c->compressed_size - c->chunk_filled;
			const size_t have = in_size - *in_pos;
			const size_t n = want < have ? want : have;
			memcpy(c->chunk + c->chunk_filled, in + *in_pos, n);
			c->chunk_filled += n;
			*in_pos += n;
			if (c->chunk_filled < c->compressed_size)
				return R_OK;
			/* Set up the LZMA decoder for this chunk. */
			c->lzma->uncompressed_size = c->uncompressed_size;
			c->lzma->allow_eopm = false;
			c->lzma->temp_size = 0;
			rc_dec_reset(&c->lzma->rc);
			c->lzma->pending_len = 0;
		}
		if (*out_pos >= out_size)
			return R_OK;

		/* Decode from the chunk buffer into dict, copying to out. */
		if (dict->pos == dict->size)
			dict->pos = 0;
		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;
		if (dict->limit - dict->pos > c->lzma->uncompressed_size)
			dict->limit = dict->pos + c->lzma->uncompressed_size;

		size_t cpos = c->chunk_pos;
		xret ret = lzma1_decode(c->lzma, dict, c->chunk, &cpos, c->compressed_size, true);
		c->chunk_pos = cpos;
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;
		c->lzma->uncompressed_size -= produced;
		if (ret != R_OK && ret != R_STREAM_END)
			return ret;
		if (c->lzma->uncompressed_size == 0 && c->lzma->pending_len == 0) {
			/* Chunk done: all compressed input must be consumed and rc code 0. */
			if (c->chunk_pos != c->compressed_size)
				return R_DATA_ERROR;
			/* Normalize to check final code. */
			if (c->lzma->rc.code != 0)
				return R_DATA_ERROR;
			c->sequence = L2_SEQ_CONTROL;
			break;
		}
		if (c->chunk_pos > c->compressed_size)
			return R_DATA_ERROR;
		if (*out_pos >= out_size)
			return R_OK;
		break;
	}
	case L2_SEQ_COPY: {
		if (dict->pos == dict->size)
			dict->pos = 0;
		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;
		dict_write(dict, in, in_pos, in_size, &c->uncompressed_size);
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;
		if (c->uncompressed_size != 0)
			return R_OK;
		c->sequence = L2_SEQ_CONTROL;
		break;
	}
	}
	}
	return R_OK;
}

static xret lzma2_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lzma2_dec *c = ctx;
	(void)action;
	if (c->finished)
		return R_STREAM_END;
	return lzma2_decode_internal(c, in, in_pos, in_size, out, out_pos, out_size);
}

static void lzma2_end(void *ctx)
{
	lzma2_dec *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c->chunk);
	free(c);
}

xret lzma2_decoder_init(xcoder *c, const lzma_options *o)
{
	if (o->dict_size < LZMA_DICT_SIZE_MIN)
		return R_OPTIONS_ERROR;
	lzma2_dec *d = calloc(1, sizeof(lzma2_dec));
	if (d == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&d->dict, o->dict_size)) {
		free(d);
		return R_MEM_ERROR;
	}
	d->chunk = malloc(65536);
	lzma_options tmp = *o;
	tmp.lc = 3; tmp.lp = 0; tmp.pb = 2;
	d->lzma = lzma1_dec_new(&tmp, 0, false);
	if (d->lzma == NULL || d->chunk == NULL) {
		lzma2_end(d);
		return R_MEM_ERROR;
	}
	d->options = tmp;
	d->sequence = L2_SEQ_CONTROL;
	d->need_properties = true;
	d->need_dictionary_reset = true;
	c->ctx = d;
	c->code = lzma2_code;
	c->end = lzma2_end;
	return R_OK;
}

uint64_t lzma2_decoder_memusage(const lzma_options *o)
{
	uint64_t dict_size = o->dict_size;
	if (dict_size < 4096)
		dict_size = 4096;
	dict_size = (dict_size + 15) & ~(uint64_t)15;
	return dict_size + LZMA2_DEC_STRUCT_MEMUSAGE;
}

uint64_t lzma1_decoder_memusage(const lzma_options *o)
{
	uint64_t dict_size = o->dict_size;
	if (dict_size < 4096)
		dict_size = 4096;
	dict_size = (dict_size + 15) & ~(uint64_t)15;
	return dict_size + LZMA1_DEC_STRUCT_MEMUSAGE;
}

bool lzma2_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 1)
		return true;
	if (props[0] > 40)
		return true;
	memset(o, 0, sizeof(*o));
	if (props[0] == 40) {
		o->dict_size = UINT32_MAX;
	} else {
		o->dict_size = 2 | (props[0] & 1);
		o->dict_size <<= props[0] / 2 + 11;
	}
	o->preset_dict = NULL;
	o->preset_dict_size = 0;
	return false;
}

bool lzma1_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 5)
		return true;
	memset(o, 0, sizeof(*o));
	if (lzma_lclppb_decode(o, props[0]))
		return true;
	o->dict_size = read32le(props + 1);
	o->preset_dict = NULL;
	o->preset_dict_size = 0;
	return false;
}
