	prob_t choice;
	prob_t choice2;
	prob_t low[POS_STATES_MAX][LEN_LOW_SYMBOLS];
	prob_t mid[POS_STATES_MAX][LEN_MID_SYMBOLS];
	prob_t high[LEN_HIGH_SYMBOLS];
} len_decoder;

#define SYMBOL_IN_MAX 64

typedef struct {
	rc_dec rc;
	lzma_state state;
	uint32_t rep0, rep1, rep2, rep3;
	uint32_t pos_mask;
	uint32_t literal_context_bits;
	uint32_t literal_pos_mask;

	prob_t literal[LITERAL_CODERS_MAX * LITERAL_CODER_SIZE];
	prob_t is_match[STATES][POS_STATES_MAX];
	prob_t is_rep[STATES];
	prob_t is_rep0[STATES];
	prob_t is_rep1[STATES];
	prob_t is_rep2[STATES];
	prob_t is_rep0_long[STATES][POS_STATES_MAX];
	prob_t dist_slot[DIST_STATES][DIST_SLOTS];
	prob_t dist_special[FULL_DISTANCES - DIST_MODEL_END];
	prob_t dist_align[ALIGN_SIZE];
	len_decoder match_len_decoder;
	len_decoder rep_len_decoder;

	uint64_t uncompressed_size; /* remaining, or VLI_UNKNOWN */
	bool allow_eopm;
	bool eopm_seen;

	uint32_t pending_len;
	uint64_t total_pos;

	uint8_t temp[SYMBOL_IN_MAX * 2];
	size_t temp_size;
} lzma1_dec;

static void len_decoder_reset(len_decoder *ld)
{
	ld->choice = PROB_INIT;
	ld->choice2 = PROB_INIT;
	probs_reset((prob_t *)ld->low, POS_STATES_MAX * LEN_LOW_SYMBOLS);
	probs_reset((prob_t *)ld->mid, POS_STATES_MAX * LEN_MID_SYMBOLS);
	probs_reset(ld->high, LEN_HIGH_SYMBOLS);
}

static void lzma1_dec_reset(lzma1_dec *d, const lzma_options *o)
{
	d->pos_mask = (1U << o->pb) - 1;
	d->literal_context_bits = o->lc;
	d->literal_pos_mask = (1U << o->lp) - 1;
	probs_reset(d->literal, (size_t)LITERAL_CODER_SIZE << (o->lc + o->lp));
	probs_reset((prob_t *)d->is_match, STATES * POS_STATES_MAX);
	probs_reset(d->is_rep, STATES);
	probs_reset(d->is_rep0, STATES);
	probs_reset(d->is_rep1, STATES);
	probs_reset(d->is_rep2, STATES);
	probs_reset((prob_t *)d->is_rep0_long, STATES * POS_STATES_MAX);
	probs_reset((prob_t *)d->dist_slot, DIST_STATES * DIST_SLOTS);
	probs_reset(d->dist_special, FULL_DISTANCES - DIST_MODEL_END);
	probs_reset(d->dist_align, ALIGN_SIZE);
	len_decoder_reset(&d->match_len_decoder);
	len_decoder_reset(&d->rep_len_decoder);
	d->state = STATE_LIT_LIT;
	d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
	d->pending_len = 0;
	d->eopm_seen = false;
	rc_dec_reset(&d->rc);
	d->temp_size = 0;
}

/* Range decoder working on a contiguous buffer. */
typedef struct {
	uint32_t range;
	uint32_t code;
	const uint8_t *in;
	size_t in_pos;
} rcl;

static inline void rcl_normalize(rcl *r)
{
	if (r->range < RC_TOP_VALUE) {
		r->range <<= RC_SHIFT_BITS;
		r->code = (r->code << RC_SHIFT_BITS) | r->in[r->in_pos++];
	}
}

static inline uint32_t rcl_bit(rcl *r, prob_t *prob)
{
	rcl_normalize(r);
	const uint32_t bound = (r->range >> RC_BIT_MODEL_TOTAL_BITS) * *prob;
	if (r->code < bound) {
		r->range = bound;
		*prob += (RC_BIT_MODEL_TOTAL - *prob) >> RC_MOVE_BITS;
		return 0;
	}
	r->range -= bound;
	r->code -= bound;
	*prob -= *prob >> RC_MOVE_BITS;
	return 1;
}

static inline uint32_t rcl_bittree(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
	return symbol - (1U << bits);
}

static inline uint32_t rcl_bittree_reverse(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	uint32_t result = 0;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rcl_bit(r, &probs[symbol]);
		symbol = (symbol << 1) | bit;
		result |= bit << i;
	}
	return result;
}

static inline uint32_t rcl_direct(rcl *r, uint32_t bits)
{
	uint32_t result = 0;
	do {
		rcl_normalize(r);
		r->range >>= 1;
		r->code -= r->range;
		const uint32_t t = 0 - (r->code >> 31);
		r->code += r->range & t;
		result = (result << 1) + (t + 1);
	} while (--bits != 0);
	return result;
}

static inline uint32_t decode_len(rcl *r, len_decoder *ld, uint32_t pos_state)
{
	if (rcl_bit(r, &ld->choice) == 0)
		return MATCH_LEN_MIN + rcl_bittree(r, ld->low[pos_state], LEN_LOW_BITS);
	if (rcl_bit(r, &ld->choice2) == 0)
		return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + rcl_bittree(r, ld->mid[pos_state], LEN_MID_BITS);
	return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + rcl_bittree(r, ld->high, LEN_HIGH_BITS);
}

enum { SYM_OK = 0, SYM_EOPM = 1, SYM_ERROR = 2 };

/* Decode one symbol. If only_eopm is set, the symbol must be an EOPM
 * (used when the known uncompressed size has been reached). */
static int decode_symbol(lzma1_dec *d, rcl *r, lz_dict *dict, bool only_eopm)
{
	const uint32_t pos_state = (uint32_t)dict->pos & d->pos_mask;
	lzma_state state = d->state;

	if (rcl_bit(r, &d->is_match[state][pos_state]) == 0) {
		if (only_eopm)
			return SYM_ERROR;
		const uint8_t prev = dict_is_empty(dict) ? 0 : dict_get(dict, 0);
		prob_t *probs = literal_subcoder(d->literal, d->literal_context_bits, d->literal_pos_mask,
				(uint32_t)dict->pos, prev);
		uint32_t symbol = 1;
		if (is_literal_state(state)) {
			for (int i = 0; i < 8; ++i)
				symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
		} else {
			uint32_t match_byte = dict_get(dict, d->rep0);
			uint32_t offset = 0x100;
			do {
				match_byte <<= 1;
				const uint32_t match_bit = match_byte & offset;
				const uint32_t idx = offset + match_bit + symbol;
				const uint32_t bit = rcl_bit(r, &probs[idx]);
				symbol = (symbol << 1) | bit;
				if (bit)
					offset &= match_bit;
				else
					offset &= ~match_bit;
			} while (symbol < 0x100);
		}
		dict_put(dict, (uint8_t)symbol);
		d->state = state_after_literal(state);
		if (lzma_dec_trace)
			lzma_dec_trace(UINT32_MAX, 1, d->total_pos);
		d->total_pos += 1;
		return SYM_OK;
	}

	uint32_t len;
	uint32_t back;
	if (rcl_bit(r, &d->is_rep[state]) == 0) {
		len = decode_len(r, &d->match_len_decoder, pos_state);
		const uint32_t dist_slot = rcl_bittree(r, d->dist_slot[get_dist_state(len)], DIST_SLOT_BITS);
		uint32_t rep0;
		if (dist_slot < DIST_MODEL_START) {
			rep0 = dist_slot;
		} else {
			const uint32_t limit = (dist_slot >> 1) - 1;
			rep0 = (2 + (dist_slot & 1)) << limit;
			if (dist_slot < DIST_MODEL_END) {
				rep0 += rcl_bittree_reverse(r, d->dist_special + rep0 - dist_slot - 1, limit);
			} else {
				rep0 += rcl_direct(r, limit - ALIGN_BITS) << ALIGN_BITS;
				rep0 += rcl_bittree_reverse(r, d->dist_align, ALIGN_BITS);
				if (rep0 == UINT32_MAX) {
					if (!d->allow_eopm)
						return SYM_ERROR;
					d->state = state_after_match(state);
					return SYM_EOPM;
				}
			}
		}
		if (only_eopm)
			return SYM_ERROR;
		d->rep3 = d->rep2;
		d->rep2 = d->rep1;
		d->rep1 = d->rep0;
		d->rep0 = rep0;
		d->state = state_after_match(state);
		back = rep0 + REPS;
	} else {
		if (only_eopm)
			return SYM_ERROR;
		if (rcl_bit(r, &d->is_rep0[state]) == 0) {
			if (rcl_bit(r, &d->is_rep0_long[state][pos_state]) == 0) {
				if (dict_is_empty(dict) || !dict_is_distance_valid(dict, d->rep0))
					return SYM_ERROR;
				d->state = state_after_short_rep(state);
				dict_put(dict, dict_get(dict, d->rep0));
				if (lzma_dec_trace)
					lzma_dec_trace(0, 1, d->total_pos);
				d->total_pos += 1;
				return SYM_OK;
			}
			back = 0;
		} else {
			uint32_t dist;
			if (rcl_bit(r, &d->is_rep1[state]) == 0) {
				dist = d->rep1;
				back = 1;
			} else {
				if (rcl_bit(r, &d->is_rep2[state]) == 0) {
					dist = d->rep2;
					back = 2;
				} else {
					dist = d->rep3;
					d->rep3 = d->rep2;
					back = 3;
				}
				d->rep2 = d->rep1;
			}
			d->rep1 = d->rep0;
			d->rep0 = dist;
		}
		len = decode_len(r, &d->rep_len_decoder, pos_state);
		d->state = state_after_long_rep(state);
	}

	if (!dict_is_distance_valid(dict, d->rep0))
		return SYM_ERROR;
	if (lzma_dec_trace)
		lzma_dec_trace(back, len, d->total_pos);
	d->total_pos += len;
	d->pending_len = len;
	return SYM_OK;
}

/* Result of trying to get contiguous input for one symbol. */
static bool prepare_input(lzma1_dec *d, rcl *r, const uint8_t *in, size_t *in_pos, size_t in_size,
		bool finishing, bool *from_temp)
{
	const size_t avail = in_size - *in_pos;
	if (d->temp_size > 0 || (avail < SYMBOL_IN_MAX && !finishing)) {
		size_t want = SYMBOL_IN_MAX - d->temp_size;
		if (want > avail)
			want = avail;
		memcpy(d->temp + d->temp_size, in + *in_pos, want);
		d->temp_size += want;
		*in_pos += want;
		if (d->temp_size < SYMBOL_IN_MAX && !finishing)
			return false;
		memset(d->temp + d->temp_size, 0, sizeof(d->temp) - d->temp_size);
		r->in = d->temp;
		r->in_pos = 0;
		*from_temp = true;
	} else {
		r->in = in;
		r->in_pos = *in_pos;
		*from_temp = false;
	}
	r->range = d->rc.range;
	r->code = d->rc.code;
	return true;
}

/* Commit consumed input. Returns false if the decoder read past the end. */
static bool commit_input(lzma1_dec *d, rcl *r, size_t *in_pos, size_t in_size, bool from_temp)
{
	d->rc.range = r->range;
	d->rc.code = r->code;
	if (from_temp) {
		if (r->in_pos > d->temp_size)
			return false;
		memmove(d->temp, d->temp + r->in_pos, d->temp_size - r->in_pos);
		d->temp_size -= r->in_pos;
	} else {
		if (r->in_pos > in_size)
			return false;
		*in_pos = r->in_pos;
	}
	return true;
}

/* Decode until dict->limit, end of input, or end of stream.
 * Returns R_OK, R_STREAM_END or R_DATA_ERROR. R_BUF_ERROR is returned
 * when finishing and the input ended prematurely. */
static xret lzma1_decode(lzma1_dec *d, lz_dict *dict, const uint8_t *in, size_t *in_pos, size_t in_size, bool finishing)
{
	if (d->rc.init_bytes_left > 0) {
		bool err = false;
		if (!rc_dec_read_init(&d->rc, in, in_pos, in_size, &err))
			return finishing ? R_BUF_ERROR : R_OK;
		if (err)
			return R_DATA_ERROR;
	}

	while (true) {
		if (d->pending_len > 0) {
			if (dict->pos >= dict->limit)
				return R_OK;
			dict_repeat(dict, d->rep0, &d->pending_len);
			continue;
		}

		const bool size_reached = d->uncompressed_size != VLI_UNKNOWN && d->uncompressed_size == 0;

		if (!size_reached && dict->pos >= dict->limit)
			return R_OK;

		rcl r;
		bool from_temp;
		if (!prepare_input(d, &r, in, in_pos, in_size, finishing, &from_temp))
			return R_OK;

		if (size_reached) {
			/* Either the stream ends here or an EOPM follows. */
			rcl_normalize(&r);
			if (r.code == 0) {
				if (!commit_input(d, &r, in_pos, in_size, from_temp))
					return R_DATA_ERROR;
				return R_STREAM_END;
			}
			if (!d->allow_eopm) {
				commit_input(d, &r, in_pos, in_size, from_temp);
				return R_DATA_ERROR;
			}
			const int res = decode_symbol(d, &r, dict, true);
			if (res != SYM_EOPM) {
				commit_input(d, &r, in_pos, in_size, from_temp);
				return R_DATA_ERROR;
			}
			rcl_normalize(&r);
			if (!commit_input(d, &r, in_pos, in_size, from_temp))
				return R_DATA_ERROR;
			if (r.code != 0)
				return R_DATA_ERROR;
			return R_STREAM_END;
		}

		const size_t dict_before = dict->pos;
		const int res = decode_symbol(d, &r, dict, false);
		const bool ok = commit_input(d, &r, in_pos, in_size, from_temp);
		if (res == SYM_ERROR)
			return R_DATA_ERROR;
		if (!ok)
			return R_DATA_ERROR;

		if (res == SYM_EOPM) {
			rcl r2 = r;
			r2.in = from_temp ? d->temp : in;
			r2.in_pos = from_temp ? 0 : *in_pos;
			rcl_normalize(&r2);
			if (!commit_input(d, &r2, in_pos, in_size, from_temp))
				return R_DATA_ERROR;
			if (r2.code != 0)
				return R_DATA_ERROR;
			if (d->uncompressed_size != VLI_UNKNOWN && d->uncompressed_size != 0)
				return R_DATA_ERROR;
			d->uncompressed_size = 0;
			d->eopm_seen = true;
			return R_STREAM_END;
		}

		if (d->uncompressed_size != VLI_UNKNOWN) {
			const uint64_t produced = (dict->pos - dict_before) + d->pending_len;
			if (produced > d->uncompressed_size)
				return R_DATA_ERROR;
			d->uncompressed_size -= produced;
		}
	}
}

/* Pads a (possibly partial) dict region out to `out`. */

/* ---------- LZMA1 as a standalone coder ---------- */

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	bool finished;
} lz1_coder;

static xret lz1_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lz1_coder *c = ctx;
	lz_dict *dict = &c->dict;

	if (dict->need_reset)
		dict_do_reset(dict);

	while (true) {
		if (c->finished)
			return R_STREAM_END;

		if (dict->pos == dict->size)
			dict->pos = 0;

		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;

		const bool finishing = action == A_FINISH;
		const size_t in_before = *in_pos;
		const xret ret = lzma1_decode(c->lzma, dict, in, in_pos, in_size, finishing);
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;

		if (ret == R_STREAM_END) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (ret != R_OK)
			return ret;

		if (*out_pos == out_size)
			return R_OK;
		if (*in_pos == in_size && *in_pos == in_before && produced == 0 && c->lzma->pending_len == 0) {
			if (finishing)
				return R_BUF_ERROR;
			return R_OK;
		}
		if (*in_pos == in_size && produced == 0 && c->lzma->pending_len == 0)
			return finishing ? R_BUF_ERROR : R_OK;
	}
}

static void lz1_end(void *ctx)
{
	lz1_coder *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c);
}

static lzma1_dec *lzma1_dec_new(const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	lzma1_dec *d = calloc(1, sizeof(lzma1_dec));
	if (d == NULL)
		return NULL;
	lzma1_dec_reset(d, o);
	d->uncompressed_size = uncompressed_size;
	d->allow_eopm = allow_eopm;
	d->total_pos = 0;
	return d;
}

xret lzma1_decoder_init(xcoder *c, const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return R_OPTIONS_ERROR;
	lz1_coder *lz = calloc(1, sizeof(lz1_coder));
	if (lz == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&lz->dict, o->dict_size)) {
		free(lz);
		return R_MEM_ERROR;
	}
	lz->lzma = lzma1_dec_new(o, uncompressed_size, allow_eopm);
	if (lz->lzma == NULL) {
		free(lz->dict.buf);
		free(lz);
		return R_MEM_ERROR;
	}
	c->ctx = lz;
	c->code = lz1_code;
	c->end = lz1_end;
	return R_OK;
}

/* ---------- LZMA2 decoder ---------- */

typedef enum {
	L2_SEQ_CONTROL,
	L2_SEQ_UNCOMPRESSED_1,
	L2_SEQ_UNCOMPRESSED_2,
	L2_SEQ_COMPRESSED_0,
	L2_SEQ_COMPRESSED_1,
	L2_SEQ_PROPERTIES,
	L2_SEQ_LZMA,
	L2_SEQ_COPY,
} l2_seq;

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	l2_seq sequence;
	l2_seq next_sequence;
	size_t uncompressed_size;
	size_t compressed_size;
	bool need_properties;
	bool need_dictionary_reset;
	lzma_options options;
	uint8_t *chunk;
	size_t chunk_pos;
	size_t chunk_filled;
	bool finished;
} lzma2_dec;

static xret lzma2_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lzma2_dec *c = ctx;
	lz_dict *dict = &c->dict;
	(void)action;

	while (true) {
	switch (c->sequence) {
	case L2_SEQ_CONTROL: {
		if (c->finished)
			return R_STREAM_END;
		if (*in_pos >= in_size)
			return R_OK;
		const uint32_t control = in[(*in_pos)++];
		if (control == 0x00) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (control >= 0xE0 || control == 1) {
			c->need_properties = true;
			c->need_dictionary_reset = true;
		} else if (c->need_dictionary_reset) {
			return R_DATA_ERROR;
		}
		if (control >= 0x80) {
			c->uncompressed_size = (control & 0x1F) << 16;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			if (control >= 0xC0) {
				c->need_properties = false;
				c->next_sequence = L2_SEQ_PROPERTIES;
			} else if (c->need_properties) {
				return R_DATA_ERROR;
			} else {
				c->next_sequence = L2_SEQ_LZMA;
				if (control >= 0xA0)
					lzma1_dec_reset(c->lzma, &c->options);
			}
		} else {
			if (control > 2)
				return R_DATA_ERROR;
			c->uncompressed_size = 0;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			c->next_sequence = L2_SEQ_COPY;
		}
		if (c->need_dictionary_reset) {
			c->need_dictionary_reset = false;
			dict_do_reset(dict);
		}
		break;
	}
	case L2_SEQ_UNCOMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_UNCOMPRESSED_2;
		break;
	case L2_SEQ_UNCOMPRESSED_2:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence == L2_SEQ_COPY ? L2_SEQ_COPY : L2_SEQ_COMPRESSED_0;
		break;
	case L2_SEQ_COMPRESSED_0:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_COMPRESSED_1;
		break;
	case L2_SEQ_COMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence;
		c->chunk_pos = 0;
		c->chunk_filled = 0;
		break;
	case L2_SEQ_PROPERTIES:
		if (*in_pos >= in_size)
			return R_OK;
		if (lzma_lclppb_decode(&c->options, in[(*in_pos)++]))
			return R_DATA_ERROR;
		lzma1_dec_reset(c->lzma, &c->options);
		c->sequence = L2_SEQ_LZMA;
