	}
}

static void lzma2_end(void *ctx)
{
	lzma2_dec *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c->chunk);
	free(c);
}

xret lzma2_decoder_init(xcoder *c, const lzma_options *o)
{
	if (o->dict_size < LZMA_DICT_SIZE_MIN)
		return R_OPTIONS_ERROR;
	lzma2_dec *d = calloc(1, sizeof(lzma2_dec));
	if (d == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&d->dict, o->dict_size)) {
		free(d);
		return R_MEM_ERROR;
	}
	d->chunk = malloc(65536);
	lzma_options tmp = *o;
	tmp.lc = 3; tmp.lp = 0; tmp.pb = 2;
	d->lzma = lzma1_dec_new(&tmp, 0, false);
	if (d->lzma == NULL || d->chunk == NULL) {
