bool lzma2_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 1 || props[0] > 40)
		return true;
	memset(o, 0, sizeof(*o));
	if (props[0] == 40) {
		o->dict_size = UINT32_MAX;
	} else {
		o->dict_size = 2 | (props[0] & 1);
		o->dict_size <<= props[0] / 2 + 11;
	}
	return false;
}

bool lzma1_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 5)
		return true;
	memset(o, 0, sizeof(*o));
	if (lzma_lclppb_decode(o, props[0]))
		return true;
	o->dict_size = read32le(props + 1);
	return false;
}
