}

/* Repeat up to *len bytes from distance; decrements *len. */
static inline void dict_repeat(lz_dict *d, uint32_t dist, uint32_t *len)
{
	const size_t dict_avail = d->limit - d->pos;
	uint32_t left = xmin32(*len, (uint32_t)dict_avail);
	*len -= left;
	size_t back = d->pos - dist - 1;
	if (dist >= d->pos)
		back += d->size;
	while (left-- > 0) {
		d->buf[d->pos++] = d->buf[back++];
		if (back == d->size)
			back = 0;
	}
	if (d->full < d->pos)
		d->full = d->pos;
}

static bool dict_alloc(lz_dict *dict, uint32_t dict_size)
