/* ---------- LZMA1 decoder ---------- */

typedef struct {
	prob_t choice;
	prob_t choice2;
	prob_t low[POS_STATES_MAX][LEN_LOW_SYMBOLS];
	prob_t mid[POS_STATES_MAX][LEN_MID_SYMBOLS];
	prob_t high[LEN_HIGH_SYMBOLS];
} len_decoder;

#define SYMBOL_IN_MAX 64

typedef struct {
	rc_dec rc;
	lzma_state state;
	uint32_t rep0, rep1, rep2, rep3;
	uint32_t pos_mask;
	uint32_t literal_context_bits;
	uint32_t literal_pos_mask;

	prob_t literal[LITERAL_CODERS_MAX * LITERAL_CODER_SIZE];
	prob_t is_match[STATES][POS_STATES_MAX];
	prob_t is_rep[STATES];
	prob_t is_rep0[STATES];
	prob_t is_rep1[STATES];
	prob_t is_rep2[STATES];
	prob_t is_rep0_long[STATES][POS_STATES_MAX];
	prob_t dist_slot[DIST_STATES][DIST_SLOTS];
	prob_t dist_special[FULL_DISTANCES - DIST_MODEL_END];
	prob_t dist_align[ALIGN_SIZE];
	len_decoder match_len_decoder;
	len_decoder rep_len_decoder;

	uint64_t uncompressed_size; /* remaining, or VLI_UNKNOWN */
	bool allow_eopm;
	bool eopm_seen;

	uint32_t pending_len;
	uint64_t total_pos;

	uint8_t temp[SYMBOL_IN_MAX * 2];
	size_t temp_size;
} lzma1_dec;

static void len_decoder_reset(len_decoder *ld)
{
	ld->choice = PROB_INIT;
	ld->choice2 = PROB_INIT;
	probs_reset((prob_t *)ld->low, POS_STATES_MAX * LEN_LOW_SYMBOLS);
	probs_reset((prob_t *)ld->mid, POS_STATES_MAX * LEN_MID_SYMBOLS);
	probs_reset(ld->high, LEN_HIGH_SYMBOLS);
}

static void lzma1_dec_reset(lzma1_dec *d, const lzma_options *o)
{
	d->pos_mask = (1U << o->pb) - 1;
	d->literal_context_bits = o->lc;
	d->literal_pos_mask = (1U << o->lp) - 1;
	probs_reset(d->literal, (size_t)LITERAL_CODER_SIZE << (o->lc + o->lp));
	probs_reset((prob_t *)d->is_match, STATES * POS_STATES_MAX);
	probs_reset(d->is_rep, STATES);
	probs_reset(d->is_rep0, STATES);
	probs_reset(d->is_rep1, STATES);
	probs_reset(d->is_rep2, STATES);
	probs_reset((prob_t *)d->is_rep0_long, STATES * POS_STATES_MAX);
	probs_reset((prob_t *)d->dist_slot, DIST_STATES * DIST_SLOTS);
	probs_reset(d->dist_special, FULL_DISTANCES - DIST_MODEL_END);
	probs_reset(d->dist_align, ALIGN_SIZE);
	len_decoder_reset(&d->match_len_decoder);
	len_decoder_reset(&d->rep_len_decoder);
	d->state = STATE_LIT_LIT;
	d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
	d->pending_len = 0;
	d->eopm_seen = false;
	rc_dec_reset(&d->rc);
	d->temp_size = 0;
}

/* Range decoder working on a contiguous buffer. */
typedef struct {
	uint32_t range;
	uint32_t code;
	const uint8_t *in;
	size_t in_pos;
} rcl;

static inline void rcl_normalize(rcl *r)
{
	if (r->range < RC_TOP_VALUE) {
		r->range <<= RC_SHIFT_BITS;
		r->code = (r->code << RC_SHIFT_BITS) | r->in[r->in_pos++];
	}
}

static inline uint32_t rcl_bit(rcl *r, prob_t *prob)
{
	rcl_normalize(r);
	const uint32_t bound = (r->range >> RC_BIT_MODEL_TOTAL_BITS) * *prob;
	if (r->code < bound) {
		r->range = bound;
		*prob += (RC_BIT_MODEL_TOTAL - *prob) >> RC_MOVE_BITS;
		return 0;
	}
	r->range -= bound;
	r->code -= bound;
	*prob -= *prob >> RC_MOVE_BITS;
	return 1;
}

static inline uint32_t rcl_bittree(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	for (uint32_t i = 0; i < bits; ++i)
		symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
	return symbol - (1U << bits);
}

static inline uint32_t rcl_bittree_reverse(rcl *r, prob_t *probs, uint32_t bits)
{
	uint32_t symbol = 1;
	uint32_t result = 0;
	for (uint32_t i = 0; i < bits; ++i) {
		const uint32_t bit = rcl_bit(r, &probs[symbol]);
		symbol = (symbol << 1) | bit;
		result |= bit << i;
	}
	return result;
}

static inline uint32_t rcl_direct(rcl *r, uint32_t bits)
{
	uint32_t result = 0;
	do {
		rcl_normalize(r);
		r->range >>= 1;
		r->code -= r->range;
		const uint32_t t = 0 - (r->code >> 31);
		r->code += r->range & t;
		result = (result << 1) + (t + 1);
	} while (--bits != 0);
	return result;
}

static inline uint32_t decode_len(rcl *r, len_decoder *ld, uint32_t pos_state)
{
	if (rcl_bit(r, &ld->choice) == 0)
		return MATCH_LEN_MIN + rcl_bittree(r, ld->low[pos_state], LEN_LOW_BITS);
	if (rcl_bit(r, &ld->choice2) == 0)
		return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + rcl_bittree(r, ld->mid[pos_state], LEN_MID_BITS);
	return MATCH_LEN_MIN + LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + rcl_bittree(r, ld->high, LEN_HIGH_BITS);
}

enum { SYM_OK = 0, SYM_EOPM = 1, SYM_ERROR = 2 };

/* Decode one symbol. If only_eopm is set, the symbol must be an EOPM
 * (used when the known uncompressed size has been reached). */
static int decode_symbol(lzma1_dec *d, rcl *r, lz_dict *dict, bool only_eopm)
{
