		uint32_t symbol = 1;
		if (is_literal_state(state)) {
			for (int i = 0; i < 8; ++i)
				symbol = (symbol << 1) | rcl_bit(r, &probs[symbol]);
		} else {
			uint32_t match_byte = dict_get(dict, d->rep0);
			uint32_t offset = 0x100;
			do {
				match_byte <<= 1;
				const uint32_t match_bit = match_byte & offset;
				const uint32_t idx = offset + match_bit + symbol;
				const uint32_t bit = rcl_bit(r, &probs[idx]);
				symbol = (symbol << 1) | bit;
				if (bit)
					offset &= match_bit;
				else
					offset &= ~match_bit;
			} while (symbol < 0x100);
		}
		dict_put(dict, (uint8_t)symbol);
		d->state = state_after_literal(state);
		if (lzma_dec_trace)
			lzma_dec_trace(UINT32_MAX, 1, d->total_pos);
		d->total_pos += 1;
		return SYM_OK;
	}

