	uint32_t back;
	if (rcl_bit(r, &d->is_rep[state]) == 0) {
		len = decode_len(r, &d->match_len_decoder, pos_state);
		const uint32_t dist_slot = rcl_bittree(r, d->dist_slot[get_dist_state(len)], DIST_SLOT_BITS);
		uint32_t rep0;
		if (dist_slot < DIST_MODEL_START) {
			rep0 = dist_slot;
		} else {
			const uint32_t limit = (dist_slot >> 1) - 1;
			rep0 = (2 + (dist_slot & 1)) << limit;
			if (dist_slot < DIST_MODEL_END) {
				rep0 += rcl_bittree_reverse(r, d->dist_special + rep0 - dist_slot - 1, limit);
			} else {
				rep0 += rcl_direct(r, limit - ALIGN_BITS) << ALIGN_BITS;
				rep0 += rcl_bittree_reverse(r, d->dist_align, ALIGN_BITS);
