					if (!d->allow_eopm)
						return SYM_ERROR;
					d->state = state_after_match(state);
					return SYM_EOPM;
				}
			}
		}
		if (only_eopm)
			return SYM_ERROR;
		d->rep3 = d->rep2;
		d->rep2 = d->rep1;
		d->rep1 = d->rep0;
		d->rep0 = rep0;
		d->state = state_after_match(state);
		back = rep0 + REPS;
