				return SYM_OK;
			}
			back = 0;
		} else {
			uint32_t dist;
			if (rcl_bit(r, &d->is_rep1[state]) == 0) {
				dist = d->rep1;
				back = 1;
			} else {
				if (rcl_bit(r, &d->is_rep2[state]) == 0) {
					dist = d->rep2;
					back = 2;
				} else {
