}

/* Result of trying to get contiguous input for one symbol. */
static bool prepare_input(lzma1_dec *d, rcl *r, const uint8_t *in, size_t *in_pos, size_t in_size,
		bool finishing, bool *from_temp)
{
	const size_t avail = in_size - *in_pos;
	if (d->temp_size > 0 || (avail < SYMBOL_IN_MAX && !finishing)) {
		size_t want = SYMBOL_IN_MAX - d->temp_size;
		if (want > avail)
			want = avail;
		memcpy(d->temp + d->temp_size, in + *in_pos, want);
		d->temp_size += want;
		*in_pos += want;
		if (d->temp_size < SYMBOL_IN_MAX && !finishing)
			return false;
		memset(d->temp + d->temp_size, 0, sizeof(d->temp) - d->temp_size);
		r->in = d->temp;
		r->in_pos = 0;
		*from_temp = true;
	} else {
		r->in = in;
		r->in_pos = *in_pos;
		*from_temp = false;
	}
	r->range = d->rc.range;
	r->code = d->rc.code;
	return true;
}

/* Commit consumed input. Returns false if the decoder read past the end. */
static bool commit_input(lzma1_dec *d, rcl *r, size_t *in_pos, size_t in_size, bool from_temp)
{
	d->rc.range = r->range;
	d->rc.code = r->code;
	if (from_temp) {
		if (r->in_pos > d->temp_size)
			return false;
		memmove(d->temp, d->temp + r->in_pos, d->temp_size - r->in_pos);
		d->temp_size -= r->in_pos;
	} else {
		if (r->in_pos > in_size)
			return false;
		*in_pos = r->in_pos;
	}
	return true;
}

/* Decode until dict->limit, end of input, or end of stream.
 * Returns R_OK, R_STREAM_END or R_DATA_ERROR. R_BUF_ERROR is returned
 * when finishing and the input ended prematurely. */
static xret lzma1_decode(lzma1_dec *d, lz_dict *dict, const uint8_t *in, size_t *in_pos, size_t in_size, bool finishing)
{
	if (d->rc.init_bytes_left > 0) {
		bool err = false;
		if (!rc_dec_read_init(&d->rc, in, in_pos, in_size, &err))
			return finishing ? R_BUF_ERROR : R_OK;
		if (err)
			return R_DATA_ERROR;
	}

	while (true) {
		if (d->pending_len > 0) {
			if (dict->pos >= dict->limit)
				return R_OK;
			dict_repeat(dict, d->rep0, &d->pending_len);
			continue;
		}

		const bool size_reached = d->uncompressed_size != VLI_UNKNOWN && d->uncompressed_size == 0;

		if (!size_reached && dict->pos >= dict->limit)
			return R_OK;

		rcl r;
		bool from_temp;
		if (!prepare_input(d, &r, in, in_pos, in_size, finishing, &from_temp))
			return R_OK;

		if (size_reached) {
			/* Either the stream ends here or an EOPM follows. */
			rcl_normalize(&r);
			if (r.code == 0) {
				if (!commit_input(d, &r, in_pos, in_size, from_temp))
					return R_DATA_ERROR;
				return R_STREAM_END;
			}
			if (!d->allow_eopm) {
				commit_input(d, &r, in_pos, in_size, from_temp);
				return R_DATA_ERROR;
			}
			const int res = decode_symbol(d, &r, dict, true);
			if (res != SYM_EOPM) {
				commit_input(d, &r, in_pos, in_size, from_temp);
				return R_DATA_ERROR;
			}
			rcl_normalize(&r);
			if (!commit_input(d, &r, in_pos, in_size, from_temp))
				return R_DATA_ERROR;
			if (r.code != 0)
				return R_DATA_ERROR;
			return R_STREAM_END;
		}

		const size_t dict_before = dict->pos;
		const int res = decode_symbol(d, &r, dict, false);
		const bool ok = commit_input(d, &r, in_pos, in_size, from_temp);
		if (res == SYM_ERROR)
			return R_DATA_ERROR;
		if (!ok)
			return R_DATA_ERROR;

		if (res == SYM_EOPM) {
			rcl r2 = r;
			r2.in = from_temp ? d->temp : in;
			r2.in_pos = from_temp ? 0 : *in_pos;
			rcl_normalize(&r2);
			if (!commit_input(d, &r2, in_pos, in_size, from_temp))
				return R_DATA_ERROR;
			if (r2.code != 0)
				return R_DATA_ERROR;
			if (d->uncompressed_size != VLI_UNKNOWN && d->uncompressed_size != 0)
				return R_DATA_ERROR;
			d->uncompressed_size = 0;
			d->eopm_seen = true;
			return R_STREAM_END;
		}

		if (d->uncompressed_size != VLI_UNKNOWN) {
			const uint64_t produced = (dict->pos - dict_before) + d->pending_len;
			if (produced > d->uncompressed_size)
				return R_DATA_ERROR;
			d->uncompressed_size -= produced;
		}
	}
}

/* Pads a (possibly partial) dict region out to `out`. */

/* ---------- LZMA1 as a standalone coder ---------- */

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	bool finished;
} lz1_coder;

static xret lz1_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lz1_coder *c = ctx;
	lz_dict *dict = &c->dict;

	if (dict->need_reset)
		dict_do_reset(dict);

	while (true) {
		if (c->finished)
			return R_STREAM_END;

		if (dict->pos == dict->size)
			dict->pos = 0;

		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;

		const bool finishing = action == A_FINISH;
		const size_t in_before = *in_pos;
		const xret ret = lzma1_decode(c->lzma, dict, in, in_pos, in_size, finishing);
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;

		if (ret == R_STREAM_END) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (ret != R_OK)
			return ret;

		if (*out_pos == out_size)
			return R_OK;
		if (*in_pos == in_size && *in_pos == in_before && produced == 0 && c->lzma->pending_len == 0) {
			if (finishing)
				return R_BUF_ERROR;
			return R_OK;
		}
		if (*in_pos == in_size && produced == 0 && c->lzma->pending_len == 0)
			return finishing ? R_BUF_ERROR : R_OK;
	}
}

static void lz1_end(void *ctx)
{
	lz1_coder *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c);
}

static lzma1_dec *lzma1_dec_new(const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	lzma1_dec *d = calloc(1, sizeof(lzma1_dec));
	if (d == NULL)
		return NULL;
	lzma1_dec_reset(d, o);
	d->uncompressed_size = uncompressed_size;
	d->allow_eopm = allow_eopm;
	d->total_pos = 0;
	return d;
}

xret lzma1_decoder_init(xcoder *c, const lzma_options *o, uint64_t uncompressed_size, bool allow_eopm)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return R_OPTIONS_ERROR;
	lz1_coder *lz = calloc(1, sizeof(lz1_coder));
	if (lz == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&lz->dict, o->dict_size)) {
		free(lz);
		return R_MEM_ERROR;
	}
	lz->lzma = lzma1_dec_new(o, uncompressed_size, allow_eopm);
	if (lz->lzma == NULL) {
		free(lz->dict.buf);
		free(lz);
		return R_MEM_ERROR;
	}
	c->ctx = lz;
	c->code = lz1_code;
	c->end = lz1_end;
	return R_OK;
}

/* ---------- LZMA2 decoder ---------- */

typedef enum {
	L2_SEQ_CONTROL,
	L2_SEQ_UNCOMPRESSED_1,
	L2_SEQ_UNCOMPRESSED_2,
	L2_SEQ_COMPRESSED_0,
	L2_SEQ_COMPRESSED_1,
	L2_SEQ_PROPERTIES,
	L2_SEQ_LZMA,
	L2_SEQ_COPY,
} l2_seq;

typedef struct {
	lz_dict dict;
	lzma1_dec *lzma;
	l2_seq sequence;
	l2_seq next_sequence;
	size_t uncompressed_size;
	size_t compressed_size;
	bool need_properties;
	bool need_dictionary_reset;
	lzma_options options;
	uint8_t *chunk;
	size_t chunk_pos;
	size_t chunk_filled;
	bool finished;
} lzma2_dec;

static xret lzma2_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lzma2_dec *c = ctx;
	lz_dict *dict = &c->dict;
	(void)action;

	while (true) {
	switch (c->sequence) {
	case L2_SEQ_CONTROL: {
		if (c->finished)
			return R_STREAM_END;
		if (*in_pos >= in_size)
			return R_OK;
		const uint32_t control = in[(*in_pos)++];
		if (control == 0x00) {
			c->finished = true;
			return R_STREAM_END;
		}
		if (control >= 0xE0 || control == 1) {
			c->need_properties = true;
			c->need_dictionary_reset = true;
		} else if (c->need_dictionary_reset) {
			return R_DATA_ERROR;
		}
		if (control >= 0x80) {
			c->uncompressed_size = (control & 0x1F) << 16;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			if (control >= 0xC0) {
				c->need_properties = false;
				c->next_sequence = L2_SEQ_PROPERTIES;
			} else if (c->need_properties) {
				return R_DATA_ERROR;
			} else {
				c->next_sequence = L2_SEQ_LZMA;
				if (control >= 0xA0)
					lzma1_dec_reset(c->lzma, &c->options);
			}
		} else {
			if (control > 2)
				return R_DATA_ERROR;
			c->uncompressed_size = 0;
			c->sequence = L2_SEQ_UNCOMPRESSED_1;
			c->next_sequence = L2_SEQ_COPY;
		}
		if (c->need_dictionary_reset) {
			c->need_dictionary_reset = false;
			dict_do_reset(dict);
		}
		break;
	}
	case L2_SEQ_UNCOMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_UNCOMPRESSED_2;
		break;
	case L2_SEQ_UNCOMPRESSED_2:
		if (*in_pos >= in_size)
			return R_OK;
		c->uncompressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence == L2_SEQ_COPY ? L2_SEQ_COPY : L2_SEQ_COMPRESSED_0;
		break;
	case L2_SEQ_COMPRESSED_0:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
		c->sequence = L2_SEQ_COMPRESSED_1;
		break;
	case L2_SEQ_COMPRESSED_1:
		if (*in_pos >= in_size)
			return R_OK;
		c->compressed_size += in[(*in_pos)++] + 1U;
		c->sequence = c->next_sequence;
		c->chunk_pos = 0;
		c->chunk_filled = 0;
		break;
	case L2_SEQ_PROPERTIES:
		if (*in_pos >= in_size)
			return R_OK;
		if (lzma_lclppb_decode(&c->options, in[(*in_pos)++]))
			return R_DATA_ERROR;
		lzma1_dec_reset(c->lzma, &c->options);
		c->sequence = L2_SEQ_LZMA;
		break;
	case L2_SEQ_LZMA: {
		if (c->chunk_filled < c->compressed_size) {
			const size_t want = c->compressed_size - c->chunk_filled;
			const size_t have = in_size - *in_pos;
			const size_t n = want < have ? want : have;
			memcpy(c->chunk + c->chunk_filled, in + *in_pos, n);
			c->chunk_filled += n;
			*in_pos += n;
			if (c->chunk_filled < c->compressed_size)
				return R_OK;
			c->lzma->uncompressed_size = c->uncompressed_size;
			c->lzma->allow_eopm = false;
			c->lzma->temp_size = 0;
			c->lzma->pending_len = 0;
			rc_dec_reset(&c->lzma->rc);
		}
		if (*out_pos >= out_size)
			return R_OK;

		if (dict->pos == dict->size)
			dict->pos = 0;
		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;
		if (dict->limit - dict->pos > c->uncompressed_size)
			dict->limit = dict->pos + c->uncompressed_size;

		size_t cpos = c->chunk_pos;
		const xret ret = lzma1_decode(c->lzma, dict, c->chunk, &cpos, c->compressed_size, true);
		c->chunk_pos = cpos;
		const size_t produced = dict->pos - dict_start;
		memcpy(out + *out_pos, dict->buf + dict_start, produced);
		*out_pos += produced;
		c->uncompressed_size -= produced;

		if (ret == R_STREAM_END) {
			if (c->uncompressed_size != 0 || c->chunk_pos != c->compressed_size)
				return R_DATA_ERROR;
			c->sequence = L2_SEQ_CONTROL;
			break;
		}
		if (ret != R_OK)
			return R_DATA_ERROR;
		if (c->chunk_pos > c->compressed_size)
			return R_DATA_ERROR;
		if (*out_pos >= out_size)
			return R_OK;
		break;
	}
	case L2_SEQ_COPY: {
		if (*out_pos >= out_size)
			return R_OK;
		if (dict->pos == dict->size)
			dict->pos = 0;
		const size_t dict_start = dict->pos;
		dict->limit = dict->pos + (out_size - *out_pos);
		if (dict->limit > dict->size)
			dict->limit = dict->size;
		size_t n = dict->limit - dict->pos;
		if (n > c->uncompressed_size)
			n = c->uncompressed_size;
		if (n > in_size - *in_pos)
			n = in_size - *in_pos;
		memcpy(dict->buf + dict->pos, in + *in_pos, n);
		dict->pos += n;
		*in_pos += n;
		if (dict->full < dict->pos)
			dict->full = dict->pos;
		c->uncompressed_size -= n;
		memcpy(out + *out_pos, dict->buf + dict_start, n);
		*out_pos += n;
		if (c->uncompressed_size != 0)
			return R_OK;
		c->sequence = L2_SEQ_CONTROL;
		break;
	}
	}
	}
}

static void lzma2_end(void *ctx)
{
	lzma2_dec *c = ctx;
	free(c->dict.buf);
	free(c->lzma);
	free(c->chunk);
	free(c);
}

xret lzma2_decoder_init(xcoder *c, const lzma_options *o)
{
	if (o->dict_size < LZMA_DICT_SIZE_MIN)
		return R_OPTIONS_ERROR;
	lzma2_dec *d = calloc(1, sizeof(lzma2_dec));
	if (d == NULL)
		return R_MEM_ERROR;
	if (dict_alloc(&d->dict, o->dict_size)) {
		free(d);
		return R_MEM_ERROR;
	}
	d->chunk = malloc(65536);
	lzma_options tmp = *o;
	tmp.lc = 3; tmp.lp = 0; tmp.pb = 2;
	d->lzma = lzma1_dec_new(&tmp, 0, false);
	if (d->lzma == NULL || d->chunk == NULL) {
		lzma2_end(d);
		return R_MEM_ERROR;
	}
	d->options = tmp;
	d->sequence = L2_SEQ_CONTROL;
	d->need_properties = true;
	d->need_dictionary_reset = true;
	c->ctx = d;
	c->code = lzma2_code;
	c->end = lzma2_end;
	return R_OK;
}

uint64_t lzma2_decoder_memusage(const lzma_options *o)
{
	uint64_t dict_size = o->dict_size;
	if (dict_size < 4096)
		dict_size = 4096;
	dict_size = (dict_size + 15) & ~(uint64_t)15;
	return dict_size + LZMA2_DEC_STRUCT_MEMUSAGE;
}

uint64_t lzma1_decoder_memusage(const lzma_options *o)
{
	uint64_t dict_size = o->dict_size;
	if (dict_size < 4096)
		dict_size = 4096;
	dict_size = (dict_size + 15) & ~(uint64_t)15;
	return dict_size + LZMA1_DEC_STRUCT_MEMUSAGE;
}

bool lzma2_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 1 || props[0] > 40)
		return true;
	memset(o, 0, sizeof(*o));
	if (props[0] == 40) {
		o->dict_size = UINT32_MAX;
	} else {
		o->dict_size = 2 | (props[0] & 1);
		o->dict_size <<= props[0] / 2 + 11;
	}
	return false;
}

bool lzma1_props_decode(lzma_options *o, const uint8_t *props, size_t size)
{
	if (size != 5)
		return true;
	memset(o, 0, sizeof(*o));
	if (lzma_lclppb_decode(o, props[0]))
		return true;
	o->dict_size = read32le(props + 1);
	return false;
}
