static size_t arm64_code(uint32_t now_pos, bool is_encoder, uint8_t *buffer, size_t size)
{
	size_t i;
	for (i = 0; i + 4 <= size; i += 4) {
		uint32_t pc = (uint32_t)(now_pos + i);
		uint32_t instr = read32le(buffer + i);

		if ((instr >> 26) == 0x25) {
			const uint32_t src = instr;
			instr = 0x94000000;
			pc >>= 2;
			if (!is_encoder)
