			buffer[i + 0] = (uint8_t)(0x48 | ((dest >> 24) & 0x03));
			buffer[i + 1] = (uint8_t)(dest >> 16);
			buffer[i + 2] = (uint8_t)(dest >> 8);
			buffer[i + 3] &= 0x03;
			buffer[i + 3] |= (uint8_t)dest;
		}
	}
	return i;
}

static size_t sparc_code(uint32_t now_pos, bool is_encoder, uint8_t *buffer, size_t size)
{
	size_t i;
	for (i = 0; i + 4 <= size; i += 4) {
		if ((buffer[i] == 0x40 && (buffer[i + 1] & 0xC0) == 0x00)
				|| (buffer[i] == 0x7F && (buffer[i + 1] & 0xC0) == 0xC0)) {
			uint32_t src = ((uint32_t)buffer[i + 0] << 24) | ((uint32_t)buffer[i + 1] << 16)
					| ((uint32_t)buffer[i + 2] << 8) | ((uint32_t)buffer[i + 3]);
			src <<= 2;
			uint32_t dest;
			if (is_encoder)
				dest = now_pos + (uint32_t)i + src;
			else
