				else
					dest = src - (now_pos + (uint32_t)i);
				dest >>= 4;
				inst_norm &= ~((uint64_t)0x8FFFFF << 13);
				inst_norm |= (uint64_t)(dest & 0xFFFFF) << 13;
				inst_norm |= (uint64_t)(dest & 0x100000) << (36 - 20);
				instruction &= (1U << bit_res) - 1;
				instruction |= (inst_norm << bit_res);
				for (size_t j = 0; j < 6; j++)
					buffer[i + j + byte_pos] = (uint8_t)(instruction >> (8 * j));
			}
		}
	}
	return i;
}

/* RISC-V filter (reconstruction of the published algorithm). */
static size_t riscv_encode(uint32_t now_pos, uint8_t *buffer, size_t size)
{
	if (size < 8)
		return 0;
	size -= 8;
	size_t i;
	for (i = 0; i <= size; i += 2) {
		uint32_t inst = buffer[i];
		if (inst == 0xEF) {
			const uint32_t b1 = buffer[i + 1];
			if ((b1 & 0x0D) != 0)
				continue;
			const uint32_t b2 = buffer[i + 2];
			const uint32_t b3 = buffer[i + 3];
			const uint32_t pc = now_pos + (uint32_t)i;
			uint32_t addr = ((b1 & 0xF0) << 13) | (b2 << 9) | (b3 << 1);
			addr += pc;
			buffer[i + 1] = (uint8_t)((b1 & 0x0F) | ((addr >> 8) & 0xF0));
			buffer[i + 2] = (uint8_t)(((addr >> 16) & 0x0F) | ((addr >> 7) & 0x10) | ((addr << 4) & 0xE0));
			buffer[i + 3] = (uint8_t)(((addr >> 4) & 0x7F) | ((addr >> 13) & 0x80));
			i += 4 - 2;
		} else if ((inst & 0x7F) == 0x17) {
			inst |= (uint32_t)buffer[i + 1] << 8;
			inst |= (uint32_t)buffer[i + 2] << 16;
			inst |= (uint32_t)buffer[i + 3] << 24;
			if (inst & 0xE80) {
				const uint32_t inst2 = read32le(buffer + i + 4);
				if (((inst << 8) ^ (inst2 - 3)) & 0xF8003) {
					i += 6 - 2;
					continue;
				}
				uint32_t addr = (inst & 0xFFFFF000) + (inst2 >> 20);
				addr += now_pos + (uint32_t)i;
				inst = 0x17 | (2 << 7) | (inst2 << 12);
				write32le(buffer + i, inst);
				write32be(buffer + i + 4, addr);
				i += 8 - 2;
			} else {
				const uint32_t fake_rs1 = inst >> 27;
				const uint32_t fake_addr = read32le(buffer + i + 4) + (uint32_t)(now_pos + i);
				const uint32_t fake_inst2 = (inst >> 12) | (fake_addr << 20);
				inst = 0x17 | (2 << 7) | (fake_addr & 0xFFFFF000) | (fake_rs1 << 7);
				(void)fake_inst2;
				write32le(buffer + i, inst);
				i += 4 - 2;
			}
		}
	}
	return i;
}

static size_t riscv_decode(uint32_t now_pos, uint8_t *buffer, size_t size)
{
	if (size < 8)
		return 0;
	size -= 8;
	size_t i;
	for (i = 0; i <= size; i += 2) {
		uint32_t inst = buffer[i];
		if (inst == 0xEF) {
			const uint32_t b1 = buffer[i + 1];
			if ((b1 & 0x0D) != 0)
				continue;
			const uint32_t b2 = buffer[i + 2];
			const uint32_t b3 = buffer[i + 3];
			const uint32_t pc = now_pos + (uint32_t)i;
			uint32_t addr = ((b1 & 0xF0) << 8) | ((b2 & 0x0F) << 16) | ((b2 & 0x10) << 7) | ((b2 & 0xE0) >> 4)
					| ((b3 & 0x7F) << 4) | ((b3 & 0x80) << 13);
			addr -= pc;
			buffer[i + 1] = (uint8_t)((b1 & 0x0F) | ((addr >> 13) & 0xF0));
			buffer[i + 2] = (uint8_t)(addr >> 9);
			buffer[i + 3] = (uint8_t)(addr >> 1);
			i += 4 - 2;
		} else if ((inst & 0x7F) == 0x17) {
			inst |= (uint32_t)buffer[i + 1] << 8;
			inst |= (uint32_t)buffer[i + 2] << 16;
			inst |= (uint32_t)buffer[i + 3] << 24;
			if (inst & 0xE80) {
				i += 6 - 2;
				continue;
			}
			uint32_t addr = read32be(buffer + i + 4);
			addr -= now_pos + (uint32_t)i;
			uint32_t inst2 = inst >> 12;
			inst = 0x17 | (inst2 << 7);
			inst2 |= (addr << 20);
			inst += (addr & 0x800) << 1;
			inst = (inst & 0xFFF) | (addr & 0xFFFFF000);
			write32le(buffer + i, inst);
			write32le(buffer + i + 4, inst2);
			i += 8 - 2;
		}
	}
	return i;
}

/* ---------- Simple coder framework ---------- */

#define SIMPLE_BUF_SIZE (UINT32_C(1) << 16)

typedef struct {
	uint64_t id;
	bool is_encoder;
	uint32_t now_pos;
	x86_state x86;
	uint8_t *buffer;    /* holds data: [0, filtered) ready to output, [filtered, size) unfiltered */
	size_t pos;         /* output position within [0, filtered) */
	size_t filtered;
	size_t size;
	size_t allocated;
	bool end_reached;
} simple_coder;

static size_t call_filter(simple_coder *c, uint8_t *buf, size_t size)
{
	size_t filtered;
	switch (c->id) {
	case FID_X86: filtered = x86_code(&c->x86, c->now_pos, c->is_encoder, buf, size); break;
	case FID_ARM: filtered = arm_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_ARMTHUMB: filtered = armthumb_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_ARM64: filtered = arm64_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_POWERPC: filtered = powerpc_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_SPARC: filtered = sparc_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_IA64: filtered = ia64_code(c->now_pos, c->is_encoder, buf, size); break;
	case FID_RISCV: filtered = c->is_encoder ? riscv_encode(c->now_pos, buf, size) : riscv_decode(c->now_pos, buf, size); break;
	default: filtered = size; break;
	}
	c->now_pos += (uint32_t)filtered;
	return filtered;
}

static xret simple_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	simple_coder *c = ctx;
	if (action == A_SYNC_FLUSH)
		return R_OPTIONS_ERROR;

	while (true) {
		/* Output already-filtered data. */
		if (c->pos < c->filtered) {
			bufcpy(c->buffer, &c->pos, c->filtered, out, out_pos, out_size);
			if (c->pos < c->filtered)
				return R_OK;
		}
		if (c->end_reached && c->pos == c->size)
			return R_STREAM_END;

		/* Compact: move unfiltered tail to the front. */
		if (c->pos > 0) {
			memmove(c->buffer, c->buffer + c->pos, c->size - c->pos);
			c->size -= c->pos;
			c->pos = 0;
			c->filtered = 0;
		}

		/* Fill with more input. */
		const size_t before = c->size;
		bufcpy(in, in_pos, in_size, c->buffer, &c->size, c->allocated);
		if (*in_pos == in_size && action != A_RUN)
			c->end_reached = true;

		if (c->size == before && !c->end_reached) {
			/* No new input available. */
			return R_OK;
		}

		/* Filter. */
		c->filtered = c->size == 0 ? 0 : call_filter(c, c->buffer, c->size);
		if (c->end_reached && *in_pos == in_size)
			c->filtered = c->size;
		if (c->filtered == 0 && !c->end_reached) {
			if (c->size == c->allocated)
				return R_PROG_ERROR;
			return R_OK;
		}
	}
}

static void simple_end(void *ctx)
{
	simple_coder *c = ctx;
	free(c->buffer);
	free(c);
}

bool filter_is_simple(uint64_t id)
{
	return id == FID_X86 || id == FID_ARM || id == FID_ARMTHUMB || id == FID_ARM64
		|| id == FID_POWERPC || id == FID_SPARC || id == FID_IA64 || id == FID_RISCV;
}

xret simple_coder_init(xcoder *c, uint64_t id, const bcj_options *o, bool is_encoder)
{
	if (!filter_is_simple(id))
		return R_OPTIONS_ERROR;
	uint32_t start = o == NULL ? 0 : o->start_offset;
	uint32_t align = id == FID_X86 ? 1 : id == FID_ARMTHUMB ? 2 : id == FID_IA64 ? 16 : id == FID_RISCV ? 2 : 4;
	if (start % align != 0)
		return R_OPTIONS_ERROR;
	simple_coder *s = calloc(1, sizeof(simple_coder));
	if (s == NULL)
		return R_MEM_ERROR;
	s->id = id;
	s->is_encoder = is_encoder;
	s->now_pos = start;
	s->x86.prev_mask = 0;
	s->x86.prev_pos = (uint32_t)(-5);
	s->allocated = SIMPLE_BUF_SIZE;
	s->buffer = malloc(s->allocated);
	if (s->buffer == NULL) {
		free(s);
		return R_MEM_ERROR;
	}
	c->ctx = s;
	c->code = simple_code;
	c->end = simple_end;
	return R_OK;
}

/* ---------- Delta ---------- */

typedef struct {
	size_t distance;
	uint8_t pos;
	uint8_t history[256];
	bool is_encoder;
} delta_coder;

static xret delta_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	delta_coder *c = ctx;
	const size_t in_avail = in_size - *in_pos;
	const size_t out_avail = out_size - *out_pos;
	const size_t n = in_avail < out_avail ? in_avail : out_avail;
	const uint8_t *src = in + *in_pos;
	uint8_t *dst = out + *out_pos;
	const size_t distance = c->distance;
	if (c->is_encoder) {
		for (size_t i = 0; i < n; ++i) {
			const uint8_t tmp = c->history[(distance + c->pos) & 0xFF];
			c->history[c->pos-- & 0xFF] = src[i];
			dst[i] = src[i] - tmp;
		}
	} else {
		for (size_t i = 0; i < n; ++i) {
			dst[i] = src[i] + c->history[(distance + c->pos) & 0xFF];
			c->history[c->pos-- & 0xFF] = dst[i];
		}
	}
	*in_pos += n;
	*out_pos += n;
	if (*in_pos == in_size && action != A_RUN)
		return R_STREAM_END;
	return R_OK;
}

static void delta_end(void *ctx) { free(ctx); }

xret delta_coder_init(xcoder *c, const delta_options *o, bool is_encoder)
{
	if (o == NULL || o->type != 0 || o->dist < 1 || o->dist > 256)
		return R_OPTIONS_ERROR;
	delta_coder *d = calloc(1, sizeof(delta_coder));
	if (d == NULL)
		return R_MEM_ERROR;
	d->distance = o->dist;
	d->is_encoder = is_encoder;
	c->ctx = d;
	c->code = delta_code;
	c->end = delta_end;
	return R_OK;
}
