		if (id == FID_LZMA1 || id == FID_LZMA1EXT || id == FID_LZMA2) {
			if (!last)
				return false;
		} else {
			if (last)
				return false;
		}
	}
	return true;
}

xret filter_props_size(const xfilter *f, uint32_t *size)
{
	switch (f->id) {
	case FID_LZMA1: *size = 5; return R_OK;
	case FID_LZMA2: *size = 1; return R_OK;
	case FID_DELTA: *size = 1; return R_OK;
	default:
		if (filter_is_simple(f->id)) {
			const bcj_options *o = f->options;
			*size = (o == NULL || o->start_offset == 0) ? 0 : 4;
			return R_OK;
		}
		return R_OPTIONS_ERROR;
	}
}

xret filter_props_encode(const xfilter *f, uint8_t *out)
{
	switch (f->id) {
	case FID_LZMA1:
		return lzma1_props_encode(f->options, out) ? R_PROG_ERROR : R_OK;
	case FID_LZMA2:
		return lzma2_props_encode(f->options, out) ? R_PROG_ERROR : R_OK;
	case FID_DELTA: {
		const delta_options *o = f->options;
		if (o->type != 0 || o->dist < 1 || o->dist > 256)
			return R_PROG_ERROR;
		out[0] = (uint8_t)(o->dist - 1);
		return R_OK;
	}
	default:
		if (filter_is_simple(f->id)) {
			const bcj_options *o = f->options;
			if (o != NULL && o->start_offset != 0)
				write32le(out, o->start_offset);
			return R_OK;
		}
		return R_OPTIONS_ERROR;
	}
}

xret filter_props_decode(xfilter *f, const uint8_t *props, size_t size)
{
	f->options = NULL;
	switch (f->id) {
	case FID_LZMA1:
	case FID_LZMA1EXT: {
		lzma_options *o = calloc(1, sizeof(*o));
		if (o == NULL) return R_MEM_ERROR;
		if (lzma1_props_decode(o, props, size)) { free(o); return R_OPTIONS_ERROR; }
		f->options = o;
		return R_OK;
	}
	case FID_LZMA2: {
		lzma_options *o = calloc(1, sizeof(*o));
		if (o == NULL) return R_MEM_ERROR;
		if (lzma2_props_decode(o, props, size)) { free(o); return R_OPTIONS_ERROR; }
		f->options = o;
		return R_OK;
	}
	case FID_DELTA: {
		if (size != 1) return R_OPTIONS_ERROR;
		delta_options *o = calloc(1, sizeof(*o));
		if (o == NULL) return R_MEM_ERROR;
		o->type = 0;
		o->dist = props[0] + 1U;
		f->options = o;
		return R_OK;
	}
	default:
		if (filter_is_simple(f->id)) {
			if (size == 0)
				return R_OK;
			if (size != 4)
				return R_OPTIONS_ERROR;
			bcj_options *o = calloc(1, sizeof(*o));
			if (o == NULL) return R_MEM_ERROR;
			o->start_offset = read32le(props);
			if (o->start_offset == 0) { free(o); return R_OK; }
			f->options = o;
			return R_OK;
		}
		return R_OPTIONS_ERROR;
	}
}

xret filter_flags_size(const xfilter *f, uint32_t *size)
{
	if (f->id >= VLI_MAX / 2)
		return R_PROG_ERROR;
	uint32_t props_size;
	xret r = filter_props_size(f, &props_size);
	if (r != R_OK)
		return r;
	*size = vli_size(f->id) + vli_size(props_size) + props_size;
	return R_OK;
}

xret filter_flags_encode(const xfilter *f, uint8_t *out, size_t *out_pos, size_t out_size)
{
	if (f->id >= VLI_MAX / 2 || vli_encode(f->id, out, out_pos, out_size) != R_STREAM_END)
		return R_PROG_ERROR;
	uint32_t props_size;
	xret r = filter_props_size(f, &props_size);
	if (r != R_OK)
		return r;
	if (vli_encode(props_size, out, out_pos, out_size) != R_STREAM_END)
		return R_PROG_ERROR;
	if (*out_pos + props_size > out_size)
		return R_PROG_ERROR;
	r = filter_props_encode(f, out + *out_pos);
	if (r != R_OK)
		return r;
	*out_pos += props_size;
	return R_OK;
}

xret filter_flags_decode(xfilter *f, const uint8_t *in, size_t *in_pos, size_t in_size)
{
	f->options = NULL;
	xret r = vli_decode(&f->id, NULL, in, in_pos, in_size);
	if (r != R_STREAM_END)
		return r == R_OK ? R_DATA_ERROR : r;
	if (f->id >= VLI_MAX / 2)
		return R_DATA_ERROR;
	uint64_t props_size;
	r = vli_decode(&props_size, NULL, in, in_pos, in_size);
	if (r != R_STREAM_END)
		return r == R_OK ? R_DATA_ERROR : r;
	if (props_size > in_size - *in_pos)
		return R_DATA_ERROR;
	if (!filter_decoder_is_supported(f->id)) {
		*in_pos += props_size;
		return R_OPTIONS_ERROR;
	}
	r = filter_props_decode(f, in + *in_pos, (size_t)props_size);
	*in_pos += props_size;
	return r;
}

void filters_free(xfilter *filters)
{
	for (size_t i = 0; i < FILTERS_MAX + 1 && filters[i].id != FID_UNKNOWN; ++i) {
		free(filters[i].options);
		filters[i].options = NULL;
	}
}

static size_t options_size(uint64_t id)
{
	switch (id) {
	case FID_LZMA1: case FID_LZMA1EXT: case FID_LZMA2: return sizeof(lzma_options);
	case FID_DELTA: return sizeof(delta_options);
	default: return filter_is_simple(id) ? sizeof(bcj_options) : 0;
	}
}

bool filters_copy(const xfilter *src, xfilter *dst)
{
	size_t i;
	for (i = 0; i <= FILTERS_MAX && src[i].id != FID_UNKNOWN; ++i) {
		dst[i].id = src[i].id;
		dst[i].options = NULL;
		if (src[i].options != NULL) {
			size_t sz = options_size(src[i].id);
			dst[i].options = malloc(sz);
			if (dst[i].options == NULL)
				return true;
			memcpy(dst[i].options, src[i].options, sz);
		}
	}
	dst[i].id = FID_UNKNOWN;
	dst[i].options = NULL;
	return false;
}

uint64_t filter_encoder_memusage(const xfilter *f)
{
	switch (f->id) {
	case FID_LZMA1: return f->options ? lzma1_encoder_memusage(f->options) : UINT64_MAX;
	case FID_LZMA2: return f->options ? lzma2_encoder_memusage(f->options) : UINT64_MAX;
	case FID_DELTA: return DELTA_MEMUSAGE;
	default: return filter_is_simple(f->id) ? SIMPLE_MEMUSAGE : UINT64_MAX;
	}
}

uint64_t filter_decoder_memusage(const xfilter *f)
{
	switch (f->id) {
	case FID_LZMA1: case FID_LZMA1EXT: return f->options ? lzma1_decoder_memusage(f->options) : UINT64_MAX;
	case FID_LZMA2: return f->options ? lzma2_decoder_memusage(f->options) : UINT64_MAX;
	case FID_DELTA: return DELTA_MEMUSAGE;
	default: return filter_is_simple(f->id) ? SIMPLE_MEMUSAGE : UINT64_MAX;
	}
}

static uint64_t chain_memusage(const xfilter *filters, bool is_encoder)
{
	if (!filters_validate_chain(filters, is_encoder))
		return UINT64_MAX;
	uint64_t total = MEMUSAGE_BASE;
	for (size_t i = 0; filters[i].id != FID_UNKNOWN; ++i) {
		const uint64_t m = is_encoder ? filter_encoder_memusage(&filters[i]) : filter_decoder_memusage(&filters[i]);
		if (m == UINT64_MAX)
			return UINT64_MAX;
		total += m;
	}
	return total;
}

uint64_t raw_encoder_memusage(const xfilter *filters) { return chain_memusage(filters, true); }
uint64_t raw_decoder_memusage(const xfilter *filters) { return chain_memusage(filters, false); }

uint64_t filters_mt_block_size(const xfilter *filters)
{
	if (!filters_validate_chain(filters, true))
		return UINT64_MAX;
	uint64_t max = 0;
	for (size_t i = 0; filters[i].id != FID_UNKNOWN; ++i) {
		if (filters[i].id == FID_LZMA2) {
			const uint64_t s = lzma2_block_size(filters[i].options);
			if (s > max) max = s;
		} else if (filters[i].id == FID_LZMA1) {
			return UINT64_MAX;
		}
	}
	return max;
}

/* ---------- pipeline ---------- */

#define STAGE_BUF_SIZE (UINT32_C(1) << 16)

typedef struct {
	xcoder c;
	uint8_t *buf;
	size_t pos;
	size_t size;
	bool ended;
} pipe_stage;

typedef struct {
	size_t count;
	pipe_stage stages[FILTERS_MAX];
} pipeline;

static xret pipeline_code(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	pipeline *p = ctx;
	if (p->count == 1)
		return xcoder_code(&p->stages[0].c, in, in_pos, in_size, out, out_pos, out_size, action);

	while (true) {
		bool progress = false;
		for (size_t i = 0; i < p->count; ++i) {
			pipe_stage *st = &p->stages[i];
			if (st->ended)
				continue;
			const uint8_t *sin;
			size_t *sin_pos;
			size_t sin_size;
			xaction act;
			if (i == 0) {
				sin = in; sin_pos = in_pos; sin_size = in_size; act = action;
			} else {
				pipe_stage *prev = &p->stages[i - 1];
				sin = prev->buf; sin_pos = &prev->pos; sin_size = prev->size;
				act = prev->ended ? A_FINISH : (action == A_RUN ? A_RUN : (prev->ended ? action : A_RUN));
				if (prev->ended && action != A_RUN)
					act = action;
			}
			uint8_t *sout;
			size_t *sout_pos;
			size_t sout_size;
			if (i == p->count - 1) {
				sout = out; sout_pos = out_pos; sout_size = out_size;
			} else {
				if (st->pos == st->size) {
					st->pos = 0;
					st->size = 0;
				} else if (st->pos > 0) {
					memmove(st->buf, st->buf + st->pos, st->size - st->pos);
					st->size -= st->pos;
					st->pos = 0;
				}
				sout = st->buf; sout_pos = &st->size; sout_size = STAGE_BUF_SIZE;
			}
			const size_t in_before = *sin_pos;
			const size_t out_before = *sout_pos;
			const xret ret = xcoder_code(&st->c, sin, sin_pos, sin_size, sout, sout_pos, sout_size, act);
			if (*sin_pos != in_before || *sout_pos != out_before)
				progress = true;
			if (ret == R_STREAM_END) {
				st->ended = true;
				progress = true;
			} else if (ret != R_OK) {
				return ret;
			}
		}
		if (p->stages[p->count - 1].ended)
			return R_STREAM_END;
		if (!progress)
			return R_OK;
	}
}

static void pipeline_end(void *ctx)
{
	pipeline *p = ctx;
	for (size_t i = 0; i < p->count; ++i) {
		xcoder_end(&p->stages[i].c);
		free(p->stages[i].buf);
	}
	free(p);
}

static xret init_one(xcoder *c, const xfilter *f, bool is_encoder)
{
	switch (f->id) {
	case FID_LZMA1:
		if (is_encoder)
			return lzma1_encoder_init(c, f->options);
		return lzma1_decoder_init(c, f->options, VLI_UNKNOWN, true);
	case FID_LZMA1EXT:
		if (is_encoder)
			return R_OPTIONS_ERROR;
		return lzma1_decoder_init(c, f->options, VLI_UNKNOWN, true);
	case FID_LZMA2:
		return is_encoder ? lzma2_encoder_init(c, f->options) : lzma2_decoder_init(c, f->options);
	case FID_DELTA:
		return delta_coder_init(c, f->options, is_encoder);
	default:
		return simple_coder_init(c, f->id, f->options, is_encoder);
	}
}

static xret raw_init(xcoder *c, const xfilter *filters, bool is_encoder)
{
	if (!filters_validate_chain(filters, is_encoder))
		return R_OPTIONS_ERROR;
	const size_t count = filters_count(filters);
	pipeline *p = calloc(1, sizeof(pipeline));
	if (p == NULL)
		return R_MEM_ERROR;
	p->count = count;
	for (size_t i = 0; i < count; ++i) {
		/* Encoder: filters[0] first. Decoder: reverse order. */
		const xfilter *f = is_encoder ? &filters[i] : &filters[count - 1 - i];
		xret r = init_one(&p->stages[i].c, f, is_encoder);
		if (r != R_OK) {
			pipeline_end(p);
			return r;
		}
		if (i + 1 < count) {
			p->stages[i].buf = malloc(STAGE_BUF_SIZE);
			if (p->stages[i].buf == NULL) {
				pipeline_end(p);
				return R_MEM_ERROR;
			}
		}
	}
	c->ctx = p;
	c->code = pipeline_code;
	c->end = pipeline_end;
	return R_OK;
}

xret raw_encoder_init(xcoder *c, const xfilter *filters) { return raw_init(c, filters, true); }
xret raw_decoder_init(xcoder *c, const xfilter *filters) { return raw_init(c, filters, false); }
