#define XZR_VLI_H
#include "common.h"

/* Returns R_STREAM_END when the whole VLI has been encoded, R_OK if the
 * output got full, R_PROG_ERROR on invalid input. */
xret vli_encode(uint64_t vli, uint8_t *out, size_t *out_pos, size_t out_size);
/* Multi-call decode: vli_pos may be NULL for single-call. */
xret vli_decode(uint64_t *vli, size_t *vli_pos, const uint8_t *in, size_t *in_pos, size_t in_size);
uint32_t vli_size(uint64_t vli);

#endif
