cat > src/vli.c <<'EOF'
#include "vli.h"

xret vli_encode(uint64_t vli, uint8_t *out, size_t *out_pos, size_t out_size)
{
	if (vli > VLI_MAX)
		return R_PROG_ERROR;
	size_t vli_pos = 0;
	while (true) {
		if (*out_pos >= out_size)
			return R_OK;
		if (vli < 0x80 || vli_pos == VLI_BYTES_MAX - 1) {
			out[(*out_pos)++] = (uint8_t)vli;
			return R_STREAM_END;
		}
		out[(*out_pos)++] = (uint8_t)(vli | 0x80);
		vli >>= 7;
		++vli_pos;
	}
}

xret vli_decode(uint64_t *vli, size_t *vli_pos, const uint8_t *in, size_t *in_pos, size_t in_size)
{
	size_t vli_pos_internal = 0;
	if (vli_pos == NULL) {
		vli_pos = &vli_pos_internal;
		*vli = 0;
		if (*in_pos >= in_size)
			return R_DATA_ERROR;
	} else {
		if (*vli_pos == 0)
			*vli = 0;
		if (*in_pos >= in_size)
			return R_BUF_ERROR;
	}
	do {
		const uint8_t byte = in[*in_pos];
		++*in_pos;
		*vli += (uint64_t)(byte & 0x7F) << (*vli_pos * 7);
		++*vli_pos;
		if ((byte & 0x80) == 0) {
			if (byte == 0x00 && *vli_pos > 1)
				return R_DATA_ERROR;
			return vli_pos == &vli_pos_internal ? R_STREAM_END : R_STREAM_END;
		}
		if (*vli_pos == VLI_BYTES_MAX)
			return R_DATA_ERROR;
	} while (*in_pos < in_size);
	return vli_pos == &vli_pos_internal ? R_DATA_ERROR : R_OK;
}

uint32_t vli_size(uint64_t vli)
{
	if (vli > VLI_MAX)
		return 0;
	uint32_t i = 0;
	do {
		vli >>= 7;
		++i;
	} while (vli != 0);
	return i;
}
