/* .xz container structures: stream flags, block headers, index. */
#ifndef XZR_XZFMT_H
#define XZR_XZFMT_H
#include "common.h"
#include "filters.h"

typedef struct {
	uint32_t version;
	uint64_t backward_size;
	xcheck check;
} stream_flags;

extern const uint8_t xz_header_magic[6];
extern const uint8_t xz_footer_magic[2];

xret stream_header_encode(const stream_flags *f, uint8_t *out);
xret stream_footer_encode(const stream_flags *f, uint8_t *out);
xret stream_header_decode(stream_flags *f, const uint8_t *in);
xret stream_footer_decode(stream_flags *f, const uint8_t *in);
xret stream_flags_compare(const stream_flags *a, const stream_flags *b);

#define INDEX_INDICATOR 0x00

typedef struct {
	uint32_t version;
	uint32_t header_size;
	xcheck check;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	xfilter filters[FILTERS_MAX + 1];
	uint8_t raw_check[64];
	bool ignore_check;
} xblock;

#define BLOCK_HEADER_SIZE_MIN 8
#define BLOCK_HEADER_SIZE_MAX 1024
#define BLOCK_UNCOMPRESSED_SIZE_MAX (VLI_MAX)
#define COMPRESSED_SIZE_MAX (VLI_MAX - 64 - 1024 - 1)

static inline uint32_t block_header_size_decode(uint8_t b) { return ((uint32_t)b + 1) * 4; }

xret block_header_size(xblock *b);
xret block_header_encode(const xblock *b, uint8_t *out);
xret block_header_decode(xblock *b, const uint8_t *in);
xret block_compressed_size(xblock *b, uint64_t unpadded_size);
uint64_t block_unpadded_size(const xblock *b);
uint64_t block_total_size(const xblock *b);
void block_init(xblock *b);
void block_free_filters(xblock *b);

/* Block encoder / decoder as streaming coders. The xblock must outlive
 * the coder; the encoder fills in compressed_size/uncompressed_size. */
xret block_encoder_init(xcoder *c, xblock *b);
xret block_decoder_init(xcoder *c, xblock *b);

/* ---------- Index ---------- */

typedef struct index_record {
	uint64_t unpadded_size;
	uint64_t uncompressed_size;
} index_record;

typedef struct index_stream {
	stream_flags flags;
	uint64_t padding;           /* stream padding after this stream */
	index_record *records;
	size_t count;
	size_t alloc;
	uint64_t total_unpadded;    /* sum of unpadded sizes */
	uint64_t total_uncompressed;
	uint64_t compressed_base;   /* offset of this stream in the file */
	uint64_t uncompressed_base;
	uint64_t index_size;        /* size of the Index field */
} index_stream;

typedef struct {
	index_stream *streams;
	size_t count;
	size_t alloc;
	uint64_t total_blocks;
	uint64_t total_file_size;   /* compressed size incl. padding */
	uint64_t total_uncompressed;
	uint64_t total_padding;
	xcheck checks; /* bitmask */
} xindex;

void xindex_init(xindex *x);
void xindex_free(xindex *x);
bool xindex_add_stream(xindex *x, const stream_flags *f);
bool xindex_append(xindex *x, uint64_t unpadded_size, uint64_t uncompressed_size);
index_stream *xindex_last_stream(xindex *x);
uint64_t index_size_for(uint64_t count, uint64_t sum_vli_sizes);
uint64_t xindex_stream_index_size(const index_stream *s);
void xindex_finish_stream(xindex *x, uint64_t padding);
static inline uint64_t vli_ceil4(uint64_t n) { return (n + 3) & ~(uint64_t)3; }

/* Encode the Index of the last stream. */
xret index_encoder_init(xcoder *c, const index_stream *s);
/* Decode an Index into a freshly added stream of x; sets s->index_size. memlimit for records. */
xret index_decoder_init(xcoder *c, xindex *x, uint64_t memlimit);

/* Block size recommendation for MT: block header overhead bound. */
uint64_t block_buffer_bound(uint64_t uncompressed_size);

#endif
