cat > src/xzfmt.c <<'EOF'
#include "xzfmt.h"
#include "check.h"
#include "vli.h"

const uint8_t xz_header_magic[6] = { 0xFD, '7', 'z', 'X', 'Z', 0x00 };
const uint8_t xz_footer_magic[2] = { 'Y', 'Z' };

static bool stream_flags_valid(const stream_flags *f)
{
	return f->version == 0 && (unsigned)f->check <= CHECK_ID_MAX;
}

xret stream_header_encode(const stream_flags *f, uint8_t *out)
{
	if (!stream_flags_valid(f))
		return R_PROG_ERROR;
	memcpy(out, xz_header_magic, 6);
	out[6] = 0x00;
	out[7] = (uint8_t)f->check;
	write32le(out + 8, crc32_calc(out + 6, 2));
	return R_OK;
}

xret stream_footer_encode(const stream_flags *f, uint8_t *out)
{
	if (!stream_flags_valid(f))
		return R_PROG_ERROR;
	if (f->backward_size < BACKWARD_SIZE_MIN || f->backward_size > BACKWARD_SIZE_MAX || (f->backward_size & 3))
		return R_PROG_ERROR;
	write32le(out + 4, (uint32_t)(f->backward_size / 4 - 1));
	out[8] = 0x00;
	out[9] = (uint8_t)f->check;
	write32le(out, crc32_calc(out + 4, 6));
	memcpy(out + 10, xz_footer_magic, 2);
	return R_OK;
}

static xret decode_flags(stream_flags *f, const uint8_t *in)
{
	if (in[0] != 0x00 || (in[1] & 0xF0) != 0)
		return R_OPTIONS_ERROR;
	f->version = 0;
	f->check = (xcheck)(in[1] & 0x0F);
	return R_OK;
}

xret stream_header_decode(stream_flags *f, const uint8_t *in)
{
	if (memcmp(in, xz_header_magic, 6) != 0)
		return R_FORMAT_ERROR;
	if (crc32_calc(in + 6, 2) != read32le(in + 8))
		return R_DATA_ERROR;
	if (decode_flags(f, in + 6) != R_OK)
		return R_OPTIONS_ERROR;
	f->backward_size = VLI_UNKNOWN;
	return R_OK;
}

xret stream_footer_decode(stream_flags *f, const uint8_t *in)
{
	if (memcmp(in + 10, xz_footer_magic, 2) != 0)
		return R_FORMAT_ERROR;
	if (crc32_calc(in + 4, 6) != read32le(in))
		return R_DATA_ERROR;
	if (decode_flags(f, in + 8) != R_OK)
		return R_OPTIONS_ERROR;
	f->backward_size = ((uint64_t)read32le(in + 4) + 1) * 4;
	return R_OK;
}

xret stream_flags_compare(const stream_flags *a, const stream_flags *b)
{
	if (!stream_flags_valid(a) || !stream_flags_valid(b))
		return R_PROG_ERROR;
	if (a->version != b->version || a->check != b->check)
		return R_DATA_ERROR;
	if (a->backward_size != VLI_UNKNOWN && b->backward_size != VLI_UNKNOWN) {
		if (a->backward_size < BACKWARD_SIZE_MIN || a->backward_size > BACKWARD_SIZE_MAX
				|| b->backward_size < BACKWARD_SIZE_MIN || b->backward_size > BACKWARD_SIZE_MAX)
			return R_PROG_ERROR;
		if (a->backward_size != b->backward_size)
			return R_DATA_ERROR;
	}
	return R_OK;
}

/* ---------- Block header ---------- */

void block_init(xblock *b)
{
	memset(b, 0, sizeof(*b));
	b->version = 1;
	b->compressed_size = VLI_UNKNOWN;
	b->uncompressed_size = VLI_UNKNOWN;
	b->check = CHECK_NONE;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) {
		b->filters[i].id = FID_UNKNOWN;
		b->filters[i].options = NULL;
	}
}

void block_free_filters(xblock *b)
{
	filters_free(b->filters);
	for (size_t i = 0; i <= FILTERS_MAX; ++i)
		b->filters[i].id = FID_UNKNOWN;
}

xret block_header_size(xblock *b)
{
	if (b->version > 1)
		return R_OPTIONS_ERROR;
	b->header_size = 2 + 4;
	if (b->compressed_size != VLI_UNKNOWN) {
		if (b->compressed_size > COMPRESSED_SIZE_MAX || b->compressed_size == 0)
			return R_PROG_ERROR;
		b->header_size += vli_size(b->compressed_size);
	}
	if (b->uncompressed_size != VLI_UNKNOWN) {
		if (vli_size(b->uncompressed_size) == 0)
			return R_PROG_ERROR;
		b->header_size += vli_size(b->uncompressed_size);
	}
	size_t i;
	for (i = 0; i <= FILTERS_MAX && b->filters[i].id != FID_UNKNOWN; ++i) {
		if (i == FILTERS_MAX)
			return R_PROG_ERROR;
		uint32_t add;
		xret r = filter_flags_size(&b->filters[i], &add);
		if (r != R_OK)
			return r;
		b->header_size += add;
	}
	if (i == 0)
		return R_PROG_ERROR;
	b->header_size = (b->header_size + 3) & ~UINT32_C(3);
	if (b->header_size > BLOCK_HEADER_SIZE_MAX)
		return R_PROG_ERROR;
	return R_OK;
}

xret block_header_encode(const xblock *b, uint8_t *out)
{
	if (b->version > 1 || b->header_size < BLOCK_HEADER_SIZE_MIN || b->header_size > BLOCK_HEADER_SIZE_MAX
			|| (b->header_size & 3))
		return R_PROG_ERROR;
	out[0] = (uint8_t)(b->header_size / 4 - 1);
	out[1] = 0x00;
	size_t out_pos = 2;
	const size_t out_size = b->header_size - 4;
	if (b->compressed_size != VLI_UNKNOWN) {
		if (b->compressed_size > COMPRESSED_SIZE_MAX || b->compressed_size == 0)
			return R_PROG_ERROR;
		out[1] |= 0x40;
		if (vli_encode(b->compressed_size, out, &out_pos, out_size) != R_STREAM_END)
			return R_PROG_ERROR;
	}
	if (b->uncompressed_size != VLI_UNKNOWN) {
		out[1] |= 0x80;
		if (vli_encode(b->uncompressed_size, out, &out_pos, out_size) != R_STREAM_END)
			return R_PROG_ERROR;
	}
	size_t count = 0;
	while (b->filters[count].id != FID_UNKNOWN) {
		if (count == FILTERS_MAX)
			return R_PROG_ERROR;
		xret r = filter_flags_encode(&b->filters[count], out, &out_pos, out_size);
		if (r != R_OK)
			return r;
		++count;
	}
	if (count == 0)
		return R_PROG_ERROR;
	out[1] |= (uint8_t)(count - 1);
	memset(out + out_pos, 0, out_size - out_pos);
	write32le(out + out_size, crc32_calc(out, out_size));
	return R_OK;
}

xret block_header_decode(xblock *b, const uint8_t *in)
{
	for (size_t i = 0; i <= FILTERS_MAX; ++i) {
		b->filters[i].id = FID_UNKNOWN;
		b->filters[i].options = NULL;
	}
	if (b->version > 1)
		return R_OPTIONS_ERROR;
	const size_t in_size = b->header_size - 4;
	if (crc32_calc(in, in_size) != read32le(in + in_size))
		return R_DATA_ERROR;
	if (in[1] & 0x3C)
		return R_OPTIONS_ERROR;
	const size_t filter_count = (in[1] & 3U) + 1;
	size_t in_pos = 2;
	if (in[1] & 0x40) {
		if (vli_decode(&b->compressed_size, NULL, in, &in_pos, in_size) != R_STREAM_END)
			return R_DATA_ERROR;
		if (b->compressed_size == 0 || b->compressed_size > COMPRESSED_SIZE_MAX)
			return R_DATA_ERROR;
	} else {
		b->compressed_size = VLI_UNKNOWN;
	}
	if (in[1] & 0x80) {
		if (vli_decode(&b->uncompressed_size, NULL, in, &in_pos, in_size) != R_STREAM_END)
			return R_DATA_ERROR;
	} else {
		b->uncompressed_size = VLI_UNKNOWN;
	}
	for (size_t i = 0; i < filter_count; ++i) {
		xret r = filter_flags_decode(&b->filters[i], in, &in_pos, in_size);
		if (r != R_OK) {
			block_free_filters(b);
			return r;
		}
	}
	/* Padding must be zero. */
	while (in_pos < in_size) {
		if (in[in_pos++] != 0x00) {
			block_free_filters(b);
			return R_OPTIONS_ERROR;
		}
	}
	return R_OK;
}

uint64_t block_unpadded_size(const xblock *b)
{
	if (b->header_size < BLOCK_HEADER_SIZE_MIN || b->header_size > BLOCK_HEADER_SIZE_MAX
			|| (b->header_size & 3) || b->compressed_size == VLI_UNKNOWN || b->compressed_size == 0
			|| (unsigned)b->check > CHECK_ID_MAX)
		return 0;
	return b->header_size + b->compressed_size + check_size(b->check);
}

uint64_t block_total_size(const xblock *b)
{
	uint64_t u = block_unpadded_size(b);
	if (u == 0)
		return 0;
	return vli_ceil4(u);
}

xret block_compressed_size(xblock *b, uint64_t unpadded_size)
{
	if (b->header_size < BLOCK_HEADER_SIZE_MIN || b->header_size > BLOCK_HEADER_SIZE_MAX
			|| (b->header_size & 3) || (unsigned)b->check > CHECK_ID_MAX)
		return R_PROG_ERROR;
	const uint64_t container = b->header_size + check_size(b->check);
	if (unpadded_size <= container)
		return R_DATA_ERROR;
	const uint64_t compressed = unpadded_size - container;
	if (b->compressed_size != VLI_UNKNOWN && b->compressed_size != compressed)
		return R_DATA_ERROR;
	b->compressed_size = compressed;
	return R_OK;
}

/* ---------- Block encoder ---------- */

typedef struct {
	xcoder next;
	xblock *block;
	enum { BSEQ_CODE, BSEQ_PADDING, BSEQ_CHECK } sequence;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	size_t pos;
	xcheck_state check;
} block_enc;

static xret block_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	block_enc *c = ctx;
	switch (c->sequence) {
	case BSEQ_CODE: {
		const size_t in_start = *in_pos;
		const size_t out_start = *out_pos;
		const xret ret = xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
		const size_t in_used = *in_pos - in_start;
		const size_t out_used = *out_pos - out_start;
		if (COMPRESSED_SIZE_MAX - c->compressed_size < out_used)
			return R_DATA_ERROR;
		c->compressed_size += out_used;
		if (BLOCK_UNCOMPRESSED_SIZE_MAX - c->uncompressed_size < in_used)
			return R_DATA_ERROR;
		c->uncompressed_size += in_used;
		check_update(&c->check, in + in_start, in_used);
		if (ret != R_STREAM_END || action == A_SYNC_FLUSH)
			return ret;
		if ((c->block->compressed_size != VLI_UNKNOWN && c->block->compressed_size != c->compressed_size)
				|| (c->block->uncompressed_size != VLI_UNKNOWN && c->block->uncompressed_size != c->uncompressed_size))
			return R_DATA_ERROR;
		c->block->compressed_size = c->compressed_size;
		c->block->uncompressed_size = c->uncompressed_size;
		c->pos = 0;
		c->sequence = BSEQ_PADDING;
	}
		/* fall through */
	case BSEQ_PADDING:
		while (c->compressed_size & 3) {
			if (*out_pos >= out_size)
				return R_OK;
			out[(*out_pos)++] = 0x00;
			++c->compressed_size;
		}
		if (c->block->check == CHECK_NONE)
			return R_STREAM_END;
		check_finish(&c->check);
		memcpy(c->block->raw_check, c->check.buffer.u8, check_size(c->block->check));
		c->sequence = BSEQ_CHECK;
		/* fall through */
	case BSEQ_CHECK: {
		const size_t csize = check_size(c->block->check);
		bufcpy(c->block->raw_check, &c->pos, csize, out, out_pos, out_size);
		return c->pos == csize ? R_STREAM_END : R_OK;
	}
	}
	return R_PROG_ERROR;
}

static void block_enc_end(void *ctx)
{
	block_enc *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

xret block_encoder_init(xcoder *c, xblock *b)
{
	if (b->version > 1 || (unsigned)b->check > CHECK_ID_MAX)
		return R_OPTIONS_ERROR;
	if (!check_is_supported(b->check))
		return R_UNSUPPORTED_CHECK;
	block_enc *e = calloc(1, sizeof(*e));
	if (e == NULL)
		return R_MEM_ERROR;
	e->block = b;
	e->sequence = BSEQ_CODE;
	check_init(&e->check, b->check);
	xret r = raw_encoder_init(&e->next, b->filters);
	if (r != R_OK) {
		free(e);
		return r;
	}
	c->ctx = e;
	c->code = block_encode;
	c->end = block_enc_end;
	return R_OK;
}

/* ---------- Block decoder ---------- */

typedef struct {
	xcoder next;
	xblock *block;
	enum { BDSEQ_CODE, BDSEQ_PADDING, BDSEQ_CHECK } sequence;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	uint64_t compressed_limit;
	uint64_t uncompressed_limit;
	size_t check_pos;
	xcheck_state check;
	bool ignore_check;
} block_dec;

static inline bool is_size_valid(uint64_t size, uint64_t reference)
{
	return reference == VLI_UNKNOWN || reference == size;
}

static xret block_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	block_dec *c = ctx;
	switch (c->sequence) {
	case BDSEQ_CODE: {
		const size_t in_start = *in_pos;
		const size_t out_start = *out_pos;
		/* Limit input to the known compressed size. */
		const size_t in_stop = (c->compressed_limit - c->compressed_size < in_size - in_start)
				? in_start + (size_t)(c->compressed_limit - c->compressed_size) : in_size;
		const size_t out_stop = (c->uncompressed_limit - c->uncompressed_size < out_size - out_start)
				? out_start + (size_t)(c->uncompressed_limit - c->uncompressed_size) : out_size;
		xret ret = xcoder_code(&c->next, in, in_pos, in_stop, out, out_pos, out_stop, action);
		const size_t in_used = *in_pos - in_start;
		const size_t out_used = *out_pos - out_start;
		c->compressed_size += in_used;
		c->uncompressed_size += out_used;
		if (c->compressed_size > c->compressed_limit || c->uncompressed_size > c->uncompressed_limit)
			return R_DATA_ERROR;
		if (!c->ignore_check)
			check_update(&c->check, out + out_start, out_used);
		if (ret != R_STREAM_END) {
			if (ret == R_OK && in_stop < in_size && *in_pos == in_stop && *out_pos < out_stop) {
				/* Decoder wants more input but the Block's compressed size is exhausted. */
				return R_DATA_ERROR;
			}
			return ret;
		}
		if (!is_size_valid(c->compressed_size, c->block->compressed_size)
				|| !is_size_valid(c->uncompressed_size, c->block->uncompressed_size))
			return R_DATA_ERROR;
		c->block->compressed_size = c->compressed_size;
		c->block->uncompressed_size = c->uncompressed_size;
		c->sequence = BDSEQ_PADDING;
	}
		/* fall through */
	case BDSEQ_PADDING:
		while (c->compressed_size & 3) {
			if (*in_pos >= in_size)
				return R_OK;
			++c->compressed_size;
			if (in[(*in_pos)++] != 0x00)
				return R_DATA_ERROR;
		}
		if (c->block->check == CHECK_NONE)
			return R_STREAM_END;
		if (!c->ignore_check)
			check_finish(&c->check);
		c->sequence = BDSEQ_CHECK;
		/* fall through */
	case BDSEQ_CHECK: {
		const size_t csize = check_size(c->block->check);
		bufcpy(in, in_pos, in_size, c->block->raw_check, &c->check_pos, csize);
		if (c->check_pos < csize)
			return R_OK;
		if (!c->ignore_check && check_is_supported(c->block->check)
				&& memcmp(c->block->raw_check, c->check.buffer.u8, csize) != 0)
			return R_DATA_ERROR;
		return R_STREAM_END;
	}
	}
	return R_PROG_ERROR;
}

static void block_dec_end(void *ctx)
{
	block_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

xret block_decoder_init(xcoder *c, xblock *b)
{
	if (b->version > 1 || b->header_size < BLOCK_HEADER_SIZE_MIN || b->header_size > BLOCK_HEADER_SIZE_MAX
			|| (b->header_size & 3) || (unsigned)b->check > CHECK_ID_MAX)
		return R_PROG_ERROR;
	block_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->block = b;
	d->sequence = BDSEQ_CODE;
	d->ignore_check = b->ignore_check;
	check_init(&d->check, b->check);
	d->compressed_limit = b->compressed_size == VLI_UNKNOWN
			? (VLI_MAX & ~UINT64_C(3)) - b->header_size - check_size(b->check)
			: b->compressed_size;
	d->uncompressed_limit = b->uncompressed_size == VLI_UNKNOWN ? VLI_MAX : b->uncompressed_size;
	xret r = raw_decoder_init(&d->next, b->filters);
	if (r != R_OK) {
		free(d);
		return r;
	}
	c->ctx = d;
	c->code = block_decode;
	c->end = block_dec_end;
	return R_OK;
}

/* ---------- Index ---------- */

void xindex_init(xindex *x)
{
	memset(x, 0, sizeof(*x));
}

void xindex_free(xindex *x)
{
	for (size_t i = 0; i < x->count; ++i)
		free(x->streams[i].records);
	free(x->streams);
	memset(x, 0, sizeof(*x));
}

bool xindex_add_stream(xindex *x, const stream_flags *f)
{
	if (x->count == x->alloc) {
		size_t na = x->alloc ? x->alloc * 2 : 4;
		index_stream *ns = realloc(x->streams, na * sizeof(*ns));
		if (ns == NULL)
			return true;
		x->streams = ns;
		x->alloc = na;
	}
	index_stream *s = &x->streams[x->count];
	memset(s, 0, sizeof(*s));
	s->flags = *f;
	if (x->count > 0) {
		const index_stream *p = &x->streams[x->count - 1];
		s->compressed_base = p->compressed_base + 2 * STREAM_HEADER_SIZE + vli_ceil4(p->total_unpadded) + p->index_size + p->padding;
		s->uncompressed_base = p->uncompressed_base + p->total_uncompressed;
	}
	s->index_size = index_size_for(0, 0);
	x->count++;
	x->checks |= (xcheck)(1U << f->check);
	return false;
}

index_stream *xindex_last_stream(xindex *x)
{
	return x->count ? &x->streams[x->count - 1] : NULL;
}

uint64_t index_size_for(uint64_t count, uint64_t sum_vli_sizes)
{
	return vli_ceil4(1 + vli_size(count) + sum_vli_sizes) + 4;
}

uint64_t xindex_stream_index_size(const index_stream *s)
{
	uint64_t sum = 0;
	for (size_t i = 0; i < s->count; ++i)
		sum += vli_size(s->records[i].unpadded_size) + vli_size(s->records[i].uncompressed_size);
	return index_size_for(s->count, sum);
}

bool xindex_append(xindex *x, uint64_t unpadded_size, uint64_t uncompressed_size)
{
	index_stream *s = xindex_last_stream(x);
	if (s == NULL)
		return true;
	if (s->count == s->alloc) {
		size_t na = s->alloc ? s->alloc * 2 : 16;
		index_record *nr = realloc(s->records, na * sizeof(*nr));
		if (nr == NULL)
			return true;
		s->records = nr;
		s->alloc = na;
	}
	s->records[s->count].unpadded_size = unpadded_size;
	s->records[s->count].uncompressed_size = uncompressed_size;
	s->count++;
	s->total_unpadded += vli_ceil4(unpadded_size);
	s->total_uncompressed += uncompressed_size;
	s->index_size = xindex_stream_index_size(s);
	x->total_blocks++;
	x->total_uncompressed += uncompressed_size;
	return false;
}

void xindex_finish_stream(xindex *x, uint64_t padding)
{
	index_stream *s = xindex_last_stream(x);
	if (s == NULL)
		return;
	s->padding = padding;
	x->total_padding += padding;
	x->total_file_size = s->compressed_base + 2 * STREAM_HEADER_SIZE + vli_ceil4(s->total_unpadded) + s->index_size + s->padding;
}

/* Index encoder */
typedef struct {
	const index_stream *s;
	enum { ISEQ_INDICATOR, ISEQ_COUNT, ISEQ_UNPADDED, ISEQ_UNCOMPRESSED, ISEQ_PADDING, ISEQ_CRC32 } sequence;
	size_t record;
	size_t pos;
	uint32_t crc32;
} index_enc;

static xret index_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	(void)in; (void)in_pos; (void)in_size; (void)action;
	index_enc *c = ctx;
	const size_t out_start = *out_pos;
	xret ret = R_OK;
	while (*out_pos < out_size) {
		switch (c->sequence) {
		case ISEQ_INDICATOR:
			out[(*out_pos)++] = INDEX_INDICATOR;
			c->sequence = ISEQ_COUNT;
			break;
		case ISEQ_COUNT:
			ret = vli_encode(c->s->count, out, out_pos, out_size);
			if (ret != R_STREAM_END) goto out;
			c->sequence = c->s->count == 0 ? ISEQ_PADDING : ISEQ_UNPADDED;
			c->record = 0;
			ret = R_OK;
			break;
		case ISEQ_UNPADDED:
			ret = vli_encode(c->s->records[c->record].unpadded_size, out, out_pos, out_size);
			if (ret != R_STREAM_END) goto out;
			c->sequence = ISEQ_UNCOMPRESSED;
			ret = R_OK;
			break;
		case ISEQ_UNCOMPRESSED:
			ret = vli_encode(c->s->records[c->record].uncompressed_size, out, out_pos, out_size);
			if (ret != R_STREAM_END) goto out;
			++c->record;
			c->sequence = c->record == c->s->count ? ISEQ_PADDING : ISEQ_UNPADDED;
			ret = R_OK;
			break;
		case ISEQ_PADDING: {
			/* Padding to multiple of four: computed from the index size. */
			const uint64_t isize = xindex_stream_index_size(c->s);
			/* bytes written so far (incl. this call) tracked via c->pos */
			const size_t written = c->pos + (*out_pos - out_start);
			const uint64_t pad_end = isize - 4;
			if (written < pad_end) {
				out[(*out_pos)++] = 0x00;
				break;
			}
			c->sequence = ISEQ_CRC32;
			c->crc32 = 0;
			break;
		}
		case ISEQ_CRC32: {
			/* CRC32 over everything before it. We need the bytes; recompute by
			 * re-encoding into a temp buffer. */
			const uint64_t isize = xindex_stream_index_size(c->s);
			const size_t written = c->pos + (*out_pos - out_start);
			const size_t crc_pos = written - (isize - 4);
			if (crc_pos == 0) {
				/* compute crc over the index body */
				uint8_t *tmp = malloc(isize);
				if (tmp == NULL) return R_MEM_ERROR;
				size_t tp = 0;
				tmp[tp++] = INDEX_INDICATOR;
				vli_encode(c->s->count, tmp, &tp, isize);
				for (size_t i = 0; i < c->s->count; ++i) {
					vli_encode(c->s->records[i].unpadded_size, tmp, &tp, isize);
					vli_encode(c->s->records[i].uncompressed_size, tmp, &tp, isize);
				}
				while (tp < isize - 4) tmp[tp++] = 0;
				c->crc32 = crc32_calc(tmp, isize - 4);
				free(tmp);
			}
			out[(*out_pos)++] = (uint8_t)(c->crc32 >> (8 * crc_pos));
			if (crc_pos == 3) {
				c->pos += *out_pos - out_start;
				return R_STREAM_END;
			}
			break;
		}
		}
	}
out:
	c->pos += *out_pos - out_start;
	return ret == R_STREAM_END ? R_OK : ret;
}

static void index_enc_end(void *ctx) { free(ctx); }

xret index_encoder_init(xcoder *c, const index_stream *s)
{
	index_enc *e = calloc(1, sizeof(*e));
	if (e == NULL)
		return R_MEM_ERROR;
	e->s = s;
	e->sequence = ISEQ_INDICATOR;
	c->ctx = e;
	c->code = index_encode;
	c->end = index_enc_end;
	return R_OK;
}

/* Index decoder */
typedef struct {
	xindex *x;
	enum { IDSEQ_INDICATOR, IDSEQ_COUNT, IDSEQ_MEMUSAGE, IDSEQ_UNPADDED, IDSEQ_UNCOMPRESSED, IDSEQ_PADDING, IDSEQ_CRC32 } sequence;
	uint64_t memlimit;
	uint64_t count;
	uint64_t unpadded_size;
	uint64_t uncompressed_size;
	size_t vli_pos;
	uint64_t total_size;   /* bytes consumed */
	uint64_t index_size;   /* computed from count when known */
	uint64_t sum_vli;
	size_t crc_pos;
	uint32_t crc32;
	uint32_t crc_read;
} index_dec;

static xret index_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	(void)out; (void)out_pos; (void)out_size; (void)action;
	index_dec *c = ctx;
	const size_t in_start = *in_pos;
	xret ret = R_OK;
	while (*in_pos < in_size) {
		switch (c->sequence) {
		case IDSEQ_INDICATOR:
			if (in[(*in_pos)++] != INDEX_INDICATOR) { ret = R_DATA_ERROR; goto out; }
			c->sequence = IDSEQ_COUNT;
			break;
		case IDSEQ_COUNT:
			ret = vli_decode(&c->count, &c->vli_pos, in, in_pos, in_size);
			if (ret != R_STREAM_END) { if (ret == R_BUF_ERROR) ret = R_OK; goto out; }
			ret = R_OK;
			c->vli_pos = 0;
			c->sequence = IDSEQ_MEMUSAGE;
			break;
		case IDSEQ_MEMUSAGE: {
			/* Memory usage approximation: count * 24 bytes + base. */
			const uint64_t memusage = (c->count > (UINT64_MAX / 32)) ? UINT64_MAX : c->count * 32 + 1024;
			if (memusage > c->memlimit) { ret = R_MEMLIMIT_ERROR; goto out; }
			c->sequence = c->count == 0 ? IDSEQ_PADDING : IDSEQ_UNPADDED;
			break;
		}
		case IDSEQ_UNPADDED:
			ret = vli_decode(&c->unpadded_size, &c->vli_pos, in, in_pos, in_size);
			if (ret != R_STREAM_END) { if (ret == R_BUF_ERROR) ret = R_OK; goto out; }
			ret = R_OK;
			c->vli_pos = 0;
			if (c->unpadded_size < 12 + 4 || c->unpadded_size > VLI_MAX) { ret = R_DATA_ERROR; goto out; }
			c->sequence = IDSEQ_UNCOMPRESSED;
			break;
		case IDSEQ_UNCOMPRESSED:
			ret = vli_decode(&c->uncompressed_size, &c->vli_pos, in, in_pos, in_size);
			if (ret != R_STREAM_END) { if (ret == R_BUF_ERROR) ret = R_OK; goto out; }
			ret = R_OK;
			c->vli_pos = 0;
			{
				index_stream *s = xindex_last_stream(c->x);
				/* Validate totals don't overflow VLI_MAX. */
				if (s->total_unpadded + vli_ceil4(c->unpadded_size) > VLI_MAX
						|| s->total_uncompressed + c->uncompressed_size > VLI_MAX) {
					ret = R_DATA_ERROR; goto out;
				}
				if (xindex_append(c->x, c->unpadded_size, c->uncompressed_size)) { ret = R_MEM_ERROR; goto out; }
				c->sum_vli += vli_size(c->unpadded_size) + vli_size(c->uncompressed_size);
			}
			if (--c->count == 0)
				c->sequence = IDSEQ_PADDING;
			else
				c->sequence = IDSEQ_UNPADDED;
			break;
		case IDSEQ_PADDING: {
			index_stream *s = xindex_last_stream(c->x);
			c->index_size = index_size_for(s->count, c->sum_vli);
			const uint64_t consumed = c->total_size + (*in_pos - in_start);
			if (consumed < c->index_size - 4) {
				if (in[(*in_pos)++] != 0x00) { ret = R_DATA_ERROR; goto out; }
				break;
			}
			c->sequence = IDSEQ_CRC32;
			c->crc_pos = 0;
			c->crc_read = 0;
			break;
		}
		case IDSEQ_CRC32:
			c->crc_read |= (uint32_t)in[(*in_pos)++] << (8 * c->crc_pos);
			if (++c->crc_pos == 4) {
				index_stream *s = xindex_last_stream(c->x);
				/* Recompute CRC over the canonical encoding. */
				uint8_t *tmp = malloc(c->index_size);
				if (tmp == NULL) { ret = R_MEM_ERROR; goto out; }
				size_t tp = 0;
				tmp[tp++] = INDEX_INDICATOR;
				vli_encode(s->count, tmp, &tp, c->index_size);
				for (size_t i = 0; i < s->count; ++i) {
					vli_encode(s->records[i].unpadded_size, tmp, &tp, c->index_size);
					vli_encode(s->records[i].uncompressed_size, tmp, &tp, c->index_size);
				}
				while (tp < c->index_size - 4) tmp[tp++] = 0;
				const uint32_t crc = crc32_calc(tmp, c->index_size - 4);
				free(tmp);
				c->total_size += *in_pos - in_start;
				s->index_size = c->index_size;
				if (crc != c->crc_read)
					return R_DATA_ERROR;
				return R_STREAM_END;
			}
			break;
		}
	}
out:
	c->total_size += *in_pos - in_start;
	return ret;
}

static void index_dec_end(void *ctx) { free(ctx); }

xret index_decoder_init(xcoder *c, xindex *x, uint64_t memlimit)
{
	index_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->x = x;
	d->memlimit = memlimit;
	d->sequence = IDSEQ_INDICATOR;
	c->ctx = d;
	c->code = index_decode;
	c->end = index_dec_end;
	return R_OK;
}

uint64_t block_buffer_bound(uint64_t uncompressed_size)
{
	if (uncompressed_size > COMPRESSED_SIZE_MAX)
		return 0;
	const uint64_t overhead = ((uncompressed_size + 65535) / 65536) * 3 + 1;
	if (COMPRESSED_SIZE_MAX - overhead < uncompressed_size)
		return 0;
	return uncompressed_size + overhead + BLOCK_HEADER_SIZE_MAX + 64;
}
