#include "stream.h"
#include "check.h"

/* ---------- Single-threaded stream encoder ---------- */

typedef enum {
	SEQ_STREAM_HEADER,
	SEQ_BLOCK_INIT,
	SEQ_BLOCK_HEADER,
	SEQ_BLOCK_ENCODE,
	SEQ_INDEX_ENCODE,
	SEQ_STREAM_FOOTER,
} se_seq;

typedef struct {
	se_seq sequence;
	xcoder block_encoder;
	xblock block;
	xcoder index_encoder;
	xindex index;
	uint8_t buffer[STREAM_HEADER_SIZE + BLOCK_HEADER_SIZE_MAX];
	size_t buffer_pos;
	size_t buffer_size;
	xfilter filters[FILTERS_MAX + 1];
	stream_flags flags;
	bool filters_changed;
} stream_enc;

static xret block_encoder_setup(stream_enc *c)
{
	block_init(&c->block);
	c->block.check = c->flags.check;
	if (filters_copy(c->filters, c->block.filters))
		return R_MEM_ERROR;
	xret r = block_header_size(&c->block);
	if (r != R_OK)
		return r;
	r = block_header_encode(&c->block, c->buffer);
	if (r != R_OK)
		return r;
	c->buffer_pos = 0;
	c->buffer_size = c->block.header_size;
	xcoder_end(&c->block_encoder);
	return block_encoder_init(&c->block_encoder, &c->block);
}

static xret stream_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	stream_enc *c = ctx;
	while (true) {
	switch (c->sequence) {
	case SEQ_STREAM_HEADER:
	case SEQ_BLOCK_HEADER:
	case SEQ_STREAM_FOOTER:
		bufcpy(c->buffer, &c->buffer_pos, c->buffer_size, out, out_pos, out_size);
		if (c->buffer_pos < c->buffer_size)
			return R_OK;
		if (c->sequence == SEQ_STREAM_FOOTER)
			return R_STREAM_END;
		c->sequence = c->sequence == SEQ_STREAM_HEADER ? SEQ_BLOCK_INIT : SEQ_BLOCK_ENCODE;
		break;

	case SEQ_BLOCK_INIT:
		if (*in_pos == in_size) {
			if (action == A_RUN)
				return R_OK;
			if (action == A_FULL_FLUSH || action == A_FULL_BARRIER)
				return R_STREAM_END;
			if (action == A_SYNC_FLUSH)
				return R_STREAM_END;
			/* FINISH: no more blocks. */
			xcoder_end(&c->index_encoder);
			xret r = index_encoder_init(&c->index_encoder, xindex_last_stream(&c->index));
			if (r != R_OK)
				return r;
			c->sequence = SEQ_INDEX_ENCODE;
			break;
		}
		{
			xret r = block_encoder_setup(c);
			if (r != R_OK)
				return r;
		}
		c->sequence = SEQ_BLOCK_HEADER;
		break;

	case SEQ_BLOCK_ENCODE: {
		const xret r = xcoder_code(&c->block_encoder, in, in_pos, in_size, out, out_pos, out_size, action);
		if (r != R_STREAM_END || action == A_SYNC_FLUSH)
			return r;
		/* Block finished. */
		if (xindex_append(&c->index, block_unpadded_size(&c->block), c->block.uncompressed_size))
			return R_MEM_ERROR;
		block_free_filters(&c->block);
		c->sequence = SEQ_BLOCK_INIT;
		if (action == A_FULL_FLUSH || action == A_FULL_BARRIER)
			return R_STREAM_END;
		break;
	}

	case SEQ_INDEX_ENCODE: {
		const xret r = xcoder_code(&c->index_encoder, NULL, NULL, 0, out, out_pos, out_size, A_RUN);
		if (r != R_STREAM_END)
			return r;
		c->flags.backward_size = xindex_last_stream(&c->index)->index_size;
		xret r2 = stream_footer_encode(&c->flags, c->buffer);
		if (r2 != R_OK)
			return r2;
		c->buffer_pos = 0;
		c->buffer_size = STREAM_HEADER_SIZE;
		c->sequence = SEQ_STREAM_FOOTER;
		break;
	}
	}
	}
}

static void stream_enc_end(void *ctx)
{
	stream_enc *c = ctx;
	xcoder_end(&c->block_encoder);
	xcoder_end(&c->index_encoder);
	block_free_filters(&c->block);
	filters_free(c->filters);
	xindex_free(&c->index);
	free(c);
}

static xret stream_enc_update(void *ctx, const xfilter *filters)
{
	stream_enc *c = ctx;
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if (c->sequence != SEQ_BLOCK_INIT && c->sequence != SEQ_STREAM_HEADER)
		return R_PROG_ERROR;
	xfilter tmp[FILTERS_MAX + 1];
	if (filters_copy(filters, tmp))
		return R_MEM_ERROR;
	filters_free(c->filters);
	memcpy(c->filters, tmp, sizeof(tmp));
	return R_OK;
}

xret stream_encoder_init(xcoder *c, const xfilter *filters, xcheck check)
{
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if ((unsigned)check > CHECK_ID_MAX)
		return R_OPTIONS_ERROR;
	if (!check_is_supported(check))
		return R_UNSUPPORTED_CHECK;
	stream_enc *s = calloc(1, sizeof(*s));
	if (s == NULL)
		return R_MEM_ERROR;
	s->sequence = SEQ_STREAM_HEADER;
	s->flags.version = 0;
	s->flags.check = check;
	s->flags.backward_size = VLI_UNKNOWN;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) { s->filters[i].id = FID_UNKNOWN; s->filters[i].options = NULL; }
	block_init(&s->block);
	xindex_init(&s->index);
	if (filters_copy(filters, s->filters) || xindex_add_stream(&s->index, &s->flags)) {
		stream_enc_end(s);
		return R_MEM_ERROR;
	}
	if (stream_header_encode(&s->flags, s->buffer) != R_OK) {
		stream_enc_end(s);
		return R_PROG_ERROR;
	}
	s->buffer_pos = 0;
	s->buffer_size = STREAM_HEADER_SIZE;
	c->ctx = s;
	c->code = stream_encode;
	c->end = stream_enc_end;
	c->update = stream_enc_update;
	return R_OK;
}

xret stream_encoder_update(xcoder *c, const xfilter *filters)
{
	if (c->update == NULL)
		return R_PROG_ERROR;
	return c->update(c->ctx, filters);
}

/* ---------- "MT"-format stream encoder (sequential implementation) ---------- */

typedef enum {
	MT_SEQ_STREAM_HEADER,
	MT_SEQ_COLLECT,
	MT_SEQ_OUTPUT,
	MT_SEQ_INDEX,
	MT_SEQ_FOOTER,
} mt_seq;

typedef struct {
	mt_seq sequence;
	xfilter filters[FILTERS_MAX + 1];
	stream_flags flags;
	uint64_t block_size;
	uint8_t *inbuf;
	size_t in_filled;
	uint8_t *outbuf;
	size_t out_filled;
	size_t out_pos;
	size_t outbuf_alloc;
	xindex index;
	xcoder index_encoder;
	uint8_t hdr[STREAM_HEADER_SIZE];
	size_t hdr_pos;
	bool finishing;
} mt_enc;

static xret mt_encode_block(mt_enc *c)
{
	/* Encode c->inbuf[0..in_filled) as one Block with sizes in header. */
	xblock block;
	block_init(&block);
	block.check = c->flags.check;
	if (filters_copy(c->filters, block.filters))
		return R_MEM_ERROR;
	block.uncompressed_size = c->in_filled;
	block.compressed_size = VLI_UNKNOWN;

	/* Encode data first into outbuf after reserving header space. */
	xcoder enc = XCODER_INIT;
	xret r = block_encoder_init(&enc, &block);
	if (r != R_OK) {
		block_free_filters(&block);
		return r;
	}
	const uint64_t bound = block_buffer_bound(c->in_filled);
	if (bound == 0 || bound > SIZE_MAX / 2) {
		xcoder_end(&enc);
		block_free_filters(&block);
		return R_MEM_ERROR;
	}
	if (c->outbuf_alloc < bound) {
		uint8_t *nb = realloc(c->outbuf, (size_t)bound);
		if (nb == NULL) {
			xcoder_end(&enc);
			block_free_filters(&block);
			return R_MEM_ERROR;
		}
		c->outbuf = nb;
		c->outbuf_alloc = (size_t)bound;
	}
	size_t in_pos = 0;
	size_t out_pos = BLOCK_HEADER_SIZE_MAX;
	r = xcoder_code(&enc, c->inbuf, &in_pos, c->in_filled, c->outbuf, &out_pos, c->outbuf_alloc, A_FINISH);
	xcoder_end(&enc);
	if (r != R_STREAM_END) {
		block_free_filters(&block);
		return r == R_OK ? R_PROG_ERROR : r;
	}
	/* Now the sizes are known; encode the header right before the data. */
	r = block_header_size(&block);
	if (r == R_OK)
		r = block_header_encode(&block, c->outbuf + BLOCK_HEADER_SIZE_MAX - block.header_size);
	if (r != R_OK) {
		block_free_filters(&block);
		return r;
	}
	c->out_pos = BLOCK_HEADER_SIZE_MAX - block.header_size;
	c->out_filled = out_pos;
	if (xindex_append(&c->index, block_unpadded_size(&block), block.uncompressed_size)) {
		block_free_filters(&block);
		return R_MEM_ERROR;
	}
	block_free_filters(&block);
	c->in_filled = 0;
	return R_OK;
}

static xret mt_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	mt_enc *c = ctx;
	while (true) {
	switch (c->sequence) {
	case MT_SEQ_STREAM_HEADER:
	case MT_SEQ_FOOTER:
		bufcpy(c->hdr, &c->hdr_pos, STREAM_HEADER_SIZE, out, out_pos, out_size);
		if (c->hdr_pos < STREAM_HEADER_SIZE)
			return R_OK;
		if (c->sequence == MT_SEQ_FOOTER)
			return R_STREAM_END;
		c->sequence = MT_SEQ_COLLECT;
		break;

	case MT_SEQ_COLLECT: {
		/* Fill the input buffer up to block_size. */
		const size_t want = (size_t)(c->block_size - c->in_filled);
		const size_t avail = in_size - *in_pos;
		const size_t n = want < avail ? want : avail;
		memcpy(c->inbuf + c->in_filled, in + *in_pos, n);
		c->in_filled += n;
		*in_pos += n;
		if (c->in_filled == c->block_size) {
			xret r = mt_encode_block(c);
			if (r != R_OK)
				return r;
			c->sequence = MT_SEQ_OUTPUT;
			break;
		}
		if (*in_pos < in_size)
			return R_PROG_ERROR;
		if (action == A_RUN)
			return R_OK;
		if (action == A_SYNC_FLUSH || action == A_FULL_FLUSH || action == A_FULL_BARRIER) {
			if (c->in_filled == 0)
				return R_STREAM_END;
			xret r = mt_encode_block(c);
			if (r != R_OK)
				return r;
			c->sequence = MT_SEQ_OUTPUT;
			break;
		}
		/* FINISH */
		c->finishing = true;
		if (c->in_filled > 0) {
			xret r = mt_encode_block(c);
			if (r != R_OK)
				return r;
			c->sequence = MT_SEQ_OUTPUT;
			break;
		}
		xcoder_end(&c->index_encoder);
		{
			xret r = index_encoder_init(&c->index_encoder, xindex_last_stream(&c->index));
			if (r != R_OK)
				return r;
		}
		c->sequence = MT_SEQ_INDEX;
		break;
	}

	case MT_SEQ_OUTPUT:
		bufcpy(c->outbuf, &c->out_pos, c->out_filled, out, out_pos, out_size);
		if (c->out_pos < c->out_filled)
			return R_OK;
		c->sequence = MT_SEQ_COLLECT;
		if (!c->finishing && action != A_RUN && *in_pos == in_size && c->in_filled == 0) {
			if (action == A_FINISH)
				break;
			return R_STREAM_END;
		}
		break;

	case MT_SEQ_INDEX: {
		const xret r = xcoder_code(&c->index_encoder, NULL, NULL, 0, out, out_pos, out_size, A_RUN);
		if (r != R_STREAM_END)
			return r;
		c->flags.backward_size = xindex_last_stream(&c->index)->index_size;
		if (stream_footer_encode(&c->flags, c->hdr) != R_OK)
			return R_PROG_ERROR;
		c->hdr_pos = 0;
		c->sequence = MT_SEQ_FOOTER;
		break;
	}
	}
	}
}

static void mt_enc_end(void *ctx)
{
	mt_enc *c = ctx;
	xcoder_end(&c->index_encoder);
	filters_free(c->filters);
	xindex_free(&c->index);
	free(c->inbuf);
	free(c->outbuf);
	free(c);
}

static xret mt_enc_update(void *ctx, const xfilter *filters)
{
	mt_enc *c = ctx;
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	xfilter tmp[FILTERS_MAX + 1];
	if (filters_copy(filters, tmp))
		return R_MEM_ERROR;
	filters_free(c->filters);
	memcpy(c->filters, tmp, sizeof(tmp));
	return R_OK;
}

xret stream_encoder_mt_init(xcoder *c, const xfilter *filters, xcheck check, uint64_t block_size)
{
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if ((unsigned)check > CHECK_ID_MAX)
		return R_OPTIONS_ERROR;
	if (!check_is_supported(check))
		return R_UNSUPPORTED_CHECK;
	if (block_size == 0 || block_size > (UINT64_C(1) << 62) || block_size > SIZE_MAX / 4)
		return R_OPTIONS_ERROR;
	mt_enc *m = calloc(1, sizeof(*m));
	if (m == NULL)
		return R_MEM_ERROR;
	m->sequence = MT_SEQ_STREAM_HEADER;
	m->flags.version = 0;
	m->flags.check = check;
	m->flags.backward_size = VLI_UNKNOWN;
	m->block_size = block_size;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) { m->filters[i].id = FID_UNKNOWN; m->filters[i].options = NULL; }
	xindex_init(&m->index);
	m->inbuf = malloc((size_t)block_size);
	if (m->inbuf == NULL || filters_copy(filters, m->filters) || xindex_add_stream(&m->index, &m->flags)) {
		mt_enc_end(m);
		return R_MEM_ERROR;
	}
	if (stream_header_encode(&m->flags, m->hdr) != R_OK) {
		mt_enc_end(m);
		return R_PROG_ERROR;
	}
	m->hdr_pos = 0;
	c->ctx = m;
	c->code = mt_encode;
	c->end = mt_enc_end;
	c->update = mt_enc_update;
	return R_OK;
}

/* ---------- .lzma (alone) encoder ---------- */

typedef struct {
	xcoder next;
	uint8_t header[13];
	size_t header_pos;
} alone_enc;

static xret alone_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	alone_enc *c = ctx;
	if (c->header_pos < sizeof(c->header)) {
		bufcpy(c->header, &c->header_pos, sizeof(c->header), out, out_pos, out_size);
		if (c->header_pos < sizeof(c->header))
			return R_OK;
	}
	return xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
}

static void alone_enc_end(void *ctx)
{
	alone_enc *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

xret alone_encoder_init(xcoder *c, const lzma_options *o)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return R_OPTIONS_ERROR;
	if (o->dict_size < LZMA_DICT_SIZE_MIN)
		return R_OPTIONS_ERROR;
	alone_enc *a = calloc(1, sizeof(*a));
	if (a == NULL)
		return R_MEM_ERROR;
	a->header[0] = (uint8_t)((o->pb * 5 + o->lp) * 9 + o->lc);
	uint32_t d = o->dict_size - 1;
	d |= d >> 2;
	d |= d >> 3;
	d |= d >> 4;
	d |= d >> 8;
	d |= d >> 16;
	if (d == UINT32_MAX)
		--d;
	write32le(a->header + 1, d + 1);
	memset(a->header + 5, 0xFF, 8);
	a->header_pos = 0;
	xfilter filters[2] = { { FID_LZMA1, (void *)o }, { FID_UNKNOWN, NULL } };
	xret r = raw_encoder_init(&a->next, filters);
	if (r != R_OK) {
		free(a);
		return r;
	}
	c->ctx = a;
	c->code = alone_encode;
	c->end = alone_enc_end;
	return R_OK;
}
