#include "stream.h"
#include "check.h"

/* ---------- Single-threaded stream encoder ---------- */

typedef enum {
	SEQ_STREAM_HEADER,
	SEQ_BLOCK_INIT,
	SEQ_BLOCK_HEADER,
	SEQ_BLOCK_ENCODE,
	SEQ_INDEX_ENCODE,
	SEQ_STREAM_FOOTER,
} se_seq;

typedef struct {
	se_seq sequence;
	xcoder block_encoder;
	xblock block;
	xcoder index_encoder;
	xindex index;
	uint8_t buffer[STREAM_HEADER_SIZE + BLOCK_HEADER_SIZE_MAX];
	size_t buffer_pos;
	size_t buffer_size;
	xfilter filters[FILTERS_MAX + 1];
	stream_flags flags;
	bool filters_changed;
} stream_enc;

static xret block_encoder_setup(stream_enc *c)
{
	block_init(&c->block);
	c->block.check = c->flags.check;
	if (filters_copy(c->filters, c->block.filters))
		return R_MEM_ERROR;
	xret r = block_header_size(&c->block);
	if (r != R_OK)
		return r;
	r = block_header_encode(&c->block, c->buffer);
	if (r != R_OK)
		return r;
	c->buffer_pos = 0;
	c->buffer_size = c->block.header_size;
	xcoder_end(&c->block_encoder);
	return block_encoder_init(&c->block_encoder, &c->block);
}

static xret stream_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	stream_enc *c = ctx;
	while (true) {
	switch (c->sequence) {
	case SEQ_STREAM_HEADER:
	case SEQ_BLOCK_HEADER:
	case SEQ_STREAM_FOOTER:
		bufcpy(c->buffer, &c->buffer_pos, c->buffer_size, out, out_pos, out_size);
		if (c->buffer_pos < c->buffer_size)
			return R_OK;
		if (c->sequence == SEQ_STREAM_FOOTER)
			return R_STREAM_END;
		c->sequence = c->sequence == SEQ_STREAM_HEADER ? SEQ_BLOCK_INIT : SEQ_BLOCK_ENCODE;
		break;

	case SEQ_BLOCK_INIT:
		if (*in_pos == in_size) {
			if (action == A_RUN)
				return R_OK;
			if (action == A_FULL_FLUSH || action == A_FULL_BARRIER)
				return R_STREAM_END;
			if (action == A_SYNC_FLUSH)
				return R_STREAM_END;
			/* FINISH: no more blocks. */
			xcoder_end(&c->index_encoder);
			xret r = index_encoder_init(&c->index_encoder, xindex_last_stream(&c->index));
			if (r != R_OK)
				return r;
			c->sequence = SEQ_INDEX_ENCODE;
			break;
		}
		{
			xret r = block_encoder_setup(c);
			if (r != R_OK)
				return r;
		}
		c->sequence = SEQ_BLOCK_HEADER;
		break;

	case SEQ_BLOCK_ENCODE: {
		const xret r = xcoder_code(&c->block_encoder, in, in_pos, in_size, out, out_pos, out_size, action);
		if (r != R_STREAM_END || action == A_SYNC_FLUSH)
			return r;
		/* Block finished. */
		if (xindex_append(&c->index, block_unpadded_size(&c->block), c->block.uncompressed_size))
			return R_MEM_ERROR;
		block_free_filters(&c->block);
		c->sequence = SEQ_BLOCK_INIT;
		if (action == A_FULL_FLUSH || action == A_FULL_BARRIER)
			return R_STREAM_END;
		break;
	}

	case SEQ_INDEX_ENCODE: {
		const xret r = xcoder_code(&c->index_encoder, NULL, NULL, 0, out, out_pos, out_size, A_RUN);
		if (r != R_STREAM_END)
			return r;
		c->flags.backward_size = xindex_last_stream(&c->index)->index_size;
		xret r2 = stream_footer_encode(&c->flags, c->buffer);
		if (r2 != R_OK)
			return r2;
		c->buffer_pos = 0;
		c->buffer_size = STREAM_HEADER_SIZE;
		c->sequence = SEQ_STREAM_FOOTER;
		break;
	}
	}
	}
}

static void stream_enc_end(void *ctx)
{
	stream_enc *c = ctx;
	xcoder_end(&c->block_encoder);
	xcoder_end(&c->index_encoder);
	block_free_filters(&c->block);
	filters_free(c->filters);
	xindex_free(&c->index);
	free(c);
}

static xret stream_enc_update(void *ctx, const xfilter *filters)
{
	stream_enc *c = ctx;
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if (c->sequence != SEQ_BLOCK_INIT && c->sequence != SEQ_STREAM_HEADER)
		return R_PROG_ERROR;
	xfilter tmp[FILTERS_MAX + 1];
	if (filters_copy(filters, tmp))
		return R_MEM_ERROR;
	filters_free(c->filters);
	memcpy(c->filters, tmp, sizeof(tmp));
	return R_OK;
}

xret stream_encoder_init(xcoder *c, const xfilter *filters, xcheck check)
{
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if ((unsigned)check > CHECK_ID_MAX)
		return R_OPTIONS_ERROR;
	if (!check_is_supported(check))
		return R_UNSUPPORTED_CHECK;
	stream_enc *s = calloc(1, sizeof(*s));
	if (s == NULL)
		return R_MEM_ERROR;
	s->sequence = SEQ_STREAM_HEADER;
	s->flags.version = 0;
	s->flags.check = check;
	s->flags.backward_size = VLI_UNKNOWN;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) { s->filters[i].id = FID_UNKNOWN; s->filters[i].options = NULL; }
	block_init(&s->block);
	xindex_init(&s->index);
	if (filters_copy(filters, s->filters) || xindex_add_stream(&s->index, &s->flags)) {
		stream_enc_end(s);
		return R_MEM_ERROR;
	}
	if (stream_header_encode(&s->flags, s->buffer) != R_OK) {
		stream_enc_end(s);
		return R_PROG_ERROR;
	}
	s->buffer_pos = 0;
	s->buffer_size = STREAM_HEADER_SIZE;
	c->ctx = s;
	c->code = stream_encode;
	c->end = stream_enc_end;
	c->update = stream_enc_update;
	return R_OK;
}

xret stream_encoder_update(xcoder *c, const xfilter *filters)
{
	if (c->update == NULL)
		return R_PROG_ERROR;
	return c->update(c->ctx, filters);
}

/* ---------- "MT"-format stream encoder (sequential implementation) ---------- */

typedef enum {
	MT_SEQ_STREAM_HEADER,
	MT_SEQ_COLLECT,
	MT_SEQ_OUTPUT,
	MT_SEQ_INDEX,
	MT_SEQ_FOOTER,
} mt_seq;

typedef struct {
	mt_seq sequence;
	xfilter filters[FILTERS_MAX + 1];
	stream_flags flags;
	uint64_t block_size;
	uint8_t *inbuf;
	size_t in_filled;
	uint8_t *outbuf;
	size_t out_filled;
	size_t out_pos;
	size_t outbuf_alloc;
	xindex index;
	xcoder index_encoder;
	uint8_t hdr[STREAM_HEADER_SIZE];
	size_t hdr_pos;
	bool finishing;
} mt_enc;

static xret mt_encode_block(mt_enc *c)
{
	/* Encode c->inbuf[0..in_filled) as one Block with sizes in header. */
	xblock block;
	block_init(&block);
	block.check = c->flags.check;
	if (filters_copy(c->filters, block.filters))
		return R_MEM_ERROR;
	block.uncompressed_size = c->in_filled;
	block.compressed_size = VLI_UNKNOWN;

	/* Encode data first into outbuf after reserving header space. */
	xcoder enc = XCODER_INIT;
	xret r = block_encoder_init(&enc, &block);
	if (r != R_OK) {
		block_free_filters(&block);
		return r;
	}
	const uint64_t bound = block_buffer_bound(c->in_filled);
	if (bound == 0 || bound > SIZE_MAX / 2) {
		xcoder_end(&enc);
		block_free_filters(&block);
		return R_MEM_ERROR;
	}
	if (c->outbuf_alloc < bound) {
		uint8_t *nb = realloc(c->outbuf, (size_t)bound);
		if (nb == NULL) {
			xcoder_end(&enc);
			block_free_filters(&block);
			return R_MEM_ERROR;
		}
		c->outbuf = nb;
		c->outbuf_alloc = (size_t)bound;
	}
