	size_t out_pos = BLOCK_HEADER_SIZE_MAX;
	r = xcoder_code(&enc, c->inbuf, &in_pos, c->in_filled, c->outbuf, &out_pos, c->outbuf_alloc, A_FINISH);
	xcoder_end(&enc);
	if (r != R_STREAM_END) {
		block_free_filters(&block);
		return r == R_OK ? R_PROG_ERROR : r;
	}
	/* Now the sizes are known; encode the header right before the data. */
	r = block_header_size(&block);
	if (r == R_OK)
		r = block_header_encode(&block, c->outbuf + BLOCK_HEADER_SIZE_MAX - block.header_size);
	if (r != R_OK) {
		block_free_filters(&block);
		return r;
	}
	c->out_pos = BLOCK_HEADER_SIZE_MAX - block.header_size;
	c->out_filled = out_pos;
	if (xindex_append(&c->index, block_unpadded_size(&block), block.uncompressed_size)) {
		block_free_filters(&block);
		return R_MEM_ERROR;
	}
	block_free_filters(&block);
	c->in_filled = 0;
	return R_OK;
}

static xret mt_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	mt_enc *c = ctx;
	while (true) {
	switch (c->sequence) {
	case MT_SEQ_STREAM_HEADER:
	case MT_SEQ_FOOTER:
		bufcpy(c->hdr, &c->hdr_pos, STREAM_HEADER_SIZE, out, out_pos, out_size);
		if (c->hdr_pos < STREAM_HEADER_SIZE)
			return R_OK;
		if (c->sequence == MT_SEQ_FOOTER)
			return R_STREAM_END;
		c->sequence = MT_SEQ_COLLECT;
		break;

	case MT_SEQ_COLLECT: {
		/* Fill the input buffer up to block_size. */
		const size_t want = (size_t)(c->block_size - c->in_filled);
		const size_t avail = in_size - *in_pos;
		const size_t n = want < avail ? want : avail;
		memcpy(c->inbuf + c->in_filled, in + *in_pos, n);
		c->in_filled += n;
		*in_pos += n;
		if (c->in_filled == c->block_size) {
			xret r = mt_encode_block(c);
			if (r != R_OK)
				return r;
			c->sequence = MT_SEQ_OUTPUT;
			break;
		}
		if (*in_pos < in_size)
			return R_PROG_ERROR;
		if (action == A_RUN)
			return R_OK;
