		c->sequence = MT_SEQ_FOOTER;
		break;
	}
	}
	}
}

static void mt_enc_end(void *ctx)
{
	mt_enc *c = ctx;
	xcoder_end(&c->index_encoder);
	filters_free(c->filters);
	xindex_free(&c->index);
	free(c->inbuf);
	free(c->outbuf);
	free(c);
}

static xret mt_enc_update(void *ctx, const xfilter *filters)
{
	mt_enc *c = ctx;
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	xfilter tmp[FILTERS_MAX + 1];
	if (filters_copy(filters, tmp))
		return R_MEM_ERROR;
	filters_free(c->filters);
	memcpy(c->filters, tmp, sizeof(tmp));
	return R_OK;
}

xret stream_encoder_mt_init(xcoder *c, const xfilter *filters, xcheck check, uint64_t block_size)
{
	if (!filters_validate_chain(filters, true))
		return R_OPTIONS_ERROR;
	if ((unsigned)check > CHECK_ID_MAX)
		return R_OPTIONS_ERROR;
	if (!check_is_supported(check))
		return R_UNSUPPORTED_CHECK;
	if (block_size == 0 || block_size > (UINT64_C(1) << 62) || block_size > SIZE_MAX / 4)
		return R_OPTIONS_ERROR;
	mt_enc *m = calloc(1, sizeof(*m));
	if (m == NULL)
		return R_MEM_ERROR;
	m->sequence = MT_SEQ_STREAM_HEADER;
	m->flags.version = 0;
	m->flags.check = check;
	m->flags.backward_size = VLI_UNKNOWN;
	m->block_size = block_size;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) { m->filters[i].id = FID_UNKNOWN; m->filters[i].options = NULL; }
	xindex_init(&m->index);
	m->inbuf = malloc((size_t)block_size);
	if (m->inbuf == NULL || filters_copy(filters, m->filters) || xindex_add_stream(&m->index, &m->flags)) {
		mt_enc_end(m);
		return R_MEM_ERROR;
	}
	if (stream_header_encode(&m->flags, m->hdr) != R_OK) {
		mt_enc_end(m);
		return R_PROG_ERROR;
	}
	m->hdr_pos = 0;
	c->ctx = m;
	c->code = mt_encode;
	c->end = mt_enc_end;
	c->update = mt_enc_update;
	return R_OK;
}

/* ---------- .lzma (alone) encoder ---------- */

typedef struct {
	xcoder next;
	uint8_t header[13];
	size_t header_pos;
} alone_enc;

static xret alone_encode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	alone_enc *c = ctx;
	if (c->header_pos < sizeof(c->header)) {
		bufcpy(c->header, &c->header_pos, sizeof(c->header), out, out_pos, out_size);
		if (c->header_pos < sizeof(c->header))
			return R_OK;
	}
	return xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
}

static void alone_enc_end(void *ctx)
{
	alone_enc *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

xret alone_encoder_init(xcoder *c, const lzma_options *o)
{
	if (o->lc > LZMA_LCLP_MAX || o->lp > LZMA_LCLP_MAX || o->lc + o->lp > LZMA_LCLP_MAX || o->pb > LZMA_PB_MAX)
		return R_OPTIONS_ERROR;
	if (o->dict_size < LZMA_DICT_SIZE_MIN)
		return R_OPTIONS_ERROR;
	alone_enc *a = calloc(1, sizeof(*a));
	if (a == NULL)
		return R_MEM_ERROR;
	a->header[0] = (uint8_t)((o->pb * 5 + o->lp) * 9 + o->lc);
	uint32_t d = o->dict_size - 1;
	d |= d >> 2;
	d |= d >> 3;
	d |= d >> 4;
	d |= d >> 8;
	d |= d >> 16;
	if (d == UINT32_MAX)
		--d;
	write32le(a->header + 1, d + 1);
	memset(a->header + 5, 0xFF, 8);
	a->header_pos = 0;
	xfilter filters[2] = { { FID_LZMA1, (void *)o }, { FID_UNKNOWN, NULL } };
	xret r = raw_encoder_init(&a->next, filters);
	if (r != R_OK) {
		free(a);
		return r;
	}
	c->ctx = a;
	c->code = alone_encode;
	c->end = alone_enc_end;
	return R_OK;
}
