			return R_FORMAT_ERROR;
		c->sequence = AL_DICTIONARY_SIZE;
		++*in_pos;
		break;
	case AL_DICTIONARY_SIZE:
		c->options.dict_size |= (uint32_t)in[*in_pos] << (c->pos * 8);
		if (++c->pos == 4) {
			if (c->picky && c->options.dict_size != UINT32_MAX) {
				uint32_t d = c->options.dict_size - 1;
				d |= d >> 2;
				d |= d >> 3;
				d |= d >> 4;
				d |= d >> 8;
				d |= d >> 16;
				++d;
				if (d != c->options.dict_size)
					return R_FORMAT_ERROR;
