		const size_t in_start = *in_pos;
		const size_t out_start = *out_pos;
		const xret r = xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
		const size_t in_used = *in_pos - in_start;
		const size_t out_used = *out_pos - out_start;
		c->member_size += in_used;
		c->uncompressed_size += out_used;
		if (!c->ignore_check)
			c->crc32 = crc32_update(out + out_start, out_used, c->crc32);
		if (r != R_STREAM_END)
			return r;
		c->pos = 0;
		c->sequence = LZ_MEMBER_FOOTER;
	}
		/* fall through */
	case LZ_MEMBER_FOOTER: {
		const size_t tsize = c->version == 0 ? 12 : 20;
		bufcpy(in, in_pos, in_size, c->trailer, &c->pos, tsize);
		if (c->pos < tsize)
			return R_OK;
		c->member_size += tsize;
		const uint32_t crc = read32le(c->trailer);
		const uint64_t usize = read64le(c->trailer + 4);
		if (!c->ignore_check && crc != c->crc32)
			return R_DATA_ERROR;
		if (usize != c->uncompressed_size)
			return R_DATA_ERROR;
		if (c->version == 1) {
			const uint64_t msize = read64le(c->trailer + 12);
			if (msize != c->member_size)
				return R_DATA_ERROR;
		}
		if (!c->concatenated) {
			c->finished = true;
			return R_STREAM_END;
		}
		c->first_member = false;
		c->pos = 0;
		c->sequence = LZ_ID_STRING;
		break;
	}
	}
	}
}

static void lzip_dec_end(void *ctx)
{
	lzip_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

static uint64_t lzip_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	lzip_dec *c = ctx;
	*memusage = c->memusage;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0) {
		if (new_memlimit < c->memusage)
			return R_MEMLIMIT_ERROR;
		c->memlimit = new_memlimit;
	}
	return R_OK;
}

static xret lzip_dec_get_check(void *ctx, xcheck *check)
{
	(void)ctx;
	*check = CHECK_CRC32;
	return R_OK;
}

xret lzip_decoder_init(xcoder *c, uint64_t memlimit, uint32_t flags)
{
	if (flags & ~UINT32_C(0x1F))
		return R_OPTIONS_ERROR;
	lzip_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->sequence = LZ_ID_STRING;
	d->memlimit = memlimit == 0 ? 1 : memlimit;
	d->memusage = MEMUSAGE_BASE;
	d->tell_any_check = (flags & DEC_TELL_ANY_CHECK) != 0;
	d->ignore_check = (flags & DEC_IGNORE_CHECK) != 0;
	d->concatenated = (flags & DEC_CONCATENATED) != 0;
	d->first_member = true;
	c->ctx = d;
	c->code = lzip_decode;
	c->end = lzip_dec_end;
	c->memconfig = lzip_dec_memconfig;
	c->get_check = lzip_dec_get_check;
	return R_OK;
}

/* ---------- auto decoder ---------- */

typedef struct {
	xcoder next;
	uint64_t memlimit;
	uint32_t flags;
	bool allow_lzip;
	bool inited;
	uint8_t peek[6];
	size_t peek_pos;
	bool peek_pending; /* peeked bytes not yet given to next */
} auto_dec;

static xret auto_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	auto_dec *c = ctx;
	if (!c->inited) {
		if (*in_pos >= in_size)
			return R_OK;
		/* Peek at the first byte to decide the format. */
		const uint8_t b = in[*in_pos];
		xret r;
		if (b == 0xFD)
			r = stream_decoder_init(&c->next, c->memlimit, c->flags);
		else if (b == 'L' && c->allow_lzip)
			r = lzip_decoder_init(&c->next, c->memlimit, c->flags);
		else
			r = alone_decoder_init(&c->next, c->memlimit, true);
		if (r != R_OK)
			return r;
		c->inited = true;
	}
	return xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
}

static void auto_dec_end(void *ctx)
{
	auto_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

static uint64_t auto_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	auto_dec *c = ctx;
	if (c->inited && c->next.memconfig != NULL)
		return c->next.memconfig(c->next.ctx, memusage, old_memlimit, new_memlimit);
	*memusage = MEMUSAGE_BASE;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0)
		c->memlimit = new_memlimit;
	return R_OK;
}

static xret auto_dec_get_check(void *ctx, xcheck *check)
{
	auto_dec *c = ctx;
	if (c->inited && c->next.get_check != NULL)
		return c->next.get_check(c->next.ctx, check);
	*check = CHECK_NONE;
	return R_OK;
}

xret auto_decoder_init(xcoder *c, uint64_t memlimit, uint32_t flags, bool allow_lzip)
{
	if (flags & ~UINT32_C(0x1F))
		return R_OPTIONS_ERROR;
	auto_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->memlimit = memlimit;
	d->flags = flags;
	d->allow_lzip = allow_lzip;
	c->ctx = d;
	c->code = auto_decode;
	c->end = auto_dec_end;
	c->memconfig = auto_dec_memconfig;
	c->get_check = auto_dec_get_check;
	return R_OK;
}

xret coder_memconfig(xcoder *c, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	if (c->memconfig == NULL) {
		*memusage = MEMUSAGE_BASE;
		*old_memlimit = UINT64_MAX;
		return R_OK;
	}
	return (xret)c->memconfig(c->ctx, memusage, old_memlimit, new_memlimit);
}

xcheck coder_get_check(xcoder *c)
{
	xcheck ch = CHECK_NONE;
	if (c->get_check != NULL)
		c->get_check(c->ctx, &ch);
	return ch;
}
