#include "stream.h"
#include "check.h"
#include "lzma_dec.h"
#include "vli.h"

/* ---------- .xz stream decoder ---------- */

typedef enum {
	SD_STREAM_HEADER,
	SD_BLOCK_HEADER,
	SD_BLOCK_INIT,
	SD_BLOCK,
	SD_INDEX,
	SD_STREAM_FOOTER,
	SD_STREAM_PADDING,
} sd_seq;

typedef struct {
	sd_seq sequence;
	xcoder block_decoder;
	xblock block;
	xcoder index_decoder;
	xindex blocks;      /* records from decoded blocks */
	xindex index;       /* records from the Index field */
	stream_flags flags;
	uint64_t memlimit;
	uint64_t memusage;
	bool tell_no_check, tell_unsupported_check, tell_any_check, ignore_check, concatenated;
	bool first_stream;
	size_t pos;
	uint8_t buffer[BLOCK_HEADER_SIZE_MAX];
	uint64_t block_count;
	bool finished;
} stream_dec;

static xret sd_reset(stream_dec *c)
{
	c->sequence = SD_STREAM_HEADER;
	c->pos = 0;
	xindex_free(&c->blocks);
	xindex_free(&c->index);
	xindex_init(&c->blocks);
	xindex_init(&c->index);
	return R_OK;
}

static xret stream_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	stream_dec *c = ctx;
	if (c->finished)
		return R_STREAM_END;

	while (true) {
	switch (c->sequence) {
	case SD_STREAM_HEADER: {
		bufcpy(in, in_pos, in_size, c->buffer, &c->pos, STREAM_HEADER_SIZE);
		if (c->pos < STREAM_HEADER_SIZE)
			return R_OK;
		c->pos = 0;
		const xret ret = stream_header_decode(&c->flags, c->buffer);
		if (ret != R_OK)
			return ret == R_FORMAT_ERROR && !c->first_stream ? R_DATA_ERROR : ret;
		c->first_stream = false;
		if (xindex_add_stream(&c->blocks, &c->flags) || xindex_add_stream(&c->index, &c->flags))
			return R_MEM_ERROR;
		c->sequence = SD_BLOCK_HEADER;
		if (c->tell_no_check && c->flags.check == CHECK_NONE)
			return R_NO_CHECK;
		if (c->tell_unsupported_check && !check_is_supported(c->flags.check))
			return R_UNSUPPORTED_CHECK;
		if (c->tell_any_check)
			return R_GET_CHECK;
		break;
	}

	case SD_BLOCK_HEADER: {
		if (*in_pos >= in_size)
			return R_OK;
		if (c->pos == 0) {
			if (in[*in_pos] == INDEX_INDICATOR) {
				xcoder_end(&c->index_decoder);
				xret r = index_decoder_init(&c->index_decoder, &c->index, c->memlimit);
				if (r != R_OK)
					return r;
				c->sequence = SD_INDEX;
				break;
			}
			block_free_filters(&c->block);
			block_init(&c->block);
			c->block.header_size = block_header_size_decode(in[*in_pos]);
		}
		bufcpy(in, in_pos, in_size, c->buffer, &c->pos, c->block.header_size);
		if (c->pos < c->block.header_size)
			return R_OK;
		c->pos = 0;
		c->sequence = SD_BLOCK_INIT;
	}
		/* fall through */

	case SD_BLOCK_INIT: {
		c->block.check = c->flags.check;
		c->block.ignore_check = c->ignore_check;
		xret r = block_header_decode(&c->block, c->buffer);
		if (r != R_OK)
			return r;
		const uint64_t memusage = raw_decoder_memusage(c->block.filters);
		if (memusage == UINT64_MAX)
			return R_OPTIONS_ERROR;
		c->memusage = memusage;
		if (memusage > c->memlimit)
			return R_MEMLIMIT_ERROR;
		xcoder_end(&c->block_decoder);
		r = block_decoder_init(&c->block_decoder, &c->block);
		if (r != R_OK)
			return r;
		c->sequence = SD_BLOCK;
	}
		/* fall through */

	case SD_BLOCK: {
		const xret r = xcoder_code(&c->block_decoder, in, in_pos, in_size, out, out_pos, out_size, action);
		if (r != R_STREAM_END)
			return r;
		if (xindex_append(&c->blocks, block_unpadded_size(&c->block), c->block.uncompressed_size))
			return R_MEM_ERROR;
		c->block_count++;
		c->sequence = SD_BLOCK_HEADER;
		break;
	}

	case SD_INDEX: {
		const xret r = xcoder_code(&c->index_decoder, in, in_pos, in_size, NULL, NULL, 0, A_RUN);
		if (r != R_STREAM_END)
			return r;
		/* Compare the Index with what we saw in the Blocks. */
		const index_stream *a = xindex_last_stream(&c->blocks);
		const index_stream *b = xindex_last_stream(&c->index);
		if (a->count != b->count)
			return R_DATA_ERROR;
		for (size_t i = 0; i < a->count; ++i)
			if (a->records[i].unpadded_size != b->records[i].unpadded_size
					|| a->records[i].uncompressed_size != b->records[i].uncompressed_size)
				return R_DATA_ERROR;
		c->sequence = SD_STREAM_FOOTER;
	}
		/* fall through */

	case SD_STREAM_FOOTER: {
		bufcpy(in, in_pos, in_size, c->buffer, &c->pos, STREAM_HEADER_SIZE);
		if (c->pos < STREAM_HEADER_SIZE)
			return R_OK;
		c->pos = 0;
		stream_flags footer;
		xret r = stream_footer_decode(&footer, c->buffer);
		if (r != R_OK)
			return r == R_FORMAT_ERROR ? R_DATA_ERROR : r;
		if (footer.backward_size != xindex_last_stream(&c->index)->index_size)
			return R_DATA_ERROR;
		if (stream_flags_compare(&c->flags, &footer) != R_OK)
			return R_DATA_ERROR;
		if (!c->concatenated) {
			c->finished = true;
			return R_STREAM_END;
		}
		c->sequence = SD_STREAM_PADDING;
	}
		/* fall through */

	case SD_STREAM_PADDING:
		while (true) {
			if (*in_pos >= in_size) {
				if (action != A_FINISH)
					return R_OK;
				if (c->pos != 0)
					return R_DATA_ERROR;
				c->finished = true;
				return R_STREAM_END;
			}
			if (in[*in_pos] != 0x00)
				break;
			++*in_pos;
			c->pos = (c->pos + 1) & 3;
		}
		if (c->pos != 0) {
			++*in_pos;
			return R_DATA_ERROR;
		}
		sd_reset(c);
		break;
	}
	}
}

static void stream_dec_end(void *ctx)
{
	stream_dec *c = ctx;
	xcoder_end(&c->block_decoder);
	xcoder_end(&c->index_decoder);
	block_free_filters(&c->block);
	xindex_free(&c->blocks);
	xindex_free(&c->index);
	free(c);
}

static uint64_t stream_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	stream_dec *c = ctx;
	*memusage = c->memusage;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0) {
		if (new_memlimit < c->memusage)
			return R_MEMLIMIT_ERROR;
		c->memlimit = new_memlimit;
	}
	return R_OK;
}

static xret stream_dec_get_check(void *ctx, xcheck *check)
{
	stream_dec *c = ctx;
	*check = c->flags.check;
	return R_OK;
}

xret stream_decoder_init(xcoder *c, uint64_t memlimit, uint32_t flags)
{
	if (flags & ~UINT32_C(0x1F))
		return R_OPTIONS_ERROR;
	stream_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->memlimit = memlimit == 0 ? 1 : memlimit;
	d->memusage = MEMUSAGE_BASE;
	d->tell_no_check = (flags & DEC_TELL_NO_CHECK) != 0;
	d->tell_unsupported_check = (flags & DEC_TELL_UNSUPPORTED_CHECK) != 0;
	d->tell_any_check = (flags & DEC_TELL_ANY_CHECK) != 0;
	d->ignore_check = (flags & DEC_IGNORE_CHECK) != 0;
	d->concatenated = (flags & DEC_CONCATENATED) != 0;
	d->first_stream = true;
	block_init(&d->block);
	xindex_init(&d->blocks);
	xindex_init(&d->index);
	d->sequence = SD_STREAM_HEADER;
	c->ctx = d;
	c->code = stream_decode;
	c->end = stream_dec_end;
	c->memconfig = stream_dec_memconfig;
	c->get_check = stream_dec_get_check;
	return R_OK;
}

/* ---------- .lzma (alone) decoder ---------- */

typedef enum { AL_PROPERTIES, AL_DICTIONARY_SIZE, AL_UNCOMPRESSED_SIZE, AL_CODER_INIT, AL_CODE } al_seq;

typedef struct {
	al_seq sequence;
	xcoder next;
	bool picky;
	size_t pos;
	lzma_options options;
	uint64_t uncompressed_size;
	uint64_t memlimit;
	uint64_t memusage;
} alone_dec;

static xret alone_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	alone_dec *c = ctx;
	while (*in_pos < in_size || c->sequence == AL_CODER_INIT || c->sequence == AL_CODE) {
	switch (c->sequence) {
	case AL_PROPERTIES:
		if (lzma_lclppb_decode(&c->options, in[*in_pos]))
			return R_FORMAT_ERROR;
		c->sequence = AL_DICTIONARY_SIZE;
		++*in_pos;
		break;
	case AL_DICTIONARY_SIZE:
		c->options.dict_size |= (uint32_t)in[*in_pos] << (c->pos * 8);
		if (++c->pos == 4) {
			if (c->picky && c->options.dict_size != UINT32_MAX) {
				uint32_t d = c->options.dict_size - 1;
				d |= d >> 2;
				d |= d >> 3;
				d |= d >> 4;
				d |= d >> 8;
				d |= d >> 16;
				++d;
				if (d != c->options.dict_size)
					return R_FORMAT_ERROR;
			}
			c->pos = 0;
			c->sequence = AL_UNCOMPRESSED_SIZE;
		}
		++*in_pos;
		break;
	case AL_UNCOMPRESSED_SIZE:
		c->uncompressed_size |= (uint64_t)in[*in_pos] << (c->pos * 8);
		++*in_pos;
		if (++c->pos < 8)
			break;
		if (c->picky && c->uncompressed_size != VLI_UNKNOWN && c->uncompressed_size >= (UINT64_C(1) << 38))
			return R_FORMAT_ERROR;
		c->memusage = lzma1_decoder_memusage(&c->options) + MEMUSAGE_BASE;
		c->pos = 0;
		c->sequence = AL_CODER_INIT;
		/* fall through */
	case AL_CODER_INIT: {
		if (c->memusage > c->memlimit)
			return R_MEMLIMIT_ERROR;
		xcoder_end(&c->next);
		xret r = lzma1_decoder_init(&c->next, &c->options, c->uncompressed_size, true);
		if (r != R_OK)
			return r;
		c->sequence = AL_CODE;
		break;
	}
	case AL_CODE:
		return xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
	}
	}
	return R_OK;
}

static void alone_dec_end(void *ctx)
{
	alone_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

static uint64_t alone_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	alone_dec *c = ctx;
	*memusage = c->memusage;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0) {
		if (new_memlimit < c->memusage)
			return R_MEMLIMIT_ERROR;
		c->memlimit = new_memlimit;
	}
	return R_OK;
}

static xret alone_dec_get_check(void *ctx, xcheck *check)
{
	(void)ctx;
	*check = CHECK_NONE;
	return R_OK;
}

xret alone_decoder_init(xcoder *c, uint64_t memlimit, bool picky)
{
	alone_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->sequence = AL_PROPERTIES;
	d->picky = picky;
	d->memlimit = memlimit == 0 ? 1 : memlimit;
	d->memusage = MEMUSAGE_BASE;
	d->uncompressed_size = 0;
	c->ctx = d;
	c->code = alone_decode;
	c->end = alone_dec_end;
	c->memconfig = alone_dec_memconfig;
	c->get_check = alone_dec_get_check;
	return R_OK;
}

/* ---------- .lz (lzip) decoder ---------- */

typedef enum { LZ_ID_STRING, LZ_VERSION, LZ_DICT_SIZE, LZ_CODER_INIT, LZ_LZMA_STREAM, LZ_MEMBER_FOOTER } lz_seq;

typedef struct {
	lz_seq sequence;
	xcoder next;
	uint64_t memlimit;
	uint64_t memusage;
	bool tell_any_check, ignore_check, concatenated;
	bool first_member;
	uint32_t version;
	size_t pos;
	lzma_options options;
	uint64_t member_size;
	uint64_t uncompressed_size;
	uint32_t crc32;
	uint8_t trailer[20];
	bool finished;
} lzip_dec;

static xret lzip_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	lzip_dec *c = ctx;
	if (c->finished)
		return R_STREAM_END;
	while (true) {
	switch (c->sequence) {
	case LZ_ID_STRING: {
		static const uint8_t magic[4] = { 'L', 'Z', 'I', 'P' };
		do {
			if (*in_pos >= in_size) {
				/* 2nd+ member: input may legitimately end here. */
				if (!c->first_member && c->pos == 0 && action == A_FINISH) {
					c->finished = true;
					return R_STREAM_END;
				}
				return R_OK;
			}
			if (in[*in_pos] != magic[c->pos]) {
				if (!c->first_member && c->pos == 0) {
					/* Trailing data: treat the rest as garbage. */
					c->finished = true;
					return R_STREAM_END;
				}
				return c->first_member ? R_FORMAT_ERROR : R_DATA_ERROR;
			}
			++*in_pos;
		} while (++c->pos < 4);
		c->pos = 0;
		c->member_size = 4;
		c->uncompressed_size = 0;
		c->crc32 = 0;
		c->sequence = LZ_VERSION;
	}
		/* fall through */
	case LZ_VERSION:
		if (*in_pos >= in_size)
			return R_OK;
		c->version = in[(*in_pos)++];
		++c->member_size;
		if (c->version > 1)
			return R_OPTIONS_ERROR;
		c->sequence = LZ_DICT_SIZE;
		/* fall through */
	case LZ_DICT_SIZE: {
		if (*in_pos >= in_size)
			return R_OK;
		const uint32_t ds = in[(*in_pos)++];
		++c->member_size;
		const uint32_t b = ds & 0x1F;
		if (b < 12 || b > 29)
			return R_DATA_ERROR;
		uint32_t dict_size = UINT32_C(1) << b;
		dict_size -= (dict_size / 16) * (ds >> 5);
		if (dict_size < 4096 || dict_size > (UINT32_C(1) << 29))
			return R_DATA_ERROR;
		memset(&c->options, 0, sizeof(c->options));
		c->options.dict_size = dict_size;
		c->options.lc = 3;
		c->options.lp = 0;
		c->options.pb = 2;
		c->memusage = lzma1_decoder_memusage(&c->options) + MEMUSAGE_BASE;
		c->sequence = LZ_CODER_INIT;
	}
		/* fall through */
	case LZ_CODER_INIT: {
		if (c->memusage > c->memlimit)
			return R_MEMLIMIT_ERROR;
		xcoder_end(&c->next);
		xret r = lzma1_decoder_init(&c->next, &c->options, VLI_UNKNOWN, true);
		if (r != R_OK)
			return r;
		c->sequence = LZ_LZMA_STREAM;
		if (c->tell_any_check)
			return R_GET_CHECK;
	}
		/* fall through */
	case LZ_LZMA_STREAM: {
		const size_t in_start = *in_pos;
		const size_t out_start = *out_pos;
		const xret r = xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
		const size_t in_used = *in_pos - in_start;
		const size_t out_used = *out_pos - out_start;
		c->member_size += in_used;
		c->uncompressed_size += out_used;
		if (!c->ignore_check)
			c->crc32 = crc32_update(out + out_start, out_used, c->crc32);
		if (r != R_STREAM_END)
			return r;
		c->pos = 0;
		c->sequence = LZ_MEMBER_FOOTER;
	}
		/* fall through */
	case LZ_MEMBER_FOOTER: {
		const size_t tsize = c->version == 0 ? 12 : 20;
		bufcpy(in, in_pos, in_size, c->trailer, &c->pos, tsize);
		if (c->pos < tsize)
			return R_OK;
		c->member_size += tsize;
		const uint32_t crc = read32le(c->trailer);
		const uint64_t usize = read64le(c->trailer + 4);
		if (!c->ignore_check && crc != c->crc32)
			return R_DATA_ERROR;
		if (usize != c->uncompressed_size)
			return R_DATA_ERROR;
		if (c->version == 1) {
			const uint64_t msize = read64le(c->trailer + 12);
			if (msize != c->member_size)
				return R_DATA_ERROR;
		}
		if (!c->concatenated) {
			c->finished = true;
			return R_STREAM_END;
		}
		c->first_member = false;
		c->pos = 0;
		c->sequence = LZ_ID_STRING;
		break;
	}
	}
	}
}

static void lzip_dec_end(void *ctx)
{
	lzip_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

static uint64_t lzip_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	lzip_dec *c = ctx;
	*memusage = c->memusage;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0) {
		if (new_memlimit < c->memusage)
			return R_MEMLIMIT_ERROR;
		c->memlimit = new_memlimit;
	}
	return R_OK;
}

static xret lzip_dec_get_check(void *ctx, xcheck *check)
{
	(void)ctx;
	*check = CHECK_CRC32;
	return R_OK;
}

xret lzip_decoder_init(xcoder *c, uint64_t memlimit, uint32_t flags)
{
	if (flags & ~UINT32_C(0x1F))
		return R_OPTIONS_ERROR;
	lzip_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->sequence = LZ_ID_STRING;
	d->memlimit = memlimit == 0 ? 1 : memlimit;
	d->memusage = MEMUSAGE_BASE;
	d->tell_any_check = (flags & DEC_TELL_ANY_CHECK) != 0;
	d->ignore_check = (flags & DEC_IGNORE_CHECK) != 0;
	d->concatenated = (flags & DEC_CONCATENATED) != 0;
	d->first_member = true;
	c->ctx = d;
	c->code = lzip_decode;
	c->end = lzip_dec_end;
	c->memconfig = lzip_dec_memconfig;
	c->get_check = lzip_dec_get_check;
	return R_OK;
}

/* ---------- auto decoder ---------- */

typedef struct {
	xcoder next;
	uint64_t memlimit;
	uint32_t flags;
	bool allow_lzip;
	bool inited;
	uint8_t peek[6];
	size_t peek_pos;
	bool peek_pending; /* peeked bytes not yet given to next */
} auto_dec;

static xret auto_decode(void *ctx, const uint8_t *in, size_t *in_pos, size_t in_size,
		uint8_t *out, size_t *out_pos, size_t out_size, xaction action)
{
	auto_dec *c = ctx;
	if (!c->inited) {
		if (*in_pos >= in_size)
			return R_OK;
		/* Peek at the first byte to decide the format. */
		const uint8_t b = in[*in_pos];
		xret r;
		if (b == 0xFD)
			r = stream_decoder_init(&c->next, c->memlimit, c->flags);
		else if (b == 'L' && c->allow_lzip)
			r = lzip_decoder_init(&c->next, c->memlimit, c->flags);
		else
			r = alone_decoder_init(&c->next, c->memlimit, true);
		if (r != R_OK)
			return r;
		c->inited = true;
	}
	return xcoder_code(&c->next, in, in_pos, in_size, out, out_pos, out_size, action);
}

static void auto_dec_end(void *ctx)
{
	auto_dec *c = ctx;
	xcoder_end(&c->next);
	free(c);
}

static uint64_t auto_dec_memconfig(void *ctx, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	auto_dec *c = ctx;
	if (c->inited && c->next.memconfig != NULL)
		return c->next.memconfig(c->next.ctx, memusage, old_memlimit, new_memlimit);
	*memusage = MEMUSAGE_BASE;
	*old_memlimit = c->memlimit;
	if (new_memlimit != 0)
		c->memlimit = new_memlimit;
	return R_OK;
}

static xret auto_dec_get_check(void *ctx, xcheck *check)
{
	auto_dec *c = ctx;
	if (c->inited && c->next.get_check != NULL)
		return c->next.get_check(c->next.ctx, check);
	*check = CHECK_NONE;
	return R_OK;
}

xret auto_decoder_init(xcoder *c, uint64_t memlimit, uint32_t flags, bool allow_lzip)
{
	if (flags & ~UINT32_C(0x1F))
		return R_OPTIONS_ERROR;
	auto_dec *d = calloc(1, sizeof(*d));
	if (d == NULL)
		return R_MEM_ERROR;
	d->memlimit = memlimit;
	d->flags = flags;
	d->allow_lzip = allow_lzip;
	c->ctx = d;
	c->code = auto_decode;
	c->end = auto_dec_end;
	c->memconfig = auto_dec_memconfig;
	c->get_check = auto_dec_get_check;
	return R_OK;
}

xret coder_memconfig(xcoder *c, uint64_t *memusage, uint64_t *old_memlimit, uint64_t new_memlimit)
{
	if (c->memconfig == NULL) {
		*memusage = MEMUSAGE_BASE;
		*old_memlimit = UINT64_MAX;
		return R_OK;
	}
	return (xret)c->memconfig(c->ctx, memusage, old_memlimit, new_memlimit);
}

xcheck coder_get_check(xcoder *c)
{
	xcheck ch = CHECK_NONE;
	if (c->get_check != NULL)
		c->get_check(c->ctx, &ch);
	return ch;
}
