#include "private.h"

void *xrealloc(void *ptr, size_t size)
{
	ptr = realloc(ptr, size);
	if (ptr == NULL)
		message_fatal("%s", strerror(errno));
	return ptr;
}

char *xstrdup(const char *src)
{
	const size_t size = strlen(src) + 1;
	char *dest = xrealloc(NULL, size);
	return memcpy(dest, src, size);
}

uint64_t str_to_uint64(const char *name, const char *value, uint64_t min, uint64_t max)
{
	uint64_t result = 0;

	while (*value == ' ' || *value == '\t')
		++value;

	if (strcmp(value, "max") == 0)
		return max;

	if (*value < '0' || *value > '9')
		message_fatal(_("%s: Value is not a non-negative decimal integer"), value);

	do {
		if (result > UINT64_MAX / 10)
			goto error;
		result *= 10;
		const uint32_t add = (uint32_t)(*value - '0');
		if (UINT64_MAX - add < result)
			goto error;
		result += add;
		++value;
	} while (*value >= '0' && *value <= '9');

	if (*value != '\0') {
		uint64_t multiplier = 0;
		if (*value == 'k' || *value == 'K')
			multiplier = UINT64_C(1) << 10;
		else if (*value == 'm' || *value == 'M')
			multiplier = UINT64_C(1) << 20;
		else if (*value == 'g' || *value == 'G')
			multiplier = UINT64_C(1) << 30;

		++value;

		if (*value != '\0' && strcmp(value, "i") != 0 && strcmp(value, "iB") != 0 && strcmp(value, "B") != 0)
			multiplier = 0;

		if (multiplier == 0) {
			message(V_ERROR, _("%s: Invalid multiplier suffix"), value - 1);
			message_fatal(_("Valid suffixes are '%s' (2^10), '%s' (2^20), and '%s' (2^30)."), "KiB", "MiB", "GiB");
		}

		if (result > max / multiplier)
			goto error;
		result *= multiplier;
	}

	if (result < min || result > max)
		goto error;

	return result;

error:
	message_fatal(_("Value of the option '%s' must be in the range [%" PRIu64 ", %" PRIu64 "]"), name, min, max);
}

uint64_t round_up_to_mib(uint64_t n)
{
	return (n >> 20) + ((n & ((UINT32_C(1) << 20) - 1)) != 0);
}

static char bufs[4][128];

const char *uint64_to_str(uint64_t value, uint32_t slot)
{
	snprintf(bufs[slot], sizeof(bufs[slot]), "%" PRIu64, value);
	return bufs[slot];
}

const char *uint64_to_nicestr(uint64_t value, enum nicestr_unit unit_min, enum nicestr_unit unit_max,
		bool always_also_bytes, uint32_t slot)
{
	enum nicestr_unit unit = NICESTR_B;
	char *pos = bufs[slot];
	size_t left = sizeof(bufs[slot]);

	if ((unit_min == NICESTR_B && value < 10000) || unit_max == NICESTR_B) {
		my_snprintf(&pos, &left, "%" PRIu64, value);
	} else {
		double d = (double)value;
		do {
			d /= 1024.0;
			++unit;
		} while (unit < unit_min || (d > 9999.9 && unit < unit_max));
		my_snprintf(&pos, &left, "%.1f", d);
	}

	static const char suffix[5][4] = { "B", "KiB", "MiB", "GiB", "TiB" };
	my_snprintf(&pos, &left, " %s", suffix[unit]);

	if (always_also_bytes && value >= 10000)
		my_snprintf(&pos, &left, " (%" PRIu64 " B)", value);

	return bufs[slot];
}

void my_snprintf(char **pos, size_t *left, const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	const int len = vsnprintf(*pos, *left, fmt, ap);
	va_end(ap);
	if (len < 0 || (size_t)len >= *left) {
		*left = 0;
	} else {
		*pos += len;
		*left -= (size_t)len;
	}
}

bool is_tty(int fd)
{
	return isatty(fd);
}

bool is_tty_stdin(void)
{
	const bool ret = isatty(STDIN_FILENO);
	if (ret)
		message_error(_("Standard input is a terminal, aborting"));
	return ret;
}

bool is_tty_stdout(void)
{
	const bool ret = isatty(STDOUT_FILENO);
	if (ret)
		message_error(_("Standard output is a terminal, aborting"));
	return ret;
}

bool is_empty_filename(const char *filename)
{
	if (filename[0] == '\0') {
		message_error(_("Empty filename, skipping"));
		return true;
	}
	return false;
}
