#include "private.h"

static enum message_verbosity verbosity = V_WARNING;
static const char *filename;
static bool first_filename = true;
static bool current_filename_printed = false;
static unsigned int files_total = 0;
static unsigned int files_pos = 0;

static bool progress_automatic;
static bool progress_started = false;
static bool progress_active = false;
static xcoder *progress_coder;
static bool progress_is_passthru;
static uint64_t expected_in_size;
static uint64_t progress_in = 0;
static uint64_t progress_out = 0;
static volatile sig_atomic_t progress_needs_updating = false;
static uint64_t start_time;

static enum exit_status_type exit_status = E_SUCCESS;
static bool no_warn = false;

void set_exit_status(enum exit_status_type new_status)
{
	if (new_status == E_WARNING && no_warn)
		return;
	if (new_status == E_WARNING && exit_status == E_ERROR)
		return;
	exit_status = new_status;
}

void set_exit_no_warn(void)
{
	no_warn = true;
}

void my_exit(enum exit_status_type status)
{
	if (status != E_ERROR) {
		if (fclose(stdout)) {
			message_error(_("Writing to standard output failed"));
			status = E_ERROR;
		}
	}
	if (status != E_ERROR && status != E_WARNING) {
		if (ferror(stderr) || fclose(stderr))
			status = E_ERROR;
	}
	if (status == E_WARNING && no_warn)
		status = E_SUCCESS;
	exit(status);
}

static void progress_signal_handler(int sig)
{
	(void)sig;
	progress_needs_updating = true;
}

void message_init(void)
{
	progress_automatic = isatty(STDERR_FILENO);
	if (progress_automatic) {
		struct sigaction sa;
		sa.sa_handler = &progress_signal_handler;
		sigemptyset(&sa.sa_mask);
		sa.sa_flags = 0;
		sigaction(SIGALRM, &sa, NULL);
	}
}

void message_verbosity_increase(void)
{
	if (verbosity < V_DEBUG)
		++verbosity;
}

void message_verbosity_decrease(void)
{
	if (verbosity > V_SILENT)
		--verbosity;
}

enum message_verbosity message_verbosity_get(void)
{
	return verbosity;
}

void message_set_files(unsigned int files)
{
	files_total = files;
}

static void print_filename(void)
{
	if (!progress_automatic || current_filename_printed)
		return;
	signals_block();
	if (!first_filename)
		fputc('\n', stderr);
	first_filename = false;
	current_filename_printed = true;
	if (files_total != 1)
		fprintf(stderr, "%s (%u/%u)\n", filename, files_pos, files_total);
	else
		fprintf(stderr, "%s\n", filename);
	signals_unblock();
}

void message_filename(const char *src_name)
{
	filename = src_name;
	current_filename_printed = false;
	++files_pos;
}

static void progress_timer_start(void)
{
	struct itimerval timer;
	timer.it_interval.tv_sec = 1;
	timer.it_interval.tv_usec = 0;
	timer.it_value.tv_sec = 1;
	timer.it_value.tv_usec = 0;
	setitimer(ITIMER_REAL, &timer, NULL);
}

static void progress_timer_stop(void)
{
	struct itimerval timer;
	memset(&timer, 0, sizeof(timer));
	setitimer(ITIMER_REAL, &timer, NULL);
}

void message_progress_start(xcoder *coder, bool is_passthru, uint64_t in_size)
{
	progress_coder = coder;
	progress_is_passthru = is_passthru;
	start_time = mytime_now();
	expected_in_size = in_size;
	progress_started = true;
	progress_in = 0;
	progress_out = 0;
	progress_needs_updating = false;
	if (verbosity >= V_VERBOSE && progress_automatic) {
		print_filename();
		progress_timer_start();
	}
}

void message_progress_set_totals(uint64_t in, uint64_t out)
{
	progress_in = in;
	progress_out = out;
}

static const char *progress_percentage(uint64_t in_pos)
{
	if (expected_in_size == 0 || in_pos > expected_in_size)
		return "--- %";
	double percentage = (double)in_pos / (double)expected_in_size * 99.9;
	static char buf[sizeof("99.9 %") + 3];
	snprintf(buf, sizeof(buf), "%.1f %%", percentage);
	return buf;
}

static const char *progress_sizes(uint64_t compressed_pos, uint64_t uncompressed_pos, bool final)
{
	static char buf[128];
	char *pos = buf;
	size_t left = sizeof(buf);
	const enum nicestr_unit unit_min = final ? NICESTR_B : NICESTR_MIB;
	my_snprintf(&pos, &left, "%s / %s",
			uint64_to_nicestr(compressed_pos, unit_min, NICESTR_TIB, false, 0),
			uint64_to_nicestr(uncompressed_pos, unit_min, NICESTR_TIB, false, 1));
	const double ratio = uncompressed_pos > 0 ? (double)compressed_pos / (double)uncompressed_pos : 16.0;
	if (ratio > 9.999) {
		my_snprintf(&pos, &left, " > %.3f", 9.999);
	} else {
		my_snprintf(&pos, &left, " = %.3f", ratio);
	}
	return buf;
}

static const char *progress_speed(uint64_t uncompressed_pos, uint64_t elapsed)
{
	if (elapsed < 3000)
		return "";
	static const char unit[][8] = { "KiB/s", "MiB/s", "GiB/s" };
	size_t unit_index = 0;
	double speed = (double)uncompressed_pos / ((double)elapsed * (1024.0 / 1000.0));
	while (speed > 999.0) {
		speed /= 1024.0;
		if (++unit_index == ARRAY_SIZE(unit))
			return "";
	}
	static char buf[sizeof("999 GiB/s")];
	snprintf(buf, sizeof(buf), "%.*f %s", speed > 9.9 ? 0 : 1, speed, unit[unit_index]);
	return buf;
}

static const char *progress_time(uint64_t mseconds)
{
	static char buf[sizeof("9999:59:59")];
	uint32_t seconds = (uint32_t)(mseconds / 1000);
	if (seconds == 0 || seconds > ((9999 * 60) + 59) * 60 + 59)
		return "";
	uint32_t minutes = seconds / 60;
	seconds %= 60;
	uint32_t hours = minutes / 60;
	minutes %= 60;
	if (hours > 0)
		snprintf(buf, sizeof(buf), "%" PRIu32 ":%02" PRIu32 ":%02" PRIu32, hours, minutes, seconds);
	else
		snprintf(buf, sizeof(buf), "%" PRIu32 ":%02" PRIu32, minutes, seconds);
	return buf;
}

static const char *progress_remaining(uint64_t in_pos, uint64_t elapsed)
{
	if (expected_in_size == 0 || in_pos > expected_in_size || in_pos == 0 || elapsed < 6000)
		return "";
	uint32_t remaining = (uint32_t)((double)(expected_in_size - in_pos) * ((double)elapsed / 1000.0) / (double)in_pos);
	if (remaining < 1)
		remaining = 1;
	static char buf[sizeof("9 h 55 min")];
	if (remaining <= 10) {
		snprintf(buf, sizeof(buf), "%" PRIu32 " s", remaining);
	} else if (remaining <= 50) {
		remaining = (remaining + 4) / 5 * 5;
		snprintf(buf, sizeof(buf), "%" PRIu32 " s", remaining);
	} else if (remaining <= 590) {
		remaining = (remaining + 9) / 10 * 10;
		snprintf(buf, sizeof(buf), "%" PRIu32 " min %" PRIu32 " s", remaining / 60, remaining % 60);
	} else if (remaining <= 59 * 60) {
		remaining = (remaining + 59) / 60;
		snprintf(buf, sizeof(buf), "%" PRIu32 " min", remaining);
	} else if (remaining <= 9 * 3600 + 50 * 60) {
		remaining = (remaining + 599) / 600 * 10;
		snprintf(buf, sizeof(buf), "%" PRIu32 " h %" PRIu32 " min", remaining / 60, remaining % 60);
	} else if (remaining <= 23 * 3600) {
		remaining = (remaining + 3599) / 3600;
		snprintf(buf, sizeof(buf), "%" PRIu32 " h", remaining);
	} else if (remaining <= 9 * 24 * 3600 + 23 * 3600) {
		remaining = (remaining + 3599) / 3600;
		snprintf(buf, sizeof(buf), "%" PRIu32 " d %" PRIu32 " h", remaining / 24, remaining % 24);
	} else if (remaining <= 999 * 24 * 3600) {
		remaining = (remaining + 24 * 3600 - 1) / (24 * 3600);
		snprintf(buf, sizeof(buf), "%" PRIu32 " d", remaining);
	} else {
		return "";
	}
	return buf;
}

static void progress_pos(uint64_t *in_pos, uint64_t *compressed_pos, uint64_t *uncompressed_pos)
{
	*in_pos = progress_in;
	if (progress_is_passthru) {
		*compressed_pos = progress_in;
		*uncompressed_pos = progress_in;
	} else if (opt_mode == MODE_COMPRESS) {
		*compressed_pos = progress_out;
		*uncompressed_pos = progress_in;
	} else {
		*compressed_pos = progress_in;
		*uncompressed_pos = progress_out;
	}
}

static void progress_flush(bool finished)
{
	if (!progress_started || verbosity < V_VERBOSE)
		return;
	uint64_t in_pos, compressed_pos, uncompressed_pos;
	progress_pos(&in_pos, &compressed_pos, &uncompressed_pos);
	const uint64_t elapsed = mytime_get_elapsed();
	signals_block();
	if (progress_automatic) {
		fprintf(stderr, "\r %6s %35s %11s %10s %12s%s",
				finished ? "100 %" : progress_percentage(in_pos),
				progress_sizes(compressed_pos, uncompressed_pos, finished),
				progress_speed(uncompressed_pos, elapsed),
				progress_time(elapsed),
				finished ? "" : progress_remaining(in_pos, elapsed),
				finished ? "\n" : "\r");
	} else {
		fprintf(stderr, "%s: %s\n", filename, progress_sizes(compressed_pos, uncompressed_pos, true));
	}
	progress_active = !finished;
	signals_unblock();
}

void message_progress_update(void)
{
	if (!progress_needs_updating)
		return;
	progress_needs_updating = false;
	progress_flush(false);
}

void message_progress_end(bool success)
{
	if (!progress_started)
		return;
	progress_started = false;
	progress_timer_stop();
	progress_needs_updating = false;
	if (success)
		progress_flush(true);
	else if (progress_active && progress_automatic) {
		/* Leave the partial progress line visible. */
		fputc('\n', stderr);
	}
	progress_active = false;
}

static void vmessage(enum message_verbosity v, const char *fmt, va_list ap)
{
	if (v <= verbosity) {
		signals_block();
		progress_timer_stop();
		if (progress_active) {
			fputc('\n', stderr);
			progress_active = false;
		}
		/* If a filename line is being shown in interactive mode, make sure it was printed. */
		if (progress_started && verbosity >= V_VERBOSE && progress_automatic)
			print_filename();
		fprintf(stderr, "%s: ", progname);
		vfprintf(stderr, fmt, ap);
		fputc('\n', stderr);
		if (progress_started && verbosity >= V_VERBOSE && progress_automatic)
			progress_timer_start();
		signals_unblock();
	}
}

void message(enum message_verbosity v, const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(v, fmt, ap);
	va_end(ap);
}

void message_warning(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_WARNING, fmt, ap);
	va_end(ap);
	set_exit_status(E_WARNING);
}

void message_error(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_ERROR, fmt, ap);
	va_end(ap);
	set_exit_status(E_ERROR);
}

void message_fatal(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_ERROR, fmt, ap);
	va_end(ap);
	my_exit(E_ERROR);
}

void message_bug(void)
{
	message_fatal(_("Internal error (bug)"));
}

void message_signal_handler(void)
{
	message_fatal(_("Cannot establish signal handlers"));
}

const char *message_strm(xret code)
{
	switch (code) {
	case R_NO_CHECK:
		return _("No integrity check; not verifying file integrity");
	case R_UNSUPPORTED_CHECK:
		return _("Unsupported type of integrity check; not verifying file integrity");
	case R_MEM_ERROR:
		return strerror(ENOMEM);
	case R_MEMLIMIT_ERROR:
		return _("Memory usage limit reached");
	case R_FORMAT_ERROR:
		return _("File format not recognized");
	case R_OPTIONS_ERROR:
		return _("Unsupported options");
	case R_DATA_ERROR:
		return _("Compressed data is corrupt");
	case R_BUF_ERROR:
		return _("Unexpected end of input");
	default:
		break;
	}
	return _("Internal error (bug)");
}

void message_mem_needed(enum message_verbosity v, uint64_t memusage)
{
	if (v > verbosity)
		return;
	memusage = round_up_to_mib(memusage);
	const uint64_t memlimit = hardware_memlimit_get(opt_mode);
	if (memlimit == UINT64_MAX) {
		message(v, _("%s MiB of memory is required. The limiter is disabled."), uint64_to_str(memusage, 0));
		return;
	}
	if (memlimit < (UINT32_C(1) << 20)) {
		message(v, _("%s MiB of memory is required. The limit is %s B."),
				uint64_to_str(memusage, 0), uint64_to_str(memlimit, 1));
	} else {
		message(v, _("%s MiB of memory is required. The limit is %s MiB."),
				uint64_to_str(memusage, 0), uint64_to_str(round_up_to_mib(memlimit), 1));
	}
}

void message_filters_show(enum message_verbosity v, const xfilter *filters)
{
	if (v > verbosity)
		return;
	char *buf = strfilter_from_filters(filters, STRFILTER_ENCODER | STRFILTER_ALL_OPTIONS);
	if (buf == NULL)
		message_bug();
	fprintf(stderr, _("%s: Filter chain: %s\n"), progname, buf);
	free(buf);
}

void message_try_help(void)
{
	message(V_WARNING, _("Try '%s --help' for more information."), progname);
}

void message_version(void)
{
	puts("xz (XZ Utils) 5.8.2");
	puts("liblzma 5.8.2");
	my_exit(E_SUCCESS);
}

void message_help(bool long_help)
{
	printf(_("Usage: %s [OPTION]... [FILE]...\n"
			"Compress or decompress FILEs in the .xz format.\n\n"), progname);

	puts(_("Mandatory arguments to long options are mandatory for short options too.\n"));

	if (long_help)
		puts(_(" Operation mode:\n"));

	puts(_(
"  -z, --compress      force compression\n"
"  -d, --decompress    force decompression\n"
"  -t, --test          test compressed file integrity\n"
"  -l, --list          list information about .xz files"));

	if (long_help)
		puts(_("\n Operation modifiers:\n"));

	puts(_(
"  -k, --keep          keep (don't delete) input files\n"
"  -f, --force         force overwrite of output file and (de)compress links\n"
"  -c, --stdout        write to standard output and don't delete input files"));

	if (long_help) {
		puts(_(
"      --no-sync       don't synchronize the output file to the storage device\n"
"                      before removing the input file"));
		puts(_(
"      --single-stream decompress only the first stream, and silently\n"
"                      ignore possible remaining input data"));
		puts(_(
"      --no-sparse     do not create sparse files when decompressing\n"
"  -S, --suffix=.SUF   use the suffix '.SUF' on compressed files\n"
"      --files[=FILE]  read filenames to process from FILE; if FILE is\n"
"                      omitted, filenames are read from the standard input;\n"
"                      filenames must be terminated with the newline character\n"
"      --files0[=FILE] like --files but use the null character as terminator"));
	}

	if (long_help) {
		puts(_("\n Basic file format and compression options:\n"));
		puts(_(
"  -F, --format=FORMAT file format to encode or decode; possible values are\n"
"                      'auto' (default), 'xz', 'lzma', 'lzip', and 'raw'\n"
"  -C, --check=NAME    integrity check type: 'none' (use with caution),\n"
"                      'crc32', 'crc64' (default), or 'sha256'"));
		puts(_(
"      --ignore-check  don't verify the integrity check when decompressing"));
	}

	puts(_(
"  -0 ... -9           compression preset; default is 6; take compressor *and*\n"
"                      decompressor memory usage into account before using 7-9!"));

	puts(_(
"  -e, --extreme       try to improve compression ratio by using more CPU time;\n"
"                      does not affect decompressor memory requirements"));

	puts(_(
"  -T, --threads=NUM   use at most NUM threads; the default is 0 which uses as\n"
"                      many threads as there are processor cores"));

	if (long_help) {
		puts(_(
"      --block-size=SIZE\n"
"                      start a new .xz block after every SIZE bytes of input;\n"
"                      use this to set the block size for threaded compression"));
		puts(_(
"      --block-list=BLOCKS\n"
"                      start a new .xz block after the given comma-separated\n"
"                      intervals of uncompressed data; optionally, specify a\n"
"                      filter chain number (0-9) followed by a ':' before the\n"
"                      uncompressed data size"));
		puts(_(
"      --flush-timeout=NUM\n"
"                      when compressing, if more than NUM milliseconds has\n"
"                      passed since the previous flush and reading more input\n"
"                      would block, all pending data is flushed out"
		));
		puts(_(
"      --memlimit-compress=LIMIT\n"
"      --memlimit-decompress=LIMIT\n"
"      --memlimit-mt-decompress=LIMIT\n"
"  -M, --memlimit=LIMIT\n"
"                      set memory usage limit for compression, decompression,\n"
"                      threaded decompression, or all of these; LIMIT is in\n"
"                      bytes, % of RAM, or 0 for defaults"));

		puts(_(
"      --no-adjust     if compression settings exceed the memory usage limit,\n"
"                      give an error instead of adjusting the settings downwards"));
	}

	if (long_help) {
		puts(_(
"\n Custom filter chain for compression (an alternative to using presets):"));
		puts(_(
"\n"
"  --filters=FILTERS   set the filter chain using the liblzma filter string\n"
"                      syntax; use --filters-help for more information"));
		puts(_(
"  --filters1=FILTERS ... --filters9=FILTERS\n"
"                      set additional filter chains using the liblzma filter\n"
"                      string syntax to use with --block-list"));
		puts(_(
"  --filters-help      display more information about the liblzma filter string\n"
"                      syntax and exit."));
		puts(_(
"\n"
"  --lzma1[=OPTS]\n"
"  --lzma2[=OPTS]      LZMA1 or LZMA2; OPTS is a comma-separated list of zero or\n"
"                      more of the following options (valid values; default):\n"
"                        preset=PRE  reset options to a preset (0-9[e])\n"
"                        dict=NUM    dictionary size (4KiB - 1536MiB; 8MiB)\n"
"                        lc=NUM      number of literal context bits (0-4; 3)\n"
"                        lp=NUM      number of literal position bits (0-4; 0)\n"
"                        pb=NUM      number of position bits (0-4; 2)\n"
"                        mode=MODE   compression mode (fast, normal; normal)\n"
"                        nice=NUM    nice length of a match (2-273; 64)\n"
"                        mf=NAME     match finder (hc3, hc4, bt2, bt3, bt4; bt4)\n"
"                        depth=NUM   maximum search depth; 0=automatic (default)"));
		puts(_(
"\n"
"  --x86[=OPTS]        x86 BCJ filter (32-bit and 64-bit)\n"
"  --arm[=OPTS]        ARM BCJ filter\n"
"  --armthumb[=OPTS]   ARM-Thumb BCJ filter\n"
"  --arm64[=OPTS]      ARM64 BCJ filter\n"
"  --powerpc[=OPTS]    PowerPC BCJ filter (big endian only)\n"
"  --ia64[=OPTS]       IA-64 (Itanium) BCJ filter\n"
"  --sparc[=OPTS]      SPARC BCJ filter\n"
"  --riscv[=OPTS]      RISC-V BCJ filter\n"
"                      Valid OPTS for all BCJ filters:\n"
"                        start=NUM   start offset for conversions (default=0)"));
		puts(_(
"\n"
"  --delta[=OPTS]      Delta filter; valid OPTS (valid values; default):\n"
"                        dist=NUM    distance between bytes being subtracted\n"
"                                    from each other (1-256; 1)"));
	}

	if (long_help)
		puts(_("\n Other options:\n"));

	puts(_(
"  -q, --quiet         suppress warnings; specify twice to suppress errors too\n"
"  -v, --verbose       be verbose; specify twice for even more verbose"));

	if (long_help) {
		puts(_(
"  -Q, --no-warn       make warnings not affect the exit status"));
		puts(_(
"      --robot         use machine-parsable messages (useful for scripts)"));
		puts("");
		puts(_(
"      --info-memory   display the total amount of RAM and the currently active\n"
"                      memory usage limits, and exit"));
		puts(_(
"  -h, --help          display the short help (lists only the basic options)\n"
"  -H, --long-help     display this long help and exit"));
	} else {
		puts(_(
"  -h, --help          display this short help and exit\n"
"  -H, --long-help     display the long help (lists also the advanced options)"));
	}

	puts(_(
"  -V, --version       display the version number and exit"));

	puts(_("\nWith no FILE, or when FILE is -, read standard input.\n"));

	printf(_("Report bugs to <%s> (in English or Finnish).\n"), "xz@tukaani.org");
	printf(_("%s home page: <%s>\n"), "XZ Utils", "https://tukaani.org/xz/");

	my_exit(E_SUCCESS);
}
EOF
echo ok"}

actions.command:
cd /workspace/src/cli && cat > message.h <<'EOF'
#ifndef XZCLI_MESSAGE_H
#define XZCLI_MESSAGE_H

enum message_verbosity {
	V_SILENT,
	V_ERROR,
	V_WARNING,
	V_VERBOSE,
	V_DEBUG,
};

void message_init(void);
void message_verbosity_increase(void);
void message_verbosity_decrease(void);
enum message_verbosity message_verbosity_get(void);
void message_set_files(unsigned int files);
void message_filename(const char *src_name);
void message_progress_start(xcoder *coder, bool is_passthru, uint64_t in_size);
void message_progress_update(void);
void message_progress_end(bool finished);
void message_progress_set_totals(uint64_t in, uint64_t out);
void message(enum message_verbosity verbosity, const char *fmt, ...) __attribute__((format(printf, 2, 3)));
void message_warning(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
void message_error(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
void message_fatal(const char *fmt, ...) __attribute__((format(printf, 1, 2), noreturn));
void message_bug(void) __attribute__((noreturn));
void message_signal_handler(void) __attribute__((noreturn));
const char *message_strm(xret code);
void message_mem_needed(enum message_verbosity v, uint64_t memusage);
void message_filters_show(enum message_verbosity v, const xfilter *filters);
void message_try_help(void);
void message_version(void) __attribute__((noreturn));
void message_help(bool long_help) __attribute__((noreturn));

enum exit_status_type {
	E_SUCCESS = 0,
	E_ERROR = 1,
	E_WARNING = 2,
};
void set_exit_status(enum exit_status_type new_status);
void set_exit_no_warn(void);
void my_exit(enum exit_status_type status) __attribute__((noreturn));

#endif
EOF
cat > message.c <<'EOF'
#include "private.h"

static enum message_verbosity verbosity = V_WARNING;
static const char *filename;
static bool first_filename = true;
static bool current_filename_printed = false;
static unsigned int files_total = 0;
static unsigned int files_pos = 0;

static bool progress_automatic;
static bool progress_started = false;
static bool progress_active = false;
static xcoder *progress_coder;
static bool progress_is_passthru;
static uint64_t expected_in_size;
static uint64_t progress_in = 0;
static uint64_t progress_out = 0;
static volatile sig_atomic_t progress_needs_updating = false;
static uint64_t start_time;

static enum exit_status_type exit_status = E_SUCCESS;
static bool no_warn = false;

void set_exit_status(enum exit_status_type new_status)
{
	if (new_status == E_WARNING && no_warn)
		return;
	if (new_status == E_WARNING && exit_status == E_ERROR)
		return;
	exit_status = new_status;
}

void set_exit_no_warn(void)
{
	no_warn = true;
}

void my_exit(enum exit_status_type status)
{
	if (status != E_ERROR) {
		if (fclose(stdout)) {
			message_error(_("Writing to standard output failed"));
			status = E_ERROR;
		}
	}
	if (status != E_ERROR && status != E_WARNING) {
		if (ferror(stderr) || fclose(stderr))
			status = E_ERROR;
	}
	if (status == E_WARNING && no_warn)
		status = E_SUCCESS;
	exit(status);
}

static void progress_signal_handler(int sig)
{
	(void)sig;
	progress_needs_updating = true;
}

void message_init(void)
{
	progress_automatic = isatty(STDERR_FILENO);
	if (progress_automatic) {
		struct sigaction sa;
		sa.sa_handler = &progress_signal_handler;
		sigemptyset(&sa.sa_mask);
		sa.sa_flags = 0;
		sigaction(SIGALRM, &sa, NULL);
	}
}

void message_verbosity_increase(void)
{
	if (verbosity < V_DEBUG)
		++verbosity;
}

void message_verbosity_decrease(void)
{
	if (verbosity > V_SILENT)
		--verbosity;
}

enum message_verbosity message_verbosity_get(void)
{
	return verbosity;
}

void message_set_files(unsigned int files)
{
	files_total = files;
}

static void print_filename(void)
{
	if (!progress_automatic || current_filename_printed)
		return;
	signals_block();
	if (!first_filename)
		fputc('\n', stderr);
	first_filename = false;
	current_filename_printed = true;
	if (files_total != 1)
		fprintf(stderr, "%s (%u/%u)\n", filename, files_pos, files_total);
	else
		fprintf(stderr, "%s\n", filename);
	signals_unblock();
}

void message_filename(const char *src_name)
{
	filename = src_name;
	current_filename_printed = false;
	++files_pos;
}

static void progress_timer_start(void)
{
	struct itimerval timer;
	timer.it_interval.tv_sec = 1;
	timer.it_interval.tv_usec = 0;
	timer.it_value.tv_sec = 1;
	timer.it_value.tv_usec = 0;
	setitimer(ITIMER_REAL, &timer, NULL);
}

static void progress_timer_stop(void)
{
	struct itimerval timer;
	memset(&timer, 0, sizeof(timer));
	setitimer(ITIMER_REAL, &timer, NULL);
}

void message_progress_start(xcoder *coder, bool is_passthru, uint64_t in_size)
{
	progress_coder = coder;
	progress_is_passthru = is_passthru;
	start_time = mytime_now();
	expected_in_size = in_size;
	progress_started = true;
	progress_in = 0;
	progress_out = 0;
	progress_needs_updating = false;
	if (verbosity >= V_VERBOSE && progress_automatic) {
		print_filename();
		progress_timer_start();
	}
}

void message_progress_set_totals(uint64_t in, uint64_t out)
{
	progress_in = in;
	progress_out = out;
}

static const char *progress_percentage(uint64_t in_pos)
{
	if (expected_in_size == 0 || in_pos > expected_in_size)
		return "--- %";
	double percentage = (double)in_pos / (double)expected_in_size * 99.9;
	static char buf[sizeof("99.9 %") + 3];
	snprintf(buf, sizeof(buf), "%.1f %%", percentage);
	return buf;
}

static const char *progress_sizes(uint64_t compressed_pos, uint64_t uncompressed_pos, bool final)
{
	static char buf[128];
	char *pos = buf;
	size_t left = sizeof(buf);
	const enum nicestr_unit unit_min = final ? NICESTR_B : NICESTR_MIB;
	my_snprintf(&pos, &left, "%s / %s",
			uint64_to_nicestr(compressed_pos, unit_min, NICESTR_TIB, false, 0),
			uint64_to_nicestr(uncompressed_pos, unit_min, NICESTR_TIB, false, 1));
	const double ratio = uncompressed_pos > 0 ? (double)compressed_pos / (double)uncompressed_pos : 16.0;
	if (ratio > 9.999) {
		my_snprintf(&pos, &left, " > %.3f", 9.999);
	} else {
		my_snprintf(&pos, &left, " = %.3f", ratio);
	}
	return buf;
}

static const char *progress_speed(uint64_t uncompressed_pos, uint64_t elapsed)
{
	if (elapsed < 3000)
		return "";
	static const char unit[][8] = { "KiB/s", "MiB/s", "GiB/s" };
	size_t unit_index = 0;
	double speed = (double)uncompressed_pos / ((double)elapsed * (1024.0 / 1000.0));
	while (speed > 999.0) {
		speed /= 1024.0;
		if (++unit_index == ARRAY_SIZE(unit))
			return "";
	}
	static char buf[sizeof("999 GiB/s")];
	snprintf(buf, sizeof(buf), "%.*f %s", speed > 9.9 ? 0 : 1, speed, unit[unit_index]);
	return buf;
}

static const char *progress_time(uint64_t mseconds)
{
	static char buf[sizeof("9999:59:59")];
	uint32_t seconds = (uint32_t)(mseconds / 1000);
	if (seconds == 0 || seconds > ((9999 * 60) + 59) * 60 + 59)
		return "";
	uint32_t minutes = seconds / 60;
	seconds %= 60;
	uint32_t hours = minutes / 60;
	minutes %= 60;
	if (hours > 0)
		snprintf(buf, sizeof(buf), "%" PRIu32 ":%02" PRIu32 ":%02" PRIu32, hours, minutes, seconds);
	else
		snprintf(buf, sizeof(buf), "%" PRIu32 ":%02" PRIu32, minutes, seconds);
	return buf;
}

static const char *progress_remaining(uint64_t in_pos, uint64_t elapsed)
{
	if (expected_in_size == 0 || in_pos > expected_in_size || in_pos == 0 || elapsed < 6000)
		return "";
	uint32_t remaining = (uint32_t)((double)(expected_in_size - in_pos) * ((double)elapsed / 1000.0) / (double)in_pos);
	if (remaining < 1)
		remaining = 1;
	static char buf[sizeof("9 h 55 min")];
	if (remaining <= 10) {
		snprintf(buf, sizeof(buf), "%" PRIu32 " s", remaining);
	} else if (remaining <= 50) {
		remaining = (remaining + 4) / 5 * 5;
		snprintf(buf, sizeof(buf), "%" PRIu32 " s", remaining);
	} else if (remaining <= 590) {
		remaining = (remaining + 9) / 10 * 10;
		snprintf(buf, sizeof(buf), "%" PRIu32 " min %" PRIu32 " s", remaining / 60, remaining % 60);
	} else if (remaining <= 59 * 60) {
		remaining = (remaining + 59) / 60;
		snprintf(buf, sizeof(buf), "%" PRIu32 " min", remaining);
	} else if (remaining <= 9 * 3600 + 50 * 60) {
		remaining = (remaining + 599) / 600 * 10;
		snprintf(buf, sizeof(buf), "%" PRIu32 " h %" PRIu32 " min", remaining / 60, remaining % 60);
	} else if (remaining <= 23 * 3600) {
		remaining = (remaining + 3599) / 3600;
		snprintf(buf, sizeof(buf), "%" PRIu32 " h", remaining);
	} else if (remaining <= 9 * 24 * 3600 + 23 * 3600) {
		remaining = (remaining + 3599) / 3600;
		snprintf(buf, sizeof(buf), "%" PRIu32 " d %" PRIu32 " h", remaining / 24, remaining % 24);
	} else if (remaining <= 999 * 24 * 3600) {
		remaining = (remaining + 24 * 3600 - 1) / (24 * 3600);
		snprintf(buf, sizeof(buf), "%" PRIu32 " d", remaining);
	} else {
		return "";
	}
	return buf;
}

static void progress_pos(uint64_t *in_pos, uint64_t *compressed_pos, uint64_t *uncompressed_pos)
{
	*in_pos = progress_in;
	if (progress_is_passthru) {
		*compressed_pos = progress_in;
		*uncompressed_pos = progress_in;
	} else if (opt_mode == MODE_COMPRESS) {
		*compressed_pos = progress_out;
		*uncompressed_pos = progress_in;
	} else {
		*compressed_pos = progress_in;
		*uncompressed_pos = progress_out;
	}
}

static void progress_flush(bool finished)
{
	if (!progress_started || verbosity < V_VERBOSE)
		return;
	uint64_t in_pos, compressed_pos, uncompressed_pos;
	progress_pos(&in_pos, &compressed_pos, &uncompressed_pos);
	const uint64_t elapsed = mytime_get_elapsed();
	signals_block();
	if (progress_automatic) {
		fprintf(stderr, "\r %6s %35s %11s %10s %12s%s",
				finished ? "100 %" : progress_percentage(in_pos),
				progress_sizes(compressed_pos, uncompressed_pos, finished),
				progress_speed(uncompressed_pos, elapsed),
				progress_time(elapsed),
				finished ? "" : progress_remaining(in_pos, elapsed),
				finished ? "\n" : "\r");
	} else {
		fprintf(stderr, "%s: %s\n", filename, progress_sizes(compressed_pos, uncompressed_pos, true));
	}
	progress_active = !finished;
	signals_unblock();
}

void message_progress_update(void)
{
	if (!progress_needs_updating)
		return;
	progress_needs_updating = false;
	progress_flush(false);
}

void message_progress_end(bool success)
{
	if (!progress_started)
		return;
	progress_started = false;
	progress_timer_stop();
	progress_needs_updating = false;
	if (success)
		progress_flush(true);
	else if (progress_active && progress_automatic) {
		/* Leave the partial progress line visible. */
		fputc('\n', stderr);
	}
	progress_active = false;
}

static void vmessage(enum message_verbosity v, const char *fmt, va_list ap)
{
	if (v <= verbosity) {
		signals_block();
		progress_timer_stop();
		if (progress_active) {
			fputc('\n', stderr);
			progress_active = false;
		}
		/* If a filename line is being shown in interactive mode, make sure it was printed. */
		if (progress_started && verbosity >= V_VERBOSE && progress_automatic)
			print_filename();
		fprintf(stderr, "%s: ", progname);
		vfprintf(stderr, fmt, ap);
		fputc('\n', stderr);
		if (progress_started && verbosity >= V_VERBOSE && progress_automatic)
			progress_timer_start();
		signals_unblock();
	}
}

void message(enum message_verbosity v, const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(v, fmt, ap);
	va_end(ap);
}

void message_warning(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_WARNING, fmt, ap);
	va_end(ap);
	set_exit_status(E_WARNING);
}

void message_error(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_ERROR, fmt, ap);
	va_end(ap);
	set_exit_status(E_ERROR);
}

void message_fatal(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vmessage(V_ERROR, fmt, ap);
	va_end(ap);
	my_exit(E_ERROR);
}

void message_bug(void)
{
	message_fatal(_("Internal error (bug)"));
}

void message_signal_handler(void)
{
	message_fatal(_("Cannot establish signal handlers"));
}

const char *message_strm(xret code)
{
	switch (code) {
	case R_NO_CHECK:
		return _("No integrity check; not verifying file integrity");
	case R_UNSUPPORTED_CHECK:
		return _("Unsupported type of integrity check; not verifying file integrity");
	case R_MEM_ERROR:
		return strerror(ENOMEM);
	case R_MEMLIMIT_ERROR:
		return _("Memory usage limit reached");
	case R_FORMAT_ERROR:
		return _("File format not recognized");
	case R_OPTIONS_ERROR:
		return _("Unsupported options");
	case R_DATA_ERROR:
		return _("Compressed data is corrupt");
	case R_BUF_ERROR:
		return _("Unexpected end of input");
	default:
		break;
	}
	return _("Internal error (bug)");
}

void message_mem_needed(enum message_verbosity v, uint64_t memusage)
{
	if (v > verbosity)
		return;
	memusage = round_up_to_mib(memusage);
	const uint64_t memlimit = hardware_memlimit_get(opt_mode);
	if (memlimit == UINT64_MAX) {
		message(v, _("%s MiB of memory is required. The limiter is disabled."), uint64_to_str(memusage, 0));
		return;
	}
	if (memlimit < (UINT32_C(1) << 20)) {
		message(v, _("%s MiB of memory is required. The limit is %s B."),
				uint64_to_str(memusage, 0), uint64_to_str(memlimit, 1));
	} else {
		message(v, _("%s MiB of memory is required. The limit is %s MiB."),
				uint64_to_str(memusage, 0), uint64_to_str(round_up_to_mib(memlimit), 1));
	}
}

void message_filters_show(enum message_verbosity v, const xfilter *filters)
{
	if (v > verbosity)
		return;
	char *buf = strfilter_from_filters(filters, STRFILTER_ENCODER | STRFILTER_ALL_OPTIONS);
	if (buf == NULL)
		message_bug();
	fprintf(stderr, _("%s: Filter chain: %s\n"), progname, buf);
	free(buf);
}

void message_try_help(void)
{
	message(V_WARNING, _("Try '%s --help' for more information."), progname);
}

void message_version(void)
{
	puts("xz (XZ Utils) 5.8.2");
	puts("liblzma 5.8.2");
	my_exit(E_SUCCESS);
}

void message_help(bool long_help)
{
	printf(_("Usage: %s [OPTION]... [FILE]...\n"
			"Compress or decompress FILEs in the .xz format.\n\n"), progname);

	puts(_("Mandatory arguments to long options are mandatory for short options too.\n"));

	if (long_help)
		puts(_(" Operation mode:\n"));

	puts(_(
"  -z, --compress      force compression\n"
"  -d, --decompress    force decompression\n"
"  -t, --test          test compressed file integrity\n"
"  -l, --list          list information about .xz files"));

	if (long_help)
