cat > signals.c <<'EOF'
#include "private.h"

volatile sig_atomic_t user_abort = 0;
static volatile sig_atomic_t exit_signal = 0;
static sigset_t hooked_signals;
static bool signals_are_initialized = false;
static bool signals_block_count = false;

static void signal_handler(int sig)
{
	exit_signal = sig;
	user_abort = 1;
}

void signals_init(void)
{
	static const int sigs[] = { SIGHUP, SIGINT, SIGPIPE, SIGTERM, SIGXCPU, SIGXFSZ };
	sigemptyset(&hooked_signals);
	for (size_t i = 0; i < ARRAY_SIZE(sigs); ++i)
		sigaddset(&hooked_signals, sigs[i]);
	sigaddset(&hooked_signals, SIGALRM);

	struct sigaction sa;
	sa.sa_handler = &signal_handler;
	sa.sa_mask = hooked_signals;
	sa.sa_flags = 0;
	for (size_t i = 0; i < ARRAY_SIZE(sigs); ++i) {
		struct sigaction old;
		if (sigaction(sigs[i], NULL, &old) == 0 && old.sa_handler == SIG_IGN)
			continue;
		if (sigaction(sigs[i], &sa, NULL))
			message_signal_handler();
	}
	signals_are_initialized = true;
}

void signals_block(void)
{
	if (signals_are_initialized && !signals_block_count) {
		sigprocmask(SIG_BLOCK, &hooked_signals, NULL);
		signals_block_count = true;
	}
}

void signals_unblock(void)
{
	if (signals_are_initialized && signals_block_count) {
		sigprocmask(SIG_UNBLOCK, &hooked_signals, NULL);
		signals_block_count = false;
	}
}

void signals_exit(void)
{
	const int sig = exit_signal;
	if (sig != 0) {
		struct sigaction sa;
		sa.sa_handler = SIG_DFL;
		sigfillset(&sa.sa_mask);
		sa.sa_flags = 0;
		sigaction(sig, &sa, NULL);
		raise(sig);
	}
}
