void hardware_memlimit_show(void)
{
	uint32_t cputhreads = hardware_cputhreads();
	if (cputhreads == 0)
		cputhreads = 1;

	if (opt_robot) {
		printf("%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu32 "\n",
				total_ram, memlimit_compress, memlimit_decompress,
				hardware_memlimit_mtdec_get(), memlimit_mt_default, cputhreads);
	} else {
		const char *msgs[] = {
			_("Amount of physical memory (RAM):"),
			_("Number of processor threads:"),
			_("Compression:"),
			_("Decompression:"),
			_("Multi-threaded decompression:"),
			_("Default for -T0:"),
		};
		size_t width_max = 1;
		for (unsigned i = 0; i < ARRAY_SIZE(msgs); ++i) {
			size_t w = strlen(msgs[i]);
			if (w > width_max)
				width_max = w;
		}
		puts(_("Hardware information:"));
		printf("  %-*s  %" PRIu64 " MiB (%" PRIu64 " B)\n", (int)width_max, msgs[0], total_ram >> 20, total_ram);
		printf("  %-*s  %" PRIu32 "\n", (int)width_max, msgs[1], cputhreads);
		putchar('\n');
		puts(_("Memory usage limits:"));
		memlimit_show(msgs[2], width_max, hardware_memlimit_get(MODE_COMPRESS));
		memlimit_show(msgs[3], width_max, hardware_memlimit_get(MODE_DECOMPRESS));
		memlimit_show(msgs[4], width_max, hardware_memlimit_mtdec_get());
		memlimit_show(msgs[5], width_max, memlimit_mt_default);
	}
	my_exit(E_SUCCESS);
}

void hardware_init(void)
{
	total_ram = hardware_physmem();
	if (total_ram == 0)
		total_ram = UINT64_C(128) << 20;
	memlimit_mt_default = total_ram / 4;
	hardware_threads_set(0);
}
