cat > mytime.c <<'EOF'
#include "private.h"

uint64_t opt_flush_timeout = 0;
bool flush_needed;
static uint64_t start_time;
static uint64_t next_flush;

uint64_t mytime_now(void)
{
	struct timespec tv;
	clock_gettime(CLOCK_MONOTONIC, &tv);
	return (uint64_t)tv.tv_sec * 1000 + (uint64_t)(tv.tv_nsec / 1000000);
}

void mytime_set_start_time(void)
{
	start_time = mytime_now();
}

uint64_t mytime_get_elapsed(void)
{
	return mytime_now() - start_time;
}

void mytime_set_flush_time(void)
{
	next_flush = mytime_now() + opt_flush_timeout;
	flush_needed = false;
}

int mytime_get_flush_timeout(void)
{
	if (opt_flush_timeout == 0 || opt_mode != MODE_COMPRESS)
		return -1;
	const uint64_t now = mytime_now();
	if (now >= next_flush)
		return 0;
	const uint64_t remaining = next_flush - now;
	return remaining > INT_MAX ? INT_MAX : (int)remaining;
}
