#include "private.h"

static char *custom_suffix = NULL;

static bool has_dir_sep(const char *str)
{
	return strchr(str, '/') != NULL;
}

static size_t test_suffix(const char *suffix, const char *src_name, size_t src_len)
{
	const size_t suffix_len = strlen(suffix);
	if (src_len <= suffix_len || has_dir_sep(src_name + src_len - suffix_len))
		return 0;
	if (strcmp(suffix, src_name + src_len - suffix_len) == 0)
		return src_len - suffix_len;
	return 0;
}

static char *uncompressed_name(const char *src_name, const size_t src_len)
{
	static const struct {
		const char *compressed;
		const char *uncompressed;
	} suffixes[] = {
		{ ".xz", "" },
		{ ".txz", ".tar" },
		{ ".lzma", "" },
		{ ".tlz", ".tar" },
		{ ".lz", "" },
	};

	const char *new_suffix = "";
	size_t new_len = 0;

	if (opt_format != FORMAT_RAW) {
		for (size_t i = 0; i < ARRAY_SIZE(suffixes); ++i) {
			new_len = test_suffix(suffixes[i].compressed, src_name, src_len);
			if (new_len != 0) {
				new_suffix = suffixes[i].uncompressed;
				break;
			}
		}
	}

	if (new_len == 0 && custom_suffix != NULL)
		new_len = test_suffix(custom_suffix, src_name, src_len);

	if (new_len == 0) {
		message_warning(_("%s: Filename has an unknown suffix, skipping"), src_name);
		return NULL;
	}

	const size_t new_suffix_len = strlen(new_suffix);
	char *dest_name = xrealloc(NULL, new_len + new_suffix_len + 1);
	memcpy(dest_name, src_name, new_len);
	memcpy(dest_name + new_len, new_suffix, new_suffix_len);
	dest_name[new_len + new_suffix_len] = '\0';
	return dest_name;
}

static void msg_suffix(const char *src_name, const char *suffix)
{
	message_warning(_("%s: File already has '%s' suffix, skipping"), src_name, suffix);
}

static char *compressed_name(const char *src_name, size_t src_len)
{
	static const char *const all_suffixes[][4] = {
		{ ".xz", ".txz", NULL },
		{ ".lzma", ".tlz", NULL },
		{ ".lz", NULL },
		{ NULL },
	};
	const size_t format = (size_t)opt_format - 1;
	const char *const *suffixes = all_suffixes[format];

	for (size_t i = 0; suffixes[i] != NULL; ++i) {
		if (test_suffix(suffixes[i], src_name, src_len) != 0) {
			msg_suffix(src_name, suffixes[i]);
			return NULL;
		}
	}

	if (custom_suffix != NULL) {
		if (test_suffix(custom_suffix, src_name, src_len) != 0) {
			msg_suffix(src_name, custom_suffix);
			return NULL;
		}
	}

	const char *suffix = custom_suffix != NULL ? custom_suffix : suffixes[0];
	const size_t suffix_len = strlen(suffix);
	char *dest_name = xrealloc(NULL, src_len + suffix_len + 1);
	memcpy(dest_name, src_name, src_len);
	memcpy(dest_name + src_len, suffix, suffix_len);
	dest_name[src_len + suffix_len] = '\0';
	return dest_name;
}

char *suffix_get_dest_name(const char *src_name)
{
	const size_t src_len = strlen(src_name);
	return opt_mode == MODE_COMPRESS ? compressed_name(src_name, src_len) : uncompressed_name(src_name, src_len);
}

