#include "private.h"

bool lzma_preset_options(lzma_options *o, uint32_t preset)
{
	const uint32_t level = preset & PRESET_LEVEL_MASK;
	const uint32_t flags = preset & ~PRESET_LEVEL_MASK;
	if (level > 9 || (flags & ~PRESET_EXTREME))
		return true;
	memset(o, 0, sizeof(*o));
	o->lc = 3;
	o->lp = 0;
	o->pb = 2;
	static const uint8_t dict_pow2[] = { 18, 20, 21, 22, 22, 23, 23, 24, 25, 26 };
	o->dict_size = UINT32_C(1) << dict_pow2[level];
	if (level <= 3) {
		o->mode = MODE_FAST;
		o->mf = level == 0 ? MF_HC3 : MF_HC4;
		o->nice_len = level <= 1 ? 128 : 273;
		static const uint8_t depths[] = { 4, 8, 24, 48 };
		o->depth = depths[level];
	} else {
		o->mode = MODE_NORMAL;
		o->mf = MF_BT4;
		o->nice_len = level == 4 ? 16 : level == 5 ? 32 : 64;
		o->depth = 0;
	}
	if (flags & PRESET_EXTREME) {
		o->mode = MODE_NORMAL;
		o->mf = MF_BT4;
		if (level == 3 || level == 5) {
			o->nice_len = 192;
			o->depth = 0;
		} else {
			o->nice_len = 273;
			o->depth = 512;
		}
	}
	return false;
}

typedef struct {
	const char *name;
	uint64_t id;
} name_id_map;

typedef struct {
	const char *name;
	const name_id_map *map;
	uint64_t min;
	uint64_t max;
} option_map;

static void parse_options(const char *str, const option_map *opts,
		void (*set)(void *filter_options, unsigned key, uint64_t value, const char *valuestr),
		void *filter_options)
{
	if (str == NULL || str[0] == '\0')
		return;

	char *s = xstrdup(str);
	char *name = s;

	while (*name != '\0') {
		if (*name == ',') {
			++name;
			continue;
		}
		char *split = strchr(name, ',');
		if (split != NULL)
			*split = '\0';

		char *value = strchr(name, '=');
		if (value != NULL)
			*value++ = '\0';

		if (value == NULL || value[0] == '\0')
			message_fatal(_("%s: Options must be 'name=value' pairs separated with commas"), str);

		unsigned i = 0;
		while (true) {
			if (opts[i].name == NULL)
				message_fatal(_("%s: Invalid option name"), name);
			if (strcmp(name, opts[i].name) == 0)
				break;
			++i;
		}

		if (opts[i].map != NULL) {
			unsigned j;
			for (j = 0; opts[i].map[j].name != NULL; ++j)
				if (strcmp(opts[i].map[j].name, value) == 0)
					break;
			if (opts[i].map[j].name == NULL)
				message_fatal(_("%s: Invalid option value"), value);
			set(filter_options, i, opts[i].map[j].id, value);
		} else if (opts[i].min == UINT64_MAX) {
			set(filter_options, i, 0, value);
		} else {
			const uint64_t v = str_to_uint64(name, value, opts[i].min, opts[i].max);
			set(filter_options, i, v, value);
		}

		if (split == NULL)
			break;
		name = split + 1;
	}
	free(s);
}

/* ---------- delta ---------- */

enum { OPT_DIST };

static void set_delta(void *options, unsigned key, uint64_t value, const char *valuestr)
{
	(void)valuestr;
	delta_options *opt = options;
	switch (key) {
	case OPT_DIST:
		opt->dist = (uint32_t)value;
		break;
	}
}

delta_options *options_delta(const char *str)
{
	static const option_map opts[] = {
		{ "dist", NULL, 1, 256 },
		{ NULL, NULL, 0, 0 },
	};
	delta_options *options = xrealloc(NULL, sizeof(delta_options));
	options->type = 0;
	options->dist = 1;
	parse_options(str, opts, &set_delta, options);
	return options;
}

/* ---------- bcj ---------- */

enum { OPT_START_OFFSET };

static void set_bcj(void *options, unsigned key, uint64_t value, const char *valuestr)
{
	(void)valuestr;
	bcj_options *opt = options;
	switch (key) {
	case OPT_START_OFFSET:
		opt->start_offset = (uint32_t)value;
		break;
	}
}

bcj_options *options_bcj(const char *str)
{
	static const option_map opts[] = {
		{ "start", NULL, 0, UINT32_MAX },
		{ NULL, NULL, 0, 0 },
	};
	bcj_options *options = xrealloc(NULL, sizeof(bcj_options));
	options->start_offset = 0;
	parse_options(str, opts, &set_bcj, options);
	return options;
}

/* ---------- lzma ---------- */

enum { OPT_PRESET, OPT_DICT, OPT_LC, OPT_LP, OPT_PB, OPT_MODE, OPT_NICE, OPT_MF, OPT_DEPTH };

static void error_lzma_preset(const char *valuestr)
{
	message_fatal(_("Unsupported LZMA1/LZMA2 preset: %s"), valuestr);
}

static void set_lzma(void *options, unsigned key, uint64_t value, const char *valuestr)
{
	lzma_options *opt = options;
	switch (key) {
	case OPT_PRESET: {
		if (valuestr[0] < '0' || valuestr[0] > '9')
			error_lzma_preset(valuestr);
		uint32_t preset = (uint32_t)(valuestr[0] - '0');
		if (valuestr[1] != '\0') {
			if (valuestr[1] == 'e')
				preset |= PRESET_EXTREME;
			else
				error_lzma_preset(valuestr);
			if (valuestr[2] != '\0')
				error_lzma_preset(valuestr);
		}
		if (lzma_preset_options(opt, preset))
			error_lzma_preset(valuestr);
		break;
	}
	case OPT_DICT: opt->dict_size = (uint32_t)value; break;
	case OPT_LC: opt->lc = (uint32_t)value; break;
	case OPT_LP: opt->lp = (uint32_t)value; break;
	case OPT_PB: opt->pb = (uint32_t)value; break;
	case OPT_MODE: opt->mode = (lzma_mode_t)value; break;
	case OPT_NICE: opt->nice_len = (uint32_t)value; break;
	case OPT_MF: opt->mf = (lzma_mf_t)value; break;
	case OPT_DEPTH: opt->depth = (uint32_t)value; break;
	}
}

lzma_options *options_lzma(const char *str)
{
	static const name_id_map modes[] = {
		{ "fast", MODE_FAST },
		{ "normal", MODE_NORMAL },
		{ NULL, 0 },
	};
	static const name_id_map mfs[] = {
		{ "hc3", MF_HC3 },
		{ "hc4", MF_HC4 },
		{ "bt2", MF_BT2 },
		{ "bt3", MF_BT3 },
		{ "bt4", MF_BT4 },
		{ NULL, 0 },
	};
	static const option_map opts[] = {
		{ "preset", NULL, UINT64_MAX, 0 },
		{ "dict", NULL, LZMA_DICT_SIZE_MIN, (UINT32_C(1) << 30) + (UINT32_C(1) << 29) },
		{ "lc", NULL, 0, LZMA_LCLP_MAX },
		{ "lp", NULL, 0, LZMA_LCLP_MAX },
		{ "pb", NULL, 0, LZMA_PB_MAX },
		{ "mode", modes, 0, 0 },
		{ "nice", NULL, 2, 273 },
		{ "mf", mfs, 0, 0 },
		{ "depth", NULL, 0, UINT32_MAX },
		{ NULL, NULL, 0, 0 },
	};

	lzma_options *options = xrealloc(NULL, sizeof(lzma_options));
	if (lzma_preset_options(options, PRESET_DEFAULT))
		message_bug();
	parse_options(str, opts, &set_lzma, options);
	if (options->lc + options->lp > LZMA_LCLP_MAX)
		message_fatal(_("The sum of lc and lp must not exceed 4"));
	return options;
}
