	o->lc = 3;
	o->lp = 0;
	o->pb = 2;
	static const uint8_t dict_pow2[] = { 18, 20, 21, 22, 22, 23, 23, 24, 25, 26 };
	o->dict_size = UINT32_C(1) << dict_pow2[level];
	if (level <= 3) {
		o->mode = MODE_FAST;
		o->mf = level == 0 ? MF_HC3 : MF_HC4;
		o->nice_len = level <= 1 ? 128 : 273;
		static const uint8_t depths[] = { 4, 8, 24, 48 };
		o->depth = depths[level];
	} else {
		o->mode = MODE_NORMAL;
		o->mf = MF_BT4;
		o->nice_len = level == 4 ? 16 : level == 5 ? 32 : 64;
		o->depth = 0;
	}
	if (flags & PRESET_EXTREME) {
		o->mode = MODE_NORMAL;
		o->mf = MF_BT4;
		if (level == 3 || level == 5) {
			o->nice_len = 192;
			o->depth = 0;
		} else {
			o->nice_len = 273;
			o->depth = 512;
		}
	}
	return false;
}

typedef struct {
	const char *name;
	uint64_t id;
} name_id_map;

typedef struct {
	const char *name;
	const name_id_map *map;
	uint64_t min;
	uint64_t max;
} option_map;

static void parse_options(const char *str, const option_map *opts,
		void (*set)(void *filter_options, unsigned key, uint64_t value, const char *valuestr),
		void *filter_options)
{
	if (str == NULL || str[0] == '\0')
		return;

	char *s = xstrdup(str);
	char *name = s;

	while (*name != '\0') {
		if (*name == ',') {
			++name;
			continue;
		}
		char *split = strchr(name, ',');
		if (split != NULL)
			*split = '\0';

		char *value = strchr(name, '=');
		if (value != NULL)
			*value++ = '\0';

		if (value == NULL || value[0] == '\0')
			message_fatal(_("%s: Options must be 'name=value' pairs separated with commas"), str);

		unsigned i = 0;
		while (true) {
			if (opts[i].name == NULL)
				message_fatal(_("%s: Invalid option name"), name);
			if (strcmp(name, opts[i].name) == 0)
				break;
			++i;
		}

		if (opts[i].map != NULL) {
			unsigned j;
			for (j = 0; opts[i].map[j].name != NULL; ++j)
				if (strcmp(opts[i].map[j].name, value) == 0)
					break;
			if (opts[i].map[j].name == NULL)
				message_fatal(_("%s: Invalid option value"), value);
			set(filter_options, i, opts[i].map[j].id, value);
		} else if (opts[i].min == UINT64_MAX) {
			set(filter_options, i, 0, value);
		} else {
			const uint64_t v = str_to_uint64(name, value, opts[i].min, opts[i].max);
			set(filter_options, i, v, value);
		}

		if (split == NULL)
			break;
		name = split + 1;
	}
	free(s);
}

/* ---------- delta ---------- */

enum { OPT_DIST };

static void set_delta(void *options, unsigned key, uint64_t value, const char *valuestr)
{
	(void)valuestr;
	delta_options *opt = options;
	switch (key) {
	case OPT_DIST:
		opt->dist = (uint32_t)value;
		break;
	}
}

