#include "private.h"

typedef enum { OT_UINT32, OT_SIZE, OT_ENUM, OT_PRESET } opt_type;

typedef struct {
	const char *name;
	uint64_t id;
} enum_map;

typedef struct {
	const char *name;
	opt_type type;
	size_t offset;
	uint64_t min;
	uint64_t max;
	const enum_map *map;
	bool decoder_relevant;   /* shown in decoder-oriented output */
	bool encoder_only;
} opt_desc;

typedef struct {
	const char *name;
	uint64_t id;
	const opt_desc *opts;
	size_t options_size;
	bool xz_format;
} filter_desc;

static const enum_map modes[] = { { "fast", MODE_FAST }, { "normal", MODE_NORMAL }, { NULL, 0 } };
static const enum_map mfs[] = { { "hc3", MF_HC3 }, { "hc4", MF_HC4 }, { "bt2", MF_BT2 }, { "bt3", MF_BT3 }, { "bt4", MF_BT4 }, { NULL, 0 } };

static const opt_desc lzma_opts[] = {
	{ "preset", OT_PRESET, 0, 0, 0, NULL, false, true },
	{ "dict", OT_SIZE, offsetof(lzma_options, dict_size), LZMA_DICT_SIZE_MIN, (UINT32_C(1) << 30) + (UINT32_C(1) << 29), NULL, true, false },
	{ "lc", OT_UINT32, offsetof(lzma_options, lc), 0, LZMA_LCLP_MAX, NULL, true, false },
	{ "lp", OT_UINT32, offsetof(lzma_options, lp), 0, LZMA_LCLP_MAX, NULL, true, false },
	{ "pb", OT_UINT32, offsetof(lzma_options, pb), 0, LZMA_PB_MAX, NULL, true, false },
	{ "mode", OT_ENUM, offsetof(lzma_options, mode), 0, 0, modes, false, true },
	{ "nice", OT_UINT32, offsetof(lzma_options, nice_len), 2, 273, NULL, false, true },
	{ "mf", OT_ENUM, offsetof(lzma_options, mf), 0, 0, mfs, false, true },
	{ "depth", OT_UINT32, offsetof(lzma_options, depth), 0, UINT32_MAX, NULL, false, true },
	{ NULL, 0, 0, 0, 0, NULL, false, false },
};

static const opt_desc bcj_opts[] = {
	{ "start", OT_SIZE, offsetof(bcj_options, start_offset), 0, UINT32_MAX, NULL, true, false },
	{ NULL, 0, 0, 0, 0, NULL, false, false },
};

static const opt_desc delta_opts[] = {
	{ "dist", OT_UINT32, offsetof(delta_options, dist), 1, 256, NULL, true, false },
	{ NULL, 0, 0, 0, 0, NULL, false, false },
};

static const filter_desc filters_table[] = {
	{ "lzma2", FID_LZMA2, lzma_opts, sizeof(lzma_options), true },
	{ "x86", FID_X86, bcj_opts, sizeof(bcj_options), true },
	{ "arm", FID_ARM, bcj_opts, sizeof(bcj_options), true },
	{ "armthumb", FID_ARMTHUMB, bcj_opts, sizeof(bcj_options), true },
	{ "arm64", FID_ARM64, bcj_opts, sizeof(bcj_options), true },
	{ "riscv", FID_RISCV, bcj_opts, sizeof(bcj_options), true },
	{ "powerpc", FID_POWERPC, bcj_opts, sizeof(bcj_options), true },
	{ "ia64", FID_IA64, bcj_opts, sizeof(bcj_options), true },
	{ "sparc", FID_SPARC, bcj_opts, sizeof(bcj_options), true },
	{ "delta", FID_DELTA, delta_opts, sizeof(delta_options), true },
	{ "lzma1", FID_LZMA1, lzma_opts, sizeof(lzma_options), false },
	{ NULL, 0, NULL, 0, false },
};

static const filter_desc *find_filter_by_id(uint64_t id)
{
	for (size_t i = 0; filters_table[i].name != NULL; ++i)
		if (filters_table[i].id == id)
			return &filters_table[i];
	return NULL;
}

/* ---------- parsing ---------- */

typedef struct {
	const char *str;
	size_t pos;
	uint32_t flags;
	xfilter *filters;
	size_t count;
} parse_ctx;

static const char *parse_uint(parse_ctx *ctx, uint64_t *result, bool allow_suffix)
{
	const char *s = ctx->str + ctx->pos;
	if (*s < '0' || *s > '9')
		return "Value is not a non-negative decimal integer";
	uint64_t v = 0;
	bool overflow = false;
	size_t i = 0;
	while (s[i] >= '0' && s[i] <= '9') {
		if (v > UINT64_MAX / 10)
			overflow = true;
		v *= 10;
		const unsigned add = (unsigned)(s[i] - '0');
		if (UINT64_MAX - add < v)
			overflow = true;
		v += add;
		++i;
	}
	if (s[i] != '\0' && s[i] != ',' && s[i] != ' ' && !(s[i] == '-' && s[i + 1] == '-')) {
		if (!allow_suffix)
			return "Value out of range";
		uint64_t mult = 0;
		const size_t suffix_pos = ctx->pos + i;
		if (s[i] == 'k' || s[i] == 'K') mult = UINT64_C(1) << 10;
		else if (s[i] == 'm' || s[i] == 'M') mult = UINT64_C(1) << 20;
		else if (s[i] == 'g' || s[i] == 'G') mult = UINT64_C(1) << 30;
		++i;
		if (mult != 0) {
			if (s[i] == 'i') ++i;
			if (s[i] == 'B') ++i;
		}
		if (mult == 0 || (s[i] != '\0' && s[i] != ',' && s[i] != ' ' && !(s[i] == '-' && s[i + 1] == '-'))) {
			ctx->pos = suffix_pos;
			return "Invalid multiplier suffix (KiB, MiB, or GiB)";
		}
		if (!overflow && v > UINT64_MAX / mult)
			overflow = true;
		else if (!overflow)
			v *= mult;
	}
	if (overflow)
		return "Value out of range";
	*result = v;
	ctx->pos += i;
	return NULL;
}

static size_t token_len(const char *s, const char *stop)
{
	size_t i = 0;
	while (s[i] != '\0' && strchr(stop, s[i]) == NULL && !(s[i] == '-' && s[i + 1] == '-'))
		++i;
	return i;
}

static const char *parse_preset_value(const char *s, size_t *consumed, uint32_t *preset, size_t *errpos)
{
	if (s[0] < '0' || s[0] > '9') {
		*errpos = 0;
		return "Unsupported preset";
	}
	*preset = (uint32_t)(s[0] - '0');
	size_t i = 1;
	while (s[i] != '\0' && s[i] != ',' && s[i] != ' ' && !(s[i] == '-' && s[i + 1] == '-')) {
		if (s[i] == 'e') {
			*preset |= PRESET_EXTREME;
		} else {
			*errpos = i;
			return "Unsupported flag in the preset";
		}
		++i;
	}
	*consumed = i;
	return NULL;
}

static const char *parse_options_str(parse_ctx *ctx, const filter_desc *fd, void *options)
{
	const char *str = ctx->str;
	while (true) {
		if (str[ctx->pos] == ',') {
			++ctx->pos;
			continue;
		}
		if (str[ctx->pos] == '\0' || str[ctx->pos] == ' ' || (str[ctx->pos] == '-' && str[ctx->pos + 1] == '-'))
			break;
		const size_t name_start = ctx->pos;
		const size_t name_len = token_len(str + ctx->pos, "=, ");
		if (str[ctx->pos + name_len] != '=' || name_len == 0) {
			ctx->pos = name_start;
			return "Options must be 'name=value' pairs separated with commas";
		}
		const opt_desc *od = NULL;
		for (size_t i = 0; fd->opts[i].name != NULL; ++i) {
			if (strlen(fd->opts[i].name) == name_len && strncmp(fd->opts[i].name, str + name_start, name_len) == 0) {
				od = &fd->opts[i];
				break;
			}
		}
		if (od == NULL) {
			ctx->pos = name_start;
			return "Unknown option name";
		}
		ctx->pos += name_len + 1;
		const size_t value_start = ctx->pos;
		if (str[ctx->pos] == '\0' || str[ctx->pos] == ',' || str[ctx->pos] == ' ' || (str[ctx->pos] == '-' && str[ctx->pos + 1] == '-'))
			return "Option value cannot be empty";

		switch (od->type) {
		case OT_UINT32:
		case OT_SIZE: {
			uint64_t v;
			const char *err = parse_uint(ctx, &v, od->type == OT_SIZE);
			if (err != NULL) {
				if (ctx->pos == value_start || strcmp(err, "Invalid multiplier suffix (KiB, MiB, or GiB)") != 0)
					ctx->pos = value_start;
				return err;
			}
			if (v < od->min || v > od->max) {
				ctx->pos = value_start;
				return "Value out of range";
			}
			*(uint32_t *)((char *)options + od->offset) = (uint32_t)v;
			break;
		}
		case OT_ENUM: {
			const size_t vlen = token_len(str + ctx->pos, ", ");
			const enum_map *m = NULL;
			for (size_t i = 0; od->map[i].name != NULL; ++i)
				if (strlen(od->map[i].name) == vlen && strncmp(od->map[i].name, str + ctx->pos, vlen) == 0) {
					m = &od->map[i];
					break;
				}
			if (m == NULL)
				return "Invalid option value";
			*(uint32_t *)((char *)options + od->offset) = (uint32_t)m->id;
			ctx->pos += vlen;
			break;
		}
		case OT_PRESET: {
			size_t consumed;
			uint32_t preset;
			size_t errpos;
			const char *err = parse_preset_value(str + ctx->pos, &consumed, &preset, &errpos);
			if (err != NULL) {
				ctx->pos += errpos;
				return err;
			}
			if (lzma_preset_options(options, preset))
				return "Unsupported preset";
			ctx->pos += consumed;
			break;
		}
		}
	}
	/* Filter-specific validation. */
	if (fd->id == FID_LZMA1 || fd->id == FID_LZMA2) {
		lzma_options *o = options;
		if (o->lc + o->lp > LZMA_LCLP_MAX)
			return "The sum of lc and lp must not exceed 4";
	}
	return NULL;
}

static const char *validate_chain(const xfilter *filters, size_t count, uint32_t flags)
{
	(void)flags;
	if (count == 0)
		return "Invalid filter chain ('lzma2' missing at the end?)";
	for (size_t i = 0; i < count; ++i) {
		const bool last = i == count - 1;
		const bool is_lzma = filters[i].id == FID_LZMA1 || filters[i].id == FID_LZMA2;
		if (last != is_lzma)
			return "Invalid filter chain ('lzma2' missing at the end?)";
	}
	return NULL;
}

const char *strfilter_to_filters(const char *str, int *error_pos, xfilter *filters, uint32_t flags)
{
	if (error_pos != NULL)
		*error_pos = 0;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) {
		filters[i].id = FID_UNKNOWN;
		filters[i].options = NULL;
	}
	parse_ctx ctx = { str, 0, flags, filters, 0 };
	const char *err = NULL;

	while (str[ctx.pos] == ' ')
		++ctx.pos;

	if (str[ctx.pos] == '\0') {
		ctx.pos = 0;
		err = "Empty string is not allowed, try '6' if a default value is needed";
		goto fail;
	}

	if (str[ctx.pos] >= '0' && str[ctx.pos] <= '9') {
		const size_t start = ctx.pos;
		size_t consumed;
		uint32_t preset;
		size_t errpos;
		err = parse_preset_value(str + ctx.pos, &consumed, &preset, &errpos);
		if (err != NULL) {
			ctx.pos += errpos;
			goto fail;
		}
		ctx.pos += consumed;
		while (str[ctx.pos] == ' ')
			++ctx.pos;
		if (str[ctx.pos] != '\0') {
			ctx.pos = start;
			err = "Unsupported preset";
			goto fail;
		}
		lzma_options *o = xrealloc(NULL, sizeof(lzma_options));
		if (lzma_preset_options(o, preset)) {
			free(o);
			ctx.pos = start;
			err = "Unsupported preset";
			goto fail;
		}
		filters[0].id = FID_LZMA2;
		filters[0].options = o;
		filters[1].id = FID_UNKNOWN;
		return NULL;
	}

	while (true) {
		/* At the start of a filter name. */
		if (str[ctx.pos] == '\0' || str[ctx.pos] == ' ' || (str[ctx.pos] == '-' && str[ctx.pos + 1] == '-')) {
			err = "Filter name is missing";
			goto fail;
		}
		if (ctx.count == FILTERS_MAX) {
			err = "The maximum number of filters is four";
			goto fail;
		}
		const size_t name_len = token_len(str + ctx.pos, ": ");
		const filter_desc *fd = NULL;
		for (size_t i = 0; filters_table[i].name != NULL; ++i) {
			if (strlen(filters_table[i].name) == name_len && strncmp(filters_table[i].name, str + ctx.pos, name_len) == 0) {
				fd = &filters_table[i];
				break;
			}
		}
		if (fd == NULL || (!fd->xz_format && !(flags & STRFILTER_ALL_FILTERS))) {
			err = "Unknown filter name";
			goto fail;
		}
		ctx.pos += name_len;
		void *options = xrealloc(NULL, fd->options_size);
		memset(options, 0, fd->options_size);
		if (fd->id == FID_LZMA1 || fd->id == FID_LZMA2)
			lzma_preset_options(options, PRESET_DEFAULT);
		else if (fd->id == FID_DELTA)
			((delta_options *)options)->dist = 1;
		filters[ctx.count].id = fd->id;
		filters[ctx.count].options = options;
		ctx.count++;
		filters[ctx.count].id = FID_UNKNOWN;
		filters[ctx.count].options = NULL;

		if (str[ctx.pos] == ':') {
			++ctx.pos;
			err = parse_options_str(&ctx, fd, options);
			if (err != NULL)
				goto fail;
		}

		/* Separator */
		while (str[ctx.pos] == ' ')
			++ctx.pos;
		if (str[ctx.pos] == '\0')
			break;
		if (str[ctx.pos] == '-' && str[ctx.pos + 1] == '-')
			ctx.pos += 2;
	}

	if (!(flags & STRFILTER_NO_VALIDATION)) {
		err = validate_chain(filters, ctx.count, flags);
		if (err != NULL) {
			ctx.pos = strlen(str);
			goto fail;
		}
	}
	return NULL;

fail:
	if (error_pos != NULL)
		*error_pos = (int)ctx.pos;
	filters_free(filters);
	for (size_t i = 0; i <= FILTERS_MAX; ++i)
		filters[i].id = FID_UNKNOWN;
	return err;
}

/* ---------- formatting ---------- */

typedef struct {
	char *buf;
	size_t len;
	size_t alloc;
} strbuf;

static void sb_add(strbuf *sb, const char *s)
{
	const size_t n = strlen(s);
	if (sb->len + n + 1 > sb->alloc) {
		sb->alloc = (sb->len + n + 1) * 2;
		sb->buf = xrealloc(sb->buf, sb->alloc);
	}
	memcpy(sb->buf + sb->len, s, n + 1);
	sb->len += n;
}

static void format_size(char *out, size_t outsize, uint64_t v)
{
	if (v != 0 && (v & ((UINT64_C(1) << 30) - 1)) == 0)
		snprintf(out, outsize, "%" PRIu64 "GiB", v >> 30);
	else if (v != 0 && (v & ((UINT64_C(1) << 20) - 1)) == 0)
		snprintf(out, outsize, "%" PRIu64 "MiB", v >> 20);
	else if (v != 0 && (v & ((UINT64_C(1) << 10) - 1)) == 0)
		snprintf(out, outsize, "%" PRIu64 "KiB", v >> 10);
	else
		snprintf(out, outsize, "%" PRIu64, v);
}

char *strfilter_from_filters(const xfilter *filters, uint32_t flags)
{
	strbuf sb = { NULL, 0, 0 };
	sb_add(&sb, "");
	const bool getopt = (flags & STRFILTER_GETOPT_LONG) != 0;
	const bool all_opts = (flags & STRFILTER_ALL_OPTIONS) != 0 || (flags & STRFILTER_ENCODER) != 0;
	for (size_t i = 0; filters[i].id != FID_UNKNOWN; ++i) {
		const filter_desc *fd = find_filter_by_id(filters[i].id);
		if (fd == NULL) {
			free(sb.buf);
			return NULL;
		}
		if (i > 0)
			sb_add(&sb, (flags & STRFILTER_NO_SPACES) ? "--" : " ");
		if (getopt)
			sb_add(&sb, "--");
		sb_add(&sb, fd->name);
		bool first = true;
		for (size_t j = 0; fd->opts[j].name != NULL; ++j) {
			const opt_desc *od = &fd->opts[j];
			if (od->type == OT_PRESET)
				continue;
			if (!all_opts && !od->decoder_relevant)
				continue;
			const uint32_t v = *(const uint32_t *)((const char *)filters[i].options + od->offset);
			/* BCJ start offset is omitted when zero. */
			if (filter_is_simple(fd->id) && v == 0)
				continue;
			sb_add(&sb, first ? (getopt ? "=" : ":") : ",");
			first = false;
			sb_add(&sb, od->name);
			sb_add(&sb, "=");
			char tmp[64];
			switch (od->type) {
			case OT_SIZE: format_size(tmp, sizeof(tmp), v); break;
			case OT_ENUM: {
				const char *name = "?";
				for (size_t k = 0; od->map[k].name != NULL; ++k)
					if (od->map[k].id == v) name = od->map[k].name;
				snprintf(tmp, sizeof(tmp), "%s", name);
				break;
			}
			default: snprintf(tmp, sizeof(tmp), "%" PRIu32, v); break;
			}
			sb_add(&sb, tmp);
		}
	}
	return sb.buf;
}

char *strfilter_list(uint32_t flags)
{
	strbuf sb = { NULL, 0, 0 };
	sb_add(&sb, "");
	for (size_t i = 0; filters_table[i].name != NULL; ++i) {
		const filter_desc *fd = &filters_table[i];
		if (!fd->xz_format && !(flags & STRFILTER_ALL_FILTERS))
			continue;
		sb_add(&sb, fd->name);
		sb_add(&sb, ":");
		for (size_t j = 0; fd->opts[j].name != NULL; ++j) {
			const opt_desc *od = &fd->opts[j];
			if (j > 0)
				sb_add(&sb, ",");
			sb_add(&sb, od->name);
			sb_add(&sb, "=<");
			char tmp[128];
			switch (od->type) {
			case OT_PRESET: snprintf(tmp, sizeof(tmp), "0-9[e]"); break;
			case OT_SIZE: {
				char a[32], b[32];
				format_size(a, sizeof(a), od->min);
				format_size(b, sizeof(b), od->max);
				snprintf(tmp, sizeof(tmp), "%s-%s", a, b);
				break;
			}
			case OT_UINT32: snprintf(tmp, sizeof(tmp), "%" PRIu64 "-%" PRIu64, od->min, od->max); break;
			case OT_ENUM: {
				tmp[0] = '\0';
				for (size_t k = 0; od->map[k].name != NULL; ++k) {
					if (k > 0) strncat(tmp, "|", sizeof(tmp) - strlen(tmp) - 1);
					strncat(tmp, od->map[k].name, sizeof(tmp) - strlen(tmp) - 1);
				}
				break;
			}
			}
			sb_add(&sb, tmp);
			sb_add(&sb, ">");
		}
		sb_add(&sb, "\n");
	}
	return sb.buf;
}
