cat > file_io.c <<'EOF'
#include "private.h"
#include <poll.h>

const char stdin_filename[] = "(stdin)";

static bool warn_fchown;
static bool try_sparse = true;
static bool do_sync = true;
static int stdout_flags = -1;
static bool restore_stdout_flags = false;

void io_init(void)
{
	warn_fchown = geteuid() == 0;
}

void io_no_sparse(void)
{
	try_sparse = false;
}

void io_no_sync(void)
{
	do_sync = false;
}

static bool io_wait(file_pair *pair, int timeout, bool is_reading)
{
	struct pollfd pfd[1];
	if (is_reading) {
		pfd[0].fd = pair->src_fd;
		pfd[0].events = POLLIN;
	} else {
		pfd[0].fd = pair->dest_fd;
		pfd[0].events = POLLOUT;
	}
	while (true) {
		const int ret = poll(pfd, 1, timeout);
		if (user_abort)
			return true;
		if (ret == -1) {
			if (errno == EINTR)
				continue;
			message_error(_("%s: poll() failed: %s"), is_reading ? pair->src_name : pair->dest_name, strerror(errno));
			return true;
		}
		if (ret == 0)
			return false;
		return false;
	}
}

static void io_unlink(const char *name, const struct stat *known_st)
{
	struct stat new_st;
	if (lstat(name, &new_st) || new_st.st_dev != known_st->st_dev || new_st.st_ino != known_st->st_ino) {
		message_warning(_("%s: File seems to have been moved, not removing"), name);
	} else if (unlink(name)) {
		message_warning(_("%s: Cannot remove: %s"), name, strerror(errno));
	}
}

static void io_copy_attrs(const file_pair *pair)
{
	if (fchown(pair->dest_fd, pair->src_st.st_uid, (gid_t)(-1)) && warn_fchown)
		message_warning(_("%s: Cannot set the file owner: %s"), pair->dest_name, strerror(errno));

	mode_t mode;
	if (pair->dest_st.st_gid != pair->src_st.st_gid && fchown(pair->dest_fd, (uid_t)(-1), pair->src_st.st_gid)) {
		message_warning(_("%s: Cannot set the file group: %s"), pair->dest_name, strerror(errno));
		mode = ((pair->src_st.st_mode & 0070) >> 3) & (pair->src_st.st_mode & 0007);
		mode = (pair->src_st.st_mode & 0700) | (mode << 3) | mode;
	} else {
		mode = pair->src_st.st_mode & 0777;
	}

	if (fchmod(pair->dest_fd, mode))
		message_warning(_("%s: Cannot set the file permissions: %s"), pair->dest_name, strerror(errno));

	struct timespec tv[2];
	tv[0] = pair->src_st.st_atim;
	tv[1] = pair->src_st.st_mtim;
	(void)futimens(pair->dest_fd, tv);
}

static bool io_open_src_real(file_pair *pair)
{
	if (pair->src_name == stdin_filename) {
		pair->src_fd = STDIN_FILENO;
		return false;
	}

	const bool follow_symlinks = opt_stdout || opt_force || opt_keep_original;
	const bool reg_files_only = !opt_stdout;

	int flags = O_RDONLY | O_NOCTTY | O_NONBLOCK;
	if (!follow_symlinks)
		flags |= O_NOFOLLOW;

	pair->src_fd = open(pair->src_name, flags);
	if (pair->src_fd == -1) {
		if (errno == ELOOP && !follow_symlinks) {
			const int saved_errno = errno;
			struct stat st;
			if (lstat(pair->src_name, &st) == 0 && S_ISLNK(st.st_mode)) {
				message_warning(_("%s: Is a symbolic link, skipping"), pair->src_name);
				return true;
			}
			errno = saved_errno;
		}
		message_error("%s: %s", pair->src_name, strerror(errno));
		return true;
	}

	if (fstat(pair->src_fd, &pair->src_st))
		goto error_msg;

	if (S_ISDIR(pair->src_st.st_mode)) {
		message_warning(_("%s: Is a directory, skipping"), pair->src_name);
		goto error;
	}

	if (reg_files_only && !S_ISREG(pair->src_st.st_mode)) {
		message_warning(_("%s: Not a regular file, skipping"), pair->src_name);
		goto error;
	}

	if (reg_files_only && !opt_force) {
		if (pair->src_st.st_mode & (S_ISUID | S_ISGID)) {
			message_warning(_("%s: File has setuid or setgid bit set, skipping"), pair->src_name);
			goto error;
		}
		if (pair->src_st.st_mode & S_ISVTX) {
			message_warning(_("%s: File has sticky bit set, skipping"), pair->src_name);
			goto error;
		}
		if (pair->src_st.st_nlink > 1) {
			message_warning(_("%s: Input file has more than one hard link, skipping"), pair->src_name);
			goto error;
		}
	}

	if (S_ISREG(pair->src_st.st_mode)) {
		/* Regular files: clear O_NONBLOCK, it isn't needed. */
		const int fl = fcntl(pair->src_fd, F_GETFL);
		if (fl != -1)
			(void)fcntl(pair->src_fd, F_SETFL, fl & ~O_NONBLOCK);
	}

	return false;

error_msg:
	message_error("%s: %s", pair->src_name, strerror(errno));
error:
	(void)close(pair->src_fd);
	return true;
}

file_pair *io_open_src(const char *src_name)
{
	if (src_name[0] == '\0') {
		message_error(_("Empty filename, skipping"));
		return NULL;
	}

	static file_pair pair;
	memset(&pair, 0, sizeof(pair));
	pair.src_name = src_name;
	pair.dest_name = NULL;
	pair.src_fd = -1;
	pair.dest_fd = -1;
	pair.src_eof = false;
	pair.src_has_seen_input = false;
	pair.flush_needed = false;
	pair.dest_try_sparse = false;
	pair.dest_pending_sparse = 0;

	signals_block();
	const bool error = io_open_src_real(&pair);
	signals_unblock();

	return error ? NULL : &pair;
}

static void io_close_src(file_pair *pair, bool success)
{
	if (pair->src_fd != STDIN_FILENO && pair->src_fd != -1) {
		if (success && !opt_keep_original)
			io_unlink(pair->src_name, &pair->src_st);
		(void)close(pair->src_fd);
	}
}

static bool io_open_dest_real(file_pair *pair)
{
	if (opt_stdout || pair->src_fd == STDIN_FILENO) {
		pair->dest_name = (char *)"(stdout)";
		pair->dest_fd = STDOUT_FILENO;
		if (opt_mode == MODE_COMPRESS && is_tty_stdout())
			return true;
	} else {
		if (opt_format == FORMAT_RAW && !suffix_is_set())
			message_fatal(_("With --format=raw, --suffix=.SUF is required unless writing to stdout"));

		pair->dest_name = suffix_get_dest_name(pair->src_name);
		if (pair->dest_name == NULL)
			return true;

		if (opt_force && unlink(pair->dest_name) && errno != ENOENT) {
			message_error(_("%s: Cannot remove: %s"), pair->dest_name, strerror(errno));
			free(pair->dest_name);
			return true;
		}

		const int flags = O_WRONLY | O_NOCTTY | O_CREAT | O_EXCL;
		const mode_t mode = S_IRUSR | S_IWUSR;
		pair->dest_fd = open(pair->dest_name, flags, mode);
		if (pair->dest_fd == -1) {
			message_error("%s: %s", pair->dest_name, strerror(errno));
			free(pair->dest_name);
			return true;
		}
	}

	if (fstat(pair->dest_fd, &pair->dest_st)) {
		pair->dest_st.st_dev = 0;
		pair->dest_st.st_ino = 0;
	} else if (try_sparse && opt_mode == MODE_DECOMPRESS) {
		if (pair->dest_fd == STDOUT_FILENO) {
			if (!S_ISREG(pair->dest_st.st_mode))
				return false;
			const int flags = fcntl(STDOUT_FILENO, F_GETFL);
			if (flags == -1)
				return false;
			if (flags & O_APPEND) {
				if (lseek(STDOUT_FILENO, 0, SEEK_END) == -1)
					return false;
				stdout_flags = flags;
				if (fcntl(STDOUT_FILENO, F_SETFL, flags & ~O_APPEND) == -1)
					return false;
				restore_stdout_flags = true;
			} else if (lseek(STDOUT_FILENO, 0, SEEK_CUR) != pair->dest_st.st_size) {
				return false;
			}
		}
		pair->dest_try_sparse = true;
	}
	return false;
}

bool io_open_dest(file_pair *pair)
{
	signals_block();
	const bool ret = io_open_dest_real(pair);
	signals_unblock();
	return ret;
}

static bool io_write_buf(file_pair *pair, const uint8_t *buf, size_t size)
{
	while (size > 0) {
		const ssize_t amount = write(pair->dest_fd, buf, size);
		if (amount == -1) {
			if (errno == EINTR) {
				if (user_abort)
					return true;
				continue;
			}
			if (errno == EAGAIN || errno == EWOULDBLOCK) {
				if (io_wait(pair, -1, false))
					return true;
				continue;
			}
			if (errno != EPIPE)
				message_error(_("%s: Write error: %s"), pair->dest_name, strerror(errno));
			return true;
		}
		buf += (size_t)amount;
		size -= (size_t)amount;
	}
	return false;
}

static bool io_close_dest(file_pair *pair, bool success)
{
	if (restore_stdout_flags) {
		restore_stdout_flags = false;
		(void)fcntl(STDOUT_FILENO, F_SETFL, stdout_flags);
	}

	if (pair->dest_fd == -1 || pair->dest_fd == STDOUT_FILENO)
		return false;

	if (success && do_sync && !opt_keep_original) {
		if (fsync(pair->dest_fd)) {
			message_error(_("%s: Synchronizing the file failed: %s"), pair->dest_name, strerror(errno));
			(void)close(pair->dest_fd);
			io_unlink(pair->dest_name, &pair->dest_st);
			free(pair->dest_name);
			return true;
		}
	}

	if (close(pair->dest_fd)) {
		message_error(_("%s: Closing the file failed: %s"), pair->dest_name, strerror(errno));
		io_unlink(pair->dest_name, &pair->dest_st);
		free(pair->dest_name);
		return true;
	}

	if (!success)
		io_unlink(pair->dest_name, &pair->dest_st);

	free(pair->dest_name);
	return false;
}

bool io_close(file_pair *pair, bool success)
{
	if (success && pair->dest_try_sparse && pair->dest_pending_sparse > 0) {
		if (lseek(pair->dest_fd, pair->dest_pending_sparse - 1, SEEK_CUR) == -1) {
			message_error(_("%s: Seeking failed when trying to create a sparse file: %s"), pair->dest_name, strerror(errno));
			success = false;
		} else {
			const uint8_t zero[1] = { '\0' };
			if (io_write_buf(pair, zero, 1))
				success = false;
		}
	}

	signals_block();

	if (success && pair->dest_fd != STDOUT_FILENO && pair->dest_fd != -1)
		io_copy_attrs(pair);

	if (io_close_dest(pair, success))
		success = false;

	io_close_src(pair, success);

	signals_unblock();
	return !success;
}

void io_fix_src_pos(file_pair *pair, size_t rewind_size)
{
	if (rewind_size > 0) {
		if (lseek(pair->src_fd, -(off_t)rewind_size, SEEK_CUR) == -1) {
			/* Ignore errors (e.g. pipes). */
		}
	}
}

size_t io_read(file_pair *pair, io_buf *buf, size_t size)
{
	size_t pos = 0;
	while (pos < size) {
		const ssize_t amount = read(pair->src_fd, buf->u8 + pos, size - pos);
		if (amount == 0) {
			pair->src_eof = true;
			break;
		}
		if (amount == -1) {
			if (errno == EINTR) {
				if (user_abort)
					return SIZE_MAX;
				continue;
			}
			if (errno == EAGAIN || errno == EWOULDBLOCK) {
				const int timeout = mytime_get_flush_timeout();
				if (timeout == 0 && pair->src_has_seen_input) {
					pair->flush_needed = true;
					return pos;
				}
				if (io_wait(pair, timeout, true))
					return SIZE_MAX;
				if (timeout > 0 && mytime_get_flush_timeout() == 0 && pair->src_has_seen_input) {
					pair->flush_needed = true;
					return pos;
				}
				continue;
			}
			message_error(_("%s: Read error: %s"), pair->src_name, strerror(errno));
			return SIZE_MAX;
		}
		pos += (size_t)amount;
		pair->src_has_seen_input = true;
	}
	return pos;
}

bool io_seek_src(file_pair *pair, uint64_t pos)
{
	if (lseek(pair->src_fd, (off_t)pos, SEEK_SET) == -1) {
		message_error(_("%s: Error seeking the file: %s"), pair->src_name, strerror(errno));
		return true;
	}
	pair->src_eof = false;
	return false;
}

bool io_pread(file_pair *pair, io_buf *buf, size_t size, uint64_t pos)
{
	if (io_seek_src(pair, pos))
		return true;
	const size_t amount = io_read(pair, buf, size);
	if (amount == SIZE_MAX)
		return true;
	if (amount != size) {
		message_error(_("%s: Unexpected end of file"), pair->src_name);
		return true;
	}
	return false;
}

static bool is_sparse(const io_buf *buf)
{
	for (size_t i = 0; i < ARRAY_SIZE(buf->u64); ++i)
		if (buf->u64[i] != 0)
			return false;
	return true;
}

bool io_write(file_pair *pair, const io_buf *buf, size_t size)
{
	if (pair->dest_try_sparse) {
		if (size == IO_BUFFER_SIZE) {
			const off_t pending_max = (off_t)1 << (sizeof(off_t) * CHAR_BIT - 2);
			if (is_sparse(buf) && pair->dest_pending_sparse < pending_max) {
				pair->dest_pending_sparse += (off_t)size;
				return false;
			}
		} else if (size == 0) {
			return false;
		}
		if (pair->dest_pending_sparse > 0) {
			if (lseek(pair->dest_fd, pair->dest_pending_sparse, SEEK_CUR) == -1) {
				message_error(_("%s: Seeking failed when trying to create a sparse file: %s"), pair->dest_name, strerror(errno));
				return true;
			}
			pair->dest_pending_sparse = 0;
		}
	}
	return io_write_buf(pair, buf->u8, size);
}
