static uint64_t ceil4_u64(uint64_t n) { return (n + 3) & ~(uint64_t)3; }

/* Memory usage of the multithreaded encoder for one filter chain. */
static uint64_t mt_memusage(const xfilter *filters, uint32_t threads, uint64_t block_size)
{
	const uint64_t f = raw_encoder_memusage(filters);
	if (f == UINT64_MAX)
		return UINT64_MAX;
	const uint64_t chunks = (block_size + 65535) / 65536;
	const uint64_t bound = block_size + chunks * 3 + 1;
	const uint64_t per_thread = f + 856 + block_size + 2 * ceil4_u64(bound);
	return 33336 + (uint64_t)threads * per_thread;
