static uint64_t strm_total_out;

#define NUM_FILTER_CHAIN_MAX 10
static xfilter chains[NUM_FILTER_CHAIN_MAX][FILTERS_MAX + 1];
static uint32_t chains_used_mask = 1U << 0;
