	for (filters_count = 0; chains[0][filters_count].id != FID_UNKNOWN; ++filters_count)
		;
}

void coder_add_block_filters(const char *str, size_t slot)
{
	chains_init();
	if (chains_used_mask & (1U << slot))
		filters_free(chains[slot]);
	str_to_filters(str, (uint32_t)slot, 0);
	chains_used_mask |= 1U << slot;
}

static void memlimit_too_small(uint64_t memory_usage) __attribute__((noreturn));
static void memlimit_too_small(uint64_t memory_usage)
{
	message(V_ERROR, _("Memory usage limit is too low for the given filter setup."));
	message_mem_needed(V_ERROR, memory_usage);
	my_exit(E_ERROR);
}

static uint64_t ceil4_u64(uint64_t n) { return (n + 3) & ~(uint64_t)3; }

/* Memory usage of the multithreaded encoder for one filter chain. */
static uint64_t mt_memusage(const xfilter *filters, uint32_t threads, uint64_t block_size)
{
	const uint64_t f = raw_encoder_memusage(filters);
	if (f == UINT64_MAX)
		return UINT64_MAX;
	const uint64_t chunks = (block_size + 65535) / 65536;
	const uint64_t bound = block_size + chunks * 3 + 1;
	const uint64_t per_thread = f + 856 + block_size + 2 * ceil4_u64(bound);
	return 33336 + (uint64_t)threads * per_thread;
}

static uint64_t get_chains_memusage(uint64_t *chains_memusages, bool mt, bool encode)
{
	uint64_t max_memusage = 0;
	for (uint32_t i = 0; i < NUM_FILTER_CHAIN_MAX; i++) {
		if (!(chains_used_mask & (1U << i)))
			continue;
		uint64_t memusage;
		if (mt)
			memusage = mt_memusage(chains[i], mt_threads, mt_block_size);
		else if (encode)
			memusage = raw_encoder_memusage(chains[i]);
		else
			memusage = raw_decoder_memusage(chains[i]);
		if (chains_memusages != NULL)
			chains_memusages[i] = memusage;
		if (memusage > max_memusage)
			max_memusage = memusage;
	}
	return max_memusage;
}

void coder_set_compression_settings(void)
{
	chains_init();

	if (check_default)
		check = CHECK_CRC64;

	if (opt_block_list != NULL) {
		const uint32_t missing_chains_mask = (block_list_chain_mask ^ chains_used_mask) & block_list_chain_mask;
		if (missing_chains_mask != 0) {
			const unsigned first_missing = (unsigned)ctz32(missing_chains_mask);
			message_fatal(_("filter chain %u used by --block-list but not specified with --filters%u="),
					first_missing, first_missing);
		}
		chains_used_mask &= block_list_chain_mask;
	} else {
		chains_used_mask = 1U << 0;
	}

	static lzma_options opt_lzma;

	if (filters_count == 0 && (chains_used_mask & 1)) {
		if (opt_format == FORMAT_RAW) {
			message(V_WARNING, _("Using a preset in raw mode is discouraged."));
			message(V_WARNING, _("The exact options of the presets may vary between software versions."));
		}
		if (lzma_preset_options(&opt_lzma, preset_number))
			message_bug();
		chains[0][0].id = opt_format == FORMAT_LZMA ? FID_LZMA1 : FID_LZMA2;
		chains[0][0].options = &opt_lzma;
		chains[0][1].id = FID_UNKNOWN;
	}

	if (opt_format == FORMAT_LZMA && (filters_count > 1 || chains[0][0].id != FID_LZMA1))
		message_fatal(_("The .lzma format supports only the LZMA1 filter"));

	if (opt_format == FORMAT_XZ && (chains_used_mask & 1))
		for (size_t i = 0; i < filters_count; ++i)
			if (chains[0][i].id == FID_LZMA1)
				message_fatal(_("LZMA1 cannot be used with the .xz format"));

	if (chains_used_mask & 1)
		message_filters_show(V_DEBUG, chains[0]);

	if (opt_mode == MODE_COMPRESS && opt_flush_timeout != 0) {
		for (uint32_t i = 0; i < NUM_FILTER_CHAIN_MAX; ++i) {
			if (!(chains_used_mask & (1U << i)))
				continue;
			const xfilter *fc = chains[i];
			for (size_t j = 0; fc[j].id != FID_UNKNOWN; j++) {
				switch (fc[j].id) {
				case FID_LZMA2:
				case FID_DELTA:
					break;
				default:
					message_fatal(_("Filter chain %u is incompatible with --flush-timeout"), (unsigned)i);
				}
			}
		}
		if (hardware_threads_is_mt()) {
			message(V_WARNING, _("Switching to single-threaded mode due to --flush-timeout"));
			hardware_threads_set(1);
		}
	}

	uint64_t memory_limit = hardware_memlimit_get(opt_mode);
	uint64_t memory_usage = UINT64_MAX;
	uint64_t encoder_memusages[NUM_FILTER_CHAIN_MAX];
	bool mt = false;

	if (opt_mode == MODE_COMPRESS) {
		if (opt_format == FORMAT_XZ && hardware_threads_is_mt()) {
			mt = true;
			memory_limit = hardware_memlimit_mtenc_get();
			mt_threads = hardware_threads_get();
			uint64_t block_size = opt_block_size;
			if (block_size == 0) {
				for (uint32_t i = 0; i < NUM_FILTER_CHAIN_MAX; i++) {
					if (!(chains_used_mask & (1U << i)))
						continue;
					const uint64_t size = filters_mt_block_size(chains[i]);
					if (size == UINT64_MAX)
						message_fatal(_("Unsupported options in filter chain %u"), (unsigned)i);
					if (size > block_size)
						block_size = size;
				}
				if (opt_block_list != NULL && block_size > block_list_largest)
					block_size = block_list_largest;
			}
			mt_block_size = block_size;
			memory_usage = get_chains_memusage(encoder_memusages, true, true);
			if (memory_usage != UINT64_MAX)
				message(V_DEBUG, _("Using up to %" PRIu32 " threads."), mt_threads);
		} else {
			memory_usage = get_chains_memusage(encoder_memusages, false, true);
		}
	} else {
		memory_usage = raw_decoder_memusage(chains[0]);
	}

	if (memory_usage == UINT64_MAX)
		message_fatal(_("Unsupported filter chain"));

	message_mem_needed(V_DEBUG, memory_usage);

	if (opt_mode == MODE_COMPRESS && message_verbosity_get() >= V_DEBUG) {
		const uint64_t decmem = get_chains_memusage(NULL, false, false);
		if (decmem != UINT64_MAX)
			message(V_DEBUG, _("Decompression will need %s MiB of memory."), uint64_to_str(round_up_to_mib(decmem), 0));
	}

	if (memory_usage <= memory_limit)
		return;

	if (opt_format == FORMAT_RAW)
		memlimit_too_small(memory_usage);

	if (mt) {
		while (mt_threads > 1) {
			--mt_threads;
			memory_usage = get_chains_memusage(encoder_memusages, true, true);
			if (memory_usage == UINT64_MAX)
				message_bug();
			if (memory_usage <= memory_limit) {
				message(V_DEBUG, _("Reduced the number of threads from %s to %s to not exceed the memory usage limit of %s MiB"),
						uint64_to_str(hardware_threads_get(), 0),
						uint64_to_str(mt_threads, 1),
						uint64_to_str(round_up_to_mib(memory_limit), 2));
				return;
			}
		}

		message(V_WARNING, _("Switching to single-threaded mode to not exceed the memory usage limit of %s MiB"),
				uint64_to_str(round_up_to_mib(memory_limit), 0));
		hardware_threads_set(1);
		memory_limit = hardware_memlimit_get(opt_mode);
		memory_usage = get_chains_memusage(encoder_memusages, false, true);
		if (memory_usage <= memory_limit)
			return;
	}

	if (!opt_auto_adjust)
		memlimit_too_small(memory_usage);

	for (uint32_t i = 0; i < NUM_FILTER_CHAIN_MAX; i++) {
		if (!(chains_used_mask & (1U << i)))
			continue;
		if (encoder_memusages[i] <= memory_limit)
			continue;

		unsigned j = 0;
		while (chains[i][j].id != FID_LZMA2 && chains[i][j].id != FID_LZMA1) {
			if (chains[i][j].id == FID_UNKNOWN)
				memlimit_too_small(encoder_memusages[i]);
			++j;
		}

		lzma_options *opt = chains[i][j].options;
		const uint32_t orig_dict_size = opt->dict_size;
		opt->dict_size &= ~((UINT32_C(1) << 20) - 1);

		while (true) {
			if (opt->dict_size < (UINT32_C(1) << 20))
				memlimit_too_small(encoder_memusages[i]);
			encoder_memusages[i] = raw_encoder_memusage(chains[i]);
			if (encoder_memusages[i] == UINT64_MAX)
				message_bug();
			if (encoder_memusages[i] <= memory_limit)
				break;
			opt->dict_size -= UINT32_C(1) << 20;
		}

		message(V_WARNING, _("Adjusted LZMA%c dictionary size from %s MiB to %s MiB to not exceed the memory usage limit of %s MiB"),
				chains[i][j].id == FID_LZMA2 ? '2' : '1',
				uint64_to_str(orig_dict_size >> 20, 0),
				uint64_to_str(opt->dict_size >> 20, 1),
				uint64_to_str(round_up_to_mib(memory_limit), 2));
	}
}

static bool is_format_xz(void)
{
	return strm_avail_in >= 6 && memcmp(in_buf.u8, xz_header_magic, 6) == 0;
}

static bool is_format_lzma(void)
{
	if (strm_avail_in < 13)
		return false;
	lzma_options o;
	if (lzma1_props_decode(&o, in_buf.u8, 5))
		return false;
	const uint32_t dict_size = o.dict_size;
	if (dict_size != UINT32_MAX) {
		uint32_t d = dict_size - 1;
		d |= d >> 2;
		d |= d >> 3;
		d |= d >> 4;
		d |= d >> 8;
		d |= d >> 16;
		++d;
		if (d != dict_size || dict_size == 0)
			return false;
	}
	uint64_t uncompressed_size = 0;
	for (size_t i = 0; i < 8; ++i)
		uncompressed_size |= (uint64_t)in_buf.u8[5 + i] << (i * 8);
	if (uncompressed_size != UINT64_MAX && uncompressed_size > (UINT64_C(1) << 38))
		return false;
	return true;
}

static bool is_format_lzip(void)
{
	static const uint8_t magic[4] = { 0x4C, 0x5A, 0x49, 0x50 };
	return strm_avail_in >= sizeof(magic) && memcmp(in_buf.u8, magic, sizeof(magic)) == 0;
}

static xret strm_code(xaction action)
{
	size_t in_pos = 0;
	size_t out_pos = 0;
	const xret ret = xcoder_code(&strm, strm_next_in, &in_pos, strm_avail_in, strm_next_out, &out_pos, strm_avail_out, action);
	strm_next_in += in_pos;
	strm_avail_in -= in_pos;
	strm_total_in += in_pos;
	strm_next_out += out_pos;
	strm_avail_out -= out_pos;
	strm_total_out += out_pos;
	message_progress_set_totals(strm_total_in, strm_total_out);
	return ret;
}

static uint64_t strm_memusage(void)
{
	uint64_t memusage, old_limit;
	coder_memconfig(&strm, &memusage, &old_limit, 0);
	return memusage;
}

static enum coder_init_ret coder_init(file_pair *pair)
{
	xret ret = R_PROG_ERROR;
	allow_trailing_input = false;
	xcoder_end(&strm);
	strm_total_in = 0;
	strm_total_out = 0;

	const xfilter *active_filters = opt_block_list == NULL ? chains[0] : chains[opt_block_list[0].chain_num];

	if (opt_mode == MODE_COMPRESS) {
		switch (opt_format) {
		case FORMAT_AUTO:
			message_bug();
		case FORMAT_XZ:
			if (hardware_threads_is_mt())
				ret = stream_encoder_mt_init(&strm, active_filters, check, mt_block_size);
			else
				ret = stream_encoder_init(&strm, active_filters, check);
			break;
		case FORMAT_LZMA:
			ret = alone_encoder_init(&strm, active_filters[0].options);
			break;
		case FORMAT_LZIP:
			message_bug();
		case FORMAT_RAW:
			ret = raw_encoder_init(&strm, active_filters);
			break;
		}
	} else {
		uint32_t flags = 0;
		if (opt_ignore_check)
			flags |= DEC_IGNORE_CHECK;
		else
			flags |= DEC_TELL_UNSUPPORTED_CHECK;

		if (opt_single_stream)
			allow_trailing_input = true;
		else
			flags |= DEC_CONCATENATED;

		enum format_type init_format = FORMAT_AUTO;
		switch (opt_format) {
		case FORMAT_AUTO:
			if (is_format_xz())
				init_format = FORMAT_XZ;
			else if (is_format_lzip())
				init_format = FORMAT_LZIP;
			else if (is_format_lzma())
				init_format = FORMAT_LZMA;
			break;
		case FORMAT_XZ:
			if (is_format_xz())
				init_format = FORMAT_XZ;
			break;
		case FORMAT_LZMA:
			if (is_format_lzma())
				init_format = FORMAT_LZMA;
			break;
		case FORMAT_LZIP:
			if (is_format_lzip())
				init_format = FORMAT_LZIP;
			break;
		case FORMAT_RAW:
			init_format = FORMAT_RAW;
			break;
		}

		switch (init_format) {
		case FORMAT_AUTO:
			if (opt_mode == MODE_DECOMPRESS && opt_stdout && opt_force)
				return CODER_INIT_PASSTHRU;
			ret = R_FORMAT_ERROR;
			break;
		case FORMAT_XZ:
			ret = stream_decoder_init(&strm, hardware_memlimit_get(MODE_DECOMPRESS), flags);
			break;
		case FORMAT_LZMA:
			ret = alone_decoder_init(&strm, hardware_memlimit_get(MODE_DECOMPRESS), false);
			break;
		case FORMAT_LZIP:
			ret = lzip_decoder_init(&strm, hardware_memlimit_get(MODE_DECOMPRESS), flags);
			break;
		case FORMAT_RAW:
			ret = raw_decoder_init(&strm, active_filters);
			break;
		}

		if (ret == R_OK && init_format != FORMAT_RAW) {
			strm_next_out = NULL;
			strm_avail_out = 0;
			while ((ret = strm_code(A_RUN)) == R_UNSUPPORTED_CHECK)
				message_warning(_("%s: %s"), pair->src_name, message_strm(ret));
			if (ret == R_STREAM_END)
				ret = R_OK;
		}
	}

	if (ret != R_OK) {
		message_error(_("%s: %s"), pair->src_name, message_strm(ret));
		if (ret == R_MEMLIMIT_ERROR)
			message_mem_needed(V_ERROR, strm_memusage());
		return CODER_INIT_ERROR;
	}

	return CODER_INIT_NORMAL;
}

static void split_block(uint64_t *block_remaining, uint64_t *next_block_remaining, size_t *list_pos)
{
	if (*next_block_remaining > 0) {
		if (*next_block_remaining > opt_block_size) {
			*block_remaining = opt_block_size;
			*next_block_remaining -= opt_block_size;
		} else {
			*block_remaining = *next_block_remaining;
			*next_block_remaining = 0;
		}
	} else {
		if (opt_block_list[*list_pos + 1].size != 0) {
			++*list_pos;
			if (opt_block_list[*list_pos - 1].chain_num != opt_block_list[*list_pos].chain_num) {
				const unsigned chain_num = opt_block_list[*list_pos].chain_num;
				const xret ret = stream_encoder_update(&strm, chains[chain_num]);
				if (ret != R_OK)
					message_fatal(_("Error changing to filter chain %u: %s"), chain_num, message_strm(ret));
			}
		}
		*block_remaining = opt_block_list[*list_pos].size;
		if (!hardware_threads_is_mt() && opt_block_size > 0 && *block_remaining > opt_block_size) {
			*next_block_remaining = *block_remaining - opt_block_size;
			*block_remaining = opt_block_size;
		}
	}
}

static bool coder_normal(file_pair *pair)
{
	xaction action = pair->src_eof ? A_FINISH : A_RUN;
	xret ret;
	bool success = false;
	uint64_t block_remaining = UINT64_MAX;
	uint64_t next_block_remaining = 0;
	size_t list_pos = 0;

	if (opt_mode == MODE_COMPRESS && opt_format == FORMAT_XZ) {
		if (!hardware_threads_is_mt() && opt_block_size > 0)
			block_remaining = opt_block_size;
		if (opt_block_list != NULL) {
			if (block_remaining < opt_block_list[list_pos].size) {
				next_block_remaining = opt_block_list[list_pos].size - block_remaining;
			} else {
				block_remaining = opt_block_list[list_pos].size;
			}
		}
	}

	strm_next_out = out_buf.u8;
	strm_avail_out = IO_BUFFER_SIZE;

	while (!user_abort) {
		if (strm_avail_in == 0 && action == A_RUN) {
			strm_next_in = in_buf.u8;
			strm_avail_in = io_read(pair, &in_buf, (size_t)my_min(block_remaining, (uint64_t)IO_BUFFER_SIZE));
			if (strm_avail_in == SIZE_MAX)
				break;
			if (pair->src_eof) {
				action = A_FINISH;
			} else if (block_remaining != UINT64_MAX) {
				block_remaining -= strm_avail_in;
				if (block_remaining == 0)
					action = A_FULL_BARRIER;
			}
			if (action == A_RUN && pair->flush_needed)
				action = A_SYNC_FLUSH;
		}

		ret = strm_code(action);

		if (strm_avail_out == 0) {
			if (opt_mode != MODE_TEST && io_write(pair, &out_buf, IO_BUFFER_SIZE - strm_avail_out))
				break;
			strm_next_out = out_buf.u8;
			strm_avail_out = IO_BUFFER_SIZE;
		}

		if (ret == R_STREAM_END && (action == A_SYNC_FLUSH || action == A_FULL_BARRIER)) {
			if (action == A_SYNC_FLUSH) {
				if (io_write(pair, &out_buf, IO_BUFFER_SIZE - strm_avail_out))
					break;
				strm_next_out = out_buf.u8;
				strm_avail_out = IO_BUFFER_SIZE;
				pair->src_has_seen_input = false;
				pair->flush_needed = false;
				mytime_set_flush_time();
			} else {
				if (opt_block_list == NULL) {
					block_remaining = opt_block_size;
				} else {
					split_block(&block_remaining, &next_block_remaining, &list_pos);
				}
			}
			action = A_RUN;
		} else if (ret != R_OK) {
			const bool stop = ret != R_UNSUPPORTED_CHECK;
			if (stop) {
				if (opt_mode != MODE_TEST && io_write(pair, &out_buf, IO_BUFFER_SIZE - strm_avail_out))
					break;
			}
			if (ret == R_STREAM_END) {
				if (allow_trailing_input) {
					io_fix_src_pos(pair, strm_avail_in);
					success = true;
					break;
				}
				if (strm_avail_in == 0 && !pair->src_eof) {
					strm_avail_in = io_read(pair, &in_buf, 1);
					if (strm_avail_in == SIZE_MAX)
						break;
				}
				if (strm_avail_in == 0) {
					success = true;
					break;
				}
				ret = R_DATA_ERROR;
			}
			if (stop)
				message_error(_("%s: %s"), pair->src_name, message_strm(ret));
			else
				message_warning(_("%s: %s"), pair->src_name, message_strm(ret));
			if (ret == R_MEMLIMIT_ERROR)
				message_mem_needed(V_ERROR, strm_memusage());
			if (stop)
				break;
		}

		message_progress_update();
	}

	return success;
}

static bool coder_passthru(file_pair *pair)
{
	while (strm_avail_in != 0) {
		if (user_abort)
			return false;
		if (io_write(pair, &in_buf, strm_avail_in))
			return false;
		strm_total_in += strm_avail_in;
		strm_total_out = strm_total_in;
		message_progress_set_totals(strm_total_in, strm_total_out);
		message_progress_update();
		strm_avail_in = io_read(pair, &in_buf, IO_BUFFER_SIZE);
		if (strm_avail_in == SIZE_MAX)
			return false;
	}
	return true;
}

void coder_run(const char *filename)
{
	message_filename(filename);

	file_pair *pair = io_open_src(filename);
	if (pair == NULL)
		return;

	bool success = false;

	if (opt_mode == MODE_COMPRESS) {
		strm_next_in = NULL;
		strm_avail_in = 0;
	} else {
		strm_next_in = in_buf.u8;
		strm_avail_in = io_read(pair, &in_buf, IO_BUFFER_SIZE);
	}

	if (strm_avail_in != SIZE_MAX) {
		const enum coder_init_ret init_ret = coder_init(pair);
		if (init_ret != CODER_INIT_ERROR && !user_abort) {
			if (opt_mode == MODE_TEST || !io_open_dest(pair)) {
				mytime_set_start_time();
				mytime_set_flush_time();
				const bool is_passthru = init_ret == CODER_INIT_PASSTHRU;
				const uint64_t in_size = pair->src_st.st_size <= 0 ? 0 : (uint64_t)pair->src_st.st_size;
				message_progress_start(&strm, is_passthru, in_size);
				if (is_passthru)
					success = coder_passthru(pair);
				else
					success = coder_normal(pair);
				message_progress_end(success);
			}
		}
	}

	io_close(pair, success);
	xcoder_end(&strm);
}
