		value = str_to_uint64(name_percentage, s, 1, 100);
		free(s);
	} else {
		value = str_to_uint64(name, str, 0, UINT64_MAX);
	}
	hardware_memlimit_set(value, set_compress, set_decompress, set_mtdec, is_percentage);
}

static void parse_block_list(const char *str_const)
{
	char *str_start = xstrdup(str_const);
	char *str = str_start;

	if (str[0] == '\0' || str[0] == ',')
		message_fatal(_("%s: Invalid argument to --block-list"), str);

	size_t count = 1;
	for (size_t i = 0; str[i] != '\0'; ++i)
		if (str[i] == ',')
			++count;

	if (count > SIZE_MAX / sizeof(block_list_entry) - 1)
		message_fatal(_("%s: Too many arguments to --block-list"), str);

	free(opt_block_list);
	opt_block_list = xrealloc(NULL, (count + 1) * sizeof(block_list_entry));
	block_list_chain_mask = 0;
	block_list_largest = 0;

	for (size_t i = 0; i < count; ++i) {
		char *p = strchr(str, ',');
		if (p != NULL)
			*p = '\0';

		opt_block_list[i].chain_num = 0;

		if (str[0] >= '0' && str[0] <= '9' && str[1] == ':') {
			if (str[2] == '\0')
				message_fatal(_("In --block-list, block size is missing after filter chain number '%c:'"), str[0]);
			const unsigned chain_num = (unsigned)(str[0] - '0');
			opt_block_list[i].chain_num = chain_num;
			block_list_chain_mask |= 1U << chain_num;
			str += 2;
		} else {
			block_list_chain_mask |= 1U << 0;
		}

		if (str[0] == '\0') {
			opt_block_list[i] = opt_block_list[i - 1];
		} else {
			opt_block_list[i].size = str_to_uint64("block-list", str, 0, UINT64_MAX);
			if (opt_block_list[i].size == 0) {
				if (i + 1 != count)
					message_fatal(_("0 can only be used as the last element in --block-list"));
				opt_block_list[i].size = UINT64_MAX;
			}
			if (block_list_largest < opt_block_list[i].size)
				block_list_largest = opt_block_list[i].size;
		}

		if (p != NULL)
			str = p + 1;
	}

	opt_block_list[count].size = 0;
	free(str_start);
}

static void parse_environment(args_info *args, char *argv0, const char *varname)
{
	char *env = getenv(varname);
	if (env == NULL)
		return;
	env = xstrdup(env);

	int argc = 1;
	bool prev_was_space = true;
	for (size_t i = 0; env[i] != '\0'; ++i) {
		if (isspace((unsigned char)env[i])) {
			prev_was_space = true;
		} else if (prev_was_space) {
			prev_was_space = false;
			if (++argc == INT_MAX)
				message_fatal(_("The environment variable %s contains too many arguments"), varname);
		}
	}

	char **argv = xrealloc(NULL, ((size_t)argc + 1) * sizeof(char *));
	argv[0] = argv0;
	argv[argc] = NULL;

	argc = 1;
	prev_was_space = true;
	for (size_t i = 0; env[i] != '\0'; ++i) {
		if (isspace((unsigned char)env[i])) {
			prev_was_space = true;
			env[i] = '\0';
		} else if (prev_was_space) {
			prev_was_space = false;
			argv[argc++] = env + i;
		}
	}

	parse_real(args, argc, argv);

	optind = 0;

	free(argv);
	free(env);
}

