static void parse_memlimit(const char *name, const char *name_percentage, const char *str,
		bool set_compress, bool set_decompress, bool set_mtdec)
{
	bool is_percentage = false;
	uint64_t value;
	const size_t len = strlen(str);
	if (len > 0 && str[len - 1] == '%') {
		char *s = xstrdup(str);
		s[len - 1] = '\0';
