static void parse_real(args_info *args, int argc, char **argv)
{
	int c;
	while ((c = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
		switch (c) {
		case '0': case '1': case '2': case '3': case '4':
		case '5': case '6': case '7': case '8': case '9':
			coder_set_preset((uint32_t)(c - '0'));
			break;

		case 'e':
			coder_set_extreme();
			break;

		case 'C':
			if (strcmp(optarg, "none") == 0)
				coder_set_check(CHECK_NONE);
			else if (strcmp(optarg, "crc32") == 0)
				coder_set_check(CHECK_CRC32);
			else if (strcmp(optarg, "crc64") == 0)
				coder_set_check(CHECK_CRC64);
			else if (strcmp(optarg, "sha256") == 0)
				coder_set_check(CHECK_SHA256);
			else
				message_fatal(_("%s: Unsupported integrity check type"), optarg);
			break;

		case 'c':
			opt_stdout = true;
			break;

		case 'd':
			opt_mode = MODE_DECOMPRESS;
			break;

		case 'f':
			opt_force = true;
			break;

		case 'F':
			if (strcmp(optarg, "auto") == 0)
				opt_format = FORMAT_AUTO;
			else if (strcmp(optarg, "xz") == 0)
				opt_format = FORMAT_XZ;
			else if (strcmp(optarg, "lzma") == 0 || strcmp(optarg, "alone") == 0)
				opt_format = FORMAT_LZMA;
			else if (strcmp(optarg, "lzip") == 0)
				opt_format = FORMAT_LZIP;
			else if (strcmp(optarg, "raw") == 0)
				opt_format = FORMAT_RAW;
			else
				message_fatal(_("%s: Unknown file format type"), optarg);
			break;

		case 'h':
			message_help(false);

		case 'H':
			message_help(true);

		case 'l':
			opt_mode = MODE_LIST;
			break;

		case 'k':
			opt_keep_original = true;
			break;

		case 'M':
			parse_memlimit("memlimit", "memlimit%", optarg, true, true, true);
			break;

		case 'q':
			message_verbosity_decrease();
			break;

		case 'Q':
			set_exit_no_warn();
			break;

		case 'r':
			message_try_help();
			my_exit(E_ERROR);

		case 't':
			opt_mode = MODE_TEST;
			break;

		case 'T': {
			const char *s = optarg;
			if (optarg[0] == '+')
				++s;
			uint32_t t = (uint32_t)str_to_uint64("threads", s, 0, 16384);
			if (t == 1 && optarg[0] == '+')
				t = UINT32_MAX;
			if (t == UINT32_MAX) {
				hardware_threads_set(1);
				hardware_threads_force_mt();
			} else {
				hardware_threads_set(t);
			}
			break;
		}

		case 'v':
			message_verbosity_increase();
			break;

		case 'V':
			message_version();

		case 'z':
			opt_mode = MODE_COMPRESS;
			break;

		case 'S':
			suffix_set(optarg);
			break;

		case OPT_X86:
			coder_add_filter(FID_X86, options_bcj(optarg));
			break;
		case OPT_POWERPC:
			coder_add_filter(FID_POWERPC, options_bcj(optarg));
			break;
		case OPT_IA64:
			coder_add_filter(FID_IA64, options_bcj(optarg));
			break;
		case OPT_ARM:
			coder_add_filter(FID_ARM, options_bcj(optarg));
			break;
		case OPT_ARMTHUMB:
			coder_add_filter(FID_ARMTHUMB, options_bcj(optarg));
			break;
		case OPT_ARM64:
			coder_add_filter(FID_ARM64, options_bcj(optarg));
			break;
		case OPT_RISCV:
			coder_add_filter(FID_RISCV, options_bcj(optarg));
			break;
		case OPT_SPARC:
			coder_add_filter(FID_SPARC, options_bcj(optarg));
			break;
		case OPT_DELTA:
			coder_add_filter(FID_DELTA, options_delta(optarg));
			break;
		case OPT_LZMA1:
			coder_add_filter(FID_LZMA1, options_lzma(optarg));
			break;
		case OPT_LZMA2:
			coder_add_filter(FID_LZMA2, options_lzma(optarg));
			break;

		case OPT_SINGLE_STREAM:
			opt_single_stream = true;
			break;

		case OPT_NO_SPARSE:
			io_no_sparse();
			break;

		case OPT_FILES:
		case OPT_FILES0:
			if (args->files_name != NULL)
				message_fatal(_("Only one file can be specified with '--files' or '--files0'."));
			if (optarg == NULL) {
				args->files_name = stdin_filename;
				args->files_file = stdin;
			} else {
				args->files_name = optarg;
				args->files_file = fopen(optarg, c == OPT_FILES ? "r" : "rb");
				if (args->files_file == NULL)
					message_fatal("%s: %s", optarg, strerror(errno));
			}
			args->files_delim = c == OPT_FILES ? '\n' : '\0';
			break;

		case OPT_FILTERS:
			coder_add_filters_from_str(optarg);
			break;

		case OPT_FILTERS1: case OPT_FILTERS2: case OPT_FILTERS3:
		case OPT_FILTERS4: case OPT_FILTERS5: case OPT_FILTERS6:
		case OPT_FILTERS7: case OPT_FILTERS8: case OPT_FILTERS9:
			coder_add_block_filters(optarg, (size_t)(c - OPT_FILTERS));
			break;

		case OPT_FILTERS_HELP: {
			puts(_("Filter chains are set using the --filters=FILTERS or\n"
				"--filters1=FILTERS ... --filters9=FILTERS options. Each filter in the chain\n"
				"can be separated by spaces or '--'. Alternatively a preset <0-9>[e] can be\n"
				"specified instead of a filter chain.\n"));
			puts(_("The supported filters and their options are:"));
			char *list = strfilter_list(0);
			fputs(list, stdout);
			free(list);
			my_exit(E_SUCCESS);
		}

		case OPT_BLOCK_SIZE:
			opt_block_size = str_to_uint64("block-size", optarg, 0, VLI_MAX);
			break;

		case OPT_BLOCK_LIST:
			parse_block_list(optarg);
			break;

		case OPT_MEM_COMPRESS:
			parse_memlimit("memlimit-compress", "memlimit-compress%", optarg, true, false, false);
			break;

		case OPT_MEM_DECOMPRESS:
			parse_memlimit("memlimit-decompress", "memlimit-decompress%", optarg, false, true, false);
			break;

		case OPT_MEM_MT_DECOMPRESS:
			parse_memlimit("memlimit-mt-decompress", "memlimit-mt-decompress%", optarg, false, false, true);
			break;

		case OPT_NO_ADJUST:
			opt_auto_adjust = false;
			break;

		case OPT_INFO_MEMORY:
			hardware_memlimit_show();

		case OPT_ROBOT:
			opt_robot = true;
			break;

		case OPT_FLUSH_TIMEOUT:
			opt_flush_timeout = str_to_uint64("flush-timeout", optarg, 0, UINT64_MAX);
			break;

		case OPT_IGNORE_CHECK:
			opt_ignore_check = true;
			break;

		case OPT_NO_SYNC:
			io_no_sync();
			break;

		default:
			message_try_help();
			my_exit(E_ERROR);
		}
	}
}

void args_parse(args_info *args, int argc, char **argv)
{
	args->files_name = NULL;
	args->files_file = NULL;
	args->files_delim = '\0';

	{
		const char *name = strrchr(argv[0], '/');
		if (name == NULL)
			name = argv[0];
		else
			++name;

		if (strstr(name, "xzcat") != NULL) {
			opt_mode = MODE_DECOMPRESS;
			opt_stdout = true;
		} else if (strstr(name, "unxz") != NULL) {
			opt_mode = MODE_DECOMPRESS;
		} else if (strstr(name, "lzcat") != NULL) {
			opt_format = FORMAT_LZMA;
			opt_mode = MODE_DECOMPRESS;
			opt_stdout = true;
		} else if (strstr(name, "unlzma") != NULL) {
			opt_format = FORMAT_LZMA;
			opt_mode = MODE_DECOMPRESS;
		} else if (strstr(name, "lzma") != NULL) {
			opt_format = FORMAT_LZMA;
		}
	}

	parse_environment(args, argv[0], "XZ_DEFAULTS");
	parse_environment(args, argv[0], "XZ_OPT");
	parse_real(args, argc, argv);

	if (opt_mode == MODE_COMPRESS && opt_format == FORMAT_LZIP)
		message_fatal(_("Compression of lzip files (.lz) is not supported"));

	if (opt_mode == MODE_LIST && opt_format == FORMAT_LZMA) {
		message(V_ERROR, _("--list works only on .xz files (--format=xz or --format=auto)"));
		message_fatal(_("Try 'lzmainfo' with .lzma files."));
	}
	if (opt_mode == MODE_LIST && opt_format != FORMAT_XZ && opt_format != FORMAT_AUTO)
		message_fatal(_("--list works only on .xz files (--format=xz or --format=auto)"));

	if (opt_stdout || opt_mode == MODE_TEST) {
		opt_keep_original = true;
		opt_stdout = true;
	}

	if (opt_mode == MODE_COMPRESS && opt_format == FORMAT_AUTO)
		opt_format = FORMAT_XZ;

	if (opt_block_list != NULL && (opt_mode != MODE_COMPRESS || opt_format != FORMAT_XZ)) {
		message(V_WARNING, _("--block-list is ignored unless compressing to the .xz format"));
		free(opt_block_list);
		opt_block_list = NULL;
	}

	if (opt_mode == MODE_COMPRESS || (opt_format == FORMAT_RAW && opt_mode != MODE_LIST))
		coder_set_compression_settings();

	if (argv[optind] == NULL && args->files_name == NULL) {
		static char *names_stdin[2] = { (char *)"-", NULL };
		args->arg_names = names_stdin;
		args->arg_count = 1;
	} else {
		args->arg_names = argv + optind;
		args->arg_count = (unsigned int)(argc - optind);
	}
}

void args_free(void)
{
	free(opt_block_list);
}
