#include "private.h"
#include "../vli.h"

static const char *const check_names[CHECK_ID_MAX + 1] = {
	"None", "CRC32", "Unknown-2", "Unknown-3", "CRC64", "Unknown-5", "Unknown-6", "Unknown-7",
	"Unknown-8", "Unknown-9", "SHA-256", "Unknown-11", "Unknown-12", "Unknown-13", "Unknown-14", "Unknown-15",
};

typedef struct {
	xindex idx;
	uint64_t stream_padding;
	uint64_t memusage_max;
	bool all_have_sizes;
	uint32_t min_version;
} xz_file_info;

typedef struct {
	char flags[3];
	uint32_t header_size;
	uint64_t compressed_size;
	uint64_t memusage;
	char *filter_chain;
} block_header_info;

static struct {
	uint64_t files;
	uint64_t streams;
	uint64_t blocks;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	uint64_t stream_padding;
	uint64_t memusage_max;
	uint32_t checks;
	uint32_t min_version;
	bool all_have_sizes;
} totals = { 0, 0, 0, 0, 0, 0, 0, 0, 50000002, true };

#define CHECKS_STR_SIZE 1024

static void get_check_names(char buf[CHECKS_STR_SIZE], uint32_t checks, bool space_after_comma)
{
	const char *sep = space_after_comma ? ", " : ",";
	bool first = true;
	char *pos = buf;
	size_t left = CHECKS_STR_SIZE;
	for (size_t i = 0; i <= CHECK_ID_MAX; ++i) {
		if (checks & (UINT32_C(1) << i)) {
			my_snprintf(&pos, &left, "%s%s", first ? "" : sep, check_names[i]);
			first = false;
		}
	}
	if (first)
		my_snprintf(&pos, &left, "%s", check_names[0]);
}

static const char *get_ratio(uint64_t compressed, uint64_t uncompressed)
{
	if (uncompressed == 0)
		return "---";
	const double ratio = (double)compressed / (double)uncompressed;
	if (ratio > 9.999)
		return "---";
	static char buf[16];
	snprintf(buf, sizeof(buf), "%.3f", ratio);
	return buf;
}

static const char *xz_ver_to_str(uint32_t ver)
{
	static char buf[32];
	unsigned int major = ver / 10000000U;
	ver -= major * 10000000U;
	unsigned int minor = ver / 10000U;
	ver -= minor * 10000U;
	unsigned int patch = ver / 10U;
	ver -= patch * 10U;
	const char *stability = ver == 0 ? "alpha" : ver == 1 ? "beta" : "";
	snprintf(buf, sizeof(buf), "%u.%u.%u%s", major, minor, patch, stability);
	return buf;
}

/* ---------- Reading the index data from the file ---------- */

static bool parse_indexes(xz_file_info *xfi, file_pair *pair)
{
	if (pair->src_st.st_size <= 0) {
		message_error(_("%s: File is empty"), pair->src_name);
		return false;
	}
	if (pair->src_st.st_size < 2 * STREAM_HEADER_SIZE) {
		message_error(_("%s: Too small to be a valid .xz file"), pair->src_name);
		return false;
	}

	const uint64_t file_size = (uint64_t)pair->src_st.st_size;
	const uint64_t memlimit = hardware_memlimit_get(MODE_LIST);
	io_buf buf;
	xret err = R_OK;

	/* Check the magic bytes at the start. */
	if (io_pread(pair, &buf, STREAM_HEADER_SIZE, 0))
		return false;
	if (memcmp(buf.u8, xz_header_magic, 6) != 0) {
		message_error(_("%s: %s"), pair->src_name, message_strm(R_FORMAT_ERROR));
		return false;
	}

	uint64_t pos = file_size;
	/* Streams are discovered from the end; collect then reverse. */
	typedef struct {
		stream_flags flags;
		uint64_t padding;
		index_record *records;
		size_t count;
		uint64_t index_size;
		uint64_t blocks_size;
	} tmp_stream;
	tmp_stream *streams = NULL;
	size_t nstreams = 0, astreams = 0;

	while (pos > 0) {
		/* Skip stream padding (4-byte zero units). */
		uint64_t padding = 0;
		while (true) {
			if (pos < STREAM_HEADER_SIZE) {
				err = R_DATA_ERROR;
				goto fail;
			}
			if (io_pread(pair, &buf, 4, pos - 4))
				goto fail_silent;
			if (read32le(buf.u8) != 0)
				break;
			padding += 4;
			pos -= 4;
		}
		if (pos < 2 * STREAM_HEADER_SIZE) {
			err = R_DATA_ERROR;
			goto fail;
		}
		/* Footer */
		if (io_pread(pair, &buf, STREAM_HEADER_SIZE, pos - STREAM_HEADER_SIZE))
			goto fail_silent;
		stream_flags footer;
		err = stream_footer_decode(&footer, buf.u8);
		if (err != R_OK) {
			if (err == R_FORMAT_ERROR)
				err = R_DATA_ERROR;
			goto fail;
		}
		pos -= STREAM_HEADER_SIZE;
		if (footer.backward_size > pos - STREAM_HEADER_SIZE) {
			err = R_DATA_ERROR;
			goto fail;
		}
		/* Index */
		const uint64_t index_pos = pos - footer.backward_size;
		xindex tmpidx;
		xindex_init(&tmpidx);
		if (xindex_add_stream(&tmpidx, &footer)) {
			err = R_MEM_ERROR;
			goto fail;
		}
		xcoder idec = XCODER_INIT;
		err = index_decoder_init(&idec, &tmpidx, memlimit);
		if (err != R_OK) {
			xindex_free(&tmpidx);
			goto fail;
		}
		{
			uint64_t ipos = index_pos;
			uint64_t left = footer.backward_size;
			xret r = R_OK;
			while (left > 0) {
				const size_t n = left > IO_BUFFER_SIZE ? IO_BUFFER_SIZE : (size_t)left;
				if (io_pread(pair, &buf, n, ipos)) {
					xcoder_end(&idec);
					xindex_free(&tmpidx);
					goto fail_silent;
				}
				size_t in_pos = 0;
				r = xcoder_code(&idec, buf.u8, &in_pos, n, NULL, NULL, 0, A_RUN);
				ipos += in_pos;
				left -= in_pos;
				if (r == R_STREAM_END) {
					if (left != 0)
						r = R_DATA_ERROR;
					break;
				}
				if (r != R_OK)
					break;
				if (in_pos < n) {
					r = R_DATA_ERROR;
					break;
				}
			}
			xcoder_end(&idec);
			if (r != R_STREAM_END) {
				if (r == R_OK)
					r = R_DATA_ERROR;
				/* Memlimit error reporting */
				if (r == R_MEMLIMIT_ERROR) {
					message_error(_("%s: %s"), pair->src_name, message_strm(r));
					message_mem_needed(V_ERROR, MEMUSAGE_BASE);
					xindex_free(&tmpidx);
					goto fail_silent;
				}
				err = r;
				xindex_free(&tmpidx);
				goto fail;
			}
		}
		index_stream *is = xindex_last_stream(&tmpidx);
		if (is->index_size != footer.backward_size) {
			err = R_DATA_ERROR;
			xindex_free(&tmpidx);
			goto fail;
		}
		/* Stream header */
		const uint64_t blocks_size = vli_ceil4(is->total_unpadded);
		if (index_pos < blocks_size + STREAM_HEADER_SIZE) {
			err = R_DATA_ERROR;
			xindex_free(&tmpidx);
			goto fail;
		}
		const uint64_t header_pos = index_pos - blocks_size - STREAM_HEADER_SIZE;
		if (io_pread(pair, &buf, STREAM_HEADER_SIZE, header_pos)) {
			xindex_free(&tmpidx);
			goto fail_silent;
		}
		stream_flags header;
		err = stream_header_decode(&header, buf.u8);
		if (err != R_OK) {
			if (err == R_FORMAT_ERROR)
				err = R_DATA_ERROR;
			xindex_free(&tmpidx);
			goto fail;
		}
		if (stream_flags_compare(&header, &footer) != R_OK) {
			err = R_DATA_ERROR;
			xindex_free(&tmpidx);
			goto fail;
		}
		/* Record this stream. */
		if (nstreams == astreams) {
			astreams = astreams ? astreams * 2 : 4;
			streams = xrealloc(streams, astreams * sizeof(tmp_stream));
		}
		streams[nstreams].flags = footer;
		streams[nstreams].padding = padding;
		streams[nstreams].records = is->records;
		streams[nstreams].count = is->count;
		streams[nstreams].index_size = is->index_size;
		streams[nstreams].blocks_size = blocks_size;
		is->records = NULL;
		is->count = 0;
		xindex_free(&tmpidx);
		nstreams++;
		pos = header_pos;
	}

	/* Build xfi->idx in file order. */
	xindex_init(&xfi->idx);
	for (size_t s = nstreams; s-- > 0;) {
		if (xindex_add_stream(&xfi->idx, &streams[s].flags)) {
			err = R_MEM_ERROR;
			goto fail;
		}
		for (size_t i = 0; i < streams[s].count; ++i)
			if (xindex_append(&xfi->idx, streams[s].records[i].unpadded_size, streams[s].records[i].uncompressed_size)) {
				err = R_MEM_ERROR;
				goto fail;
			}
		xindex_finish_stream(&xfi->idx, streams[s].padding);
		xfi->stream_padding += streams[s].padding;
	}
	for (size_t s = 0; s < nstreams; ++s)
		free(streams[s].records);
	free(streams);
	return true;

fail:
	message_error(_("%s: %s"), pair->src_name, message_strm(err));
fail_silent:
	for (size_t s = 0; s < nstreams; ++s)
		free(streams[s].records);
	free(streams);
	xindex_free(&xfi->idx);
	return false;
}

/* Iteration helpers */
typedef struct {
	size_t stream_idx;
	size_t block_idx;
	uint64_t block_number_in_file;
	uint64_t block_comp_offset;   /* file offset of block header */
	uint64_t block_uncomp_offset;
} iter_pos;

static bool parse_details(file_pair *pair, const xz_file_info *xfi, const index_stream *s, size_t bi,
		uint64_t comp_offset, block_header_info *bhi, xz_file_info *xfi_mut)
{
	io_buf buf;
	xblock block;
	block_init(&block);

	if (io_pread(pair, &buf, 1, comp_offset))
		return true;
	block.version = 0;
	block.check = s->flags.check;
	block.header_size = block_header_size_decode(buf.u8[0]);
	if (io_pread(pair, &buf, block.header_size, comp_offset))
		return true;

	switch (block_header_decode(&block, buf.u8)) {
	case R_OK:
		break;
	case R_OPTIONS_ERROR:
		message_error("%s: %s", pair->src_name, message_strm(R_OPTIONS_ERROR));
		return true;
	case R_DATA_ERROR:
		message_error("%s: %s", pair->src_name, message_strm(R_DATA_ERROR));
		return true;
	default:
		message_bug();
	}

	bhi->flags[0] = block.compressed_size != VLI_UNKNOWN ? 'c' : '-';
	bhi->flags[1] = block.uncompressed_size != VLI_UNKNOWN ? 'u' : '-';
	bhi->flags[2] = '\0';

	xfi_mut->all_have_sizes &= block.compressed_size != VLI_UNKNOWN && block.uncompressed_size != VLI_UNKNOWN;

	const index_record *rec = &s->records[bi];
	switch (block_compressed_size(&block, rec->unpadded_size)) {
	case R_OK:
		if (block.uncompressed_size == VLI_UNKNOWN || block.uncompressed_size == rec->uncompressed_size)
			break;
		/* fall through */
	case R_DATA_ERROR:
		block_free_filters(&block);
		message_error("%s: %s", pair->src_name, message_strm(R_DATA_ERROR));
		return true;
	default:
		message_bug();
	}

	bhi->header_size = block.header_size;
	bhi->compressed_size = block.compressed_size;
	bhi->memusage = raw_decoder_memusage(block.filters);
	if (xfi_mut->memusage_max < bhi->memusage)
		xfi_mut->memusage_max = bhi->memusage;

	for (size_t i = 0; block.filters[i].id != FID_UNKNOWN; ++i) {
		if (block.filters[i].id == FID_ARM64 && xfi_mut->min_version < 50040002)
			xfi_mut->min_version = 50040002;
		if (block.filters[i].id == FID_RISCV && xfi_mut->min_version < 50060002)
			xfi_mut->min_version = 50060002;
	}
	if (rec->uncompressed_size == 0 && xfi_mut->min_version < 50000022) {
		/* Empty LZMA2 Blocks need 5.0.2. */
		size_t n = 0;
		while (block.filters[n].id != FID_UNKNOWN)
			++n;
		if (n > 0 && block.filters[n - 1].id == FID_LZMA2)
			xfi_mut->min_version = 50000022;
	}

	bhi->filter_chain = strfilter_from_filters(block.filters, STRFILTER_GETOPT_LONG);
	block_free_filters(&block);
	if (bhi->filter_chain == NULL) {
		message_error("%s: %s", pair->src_name, message_strm(R_OPTIONS_ERROR));
		return true;
	}
	(void)xfi;
	return false;
}

static void block_header_info_end(block_header_info *bhi)
{
	free(bhi->filter_chain);
	bhi->filter_chain = NULL;
}

/* Read the Check field of a block as a hex string ("---" if none). */
static bool get_check_value(file_pair *pair, const index_stream *s, uint64_t block_offset,
		uint64_t unpadded_size, char *out, size_t outsize)
{
	const uint32_t csize = check_size(s->flags.check);
	if (csize == 0) {
		snprintf(out, outsize, "---");
		return false;
	}
	io_buf buf;
	if (io_pread(pair, &buf, csize, block_offset + unpadded_size - csize))
		return true;
	size_t p = 0;
	for (uint32_t i = 0; i < csize && p + 3 <= outsize; ++i)
		p += (size_t)snprintf(out + p, outsize - p, "%02x", buf.u8[i]);
	return false;
}

/* Column strings for the adv output. */
enum {
	COLON_STR_STREAMS,
	COLON_STR_BLOCKS,
	COLON_STR_COMPRESSED_SIZE,
	COLON_STR_UNCOMPRESSED_SIZE,
	COLON_STR_RATIO,
	COLON_STR_CHECK,
	COLON_STR_STREAM_PADDING,
	COLON_STR_MEMORY_NEEDED,
	COLON_STR_SIZES_IN_HEADERS,
	COLON_STR_NUMBER_OF_FILES,
};

static const char *const colon_strs[] = {
	"Streams:",
	"Blocks:",
	"Compressed size:",
	"Uncompressed size:",
	"Ratio:",
	"Check:",
	"Stream Padding:",
	"Memory needed:",
	"Sizes in headers:",
	"Number of files:",
};

static int colon_width(void)
{
	size_t w = 0;
	for (size_t i = 0; i < ARRAY_SIZE(colon_strs); ++i) {
		const size_t l = strlen(colon_strs[i]);
		if (l > w)
			w = l;
	}
	return (int)w;
}

static void print_adv_helper(uint64_t stream_count, uint64_t block_count, uint64_t compressed_size,
		uint64_t uncompressed_size, uint32_t checks, uint64_t stream_padding)
{
	char checks_str[CHECKS_STR_SIZE];
	get_check_names(checks_str, checks, true);
	const int w = colon_width();
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_STREAMS], uint64_to_str(stream_count, 0));
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_BLOCKS], uint64_to_str(block_count, 0));
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_COMPRESSED_SIZE], uint64_to_nicestr(compressed_size, NICESTR_B, NICESTR_TIB, true, 0));
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_UNCOMPRESSED_SIZE], uint64_to_nicestr(uncompressed_size, NICESTR_B, NICESTR_TIB, true, 0));
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_RATIO], get_ratio(compressed_size, uncompressed_size));
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_CHECK], checks_str);
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_STREAM_PADDING], uint64_to_nicestr(stream_padding, NICESTR_B, NICESTR_TIB, true, 0));
}

static uint64_t idx_file_size(const xz_file_info *xfi) { return xfi->idx.total_file_size; }

static bool print_info_basic(const xz_file_info *xfi, file_pair *pair)
{
	static bool headings_displayed = false;
	if (!headings_displayed) {
		headings_displayed = true;
		puts(_("Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename"));
	}
	char checks[CHECKS_STR_SIZE];
	get_check_names(checks, xfi->idx.checks, false);
	const char *cols[7] = {
		uint64_to_str(xfi->idx.count, 0),
		uint64_to_str(xfi->idx.total_blocks, 1),
		uint64_to_nicestr(idx_file_size(xfi), NICESTR_B, NICESTR_TIB, false, 2),
		uint64_to_nicestr(xfi->idx.total_uncompressed, NICESTR_B, NICESTR_TIB, false, 3),
		get_ratio(idx_file_size(xfi), xfi->idx.total_uncompressed),
		checks,
		pair->src_name,
	};
	printf("%5s %7s  %11s  %11s  %5s  %-7s %s\n", cols[0], cols[1], cols[2], cols[3], cols[4], cols[5], cols[6]);
	return false;
}

static bool print_info_adv(xz_file_info *xfi, file_pair *pair)
{
	print_adv_helper(xfi->idx.count, xfi->idx.total_blocks, idx_file_size(xfi), xfi->idx.total_uncompressed,
			xfi->idx.checks, xfi->stream_padding);

	uint32_t check_max = 0;

	puts(_("  Streams:"));
	printf("    %6s %9s %15s %15s %15s %15s %6s  %-10s %7s\n",
			_("Stream"), _("Blocks"), _("CompOffset"), _("UncompOffset"), _("CompSize"), _("UncompSize"),
			_("Ratio"), _("Check"), _("Padding"));

	for (size_t si = 0; si < xfi->idx.count; ++si) {
		const index_stream *s = &xfi->idx.streams[si];
		const uint64_t comp_size = 2 * STREAM_HEADER_SIZE + vli_ceil4(s->total_unpadded) + s->index_size;
		const char *cols1[4] = {
			uint64_to_str(si + 1, 0),
			uint64_to_str(s->count, 1),
			uint64_to_str(s->compressed_base, 2),
			uint64_to_str(s->uncompressed_base, 3),
		};
		printf("    %6s %9s %15s %15s ", cols1[0], cols1[1], cols1[2], cols1[3]);
		const char *cols2[5] = {
			uint64_to_str(comp_size, 0),
			uint64_to_str(s->total_uncompressed, 1),
			get_ratio(comp_size, s->total_uncompressed),
			check_names[s->flags.check],
			uint64_to_str(s->padding, 2),
		};
		printf("%15s %15s %6s  %-10s %7s\n", cols2[0], cols2[1], cols2[2], cols2[3], cols2[4]);
		const uint32_t cs = check_size(s->flags.check);
		if (check_max < cs)
			check_max = cs;
	}

	const bool detailed = message_verbosity_get() >= V_DEBUG;
	puts(_("  Blocks:"));
	printf("    %6s %9s %15s %15s %15s %15s %6s  %-*s",
			_("Stream"), _("Block"), _("CompOffset"), _("UncompOffset"), _("TotalSize"), _("UncompSize"),
			_("Ratio"), detailed ? 10 : 1, _("Check"));
	if (detailed) {
		const int checkval_width = my_max(8, 2 * (int)check_max);
		printf(" %-*s %7s  %-5s %15s %11s  %s",
				checkval_width, _("CheckVal"), _("Header"), _("Flags"), _("CompSize"), _("MemUsage"), _("Filters"));
	}
	putchar('\n');

	uint64_t block_number_in_file = 0;
	for (size_t si = 0; si < xfi->idx.count; ++si) {
		const index_stream *s = &xfi->idx.streams[si];
		uint64_t comp_offset = s->compressed_base + STREAM_HEADER_SIZE;
		uint64_t uncomp_offset = s->uncompressed_base;
		for (size_t bi = 0; bi < s->count; ++bi) {
			const index_record *rec = &s->records[bi];
			const uint64_t total_size = vli_ceil4(rec->unpadded_size);
			++block_number_in_file;
			block_header_info bhi = { "", 0, 0, 0, NULL };
			char check_value[2 * 64 + 1] = "";
			if (detailed) {
				if (parse_details(pair, xfi, s, bi, comp_offset, &bhi, xfi))
					return true;
				if (get_check_value(pair, s, comp_offset, rec->unpadded_size, check_value, sizeof(check_value))) {
					block_header_info_end(&bhi);
					return true;
				}
			}
			const char *cols1[4] = {
				uint64_to_str(si + 1, 0),
				uint64_to_str(bi + 1, 1),
				uint64_to_str(comp_offset, 2),
				uint64_to_str(uncomp_offset, 3),
			};
			printf("    %6s %9s %15s %15s ", cols1[0], cols1[1], cols1[2], cols1[3]);
			const char *cols2[4] = {
				uint64_to_str(total_size, 0),
				uint64_to_str(rec->uncompressed_size, 1),
				get_ratio(total_size, rec->uncompressed_size),
				check_names[s->flags.check],
			};
			if (detailed) {
				const int checkval_width = my_max(8, 2 * (int)check_max);
				printf("%15s %15s %6s  %-10s %-*s %7s  %-5s %15s %11s  %s\n",
						cols2[0], cols2[1], cols2[2], cols2[3], checkval_width, check_value,
						uint64_to_str(bhi.header_size, 0), bhi.flags,
						uint64_to_str(bhi.compressed_size, 1),
						uint64_to_nicestr(bhi.memusage, NICESTR_MIB, NICESTR_MIB, false, 2) + 0,
						bhi.filter_chain);
			} else {
				printf("%15s %15s %6s  %s\n", cols2[0], cols2[1], cols2[2], cols2[3]);
			}
			block_header_info_end(&bhi);
			comp_offset += total_size;
			uncomp_offset += rec->uncompressed_size;
		}
	}

	if (detailed) {
		const int w = colon_width();
		printf("  %-*s %s MiB\n", w, colon_strs[COLON_STR_MEMORY_NEEDED], uint64_to_str(round_up_to_mib(xfi->memusage_max), 0));
		printf("  %-*s %s\n", w, colon_strs[COLON_STR_SIZES_IN_HEADERS], xfi->all_have_sizes ? _("Yes") : _("No"));
		printf("  %s %s\n", _("Minimum XZ Utils version:"), xz_ver_to_str(xfi->min_version));
	}
	return false;
}

static bool print_info_robot(xz_file_info *xfi, file_pair *pair)
{
	char checks[CHECKS_STR_SIZE];
	get_check_names(checks, xfi->idx.checks, false);

	printf("name\t%s\n", pair->src_name);
	printf("file\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t%" PRIu64 "\n",
			(uint64_t)xfi->idx.count, xfi->idx.total_blocks, idx_file_size(xfi), xfi->idx.total_uncompressed,
			get_ratio(idx_file_size(xfi), xfi->idx.total_uncompressed), checks, xfi->stream_padding);

	if (message_verbosity_get() >= V_VERBOSE) {
		for (size_t si = 0; si < xfi->idx.count; ++si) {
			const index_stream *s = &xfi->idx.streams[si];
			const uint64_t comp_size = 2 * STREAM_HEADER_SIZE + vli_ceil4(s->total_unpadded) + s->index_size;
			printf("stream\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t%" PRIu64 "\n",
					(uint64_t)si + 1, (uint64_t)s->count, s->compressed_base, s->uncompressed_base,
					comp_size, s->total_uncompressed, get_ratio(comp_size, s->total_uncompressed),
					check_names[s->flags.check], s->padding);
		}

		uint64_t block_number_in_file = 0;
		for (size_t si = 0; si < xfi->idx.count; ++si) {
			const index_stream *s = &xfi->idx.streams[si];
			uint64_t comp_offset = s->compressed_base + STREAM_HEADER_SIZE;
			uint64_t uncomp_offset = s->uncompressed_base;
			for (size_t bi = 0; bi < s->count; ++bi) {
				const index_record *rec = &s->records[bi];
				const uint64_t total_size = vli_ceil4(rec->unpadded_size);
				++block_number_in_file;
				block_header_info bhi = { "", 0, 0, 0, NULL };
				char check_value[2 * 64 + 1] = "";
				if (message_verbosity_get() >= V_DEBUG) {
					if (parse_details(pair, xfi, s, bi, comp_offset, &bhi, xfi))
						return true;
					if (get_check_value(pair, s, comp_offset, rec->unpadded_size, check_value, sizeof(check_value))) {
						block_header_info_end(&bhi);
						return true;
					}
				}
				printf("block\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s",
						(uint64_t)si + 1, (uint64_t)bi + 1, block_number_in_file, comp_offset, uncomp_offset,
						total_size, rec->uncompressed_size, get_ratio(total_size, rec->uncompressed_size),
						check_names[s->flags.check]);
				if (message_verbosity_get() >= V_DEBUG)
					printf("\t%s\t%" PRIu32 "\t%s\t%" PRIu64 "\t%" PRIu64 "\t%s",
							check_value, bhi.header_size, bhi.flags, bhi.compressed_size, bhi.memusage, bhi.filter_chain);
				putchar('\n');
				block_header_info_end(&bhi);
				comp_offset += total_size;
				uncomp_offset += rec->uncompressed_size;
			}
		}
	}

	if (message_verbosity_get() >= V_DEBUG)
		printf("summary\t%" PRIu64 "\t%s\t%" PRIu32 "\n", xfi->memusage_max, xfi->all_have_sizes ? "yes" : "no", xfi->min_version);

	return false;
}

static void update_totals(const xz_file_info *xfi)
{
	++totals.files;
	totals.streams += xfi->idx.count;
	totals.blocks += xfi->idx.total_blocks;
	totals.compressed_size += idx_file_size(xfi);
	totals.uncompressed_size += xfi->idx.total_uncompressed;
	totals.stream_padding += xfi->stream_padding;
	totals.checks |= xfi->idx.checks;
	if (totals.memusage_max < xfi->memusage_max)
		totals.memusage_max = xfi->memusage_max;
	if (totals.min_version < xfi->min_version)
		totals.min_version = xfi->min_version;
	totals.all_have_sizes &= xfi->all_have_sizes;
}

static void print_totals_basic(void)
{
	char line[80];
	memset(line, '-', sizeof(line));
	line[sizeof(line) - 1] = '\0';
	puts(line);
	char checks[CHECKS_STR_SIZE];
	get_check_names(checks, totals.checks, false);
	printf("%5s %7s  %11s  %11s  %5s  %-7s ",
			uint64_to_str(totals.streams, 0),
			uint64_to_str(totals.blocks, 1),
			uint64_to_nicestr(totals.compressed_size, NICESTR_B, NICESTR_TIB, false, 2),
			uint64_to_nicestr(totals.uncompressed_size, NICESTR_B, NICESTR_TIB, false, 3),
			get_ratio(totals.compressed_size, totals.uncompressed_size),
			checks);
	printf(totals.files == 1 ? "%s file\n" : "%s files\n", uint64_to_str(totals.files, 0));
}

static void print_totals_adv(void)
{
	putchar('\n');
	puts(_("Totals:"));
	const int w = colon_width();
	printf("  %-*s %s\n", w, colon_strs[COLON_STR_NUMBER_OF_FILES], uint64_to_str(totals.files, 0));
	print_adv_helper(totals.streams, totals.blocks, totals.compressed_size, totals.uncompressed_size,
			totals.checks, totals.stream_padding);
	if (message_verbosity_get() >= V_DEBUG) {
		printf("  %-*s %s MiB\n", w, colon_strs[COLON_STR_MEMORY_NEEDED], uint64_to_str(round_up_to_mib(totals.memusage_max), 0));
		printf("  %-*s %s\n", w, colon_strs[COLON_STR_SIZES_IN_HEADERS], totals.all_have_sizes ? _("Yes") : _("No"));
		printf("  %s %s\n", _("Minimum XZ Utils version:"), xz_ver_to_str(totals.min_version));
	}
}

static void print_totals_robot(void)
{
	char checks[CHECKS_STR_SIZE];
	get_check_names(checks, totals.checks, false);
	printf("totals\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t%" PRIu64 "\t%" PRIu64,
			totals.streams, totals.blocks, totals.compressed_size, totals.uncompressed_size,
			get_ratio(totals.compressed_size, totals.uncompressed_size), checks, totals.stream_padding, totals.files);
	if (message_verbosity_get() >= V_DEBUG)
		printf("\t%" PRIu64 "\t%s\t%" PRIu32, totals.memusage_max, totals.all_have_sizes ? "yes" : "no", totals.min_version);
	putchar('\n');
}

void list_totals(void)
{
	if (opt_robot) {
		print_totals_robot();
	} else if (totals.files > 1) {
		if (message_verbosity_get() <= V_WARNING)
			print_totals_basic();
		else
			print_totals_adv();
	}
}

void list_file(const char *filename)
{
	message_filename(filename);

	if (filename == stdin_filename) {
		message_error(_("--list does not support reading from standard input"));
		return;
	}

	opt_stdout = false;
	opt_force = true;
	file_pair *pair = io_open_src(filename);
	if (pair == NULL)
		return;

	xz_file_info xfi;
	memset(&xfi, 0, sizeof(xfi));
	xindex_init(&xfi.idx);
	xfi.all_have_sizes = true;
	xfi.min_version = 50000002;

	if (parse_indexes(&xfi, pair)) {
		bool fail;
		if (opt_robot)
			fail = print_info_robot(&xfi, pair);
		else if (message_verbosity_get() <= V_WARNING)
			fail = print_info_basic(&xfi, pair);
		else
			fail = print_info_adv(&xfi, pair);
		if (!fail)
			update_totals(&xfi);
		xindex_free(&xfi.idx);
	}

	io_close(pair, false);
}
