		if (opt_stdout || (args.arg_count == 1 && strcmp(args.arg_names[0], "-") == 0)) {
			if (is_tty_stdout()) {
				message_try_help();
				my_exit(E_ERROR);
			}
		}
	}

	if (opt_mode != MODE_LIST)
		signals_init();

	for (unsigned i = 0; i < args.arg_count && !user_abort; ++i) {
		if (strcmp("-", args.arg_names[i]) == 0) {
			if (opt_mode == MODE_COMPRESS) {
