		while (true) {
			const char *name = read_name(&args);
			if (name == NULL)
				break;
			if (opt_mode == MODE_LIST)
				list_file(name);
			else
				coder_run(name);
		}
		if (args.files_name != stdin_filename)
			(void)fclose(args.files_file);
	}

	if (opt_mode == MODE_LIST)
		list_totals();

	signals_exit();

	my_exit(E_SUCCESS);
}
