new='''/* Input handling: a symbol is decoded from a contiguous buffer. If the
 * caller's buffer has fewer than SYMBOL_IN_MAX bytes, a temporary buffer is
 * built from the stashed bytes of an incomplete symbol plus a peek at the
 * new input. Only the bytes actually used are consumed. */
typedef struct {
	bool from_temp;
	size_t stash;    /* bytes in temp that were already consumed earlier */
	size_t peeked;   /* bytes copied from in[] without consuming them */
	uint8_t buf[SYMBOL_IN_MAX * 2];
} sym_input;

static void prepare_input(lzma1_dec *d, rcl *r, sym_input *si, const uint8_t *in, size_t *in_pos, size_t in_size)
{
	const size_t avail = in_size - *in_pos;
	si->stash = d->temp_size;
	si->peeked = 0;
	if (d->temp_size == 0 && avail >= SYMBOL_IN_MAX) {
		si->from_temp = false;
		r->in = in;
		r->in_pos = *in_pos;
	} else {
		si->from_temp = true;
		memcpy(si->buf, d->temp, d->temp_size);
		size_t want = SYMBOL_IN_MAX - d->temp_size;
		if (want > avail)
			want = avail;
		memcpy(si->buf + d->temp_size, in + *in_pos, want);
		si->peeked = want;
		memset(si->buf + d->temp_size + want, 0, sizeof(si->buf) - d->temp_size - want);
		r->in = si->buf;
		r->in_pos = 0;
	}
	r->range = d->rc.range;
	r->code = d->rc.code;
}

enum { COMMIT_OK, COMMIT_NEED_MORE, COMMIT_TRUNCATED };

/* Commit the bytes used by a successfully decoded symbol. */
static void commit_input(lzma1_dec *d, const rcl *r, const sym_input *si, size_t *in_pos)
{
	d->rc.range = r->range;
	d->rc.code = r->code;
	if (!si->from_temp) {
		*in_pos = r->in_pos;
		d->temp_size = 0;
		return;
	}
	if (r->in_pos >= si->stash) {
		*in_pos += r->in_pos - si->stash;
		d->temp_size = 0;
	} else {
		memmove(d->temp, si->buf + r->in_pos, si->stash - r->in_pos);
		d->temp_size = si->stash - r->in_pos;
	}
}

/* Returns true if the symbol decoding ran past the available bytes. */
static bool input_overrun(const rcl *r, const sym_input *si)
{
	return si->from_temp && r->in_pos > si->stash + si->peeked;
}

/* Handle an overrun: stash the peeked bytes when more input may come. */
static int handle_overrun(lzma1_dec *d, const sym_input *si, const uint8_t *in, size_t *in_pos, size_t in_size, bool finishing)
{
	const size_t avail = in_size - *in_pos;
	if (!finishing && si->peeked == avail && si->stash + avail < SYMBOL_IN_MAX) {
		memcpy(d->temp + si->stash, in + *in_pos, avail);
		d->temp_size = si->stash + avail;
		*in_pos = in_size;
		return COMMIT_NEED_MORE;
	}
	return COMMIT_TRUNCATED;
}

