		if (c->hdr_pos < STREAM_HEADER_SIZE)
			return XR_OK;
		if (c->sequence == MT_SEQ_FOOTER)
			return XR_STREAM_END;
		c->sequence = MT_SEQ_COLLECT;
		break;

	case MT_SEQ_COLLECT: {
		if (c->current == NULL) {
			c->current = mt_job_new(c);
			if (c->current == NULL)
				return XR_MEM_ERROR;
		}
		mt_job *j = c->current;
		const size_t want = (size_t)(c->block_size - j->in_filled);
		const size_t avail = in_size - *in_pos;
		const size_t n = want < avail ? want : avail;
		memcpy(j->inbuf + j->in_filled, in + *in_pos, n);
		j->in_filled += n;
		*in_pos += n;
		if (j->in_filled == c->block_size) {
			c->current = NULL;
			xret r = mt_start_job(c, j);
			if (r != XR_OK)
				return r;
			c->sequence = MT_SEQ_OUTPUT;
			break;
		}
		if (*in_pos < in_size)
			return XR_PROG_ERROR;
		if (action == A_RUN) {
			/* Output any finished blocks meanwhile. */
			if (c->queue_head != NULL && !c->queue_head->running) {
				c->sequence = MT_SEQ_OUTPUT;
				break;
			}
			return XR_OK;
		}
		if (action == A_FINISH)
			c->finishing = true;
		if (j->in_filled > 0) {
			c->current = NULL;
			xret r = mt_start_job(c, j);
			if (r != XR_OK)
				return r;
		}
		c->sequence = MT_SEQ_OUTPUT;
		break;
	}

	case MT_SEQ_OUTPUT: {
		mt_job *j = c->queue_head;
		if (j == NULL) {
			if (c->finishing) {
				xcoder_end(&c->index_encoder);
				xret r = index_encoder_init(&c->index_encoder, xindex_last_stream(&c->index));
				if (r != XR_OK)
					return r;
				c->sequence = MT_SEQ_INDEX;
				break;
			}
			c->sequence = MT_SEQ_COLLECT;
			if (action != A_RUN && *in_pos == in_size)
				return XR_STREAM_END;
			break;
		}
		if (j->running) {
			/* While collecting (RUN) don't block unless the queue is full. */
			if (!c->finishing && action == A_RUN && c->in_flight < c->threads) {
				c->sequence = MT_SEQ_COLLECT;
				if (*in_pos < in_size)
					break;
				return XR_OK;
			}
			xret r = mt_wait_oldest(c);
			if (r != XR_OK)
				return r;
		}
		if (j->result != XR_OK)
			return j->result;
		if (j->out_pos == 0 && j->out_filled == 0) {
			/* nothing (shouldn't happen) */
		}
		bufcpy(j->outbuf, &j->out_pos, j->out_filled, out, out_pos, out_size);
		if (j->out_pos < j->out_filled)
			return XR_OK;
		/* Block fully written. */
		if (xindex_append(&c->index, j->unpadded_size, j->uncompressed_size))
			return XR_MEM_ERROR;
		c->queue_head = j->next;
		if (c->queue_head == NULL)
			c->queue_tail = NULL;
		j->next = c->free_jobs;
		c->free_jobs = j;
		break;
	}

	case MT_SEQ_INDEX: {
		const xret r = xcoder_code(&c->index_encoder, NULL, NULL, 0, out, out_pos, out_size, A_RUN);
		if (r != XR_STREAM_END)
			return r;
		c->flags.backward_size = xindex_last_stream(&c->index)->index_size;
		if (stream_footer_encode(&c->flags, c->hdr) != XR_OK)
			return XR_PROG_ERROR;
		c->hdr_pos = 0;
		c->sequence = MT_SEQ_FOOTER;
		break;
	}
	}
	}
}

static void mt_enc_end(void *ctx)
{
	mt_enc *c = ctx;
	mt_job *j = c->queue_head;
	while (j != NULL) {
		mt_job *next = j->next;
		if (j->running)
			pthread_join(j->thread, NULL);
		mt_job_free(j);
		j = next;
	}
	j = c->free_jobs;
	while (j != NULL) {
		mt_job *next = j->next;
		mt_job_free(j);
		j = next;
	}
	if (c->current != NULL)
		mt_job_free(c->current);
	xcoder_end(&c->index_encoder);
	filters_free(c->filters);
	xindex_free(&c->index);
	free(c);
}

static xret mt_enc_update(void *ctx, const xfilter *filters)
{
	mt_enc *c = ctx;
	if (!filters_validate_chain(filters, true))
		return XR_OPTIONS_ERROR;
	xfilter tmp[FILTERS_MAX + 1];
	if (filters_copy(filters, tmp))
		return XR_MEM_ERROR;
	filters_free(c->filters);
	memcpy(c->filters, tmp, sizeof(tmp));
	return XR_OK;
}

xret stream_encoder_mt_init(xcoder *c, const xfilter *filters, xcheck check, uint64_t block_size, uint32_t threads)
{
	if (!filters_validate_chain(filters, true))
		return XR_OPTIONS_ERROR;
	if ((unsigned)check > CHECK_ID_MAX)
		return XR_OPTIONS_ERROR;
	if (!check_is_supported(check))
		return XR_UNSUPPORTED_CHECK;
	if (block_size == 0 || block_size > (UINT64_C(1) << 62) || block_size > SIZE_MAX / 4)
		return XR_OPTIONS_ERROR;
	mt_enc *m = calloc(1, sizeof(*m));
	if (m == NULL)
		return XR_MEM_ERROR;
	m->sequence = MT_SEQ_STREAM_HEADER;
	m->flags.version = 0;
	m->flags.check = check;
	m->flags.backward_size = VLI_UNKNOWN;
	m->block_size = block_size;
	m->threads = threads == 0 ? 1 : threads;
	for (size_t i = 0; i <= FILTERS_MAX; ++i) { m->filters[i].id = FID_UNKNOWN; m->filters[i].options = NULL; }
	xindex_init(&m->index);
	if (filters_copy(filters, m->filters) || xindex_add_stream(&m->index, &m->flags)) {
		mt_enc_end(m);
		return XR_MEM_ERROR;
	}
	if (stream_header_encode(&m->flags, m->hdr) != XR_OK) {
		mt_enc_end(m);
		return XR_PROG_ERROR;
	}
	m->hdr_pos = 0;
	c->ctx = m;
	c->code = mt_encode;
	c->end = mt_enc_end;
	c->update = mt_enc_update;
	return XR_OK;
}

